v4("__root", function(arg)
	local Executor = arg("Utility/Executor")

	for i = 1, 8 do
		local v = table.pack(pcall(getfenv, i))
		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
