	_G.__rbx_runtime_auth = {
		script_key = Executor.get("script_key"),
		LRM_LinkedDiscordID = Executor.get("LRM_LinkedDiscordID"),
		LRM_UserNote = Executor.get("LRM_UserNote"),
		LRM_TotalExecutions = Executor.get("LRM_TotalExecutions"),
		LRM_IsUserPremium = Executor.get("LRM_IsUserPremium"),
		LRM_ScriptName = Executor.get("LRM_ScriptName"),
	}

	local Log = arg("Utility/Log")
	local Services = arg("Services")

	if Services.Game.PlaceId ~= 0 then
		Log.print(("[Cerberus] execution start — placeId=%d jobId=%q time=%.3f"):format(Services.Game.PlaceId, tostring(Services.Game.JobId or ""), os.clock()))
		if arg("Bootstrap/Init")() then
			arg("Cerberus")()
