	local free = nil
	local tbl2 = nil
	local v = nil

	local tbl3 = {
		DEV = "dev",
		PREMIUM = "premium",
		FREE = "free",
		key = function()
			local scriptKey = Executor.get("script_key")

			if type(scriptKey) == "string" then
				if scriptKey ~= "" then
					return scriptKey, "env chain"
				end
			end

			local value = rawget(_G, "__rbx_runtime_auth")

			if type(value) == "table" then
				if type(value.script_key) == "string" then
					if value.script_key ~= "" then
						return value.script_key, "boot snapshot"
					end
				end
			end

			return nil
		end,
	}

	local function fn2()
		return nil
	end

	local function fn3()
		local v5 = tbl3.key()

		if v5 then
			local v6 = table.pack(Sdk.new().Check(v5))
			local v7, v8

			if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
				v7 = v6[1]
				v8 = v6[2]
			else
				v7 = nil
				v8 = nil
			end

			if v7 then
				tbl2 = v7
				local v9 = Policy.new().Resolve(v7.code)

				if not v9.valid then
					if v9.action ~= Policy.ACTION.RETRY then
						return tbl3.FREE
					end
				end

				return tbl3.PREMIUM
			end

			tbl2 = { code = Policy.CODES.UNKNOWN_ERROR, message = v8 }
			Log.devwarn("Tier", "key check failed: %s — treating as premium (fail-open)", tostring(v8))
			return tbl3.PREMIUM
		end

		return tbl3.FREE
	end

	tbl3.resolve = function()
		if free then
			return free
		end
		v = fn2()

		if v then
			free = v
			Log.dev("Tier", "forced to %q — cosmetic only, the premium gate still reads the real key", free)
			return free
		end

		local now = os.clock()
		local v5 = table.pack(pcall(fn3))
		local v6, v7

		if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
			v6 = v5[1]
			v7 = v5[2]
		else
			v6 = nil
			v7 = nil
		end

		if not v6 then
			Log.devwarn("Tier", "resolve threw: %s", tostring(v7))
		end

		local v8 = v6

		if v8 then
			v8 = v7
		end

		free = v8 or tbl3.FREE
		Log.dev("Tier", "%s (%.2fs)", free, os.clock() - now)
		return free
	end

	tbl3.current = function()
		return free or tbl3.resolve()
	end

	tbl3.bootResult = function()
		return tbl2
	end

	tbl3.isForced = function()
		return v ~= nil
	end

	return tbl3
end)

