v4("Utility/Jobs", function(arg)
	local Log = arg("Utility/Log")
	local tbl = {}
	local count = 0

	local function fn2(thread)
		if type(thread) == "thread" then
			if coroutine.running() == thread then
				return
			end

			if coroutine.status(thread) ~= "dead" then
				if not pcall(task.cancel, thread) then
					task.defer(function()
						pcall(task.cancel, thread)
					end)
				end

				return
			end

			return
		end
	end

	local function fn3(arg2)
		if arg2.alive then
			arg2.alive = false
			tbl[arg2] = nil
		end
	end

	local function fn4(name)
		count += 1
		local tbl2 = { name = name or "job#" .. count, seq = count, alive = true, thread = nil }

		tbl2.sleep = function(arg2, delay)
			if arg2.alive then
				task.wait(delay)
				return arg2.alive
			end
			return false
		end

		tbl2.Cancel = function(arg2)
			if arg2.alive then
				local thread = arg2.thread
				fn3(arg2)
				fn2(thread)
				return
			end
		end

		tbl2.Disconnect = tbl2.Cancel
		tbl2.Destroy = tbl2.Cancel

		tbl2.IsRunning = function(arg2)
			return arg2.alive
		end

		tbl[tbl2] = true
