	local tbl2 = {
		read = function()
			if not isfile then
				return nil
			end

			if not readfile then
				return nil
			end
			local json = false

			pcall(function()
				json = isfile("Cerberus/language.json")
			end)

			if json then
				local v = table.pack(pcall(readfile, "Cerberus/language.json"))
				local v5, v6

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					v6 = v[2]
				else
					v5 = nil
					v6 = nil
				end

				if not v5 then
					return nil
				end

				if type(v6) ~= "string" then
					return nil
				end

				if v6 == "" then
					return nil
				end
				local v7 = table.pack(pcall(Services.HttpService.JSONDecode, Services.HttpService, v6))
				local v8, v9

				if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
					v8 = v7[1]
					v9 = v7[2]
				else
					v8 = nil
					v9 = nil
				end

				if v8 then
					if type(v9) == "table" then
						if type(v9.locale) == "string" then
							if v9.locale ~= "" then
								return v9.locale
							end
						end

						return nil
					end
				end

				return nil
			end

			return nil
		end,
		save = function(arg2)
			if type(arg2) ~= "string" then
				return
			end

