			end

			if writefile then
				local v = table.pack(pcall(Services.HttpService.JSONEncode, Services.HttpService, { locale = arg2 }))
				local v5, content

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					content = v[2]
				else
					v5 = nil
					content = nil
				end

