						v7 = v6[1]
						v8 = v6[2]
					else
						v7 = nil
						v8 = nil
					end

					if not v7 then
						Log.warn(("[Cerberus/LanguagePicker] save failed: %s"):format(tostring(v8)))
					end

					return
				end

				return
			end

			Log.warn("[Cerberus/LanguagePicker] writefile unavailable; selection won't persist")
		end,
		clear = function()
			if delfile then
				local json2 = false

				local function fn2()
					local json = isfile

					if json then
						json = isfile("Cerberus/language.json")
					end

					json2 = json
				end

				pcall(fn2)
				if not json2 then
					return
				end
				pcall(delfile, "Cerberus/language.json")
				Log.print("[Cerberus/LanguagePicker] selection file cleared")
			end
		end,
	}

