v4("UI/UiHost", function(arg)
	local Services = arg("Services")
	local References = arg("References")

	local function fn2()
		local str = tostring(References.executorName or ""):lower()
		return str:find("xeno", 1, true) ~= nil or str:find("solara", 1, true) ~= nil
	end

	return {
		pick = function()
			if not fn2() then
				local value = rawget(getfenv(), "gethui") or rawget(_G, "gethui")

				if type(value) == "function" then
					local v = table.pack(pcall(value))
					local v5, v6

					if select("#", table.unpack(v, 1, v.n)) ~= 0 then
						v5 = v[1]
						v6 = v[2]
					else
						v5 = nil
						v6 = nil
					end

					if v5 then
						if typeof(v6) == "Instance" then
							return v6
						end
					end
				end
			end

			if Services.CoreGui then
				return Services.CoreGui
			end
			local players = Services.Players

			if players then
				players = Services.Players.LocalPlayer
			end

			if players then
				local playerGui = players:FindFirstChildOfClass("PlayerGui")
				if playerGui then
					return playerGui
				end
			end

			return nil
		end,
		isLimited = function()
			return fn2()
		end,
	}
end)

v4("References", function(arg)
	local Services = arg("Services")
	local gameName = arg("Meta").gameName

	local tbl = {
		player = cloneref(Services.Players.LocalPlayer),
		character = nil,
		humanoid = nil,
		humanoidRootPart = nil,
		camera = cloneref(Services.Workspace.CurrentCamera),
		gameName = gameName,
		gameDir = ("Cerberus/%s"):format(gameName),
	}

