	if executorName then
		executorName = identifyexecutor()
	end

	tbl.executorName = executorName or "Unknown"
	local tbl2 = {}
	local tbl3 = {}

	tbl.onCharacter = function(arg2)
		tbl2[#tbl2 + 1] = arg2

		if tbl.character then
			pcall(arg2, tbl.character)
		end

		return function()
			for i = #tbl2, 1, -1 do
				if tbl2[i] == arg2 then
					table.remove(tbl2, i)
				end

				continue
			end
		end
	end

	tbl.onCharacterRemoving = function(arg2)
		tbl3[#tbl3 + 1] = arg2

		return function()
			for i = #tbl3, 1, -1 do
				if tbl3[i] == arg2 then
					table.remove(tbl3, i)
				end
			end
		end
	end

	tbl._fireCharacter = function(arg2)
		local v = table.move(tbl2, 1, #tbl2, 1, table.create(#tbl2))
		local v5 = table.pack(ipairs(v))
		local v6, v7, v8

		if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
			v6 = v5[1]
			v7 = v5[2]
			v8 = v5[3]
		else
			v6 = nil
			v7 = nil
			v8 = nil
		end

		for _, v9 in v6, v7, v8 do
			pcall(v9, arg2)
		end
	end

	tbl._fireCharacterRemoving = function()
		local v = table.move(tbl3, 1, #tbl3, 1, table.create(#tbl3))
		local v5 = table.pack(ipairs(v))
		local v6, v7, v8

		if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
			v6 = v5[1]
			v7 = v5[2]
			v8 = v5[3]
		else
			v6 = nil
			v7 = nil
			v8 = nil
		end

		for _, v9 in v6, v7, v8 do
			pcall(v9)
		end
	end

	return tbl
end)

