					tween.Completed:Connect(function()
						if not arg3.opened then
							if arg3.gui then
								arg3.gui.Enabled = false
							end
						end
					end)

					return
				end
			end
		end

		return tbl2
	end
end)

v4("Features/Configs/Tr", function(arg)
	local Translations = arg("Features/Configs/Translations")
	local LanguagePicker = arg("Auth/LanguagePicker")

	local function getMatch()
		return (LanguagePicker.read() or "en"):lower():match("^([a-z]+)") or "en"
	end

	return { tr = function(arg2)
		if type(arg2) ~= "string" then
			return arg2
		end

		if arg2 ~= "" then
			local match = getMatch()

			if match ~= "en" then
				local Translation = Translations[match]
				if Translation then
					return Translation[arg2] or arg2
				end
				return arg2
			end

			return arg2
		end

		return arg2
	end }
end)

