v4("Features/Configs/Reporter", function(arg)
	local ConfigSecrets = arg("ConfigSecrets")
	local Api = arg("Features/Configs/Api")
	local Http = arg("Utility/Helpers/Http")
	local Log = arg("Utility/Log")

	local function fn2(ConfigSecrets2, arg2)
		if Http.client() then
			local v = table.pack(Http.postJson(ConfigSecrets2, arg2, { Accept = "application/json" }))
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				return true
			end
			return false, tostring(v6)
		end

		return false, "no http client"
	end

	local function fn3(arg2)
		local tbl = {}
		local tbl2 = { name = "Reason", value = tostring(arg2.reason or "Unspecified"), inline = true }
		local tbl3 = { name = "Game", value = tostring(arg2.game or "Unknown"), inline = true }
		local tbl4 = { name = "Config Name", value = tostring(arg2.configName or "(unnamed)"), inline = false }
		local tbl5 = { name = "Config ID", value = "`" .. tostring(arg2.configId or "?") .. "`", inline = true }
		local tbl6 = { name = "Owner", value = "`" .. tostring(arg2.ownerDiscordId or "?") .. "`", inline = true }

		local tbl7 = {
			name = "Reporter",
			value = "`" .. tostring(arg2.reporterDiscordId or "anonymous") .. "`",
			inline = true,
		}

		tbl[1] = tbl2
		tbl[2] = tbl3
		tbl[3] = tbl4
		tbl[4] = tbl5
		tbl[5] = tbl6
		tbl[6] = tbl7
		local description = arg2.description

		if type(description) == "string" then
			if description:gsub("%s", "") ~= "" then
				tbl[#tbl + 1] = { name = "Description", value = description, inline = false }
			end
		end

		if type(arg2.deleteUrl) ~= "string" then
			if arg2.deleteUrlError then
				tbl[#tbl + 1] = {
					name = "Moderator Action",
					value = "Couldn't mint delete link: `" .. tostring(arg2.deleteUrlError) .. "` — delete via the admin panel.",
					inline = false,
				}
			end
		elseif arg2.deleteUrl ~= "" then
			local deleteExpiresAt = arg2.deleteExpiresAt
			local deleteExpiresAt2 = deleteExpiresAt

			if deleteExpiresAt2 then
				deleteExpiresAt2 = "expires " .. tostring(deleteExpiresAt)
			end

			tbl[#tbl + 1] = {
				name = "Moderator Action",
				value = "[Click to delete (one-time, " .. (deleteExpiresAt2 or "TTL bounded") .. ")](" .. arg2.deleteUrl .. ")",
				inline = false,
			}
		elseif arg2.deleteUrlError then
			tbl[#tbl + 1] = {
				name = "Moderator Action",
				value = "Couldn't mint delete link: `" .. tostring(arg2.deleteUrlError) .. "` — delete via the admin panel.",
				inline = false,
			}
		end

		return {
			title = "Config Reported",
			description = "A user has flagged a community config for review.",
			color = 15158332,
			fields = tbl,
			timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
			footer = { text = "Cerberus / Community Configs" },
		}
	end

	local tbl = { submit = function(arg2)
		if type(arg2) ~= "table" then
			return false, "invalid opts"
		end

		if type(arg2.configId) ~= "string" then
			return false, "missing config id"
		end

		if arg2.configId == "" then
			return false, "missing config id"
		end
		local ConfigSecrets2 = ConfigSecrets

		if ConfigSecrets2 then
			ConfigSecrets2 = ConfigSecrets.ConfigsReportWebhook
		end

		if type(ConfigSecrets2) == "string" then
			if ConfigSecrets2 ~= "" then
				local url = nil
				local expiresAt = nil
				local str = nil

				if Api.canWrite() then
					if type(arg2.ownerDiscordId) ~= "string" then
						str = "no API key or missing owner id"
					elseif arg2.ownerDiscordId ~= "" then
						local v = table.pack(Api.mintDeleteLink(arg2.configId, arg2.ownerDiscordId, 720))
						local v5, v6

						if select("#", table.unpack(v, 1, v.n)) ~= 0 then
							v5 = v[1]
							v6 = v[2]
						else
							v5 = nil
							v6 = nil
						end

						if v5 then
							if type(v5.url) ~= "string" then
								str = v6 or "unknown error"
							else
								url = v5.url
								expiresAt = v5.expires_at
							end
						else
							str = v6 or "unknown error"
						end
					else
						str = "no API key or missing owner id"
					end
				else
					str = "no API key or missing owner id"
				end

				local v = fn3({
					reason = arg2.reason,
					description = arg2.description,
					configId = arg2.configId,
					configName = arg2.configName,
					game = arg2.game,
					ownerDiscordId = arg2.ownerDiscordId,
					reporterDiscordId = arg2.reporterDiscordId,
					deleteUrl = url,
					deleteExpiresAt = expiresAt,
					deleteUrlError = str,
				})

				local v5 = table.pack(fn2(ConfigSecrets2, { embeds = { v } }))
				local v6, v7

				if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
					v6 = v5[1]
					v7 = v5[2]
				else
					v6 = nil
					v7 = nil
				end

				Log.webhook("config report", v6)
				return v6, v7
			end
		end

		return false, "report webhook not configured"
	end }

	return tbl
end)

v4("Features/Configs/Api", function(arg)
	local ConfigSecrets = arg("ConfigSecrets")
	local Http = arg("Utility/Helpers/Http")
	local httpService = arg("Services").HttpService
	local tbl = { attempts = 3 }

	local function fn2(configsApiUrl)
		return (tostring(configsApiUrl or ""):gsub("/+$", ""))
	end

	local function fn3()
		return fn2(ConfigSecrets.ConfigsApiUrl or "")
	end

	local function fn4(arg2)
		if httpService.UrlEncode then
			local v = table.pack(pcall(httpService.UrlEncode, httpService, tostring(arg2)))
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				return v6
			end
		end

		return tostring(arg2):gsub("[^%w%-_%.~]", function(arg3)
			return string.format("%%%02X", string.byte(arg3))
		end)
	end

	local function fn5(arg2)
		if type(arg2) ~= "table" then
			return ""
		end
		local tbl2 = {}
		local v = table.pack(pairs(arg2))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for k, v8 in v5, v6, v7 do
			if v8 ~= nil then
				if v8 ~= "" then
					tbl2[#tbl2 + 1] = fn4(k) .. "=" .. fn4(v8)
				end
			end
		end

		if #tbl2 ~= 0 then
			return "?" .. table.concat(tbl2, "&")
		end
		return ""
	end

	local function fn6(arg2, arg3, arg4, arg5)
		if not Http.client() then
			return nil, "no http client available on this executor", 0, nil
		end
		local v = fn3()

		if v ~= "" then
			local tbl2 = { Accept = "application/json" }

			if arg5 then
				local configsApiKey = ConfigSecrets.ConfigsApiKey or ""
				if configsApiKey == "" then
					return nil, "ConfigsApiKey not configured (writes disabled)", 0, nil
				end
				tbl2.Authorization = "Bearer " .. configsApiKey
			end

			local json = Http.json
			local tbl3 = { url = v .. arg3, method = arg2, body = arg4, headers = tbl2 }
			local retry = arg2 == "GET"

			if retry then
				retry = tbl
			end

			tbl3.retry = retry or false
			return json(tbl3)
		end

		return nil, "ConfigsApiUrl not configured", 0, nil
	end

	local tbl2 = {
		list = function(arg2)
			local tbl2 = arg2 or {}

			local v = fn5({
				game = tbl2.game,
				discord_id = tbl2.discord_id,
				viewer_discord_id = tbl2.viewer_discord_id,
				sort = tbl2.sort,
				limit = tbl2.limit,
			})

			return fn6("GET", "/api/configs" .. v, nil, false)
		end,
		get = function(arg2, arg3)
			if arg2 ~= nil then
				if arg2 ~= "" then
					local v = fn5({ viewer_discord_id = arg3 })
					return fn6("GET", "/api/configs/" .. fn4(tostring(arg2)) .. v, nil, false)
				end
			end

			return nil, "missing id", 0, nil
		end,
		create = function(arg2)
			return fn6("POST", "/api/configs", arg2, true)
		end,
		update = function(arg2, arg3)
			if arg2 ~= nil then
				if arg2 ~= "" then
					return fn6("PATCH", "/api/configs/" .. fn4(tostring(arg2)), arg3, true)
				end
			end

			return nil, "missing id", 0, nil
		end,
		mintDeleteLink = function(arg2, arg3, arg4)
			if arg2 ~= nil then
				if arg2 ~= "" then
					return fn6("POST", "/api/configs/" .. fn4(tostring(arg2)) .. "/delete-link", { discord_id = arg3, ttl_hours = arg4 or 720 }, true)
				end
			end

			return nil, "missing id", 0, nil
		end,
		delete = function(arg2, arg3)
			if arg2 ~= nil then
				if arg2 ~= "" then
					return fn6("DELETE", "/api/configs/" .. fn4(tostring(arg2)), { discord_id = arg3 }, true)
				end
			end

			return nil, "missing id", 0, nil
		end,
		vote = function(arg2, arg3)
			if arg2 ~= nil then
				if arg2 ~= "" then
					return fn6("POST", "/api/configs/" .. fn4(tostring(arg2)) .. "/vote", { discord_id = arg3 }, true)
				end
			end

			return nil, "missing id", 0, nil
		end,
		unvote = function(arg2, arg3)
			if arg2 ~= nil then
				if arg2 ~= "" then
					return fn6("DELETE", "/api/configs/" .. fn4(tostring(arg2)) .. "/vote", { discord_id = arg3 }, true)
				end
			end

			return nil, "missing id", 0, nil
		end,
		canWrite = function()
			local configsApiKey = ConfigSecrets.ConfigsApiKey
			local flag = type(configsApiKey) == "string"

			if flag then
				flag = configsApiKey ~= ""
			end

			return flag
		end,
	}

	return tbl2
end)

v4("UI/Build", function()
	local tbl = {
		New = function(arg, instance, arg2)
			local instance2 = Instance.new(arg)

			if type(instance) == "table" then
				local parent = instance.Parent
				local v = table.pack(pairs(instance))
				local v5, v6, v7

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					v6 = v[2]
					v7 = v[3]
				else
					v5 = nil
					v6 = nil
					v7 = nil
				end

				for k, v8 in v5, v6, v7 do
					if k ~= "Parent" then
						instance2[k] = v8
					end
				end

				if parent then
					instance2.Parent = parent
				end
			end

			if type(arg2) == "table" then
				local v = table.pack(ipairs(arg2))
				local v5, v6, v7

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					v6 = v[2]
					v7 = v[3]
				else
					v5 = nil
					v6 = nil
					v7 = nil
				end

				for _, instance3 in v5, v6, v7 do
					if typeof(instance3) == "Instance" then
						instance3.Parent = instance2
					end
				end
			end

			return instance2
		end,
		Round = function(parent, arg, color)
			local uiCorner = Instance.new("UICorner")
			uiCorner.CornerRadius = UDim.new(0, arg or 6)
			uiCorner.Parent = parent

			if color then
				local uiStroke = Instance.new("UIStroke")
				uiStroke.Thickness = 1
				uiStroke.Color = color
				uiStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				uiStroke.Parent = parent
			end
		end,
		Pad = function(parent, arg)
			local uiPadding = Instance.new("UIPadding")
			uiPadding.PaddingLeft = UDim.new(0, arg)
			uiPadding.PaddingRight = UDim.new(0, arg)
			uiPadding.PaddingTop = UDim.new(0, arg)
			uiPadding.PaddingBottom = UDim.new(0, arg)
			uiPadding.Parent = parent
			return uiPadding
		end,
		Hoverable = function(guiObject, backgroundColor3, backgroundColor32)
			local connections = {}
			guiObject.BackgroundColor3 = backgroundColor3
			local n = #connections + 1

			local function onMouseEnter()
				guiObject.BackgroundColor3 = backgroundColor32
			end

			connections[n] = guiObject.MouseEnter:Connect(onMouseEnter)

			connections[#connections + 1] = guiObject.MouseLeave:Connect(function()
				guiObject.BackgroundColor3 = backgroundColor3
			end)

			return connections
		end,
	}

	return tbl
end)

v4("Features/Configs/Ui/Submit", function(arg)
	local Build = arg("UI/Build")
	local Filter = arg("Features/Configs/Filter")
	local Jobs_ = arg("Utility/Jobs")
	local Log = arg("Utility/Log")
	local tr = arg("Features/Configs/Tr").tr
	local new = Build.New
	local round = Build.Round
	local pad = Build.Pad
	local hoverable = Build.Hoverable

	return function(arg2, arg3)
		local api = arg3.Api
		local storage = arg3.Storage
		local library = arg3.Library
		local theme = arg3.theme
		local Frame = new("Frame", { Name = "SubmitRoot", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Parent = arg2 })
		pad(Frame, 14)

		local Frame2 = new("Frame", {
			Name = "Left",
			Size = UDim2.new(0.4, -8, 1, 0),
			BackgroundColor3 = theme.Row,
			BorderSizePixel = 0,
			Parent = Frame,
		})

		round(Frame2, 8, theme.Outline)
