v4("Features/Configs/Filter", function()
	local tbl = {}

	local tbl2 = {
		{ 110, 105, 103, 103, 101, 114 },
		{ 110, 105, 103, 103, 97 },
		{ 102, 97, 103, 103, 111, 116 },
		{ 114, 101, 116, 97, 114, 100 },
		{ 107, 105, 107, 101 },
		{ 99, 104, 105, 110, 107 },
		{ 116, 114, 97, 110, 110, 121 },
		{ 99, 111, 111, 110 },
		{ 103, 111, 111, 107 },
	}

	local tbl3 = {}
	local unpack_ = table.unpack or unpack
	local v = table.pack(ipairs(tbl2))
	local v5, v6, v7

	if select("#", table.unpack(v, 1, v.n)) ~= 0 then
		v5 = v[1]
		v6 = v[2]
		v7 = v[3]
	else
		v5 = nil
		v6 = nil
		v7 = nil
	end

	for _, v8 in v5, v6, v7 do
		tbl3[#tbl3 + 1] = string.char(unpack_(v8))
	end

	local function fn2(arg)
		if type(arg) == "string" then
			if arg ~= "" then
				local str = arg:lower():gsub("[!|1]", "i"):gsub("0", "o"):gsub("3", "e"):gsub("[4@]", "a"):gsub("[5%$]", "s"):gsub("7", "t")
				return (str:gsub("[^a-z]", ""))
			end
		end

		return ""
	end

	tbl.check = function(arg)
		local v8 = fn2(arg)
		if v8 == "" then
			return true
		end
		local v9 = table.pack(ipairs(tbl3))
		local v10, v11, v12

		if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
			v10 = v9[1]
			v11 = v9[2]
			v12 = v9[3]
		else
			v10 = nil
			v11 = nil
			v12 = nil
		end

		for _, v13 in v10, v11, v12 do
			if v8:find(v13, 1, true) then
				return false, "Submission contains disallowed language. Please remove slurs and try again."
			end
		end

		return true
	end

	tbl.checkSubmission = function(arg, arg2)
		local v8 = table.pack(tbl.check(arg))
		local v9, v10

		if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
			v9 = v8[1]
			v10 = v8[2]
		else
			v9 = nil
			v10 = nil
		end

		if v9 then
			return tbl.check(arg2)
		end
		return false, v10
	end

	return tbl
end)

