				if not hasVoted4 then
					hasVoted4 = viewerDiscordId

					if hasVoted4 then
						hasVoted4 = theme.Background
					end

					hasVoted4 = hasVoted4 or theme.Row
				end

				parent.BackgroundColor3 = hasVoted4
				local hasVoted5 = hasVoted3

				if hasVoted5 then
					hasVoted5 = Color3.new(1, 1, 1)
				end

				if not hasVoted5 then
					hasVoted5 = viewerDiscordId

					if hasVoted5 then
						hasVoted5 = theme.Text
					end

					hasVoted5 = hasVoted5 or theme.TextMuted
				end

				guiObject.TextColor3 = hasVoted5
				TextLabel3.TextColor3 = Color3.new(1, 1, 1)
				guiObject.Text = tostring(voteCount)
			end

			parent.Activated:Connect(function()
				if viewerDiscordId then
					local hasVoted3 = item.has_voted == true
					local voteCount = tonumber(item.vote_count) or 0
					local hasVoted4 = not hasVoted3
					local max = math.max
					local n7 = 0
					local hasVoted5 = hasVoted4

					if hasVoted5 then
						hasVoted5 = 1
					end

					local voteCount2 = max(n7, voteCount + (hasVoted5 or -1))
					item.has_voted = hasVoted4
					item.vote_count = voteCount2
					fn6(hasVoted4, voteCount2)

					task.spawn(function()
						local n = arg3.viewerDiscordId
						local C, P

						if hasVoted4 then
							C, P = api.vote(item.id, n)
						else
							C, P = api.unvote(item.id, n)
						end

						if not C then
							item.has_voted = hasVoted3
							item.vote_count = voteCount
							fn6(hasVoted3, voteCount)
							library:Notify(string.format(tr("Vote failed: %s"), tostring(P)), 4)
						end
					end)

					return
				end

				if api.canWrite() then
					library:Notify(tr("Link your Discord on the Luarmor dashboard to vote"), 4)
				else
					library:Notify(tr("Voting is disabled in this build"), 3)
				end
			end)

			local function fn7()
				local saveManager = arg3.SaveManager
				if not saveManager then
					return
				end

				if not saveManager.Library then
					return
				end

				if saveManager.Library.Options then
					if saveManager.Library.Options.SaveManager_ConfigList then
						pcall(function()
							saveManager.Library.Options.SaveManager_ConfigList:SetValues(saveManager[nil --[[ constant not decoded ]]](saveManager))
						end)
					end
				end
			end

			TextButton3.Activated:Connect(function()
				if storage.exists(item.name) then
					TextButton3.Text = "..."
					local v = table.pack(storage.deleteLocal(item.name))
					local v5, v6

					if select("#", table.unpack(v, 1, v.n)) ~= 0 then
						v5 = v[1]
						v6 = v[2]
					else
						v5 = nil
						v6 = nil
					end

					if v5 then
						library:Notify(string.format(tr("Deleted local %q — you can re-download now."), item.name), 4)
						fn7()
						fn5(false)
						return
					end

					library:Notify(string.format(tr("Delete failed: %s"), tostring(v6)), 4)
					fn5(true)
					return
				end

				TextButton3.AutoButtonColor = false
				TextButton3.Text = "..."

				task.spawn(function()
					local n, P = api.get(item.id)

					if not n then
						library:Notify(string.format(tr("Download failed: %s"), tostring(P)), 4)
						fn5(false)
						return
					end

					local z = n.data

					if (z == nil) and (type(n.config) == "table") then
						z = n.config.data
					end

					if (z == nil) and (type(n.payload) ~= "nil") then
						z = n.payload
					end

					if type(z) == "string" then
						local P = Services.HttpService
						local p, b = pcall(P.JSONDecode, P, z)

						if p then
							z = b
						end
					end

					if z == nil then
						local p = {}

						for P in pairs(n) do
							p[#p + 1] = tostring(P)
						end

						Log.warn("[Cerberus.Configs] /api/configs/" .. (tostring(item.id) .. (" \226\128\148 no recognized data field. keys=[" .. (table.concat(p, ", ") .. "]"))))
						library:Notify(string.format(tr("Download failed: server returned no data field (keys: %s)"), table.concat(p, ", ")), 8)
						fn5(false)
						return
					end

					if storage.exists(item.name) then
						library:Notify(string.format(tr("You already have a config named %q \226\128\148 delete the local copy first."), item.name), 6)
						fn5(true)
						return
					end

					local n, p = storage.write(item.name, z)

					if not n then
						library:Notify(string.format(tr("Save failed: %s"), tostring(p)), 4)
						fn5(false)
						return
					end

					library:Notify(string.format(tr("Saved %q \226\128\148 visible in Configurations"), item.name), 4)
					fn7()
					fn5(true)
				end)
			end)

