		end

		tbl3.Refresh = function(arg4)
			if arg4.loading then
				return
			end
			arg4.loading = true
			fn4()
			TextLabel2.Visible = false
			fn3(tr("Loading…"), false)

			task.spawn(function()
				local n, v = api.list({game = storage.gameName(), viewer_discord_id = arg3.viewerDiscordId, sort = arg4.sort, limit = 100})
				arg4.loading = false
				if not n then
					fn3(string.format(tr("Couldn't load: %s"), tostring(v)), true)
					return
				end
				local p = (n.items or n.configs) or n

				if (type(p) ~= "table") or (#p == 0) then
					fn3("", false)
					TextLabel2.Text = string.format(tr("No configs uploaded for %s yet \226\128\148 be the first!"), storage.gameName())
					TextLabel2.Visible = true
					return
				end

				arg4.items = p

				for n, s in ipairs(p) do
					arg4.rows[s.id] = getFrame(s, n)
				end

				fn3(string.format(tr("%d configs"), #p), false)
			end)
		end

		TextButton.Activated:Connect(function()
			local flag = tbl3.sort == "popular"

			if flag then
				flag = 2
			end

			flag = flag or 1
			tbl3.sort = tbl[flag]
			TextButton.Text = tr("Sort: ") .. tr(tbl2[tbl3.sort])
			tbl3:Refresh()
		end)

		TextButton2.Activated:Connect(function()
			tbl3:Refresh()
		end)

		tbl3.OnShow = function(arg4)
			arg4:Refresh()
		end

		return tbl3
	end
end)

v4("Features/Configs/Ui", function(arg)
	local Scheme = arg("UI/Scheme")
	local Build = arg("UI/Build")
	local Log = arg("Utility/Log")
