					end

					currentCamera2 = currentCamera2 or Vector2.new(0, 0)
					local v5 = table.pack(ipairs(arg3._viewportListeners))
					local v6, v7, v8

					if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
						v6 = v5[1]
						v7 = v5[2]
						v8 = v5[3]
					else
						v6 = nil
						v7 = nil
						v8 = nil
					end

					for _, v9 in v6, v7, v8 do
						pcall(v9, currentCamera2)
					end
				end

				local function fn2()
					local currentCamera = workspace.CurrentCamera
					if currentCamera then
