				arg3._fireViewport = fireViewport

				local Frame2 = new("Frame", {
					Name = "Header",
					Size = UDim2.new(1, 0, 0, 56),
					BackgroundColor3 = v.Background,
					BorderSizePixel = 0,
					Parent = Frame,
				})

				new("Frame", {
