			end
			return Presets.propsFromPreset(Presets.getEntry(v.entries, v.selected))
		end

		fn2 = function()
			v5.apply(fn3(), v.enabled)
		end

		v5.bindLoop({
			getProps = fn3,
			isEnabled = function()
				return v.enabled
			end,
			getNudge = function()
				return v.settings.xNudge or 0, v.settings.yNudge or 0
			end,
		})

		track(references.player.CharacterAdded:Connect(function()
