		local options = arg2.Options
		local window = arg2.Window
		local cfg = arg3.CFG
		local live = arg3.Live
		local saveConfig = arg3.saveConfig
		local applyCurrent = arg3.applyCurrent
		local hexToColor3 = Presets.hexToColor3
		local color3ToHex = Presets.color3ToHex

		local function fn2()
			if not options then
				return nil
			end

			if toggles then
				local cursorType = options.CursorType

				if cursorType then
					cursorType = options.CursorType.Value
				end

				cursorType = cursorType or "crosshair"
				local primaryColor = options.PrimaryColor

				if primaryColor then
					primaryColor = options.PrimaryColor.Value
				end

				primaryColor = primaryColor or Color3.new(1, 1, 1)
				local outlineColor = options.OutlineColor

				if outlineColor then
					outlineColor = options.OutlineColor.Value
				end

				outlineColor = outlineColor or Color3.new(0, 0, 0)
				local outlineEnabled = toggles.OutlineEnabled

				if outlineEnabled then
					outlineEnabled = toggles.OutlineEnabled.Value == true
				end

				outlineEnabled = outlineEnabled or false
				local outlineThick = options.OutlineThick

				if outlineThick then
					outlineThick = options.OutlineThick.Value
				end

				outlineThick = outlineThick or 1

				if cursorType ~= "crosshair" then
					local tbl = { type = "dot", color = primaryColor }
					local dotSize = options.DOT_Size

					if dotSize then
						dotSize = options.DOT_Size.Value
					end

					tbl.size = dotSize or 10
					tbl.outline = outlineEnabled
					tbl.outlineThickness = outlineThick
					tbl.outlineColor = outlineColor
					return tbl
				end

				local tbl = { type = "crosshair", color = primaryColor }
				local chThickness = options.CH_Thickness

				if chThickness then
					chThickness = options.CH_Thickness.Value
				end

				tbl.thickness = chThickness or 2
				local chLength = options.CH_Length

				if chLength then
					chLength = options.CH_Length.Value
				end

				tbl.length = chLength or 18
				local chGap = options.CH_Gap

				if chGap then
					chGap = options.CH_Gap.Value
				end

				tbl.gap = chGap or 8
				local chLineCount = options.CH_LineCount

				if chLineCount then
					chLineCount = options.CH_LineCount.Value
				end

				tbl.lineCount = chLineCount or 4
				local chCenterDot = toggles.CH_CenterDot

				if chCenterDot then
					chCenterDot = toggles.CH_CenterDot.Value == true
				end

				tbl.centerDot = chCenterDot or false
				local chDotSize = options.CH_DotSize

				if chDotSize then
					chDotSize = options.CH_DotSize.Value
				end

				tbl.dotSize = chDotSize or 2
				tbl.outline = outlineEnabled
				tbl.outlineThickness = outlineThick
				tbl.outlineColor = outlineColor
				return tbl
			end

			return nil
		end

		local function fn3()
			local v = fn2()

			if v then
				if v.type ~= "crosshair" then
					return {
						type = "dot",
						props = {
							color = color3ToHex(v.color),
							size = v.size,
							outline = v.outline,
							outlineColor = color3ToHex(v.outlineColor),
							outlineThickness = v.outlineThickness,
						},
					}
				end

				return {
					type = "crosshair",
					props = {
						color = color3ToHex(v.color),
						thickness = v.thickness,
						length = v.length,
						gap = v.gap,
						lineCount = v.lineCount,
						centerDot = v.centerDot,
						dotSize = v.dotSize,
						outline = v.outline,
						outlineColor = color3ToHex(v.outlineColor),
						outlineThickness = v.outlineThickness,
					},
				}
			end

			return nil
		end

		local v = arg2.Tabs.Fun:AddRightGroupbox("Cursor Builder", "mouse-pointer")

		v:AddToggle("CursorEnabled", {
			Text = "Enable Custom Cursor",
			Default = cfg.enabled,
			Callback = function(enableCustomCursor)
				cfg.enabled = enableCustomCursor == true
				saveConfig(cfg)
				applyCurrent()
				local library2 = library
				local notify = library.Notify
				local enableCustomCursor2 = enableCustomCursor

				if enableCustomCursor2 then
					enableCustomCursor2 = "Custom cursor enabled."
				end

				notify(library2, enableCustomCursor2 or "Custom cursor disabled.", 2)
			end,
		})

		v:AddToggle("LiveBuild", {
			Text = "Live Build",
			Tooltip = "Apply changes instantly as you modify the builder options.",
			Default = false,
			Callback = function(liveBuild)
				live.enabled = liveBuild == true
				applyCurrent()
			end,
		})

		local names = Presets.buildNames(cfg.entries)
		local v5 = v
		local addDropdown = v.AddDropdown
		local str = "CursorSelect"
		local tbl = { Text = "Select Preset", Values = names }
		local selected = table.find(names, cfg.selected)

		if selected then
			selected = cfg.selected
		end

		tbl.Default = selected or names[1]

		tbl.Callback = function(selected2)
			if selected2 then
				if Presets.getEntry(cfg.entries, selected2) then
					cfg.selected = selected2
					saveConfig(cfg)

					if not live.enabled then
						applyCurrent()
					end
				end
			end
		end

		local v6 = addDropdown(v5, str, tbl)

		if not table.find(names, cfg.selected) then
			if names[1] then
				cfg.selected = names[1]
				saveConfig(cfg)
				v6:SetValue(cfg.selected)
			end
		end

		v:AddDivider()

		v:AddSlider("XNudge", {
			Text = "X Nudge (px)",
			Default = cfg.settings.xNudge or 0,
			Min = -40,
			Max = 40,
			Rounding = 0,
			Callback = function(xNudge)
				cfg.settings.xNudge = xNudge
				saveConfig(cfg)
			end,
		})

		v:AddSlider("YNudge", {
			Text = "Y Nudge (px)",
			Default = cfg.settings.yNudge or 0,
			Min = -40,
			Max = 40,
			Rounding = 0,
			Callback = function(yNudge)
				cfg.settings.yNudge = yNudge
				saveConfig(cfg)
			end,
		})

		v:AddDivider()

		local function fn4()
			if live.enabled then
				applyCurrent()
			end
		end

		v:AddDropdown("CursorType", { Text = "Type", Values = { "crosshair", "dot" }, Default = "crosshair" })
		v:AddLabel("Primary Color"):AddColorPicker("PrimaryColor", { Default = hexToColor3("#FFFFFF"), Callback = fn4 })
		v:AddToggle("OutlineEnabled", { Text = "Outline", Default = true, Callback = fn4 })
		local v7 = v:AddDependencyBox()
		v7:AddLabel("Outline Color"):AddColorPicker("OutlineColor", { Default = hexToColor3("#000000"), Callback = fn4 })
		v7:AddSlider("OutlineThick", { Text = "Outline Thickness", Default = 1, Min = 0, Max = 6, Rounding = 0, Callback = fn4 })
		v7:SetupDependencies({ { toggles.OutlineEnabled, true } })

		v:AddSlider("CH_LineCount", {
			Text = "Number of Lines",
			Tooltip = "Can be a little buggy, to fix any issues in alignment just update the gap.",
			Default = 4,
			Min = 2,
			Max = 24,
			Rounding = 0,
			Callback = fn4,
		})

		v:AddSlider("CH_Thickness", { Text = "Line Thickness", Default = 2, Min = 1, Max = 12, Rounding = 0, Callback = fn4 })
		v:AddSlider("CH_Length", { Text = "Line Length", Default = 18, Min = 2, Max = 128, Rounding = 0, Callback = fn4 })
		v:AddSlider("CH_Gap", { Text = "Gap", Default = 8, Min = 0, Max = 96, Rounding = 0, Callback = fn4 })
		v:AddToggle("CH_CenterDot", { Text = "Center Dot", Default = false, Callback = fn4 })

		local v8 = v:AddDependencyBox()
		v8:AddSlider("CH_DotSize", { Text = "Center Dot Size", Default = 2, Min = 1, Max = 24, Rounding = 0, Callback = fn4 })
		v8:SetupDependencies({ { toggles.CH_CenterDot, true } })

		v:AddSlider("DOT_Size", { Text = "Dot Size", Default = 10, Min = 1, Max = 128, Rounding = 0, Callback = fn4 })
		v:AddDivider()
		v:AddInput("PresetName", { Text = "Preset Name", Placeholder = "My Crosshair", Finished = false })

		v:AddButton({
			Text = "Save / Update Preset",
			Func = function()
				local selected2 = tostring(options.PresetName.Value or ""):gsub("^%s+", ""):gsub("%s+$", "")

				if selected2 ~= "" then
					local v9 = fn3()

					if v9 then
						local entryIndex = Presets.getEntryIndex(cfg.entries, selected2)
						local tbl2 = { name = selected2, locked = false, type = v9.type, props = v9.props }

						if entryIndex then
							cfg.entries[entryIndex] = tbl2
						else
							table.insert(cfg.entries, tbl2)
						end

						cfg.selected = selected2
						saveConfig(cfg)
						local names2 = Presets.buildNames(cfg.entries)
						v6:SetValues(names2)
						v6:SetValue(selected2)

						if not live.enabled then
							applyCurrent()
						end

						local library2 = library
						local notify = library.Notify
						local entryIndex2 = entryIndex

						if entryIndex2 then
							entryIndex2 = "Preset updated."
						end

						notify(library2, entryIndex2 or "Preset saved.", 2)
						return
					end

					return
				end

				library:Notify("Enter a preset name.", 2)
			end,
		})

		v:AddButton({
			Text = "Remove Selected",
			Func = function()
				local getEntryIndex = Presets.getEntryIndex
				local entries = cfg.entries
				local str2 = v6.Value or ""
				local v9 = table.pack(getEntryIndex(entries, str2))
				local v10, v11

				if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
					v10 = v9[1]
					v11 = v9[2]
				else
					v10 = nil
					v11 = nil
				end

				if v11 then
					if v11.locked then
						return library:Notify("That preset is locked.", 2)
					end
					table.remove(cfg.entries, v10)
					local names2 = Presets.buildNames(cfg.entries)

					if #names2 == 0 then
						local v12 = table.clone(Presets.DEFAULTS)
						local v13 = table.pack(pairs(v12))
						local v14, v15, v16

						if select("#", table.unpack(v13, 1, v13.n)) ~= 0 then
							v14 = v13[1]
							v15 = v13[2]
							v16 = v13[3]
						else
							v14 = nil
							v15 = nil
							v16 = nil
						end

						for k, v17 in v14, v15, v16 do
							cfg[k] = v17
						end

						names2 = Presets.buildNames(cfg.entries)
					end

					cfg.selected = names2[1]
					saveConfig(cfg)
					v6:SetValues(names2)
					v6:SetValue(cfg.selected)

					if not live.enabled then
						applyCurrent()
					end

					library:Notify("Preset removed.", 2)
					return
				end

				return library:Notify("Select a preset first.", 2)
			end,
		})

		local function fn5()
			local v9 = table.clone(Presets.DEFAULTS)
			local v10 = table.pack(pairs(v9))
			local v11, v12, v13

			if select("#", table.unpack(v10, 1, v10.n)) ~= 0 then
				v11 = v10[1]
				v12 = v10[2]
				v13 = v10[3]
			else
				v11 = nil
				v12 = nil
				v13 = nil
			end

			for k, v14 in v11, v12, v13 do
				cfg[k] = v14
			end

			saveConfig(cfg)
			local names2 = Presets.buildNames(cfg.entries)
			v6:SetValues(names2)
			v6:SetValue(cfg.selected)

			if not live.enabled then
				applyCurrent()
			end

			library:Notify("Defaults restored.", 2)
		end

		v:AddButton({
			Text = "Restore Defaults",
			Func = function()
				if window then
					if window.AddDialog then
						window:AddDialog("CursorRestoreDefaultsDialog", {
							Title = "Restore Default Cursors?",
							Description = "This will erase any presets you have made and bring back the built-in ones.",
							AutoDismiss = true,
							OutsideClickDismiss = true,
							FooterButtons = {
								Cancel = {
									Title = "Keep My Presets",
									Variant = "Ghost",
									Order = 1,
									Callback = function()
									end,
								},
								Confirm = { Title = "Restore Defaults", Variant = "Destructive", Order = 2, Callback = fn5 },
							},
						})
					else
						fn5()
					end

					return
				end

				fn5()
			end,
		})

		return { propsFromBuilder = fn2, dropdown = v6 }
	end
end)

v4("Features/Fun/CustomCursor/Presets", function()
	local tbl = {
		color3ToHex = function(arg)
			local r = math.floor(arg.R * 255 + 0.5)
			local g = math.floor(arg.G * 255 + 0.5)
			local b = math.floor(arg.B * 255 + 0.5)
			return string.format("#%02X%02X%02X", r, g, b)
		end,
		hexToColor3 = function(arg)
			local str = tostring(arg or ""):gsub("#", "")

			if #str ~= 3 then
				if #str ~= 6 then
					return Color3.new(1, 1, 1)
				end
				local num = tonumber(str:sub(1, 2), 16)
				local num2 = tonumber(str:sub(3, 4), 16)
				local num3 = tonumber(str:sub(5, 6), 16)
				return Color3.fromRGB(num, num2, num3)
			end

			local num = tonumber(str:sub(1, 1) .. str:sub(1, 1), 16)
			local num2 = tonumber(str:sub(2, 2) .. str:sub(2, 2), 16)
			local num3 = tonumber(str:sub(3, 3) .. str:sub(3, 3), 16)
			return Color3.fromRGB(num, num2, num3)
		end,
	}

	tbl.DEFAULTS = {
		enabled = false,
		selected = "Classic",
		settings = { xNudge = 0, yNudge = 0 },
		entries = {
			{
				name = "Classic",
				locked = false,
				type = "crosshair",
				props = {
					color = "#FFFFFF",
					thickness = 2,
					length = 18,
					gap = 8,
					lineCount = 4,
					centerDot = false,
					dotSize = 2,
					outline = true,
					outlineColor = "#000000",
					outlineThickness = 1,
				},
			},
			{
				name = "Precision",
				locked = false,
				type = "crosshair",
				props = {
					color = "#00FF00",
					thickness = 1,
					length = 12,
					gap = 4,
					lineCount = 4,
					centerDot = true,
					dotSize = 2,
					outline = true,
					outlineColor = "#003300",
					outlineThickness = 1,
				},
			},
			{
				name = "Bold",
				locked = false,
				type = "crosshair",
				props = {
					color = "#FFFFFF",
					thickness = 4,
					length = 24,
					gap = 12,
					lineCount = 4,
					centerDot = true,
					dotSize = 4,
					outline = true,
					outlineColor = "#000000",
					outlineThickness = 2,
				},
			},
			{
				name = "CS:GO Pro",
				locked = false,
				type = "crosshair",
				props = {
					color = "#00FF80",
					thickness = 2,
					length = 16,
					gap = 6,
					lineCount = 4,
					centerDot = true,
					dotSize = 2,
					outline = true,
					outlineColor = "#001A0D",
					outlineThickness = 1,
				},
			},
			{
				name = "Valorant",
				locked = false,
				type = "crosshair",
				props = {
					color = "#FFFFFF",
					thickness = 2,
					length = 10,
					gap = 3,
					lineCount = 4,
					centerDot = false,
					dotSize = 2,
					outline = true,
					outlineColor = "#000000",
					outlineThickness = 1,
				},
			},
			{
				name = "Rainbow Six",
				locked = false,
				type = "crosshair",
				props = {
					color = "#00FFFF",
					thickness = 1,
					length = 14,
					gap = 5,
					lineCount = 4,
					centerDot = true,
					dotSize = 3,
					outline = true,
					outlineColor = "#003333",
					outlineThickness = 1,
				},
			},
			{
				name = "Simple Dot",
				locked = false,
				type = "dot",
				props = {
					color = "#FFFFFF",
					size = 6,
					outline = true,
					outlineColor = "#000000",
					outlineThickness = 1,
				},
			},
			{
				name = "Large Dot",
				locked = false,
				type = "dot",
				props = {
					color = "#FFFFFF",
					size = 12,
					outline = true,
					outlineColor = "#000000",
					outlineThickness = 2,
				},
			},
			{
				name = "Neon Dot",
				locked = false,
				type = "dot",
				props = {
					color = "#00FFFF",
					size = 8,
					outline = true,
					outlineColor = "#003333",
					outlineThickness = 1,
				},
			},
			{
				name = "Sniper",
				locked = false,
				type = "crosshair",
				props = {
					color = "#FF0000",
					thickness = 1,
					length = 32,
					gap = 16,
					lineCount = 4,
					centerDot = true,
					dotSize = 3,
					outline = true,
					outlineColor = "#330000",
					outlineThickness = 1,
				},
			},
			{
				name = "Circle",
				locked = false,
				type = "crosshair",
				props = {
					color = "#FFFF00",
					thickness = 2,
					length = 4,
					gap = 20,
					lineCount = 16,
					centerDot = true,
					dotSize = 2,
					outline = true,
					outlineColor = "#333300",
					outlineThickness = 1,
				},
			},
			{
				name = "Plus",
				locked = false,
				type = "crosshair",
				props = {
					color = "#FF00FF",
					thickness = 3,
					length = 20,
					gap = 0,
					lineCount = 4,
					centerDot = false,
					dotSize = 2,
					outline = true,
