					outlineThickness = 1,
				},
			},
			{
				name = "Tiny Cross",
				locked = false,
				type = "crosshair",
				props = {
					color = "#FFFFFF",
					thickness = 1,
					length = 6,
					gap = 2,
					lineCount = 4,
					centerDot = false,
					dotSize = 2,
					outline = false,
					outlineColor = "#000000",
					outlineThickness = 0,
				},
			},
			{
				name = "T-Shape",
				locked = false,
				type = "crosshair",
				props = {
					color = "#00FF00",
					thickness = 2,
					length = 14,
					gap = 6,
					lineCount = 3,
					centerDot = false,
					dotSize = 2,
					outline = true,
					outlineColor = "#003300",
					outlineThickness = 1,
				},
			},
			{
				name = "Bright Pink",
				locked = false,
				type = "crosshair",
				props = {
					color = "#FF1493",
					thickness = 3,
					length = 18,
					gap = 8,
					lineCount = 4,
					centerDot = true,
					dotSize = 4,
					outline = true,
					outlineColor = "#330011",
					outlineThickness = 2,
				},
			},
			{
				name = "Neon Green",
				locked = false,
				type = "dot",
				props = {
					color = "#39FF14",
					size = 10,
					outline = true,
					outlineColor = "#0D3305",
					outlineThickness = 2,
				},
			},
		},
	}

	tbl.getEntry = function(arg, arg2)
		local v = table.pack(ipairs(arg))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for k, v8 in v5, v6, v7 do
			if v8.name == arg2 then
				return v8, k
			end
		end
	end

	tbl.getEntryIndex = function(arg, arg2)
		local v = table.pack(ipairs(arg))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for k, v8 in v5, v6, v7 do
			if v8.name == arg2 then
				return k, v8
			end
			continue
		end
	end

	tbl.buildNames = function(arg)
		local names = {}
		local v = table.pack(ipairs(arg))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for _, v8 in v5, v6, v7 do
			names[#names + 1] = v8.name
		end

		return names
	end

	tbl.propsFromPreset = function(arg)
		if arg then
			local props = arg.props or {}

			if arg.type ~= "crosshair" then
				return {
					type = "dot",
					color = tbl.hexToColor3(props.color or "#FFFFFF"),
					size = math.max(1, tonumber(props.size) or 10),
					outline = props.outline == true,
					outlineColor = tbl.hexToColor3(props.outlineColor or "#000000"),
					outlineThickness = math.max(0, tonumber(props.outlineThickness) or 0),
				}
			end

			return {
				type = "crosshair",
				color = tbl.hexToColor3(props.color or "#FFFFFF"),
				thickness = math.max(1, tonumber(props.thickness) or 2),
				length = math.max(2, tonumber(props.length) or 18),
				gap = math.max(0, tonumber(props.gap) or 8),
				lineCount = math.clamp(tonumber(props.lineCount) or 4, 2, 24),
				centerDot = props.centerDot == true,
				dotSize = math.max(1, tonumber(props.dotSize) or 2),
				outline = props.outline == true,
				outlineColor = tbl.hexToColor3(props.outlineColor or "#000000"),
				outlineThickness = math.max(0, tonumber(props.outlineThickness) or 0),
			}
		end

		return nil
	end

	return tbl
end)

v4("Features/Fun/CustomCursor/Render", function(arg)
	local Scheduler = arg("Utility/Scheduler")
	local UiHost = arg("UI/UiHost")

	return function(arg2)
		local services = arg2.Services
