			tbl2.alias = {}
			tbl2.plain = {}
			tbl2.dirty = true
		end }
	end
end)

v4("Features/Misc/Spectate", function()
	return function(arg)
		local services = arg.Services
		local tabs = arg.Tabs
		local references = arg.References
		local library = arg.Library
		local track = arg.track
		local player2 = references.player

		if player2 then
			player2 = references.player.UserId
		end

		local function fn2(player)
			local flag = player2 ~= nil

			if flag then
				flag = player.UserId == player2
			end

			return flag
		end

		local Spectate = tabs.Misc:AddLeftGroupbox("Spectate", "view")
		local player3 = nil
		local connections = {}
		local tbl = {}

		local function getDisplayName(displayNames, displayName)
			local displayName2 = displayName
			local n = 1

			while displayNames[displayName2] do
				n += 1
				displayName2 = ("%s (%d)"):format(displayName, n)
			end

			displayNames[displayName2] = true
			return displayName2
		end

		local function getDisplayNames(arg2)
			local tbl2 = {}
			local displayNames = {}
			table.clear(tbl)
			local v = table.pack(ipairs(services.Players:GetPlayers()))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, player in v5, v6, v7 do
				if fn2(player) then
					continue
				end

				if player ~= arg2 then
					local displayName = player.DisplayName

					if displayName then
						displayName = player.DisplayName ~= ""
					end

					if displayName then
						displayName = player.DisplayName
					end

					local displayName2 = getDisplayName(tbl2, displayName or player.Name)
					tbl[displayName2] = player.UserId
					displayNames[#displayNames + 1] = displayName2
				end
			end

			return displayNames
		end

		local function getPlayer(arg2)
			local v = arg2

			if v then
				v = tbl[arg2]
			end

			if not v then
				return nil
			end
			local v5 = table.pack(ipairs(services.Players:GetPlayers()))
			local v6, v7, v8

			if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
				v6 = v5[1]
				v7 = v5[2]
				v8 = v5[3]
			else
				v6 = nil
				v7 = nil
				v8 = nil
			end

			for _, player in v6, v7, v8 do
				if player.UserId == v then
					return player
				end
				continue
			end

			return nil
		end

		local SpectateTarget = Spectate:AddDropdown("SpectateTarget", { Values = {}, Default = nil, Multi = false, Text = "Select Player", Searchable = true })

		Spectate:AddButton({
			Text = "Refresh Players",
			Func = function()
				SpectateTarget:SetValues(getDisplayNames())
			end,
		})

		local SpectateEnabled = Spectate:AddToggle("SpectateEnabled", { Text = "Spectate Player", Default = false })

		local function fn3()
			for i = #connections, 1, -1 do
				local connection = connections[i]

				if connection then
					pcall(function()
						connection:Disconnect()
					end)
				end

				connections[i] = nil
			end

			player3 = nil

			if references.humanoid then
				references.camera.CameraSubject = references.humanoid
			end
		end

		local function fn4(instance)
			if instance then
				local humanoid = instance:FindFirstChildOfClass("Humanoid")

				if humanoid then
					references.camera.CameraSubject = humanoid
				end
			end
		end

		local function fn5(player)
			fn3()
			player3 = player

			if player3 then
				fn4(player3.Character)

				connections[#connections + 1] = player3.CharacterAdded:Connect(function(character)
					task.defer(function()
						local v = nil

						if player3 == player then
							fn4(character)
						end
					end)
				end)

				return
			end
		end

		SpectateEnabled:OnChanged(function()
			if SpectateEnabled.Value then
				local player = getPlayer(SpectateTarget.Value)

				if player then
					fn5(player)
				else
					library:Notify("Select a player to spectate.", 3)
					SpectateEnabled:SetValue(false)
				end
			else
				fn3()
			end
		end)

		SpectateTarget:OnChanged(function(arg2)
			if SpectateEnabled.Value then
				local player = getPlayer(arg2)

				if player then
					fn5(player)
				end
			end
		end)

		track(services.Players.PlayerAdded:Connect(function()
			SpectateTarget:SetValues(getDisplayNames())
		end))

		track(services.Players.PlayerRemoving:Connect(function(player)
			SpectateTarget:SetValues(getDisplayNames(player))

			if player3 == player then
				SpectateEnabled:SetValue(false)
			end
		end))

		SpectateTarget:SetValues(getDisplayNames())

		return { cleanup = function()
			fn3()

			if SpectateEnabled then
				if SpectateEnabled.SetValue then
					SpectateEnabled:SetValue(false)
				end
			end
		end }
	end
end)

v4("Features/Misc/ServerPanel", function(arg)
	local Identity = arg("Utility/Identity")
	local Jobs_ = arg("Utility/Jobs")
	local Place = arg("UI/Place")
	local AutoRejoin = arg("Features/Player/Utils/AutoRejoin")

	local tbl = {
		FILTER_NAMES = { "Lowest Players", "Lowest Ping", "Random" },
		FILTERS = { ["Lowest Players"] = "players", ["Lowest Ping"] = "ping", Random = "random" },
		ANY_REGION = "Any Region",
		REGIONS = { "NA-WEST", "NA-CENTRAL", "NA-EAST", "SA", "EU", "AF", "AS", "OCE" },
		KICK_MIN = 1,
		KICK_MAX = 240,
		KICK_DEFAULT = 30,
	}

	tbl.KICK_GRACE = 60
	tbl.INFO_EVERY = 2
	tbl.PRIVATE_REASON = "auto join private"
	tbl.RESUME_FOR = 600
	tbl.RESUME_SETTLE = 3

	tbl.hopOptions = function(arg2)
		local flag = type(arg2) == "table"

		if flag then
			flag = arg2
		end

		local tbl2 = flag or {}
		local tbl3 = { sort = tbl.FILTERS[tbl2.filter] or "ping", avoidVisited = true }
		local maxPlayers = tonumber(tbl2.maxPlayers)

		if maxPlayers then
			tbl3.maxPlayers = maxPlayers
		end

		local region = tbl2.region
		local maxPing

		if type(region) ~= "string" then
			maxPing = tonumber(tbl2.maxPing)

			if maxPing then
				tbl3.maxPing = maxPing
			end
		elseif region ~= "" then
			if region == tbl.ANY_REGION then
				maxPing = tonumber(tbl2.maxPing)

				if maxPing then
					tbl3.maxPing = maxPing
				end
			else
				tbl3.region = region
			end
		else
			maxPing = tonumber(tbl2.maxPing)

			if maxPing then
				tbl3.maxPing = maxPing
			end
		end

		return tbl3
	end

	tbl.duration = function(arg2)
		local n = math.max(0, math.floor(tonumber(arg2) or 0))
		local n7 = math.floor(n / 86400)
		local n8 = math.floor(n % 86400 / 3600)
		local n9 = math.floor(n % 3600 / 60)
		local n10 = n % 60

		if not (n7 > 0) then
			if not (n8 > 0) then
				if not (n9 > 0) then
					return ("%ds"):format(n10)
				end
				return ("%dm %ds"):format(n9, n10)
			end

			return ("%dh %dm"):format(n8, n9)
		end

		return ("%dd %dh"):format(n7, n8)
	end

	tbl.infoText = function(arg2)
		if type(arg2) ~= "table" then
			return "Reading the server..."
		end
		local name = type(arg2.name) == "string"

		if name then
			name = arg2.name
		end

		name = name or "This server"

		if arg2.privateServer then
			name ..= " (private server)"
		end

		if type(arg2.place) == "string" then
			if arg2.place ~= "Ouwland" then
				name ..= " - " .. arg2.place
			end
		end

		local str = "unknown"

		if arg2.pvp ~= true then
			if arg2.pvp == false then
				str = "off"
			end
		else
			str = "on"
		end

		local age = arg2.age

		if age then
			age = tbl.duration(arg2.age)
		end

		age = age or "unknown"

		if arg2.night ~= nil then
			if arg2.phaseLeft then
				local str2 = "%s   %s for %s"
				local format = ("%s   %s for %s").format
				local age2 = age
				local night = arg2.night

				if night then
					night = "Night"
				end

				age = format(str2, age2, night or "Day", tbl.duration(arg2.phaseLeft))
			end
		end

		local str2 = "unknown"

		if arg2.players then
			local str3 = "%d/%s"
			local format = ("%d/%s").format
			local players = arg2.players
			local maxPlayers = arg2.maxPlayers

			if maxPlayers then
				maxPlayers = tostring(arg2.maxPlayers)
			end

			str2 = format(str3, players, maxPlayers or "?")
		end

		local ping = arg2.ping

		if ping then
			ping = ("%d ms"):format(arg2.ping)
		end

		ping = ping or "unknown"
		local concat = table.concat
		local tbl2 = {}
		local name2 = name
		local str3 = "Region: %s   PvP: %s"
		local format = ("Region: %s   PvP: %s").format
		local region = arg2.region or "unknown"

		do
			local values = table.pack(name2, format(str3, region, str), ("Running for %s"):format(age), ("Players: %s   Ping: %s"):format(str2, ping))
			table.move(values, 1, values.n, 1, tbl2)
		end

		return concat(tbl2, "\n")
	end

	tbl.clampMinutes = function(arg2)
		local kickDefault = math.floor((tonumber(arg2) or tbl.KICK_DEFAULT) + 0.5)
