		local function fn7(arg3, arg4)
			local api = getApi()
			local v5 = nil

			if api then
				if type(api.explain) == "function" then
					local v6 = table.pack(pcall(api.explain, arg3))
					local v7, v8, v9

					if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
						v7 = v6[1]
