				local D = references.humanoidRootPart
				local Z = "--"

				if K then
					Z = string.format("%d / %d", math.floor(K.Health + 0.5), math.floor(K.MaxHealth + 0.5))
				end

				fn15("fps", string.format("%d", math.floor(tbl2.fpsSmooth + 0.5)))
				fn15("framems", string.format("%.1f ms", tbl2.frameMs))
				fn15("ping", (P and (math.floor(P + 0.5) .. " ms")) or "--")
				fn15("luamem", (A and string.format("%.1f MB", A / 1024)) or "--")
				fn15("totalmem", (I and string.format("%.1f MB", I)) or "--")
				fn15("netin", (r and string.format("%.1f kbps", r)) or "n/a")
				fn15("netout", (s and string.format("%.1f kbps", s)) or "n/a")
				fn15("health", Z)
				fn15("walkspeed", (K and string.format("%.1f", K.WalkSpeed)) or "--")
				fn15("jumppower", (K and string.format("%.1f", K.JumpPower)) or "--")
				fn15("velocity", (D and string.format("%.1f", D.AssemblyLinearVelocity.Magnitude)) or "--")
				fn15("position", (D and fn16(D.Position)) or "--")
				fn15("fov", (references.camera and string.format("%.1f", references.camera.FieldOfView)) or "--")
				fn15("gravity", tostring(services.Workspace.Gravity))
				fn15("place", tostring(services.Game.PlaceId))
				fn15("job", tostring(services.Game.JobId or "--"))
				fn15("players", tostring(#services.Players:GetPlayers()))
				fn15("toggles", tostring(getCount()))
				fn15("uptime", string.format("%.0f s", os.clock() - now))
				local p = Scheduler.stats()
				local s = 0
				local C = 0

				for K, K in pairs(p.lanes) do
					s = s + K.spentMs
					C = C + K.tasks
				end

				fn15("loops", string.format("%d (%.2f ms%s)", C, s, (p.budgetMs and string.format(", cap %.0f ms", p.budgetMs)) or ""))
				tbl2.lastCostMs = (os.clock() - n) * 1000
				fn15("cerbcost", string.format("%.2f ms", tbl2.lastCostMs))
			end, { name = "PerfDiagnostics", priority = 200 }))
		end

		v:AddToggle("HUD_Enable", {
			Text = "Show FPS + Ping",
			Tooltip = "Can only show up to 60 fps",
			Default = false,
			Callback = function(enabled)
				if enabled then
					fn5()
				else
					fn4()
				end
			end,
		})

		local v5 = v:AddDependencyBox()

		v5:AddSlider("HUD_Scale", {
			Text = "HUD Scale",
			Default = 90,
			Min = 70,
			Max = 150,
			Rounding = 0,
			Suffix = "%",
			Callback = function(hudScale)
				tbl.scale = hudScale / 100

				if tbl.gui then
					if tbl.gui:FindFirstChild("Holder") then
						local holder = tbl.gui.Holder
						holder.Size = UDim2.fromOffset(320 * tbl.scale, 100 * tbl.scale)
						local v6 = table.pack(ipairs(holder:GetDescendants()))
						local v7, v8, v9

						if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
							v7 = v6[1]
							v8 = v6[2]
							v9 = v6[3]
						else
							v7 = nil
							v8 = nil
							v9 = nil
						end

						for _, guiObject in v7, v8, v9 do
							if not guiObject:IsA("TextLabel") then
								continue
							end

							if guiObject.Name ~= "Title" then
								if guiObject.Name == "Value" then
									guiObject.TextSize = 28 * tbl.scale
								end
							else
								guiObject.TextSize = 16 * tbl.scale
							end
						end
					end
				end
			end,
		})

		v5:SetupDependencies({ { toggles.HUD_Enable, true } })

		v:AddToggle("HUD_Diagnostics", {
			Text = "Diagnostics Panel",
			Tooltip = "Pop-out diagnostics with system and Cerberus stats",
			Default = false,
			Callback = function(diagnosticsPanel)
				if diagnosticsPanel then
					fn7()
				else
					fn6()
				end
			end,
		})

		return { cleanup = function()
			fn4()
			fn6()
		end }
	end
end)

v4("Features/Misc/Environment", function(arg)
	local Scheduler = arg("Utility/Scheduler")

	return function(arg2)
		local services = arg2.Services
		local library = arg2.Library
		local toggles = arg2.Toggles
		local track = arg2.track
		local Environment = arg2.Tabs.Misc:AddRightGroupbox("Environment", "trees")
		local customAmbient2 = false
		local color = Color3.fromRGB(128, 128, 128)
		local lighting = services.Lighting

		if lighting then
			lighting = services.Lighting.Ambient
		end

		lighting = lighting or Color3.new()
		local lighting2 = services.Lighting

		if lighting2 then
			lighting2 = services.Lighting.ClockTime
		end

		lighting2 = lighting2 or 12
		local customTimeOfDay2 = false
		local lighting4 = lighting2
		local connection = nil

		local function fn2()
			if services.Lighting then
				local lighting3 = services.Lighting
				local customAmbient = customAmbient2

				if customAmbient then
					customAmbient = color
				end

				lighting3.Ambient = customAmbient or lighting
			end
		end

		Environment:AddToggle("ENV_Ambient", {
			Text = "Custom Ambient",
			Default = false,
			Tooltip = "Choose your own custom ambient color.",
			Callback = function(customAmbient)
				customAmbient2 = customAmbient
				fn2()
			end,
		})

		local v = Environment:AddDependencyBox()

		v:AddLabel("Ambient Color"):AddColorPicker("ENV_AmbientColor", {
			Default = color,
			Title = "Ambient Color",
			Callback = function(ambientColor)
				color = ambientColor

				if customAmbient2 then
					fn2()
				end
			end,
		})

		v:SetupDependencies({ { toggles.ENV_Ambient, true } })

		Environment:AddToggle("ENV_TimeLock", {
			Text = "Custom Time of Day",
			Default = false,
			Callback = function(customTimeOfDay)
				customTimeOfDay2 = customTimeOfDay

				if customTimeOfDay then
					if services.Lighting then
						services.Lighting.ClockTime = lighting4
					end

					if not connection then
						connection = track(Scheduler.render(function()
							if services.Lighting then
								services.Lighting.ClockTime = lighting4
							end
						end, { name = "TimeLock" }))
					end

					library:Notify("Time of Day locked.", 3)
				else
					if connection then
						connection:Disconnect()
						connection = nil
					end

					library:Notify("Time of Day unlocked.", 3)
				end
			end,
		})

		local v5 = Environment:AddDependencyBox()

		v5:AddSlider("ENV_Time", {
			Text = "Time of Day",
			Default = lighting4,
			Min = 0,
			Max = 24,
			Rounding = 2,
			Suffix = "h",
			Callback = function(timeOfDay)
				lighting4 = timeOfDay

				if customTimeOfDay2 then
					if services.Lighting then
						services.Lighting.ClockTime = timeOfDay
					end
				end
			end,
		})

		v5:SetupDependencies({ { toggles.ENV_TimeLock, true } })

		return { cleanup = function()
			if connection then
				connection:Disconnect()
				connection = nil
			end

			if services.Lighting then
				pcall(function()
					services.Lighting.Ambient = lighting

					if customTimeOfDay2 then
						services.Lighting.ClockTime = lighting2
					end
				end)
			end

			customAmbient2 = false
			customTimeOfDay2 = false
		end }
	end
end)

v4("Features/Misc/Console", function(arg)
	local Globals = arg("Utility/Globals")
	local Services = arg("Services")
	local UiHost = arg("UI/UiHost")

	return function(arg2)
		local library = arg2.Library
		local newMaid = arg2.NewMaid
		local Console = arg2.Tabs.Misc:AddRightGroupbox("Console", "code")
		local tbl = nil

		local function fn2()
			local players = Services.Players
			local logService = Services.LogService
			local userInputService = Services.UserInputService
			if Globals.get("__rbx_runtime_console") then
				return
			end
			Globals.set("__rbx_runtime_console", true)
			local newMaid2 = newMaid

			if newMaid2 then
				newMaid2 = newMaid()
			end

			newMaid2 = newMaid2 or nil

			local function getConnection(connection)
				if newMaid2 then
					if connection then
						newMaid2:GiveTask(connection)
					end
				end

				return connection
			end

			local tbl2 = {
				gui = nil,
				minimized = false,
				showLog = true,
				showWarn = true,
				showErr = true,
				buffer = {},
				maxBuffer = 1000,
			}

			local function onActivated()
				if newMaid2 then
					newMaid2:DoCleaning()
				end

				if tbl2.gui then
					tbl2.gui:Destroy()
					tbl2.gui = nil
				end

				tbl = nil
				Globals.unset("__rbx_runtime_console")
			end

			local function fn3(arg3, arg4)
				local str = "Log"

				if arg4 == Enum.MessageType.MessageWarning then
					str = "Warning"
				elseif arg4 == Enum.MessageType.MessageError then
					str = "Error"
				end

				local buffer = tbl2.buffer
				buffer[#buffer + 1] = { msg = tostring(arg3 or ""), type = str }

				if tbl2.maxBuffer < #buffer then
					table.remove(buffer, 1)
				end
			end

			local function fn4()
				local console = Instance.new("ScreenGui")
				console.Name = "Console"
				console.IgnoreGuiInset = true
				console.ResetOnSpawn = false
				console.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
				console.DisplayOrder = 10000
				console.Parent = UiHost.pick() or players.LocalPlayer:WaitForChild("PlayerGui")

				local window = Instance.new("Frame")
				window.Name = "Window"
				window.Size = UDim2.new(0, 560, 0, 300)
				window.Position = UDim2.new(0.5, -280, 0.16, 0)
				window.BackgroundColor3 = Color3.fromRGB(15, 16, 26)
				window.BorderSizePixel = 0
				window.Parent = console
				Instance.new("UICorner", window).CornerRadius = UDim.new(0, 10)
				local uiStroke = Instance.new("UIStroke", window)
				uiStroke.Thickness = 1
				uiStroke.Color = Color3.fromRGB(32, 34, 52)

				local flag = nil
				local position = nil
				local position2 = nil

				getConnection(window.InputBegan:Connect(function(n)
					if n.UserInputType == Enum.UserInputType.MouseButton1 then
						flag = true
						position = n.Position
						position2 = window.Position
					end
				end))

				getConnection(window.InputEnded:Connect(function(n)
					if n.UserInputType == Enum.UserInputType.MouseButton1 then
						flag = false
					end
				end))

				getConnection(userInputService.InputChanged:Connect(function(n)
					if flag and (n.UserInputType == Enum.UserInputType.MouseMovement) then
						local s = n.Position - position
						window.Position = UDim2.new(position2.X.Scale, position2.X.Offset + s.X, position2.Y.Scale, position2.Y.Offset + s.Y)
					end
				end))

				local topbar = Instance.new("Frame")
				topbar.Name = "Topbar"
				topbar.Size = UDim2.new(1, 0, 0, 34)
				topbar.BackgroundColor3 = Color3.fromRGB(21, 22, 34)
				topbar.BorderSizePixel = 0
				topbar.Parent = window
				Instance.new("UICorner", topbar).CornerRadius = UDim.new(0, 10)
				local imageLabel = Instance.new("ImageLabel")
				imageLabel.Size = UDim2.new(0, 22, 0, 22)
