				imageLabel.BackgroundTransparency = 1
				imageLabel.Image = "rbxassetid://136497541793809"
				imageLabel.Parent = topbar

				local textLabel = Instance.new("TextLabel")
				textLabel.BackgroundTransparency = 1
				textLabel.Position = UDim2.new(0, 40, 0, 0)
				textLabel.Size = UDim2.new(1, -120, 1, 0)
				textLabel.TextXAlignment = Enum.TextXAlignment.Left
				textLabel.Font = Enum.Font.GothamMedium
				textLabel.TextSize = 16
				textLabel.TextColor3 = Color3.fromRGB(220, 228, 242)
				textLabel.Text = "Cerberus Console • by @tevilii"
				textLabel.Parent = topbar

				local textButton = Instance.new("TextButton")
				textButton.Size = UDim2.new(0, 34, 0, 24)
				textButton.Position = UDim2.new(1, -80, 0.5, -12)
				textButton.BackgroundColor3 = Color3.fromRGB(28, 46, 44)
				textButton.Text = "—"
				textButton.Font = Enum.Font.Gotham
				textButton.TextSize = 16
				textButton.BorderSizePixel = 0
				textButton.TextColor3 = Color3.fromRGB(200, 240, 230)
				textButton.Parent = topbar
				Instance.new("UICorner", textButton).CornerRadius = UDim.new(0, 6)
				local textButton2 = Instance.new("TextButton")
				textButton2.Size = UDim2.new(0, 24, 0, 24)
				textButton2.Position = UDim2.new(1, -40, 0.5, -12)
				textButton2.BackgroundColor3 = Color3.fromRGB(60, 28, 28)
				textButton2.Text = ""
				textButton2.BorderSizePixel = 0
				textButton2.Parent = topbar
				Instance.new("UICorner", textButton2).CornerRadius = UDim.new(0, 6)
				local frame = Instance.new("Frame", textButton2)
				frame.AnchorPoint = Vector2.new(0.5, 0.5)
				frame.Position = UDim2.new(0.5, 0, 0.5, 0)
				frame.Size = UDim2.new(0, 14, 0, 14)
				frame.BackgroundColor3 = Color3.fromRGB(180, 64, 64)
				Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 3)
				local body = Instance.new("Frame")
				body.Name = "Body"
				body.Size = UDim2.new(1, -12, 1, -46)
				body.Position = UDim2.new(0, 6, 0, 40)
				body.BackgroundColor3 = Color3.fromRGB(13, 14, 22)
				body.BorderSizePixel = 0
				body.Parent = window
				Instance.new("UICorner", body).CornerRadius = UDim.new(0, 8)
				local tools = Instance.new("Frame")
				tools.Name = "Tools"
				tools.Size = UDim2.new(1, -12, 0, 28)
				tools.Position = UDim2.new(0, 6, 0, 6)
				tools.BackgroundTransparency = 1
				tools.Parent = body

				local uiListLayout = Instance.new("UIListLayout", tools)
				uiListLayout.FillDirection = Enum.FillDirection.Horizontal
				uiListLayout.Padding = UDim.new(0, 6)
				uiListLayout.VerticalAlignment = Enum.VerticalAlignment.Center
				uiListLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left

				local function createTextButton(...)
					local text = ...
					local value = select(2, ...)
					local textButton3 = Instance.new("TextButton")
					textButton3.Size = UDim2.new(0, value or 86, 0, 24)
					textButton3.BackgroundColor3 = Color3.fromRGB(32, 33, 49)
					textButton3.Text = text
					textButton3.Font = Enum.Font.Gotham
					textButton3.TextSize = 14
					textButton3.BorderSizePixel = 0
					textButton3.TextColor3 = Color3.fromRGB(220, 255, 230)
					Instance.new("UICorner", textButton3).CornerRadius = UDim.new(0, 6)
					textButton3.Parent = tools
					return textButton3
				end

				local Clear = createTextButton("Clear", 86)
				local Copy = createTextButton("Copy", 86)
				local fn5 = nil

				local function createTextButton2(text, arg3, arg4)
					local textButton3 = Instance.new("TextButton")
					textButton3.Size = UDim2.new(0, 100, 0, 24)
					textButton3.BorderSizePixel = 0
					textButton3.AutoButtonColor = true
					textButton3.Text = ""
					textButton3.TextTransparency = 1
					textButton3.Parent = tools
					Instance.new("UICorner", textButton3).CornerRadius = UDim.new(0, 6)
					local textLabel2 = Instance.new("TextLabel", textButton3)
					textLabel2.BackgroundTransparency = 1
					textLabel2.Size = UDim2.new(1, -18, 1, 0)
					textLabel2.Position = UDim2.new(0, 18, 0, 0)
					textLabel2.Font = Enum.Font.Gotham
					textLabel2.TextXAlignment = Enum.TextXAlignment.Left
					textLabel2.TextSize = 14

					local frame2 = Instance.new("Frame", textButton3)
					frame2.Size = UDim2.new(0, 8, 0, 8)
					frame2.Position = UDim2.new(0, 8, 0.5, -4)
					Instance.new("UICorner", frame2).CornerRadius = UDim.new(1, 0)

					local function fn6()
						local v = arg3()
						local color = v

						if color then
							color = Color3.fromRGB(26, 44, 32)
						end

						textButton3.BackgroundColor3 = color or Color3.fromRGB(25, 26, 32)
						local color2 = v

						if color2 then
							color2 = Color3.fromRGB(0, 220, 120)
						end

						textLabel2.TextColor3 = color2 or Color3.fromRGB(150, 155, 170)
						textLabel2.Text = text
						local color3 = v

						if color3 then
							color3 = Color3.fromRGB(0, 220, 120)
						end

						frame2.BackgroundColor3 = color3 or Color3.fromRGB(95, 100, 115)
					end

					getConnection(textButton3.Activated:Connect(function()
						arg4(not arg3())
						fn6()
						fn5()
					end))

					fn6()
					return textButton3
				end

				local scroll = Instance.new("ScrollingFrame")
				scroll.Name = "Scroll"
				scroll.BackgroundTransparency = 1
				scroll.Position = UDim2.new(0, 6, 0, 40)
				scroll.Size = UDim2.new(1, -12, 1, -46)
				scroll.BorderSizePixel = 0
				scroll.ScrollBarThickness = 6
				scroll.CanvasSize = UDim2.new()
				scroll.AutomaticCanvasSize = Enum.AutomaticSize.None
				scroll.Parent = body

				local uiListLayout2 = Instance.new("UIListLayout", scroll)
				uiListLayout2.FillDirection = Enum.FillDirection.Vertical
				uiListLayout2.SortOrder = Enum.SortOrder.LayoutOrder
				uiListLayout2.Padding = UDim.new(0, 4)

				local function fn6()
					scroll.CanvasSize = UDim2.fromOffset(0, uiListLayout2.AbsoluteContentSize.Y + 8)
					scroll.CanvasPosition = Vector2.new(0, math.max(0, uiListLayout2.AbsoluteContentSize.Y - scroll.AbsoluteSize.Y))
				end

				getConnection(uiListLayout2:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fn6))

				local function getColor(type_)
					if type_ == "Error" then
						return Color3.fromRGB(255, 90, 90)
					end

					if type_ == "Warning" then
						return Color3.fromRGB(255, 210, 100)
					end
					return Color3.fromRGB(210, 215, 230)
				end

				local textLabels = {}

				local function fn7(msg, type_)
					local showLog = type_ == "Log"

					if showLog then
						showLog = tbl2.showLog
					end

					if not showLog then
						showLog = type_ == "Warning"

						if showLog then
							showLog = tbl2.showWarn
						end
					end

					if not showLog then
						showLog = type_ == "Error"

						if showLog then
							showLog = tbl2.showErr
						end
					end

					if not showLog then
						return
					end
					local textLabel2 = Instance.new("TextLabel")
					textLabel2.BackgroundTransparency = 1
					textLabel2.Font = Enum.Font.Code
					textLabel2.TextXAlignment = Enum.TextXAlignment.Left
					textLabel2.TextYAlignment = Enum.TextYAlignment.Top
					textLabel2.TextWrapped = true
					textLabel2.RichText = false
					textLabel2.Size = UDim2.new(1, -8, 0, 0)
					textLabel2.AutomaticSize = Enum.AutomaticSize.Y
					textLabel2.TextSize = 14
					textLabel2.TextColor3 = getColor(type_)
					textLabel2.Text = nil --[[ constant not decoded ]] .. type_ .. nil --[[ constant not decoded ]] .. msg
					textLabel2.Parent = scroll
					textLabels[#textLabels + 1] = textLabel2

					while tbl2.maxBuffer < #textLabels do
						local v = table.remove(textLabels, 1)

						if v then
							v:Destroy()
						end
					end
				end

				fn5 = function()
					for i = 1, #textLabels do
						local textLabel2 = textLabels[i]

						if textLabel2 then
							textLabel2:Destroy()
						end
					end

					table.clear(textLabels)

					for i = 1, #tbl2.buffer do
						local v = tbl2.buffer[i]
						fn7(v.msg, v.type)
					end

					fn6()
				end

				getConnection(Clear.Activated:Connect(function()
					table.clear(tbl2.buffer)
					fn5()
				end))

				getConnection(Copy.Activated:Connect(function()
					local tbl3 = {}

					for i = 1, #tbl2.buffer do
						local v = tbl2.buffer[i]
						local showLog = v.type == "Log"

						if showLog then
							showLog = tbl2.showLog
						end

						if not showLog then
							showLog = v.type == "Warning"

							if showLog then
								showLog = tbl2.showWarn
							end
						end

						if not showLog then
							showLog = v.type == "Error"

							if showLog then
								showLog = tbl2.showErr
							end
						end

						if showLog then
							tbl3[#tbl3 + 1] = nil --[[ constant not decoded ]] .. v.type .. nil --[[ constant not decoded ]] .. v.msg
						end
					end

					local text = table.concat(tbl3, "\n")

					if setclipboard then
						pcall(setclipboard, text)
					elseif toclipboard then
						pcall(toclipboard, text)
					end
				end))

				createTextButton2("Errors", function()
					return tbl2.showErr
				end, function(showErr)
					tbl2.showErr = showErr
				end)

				createTextButton2("Logs", function()
					return tbl2.showLog
				end, function(showLog)
					tbl2.showLog = showLog
				end)

				createTextButton2("Warnings", function()
					return tbl2.showWarn
				end, function(showWarn)
					tbl2.showWarn = showWarn
				end)

				local function fn8(minimized)
					tbl2.minimized = minimized

					if minimized then
						body.Visible = false
						window.Size = UDim2.new(window.Size.X.Scale, window.Size.X.Offset, 0, 34)
					else
						body.Visible = true
						window.Size = UDim2.new(0, 560, 0, 300)
					end
				end

				getConnection(textButton.Activated:Connect(function()
					fn8(not tbl2.minimized)
				end))

				getConnection(textButton2.Activated:Connect(onActivated))

				getConnection(logService.MessageOut:Connect(function(arg3, arg4)
					fn3(arg3, arg4)
					local v = tbl2.buffer[#tbl2.buffer]

					if v then
						fn7(v.msg, v.type)
						fn6()
					end
				end))

				tbl2.gui = console

				if newMaid2 then
					newMaid2:GiveTask(console)
				end

				fn5()
			end

			fn4()
			tbl = { cleanup = onActivated }
		end

		Console:AddButton({
			Text = "Console",
			Func = function()
				library:Notify("Launched console.", 3)
				fn2()
			end,
		})

		return { cleanup = function()
			if tbl then
				tbl.cleanup()
			end
