v4("Utility/Helpers/VMath", function()
	local tbl = {
		distanceSqr3 = function(arg, arg2)
			local n = arg.X - arg2.X
			local n7 = arg.Y - arg2.Y
			local n8 = arg.Z - arg2.Z
