		visualsGroup:AddToggle("NoFog", {
			Text = "No Fog",
			Default = false,
			Tooltip = "Disables fog, atmosphere, clouds, and post-processing effects that obscure vision.",
		})

		local tbl = nil
		local connections = {}
		local flag = false

		local function getConnection(connection)
			connections[#connections + 1] = connection
			return connection
		end

		local function fn2()
			for i = 1, #connections do
				pcall(function()
					connections[i]:Disconnect()
				end)
			end

			connections = {}
		end

		local function fn3()
			flag = true
			services.Lighting.FogEnd = 1e10
			services.Lighting.FogStart = 1e10
			flag = false
		end

		local function fn4(descendant)
			if tbl then
				if not tbl.Atmo[descendant] then
					tbl.Atmo[descendant] = { D = descendant.Density, H = descendant.Haze, G = descendant.Glare }
				end

				descendant.Density = 0
				descendant.Haze = 0
				descendant.Glare = 0
			end
		end

		local function fn5(arg2)
			if tbl then
				if not tbl.Clouds[arg2] then
					tbl.Clouds[arg2] = { Cover = arg2.Cover, Density = arg2.Density }
				end

				arg2.Cover = 0
				arg2.Density = 0
			end
		end

		local function fn6(instance)
			if not instance:IsA("BloomEffect") then
				if not instance:IsA("SunRaysEffect") then
					if not instance:IsA("DepthOfFieldEffect") then
						if not instance:IsA("ColorCorrectionEffect") then
							if not instance:IsA("BlurEffect") then
								return false
							end
						end
					end
				end
			end

			if instance.Enabled then
				instance:SetAttribute("NFWasEnabled", true)
				instance.Enabled = false
			end

			return true
		end

