v4("Features/Visuals/Visuals/MapFade", function(arg)
	local Jobs_ = arg("Utility/Jobs")
	local tbl = { CHUNK = 2000, BUDGET = 0.004, SLICE = 250, DEPTH = 5 }
	local n7 = 0.001

	local function getLocalTransparencyModifier(arg2)
		return arg2.LocalTransparencyModifier
	end

	local function fn2(arg2, localTransparencyModifier)
		arg2.LocalTransparencyModifier = localTransparencyModifier
	end

	tbl.new = function(arg2)
		local workspace = arg2.Services.Workspace
		local track = arg2.track
		local tbl2 = {}
		local tbl3 = {}
		local n8 = 0
		local v5 = nil
		local connection = nil
		local flag = false

		local function getHumanoids()
			return workspace:FindFirstChild("Humanoids")
		end

		local function fn3(n, C)
			if C and n:IsDescendantOf(C) then
				return true
			end
			local C = n.Parent

			for n = 1, tbl.DEPTH do
				if (C == nil) or (C == workspace) then
					return false
				end

				if C:IsA("Model") and (C:FindFirstChild("HumanoidRootPart") or C:FindFirstChildOfClass("Humanoid")) then
					return true
				end
				C = C.Parent
			end

			return false
		end

		local function fn4(n, S, z)
			local k = n:IsA("BasePart")
			if not k and not n:IsA("Decal") then
				return
			end

			if n:IsA("Terrain") then
				return
			end
			local v, P = pcall(getLocalTransparencyModifier, n)
			if not v or (type(P) ~= "number") then
				return
			end

			if S > 0 then
				if k and (n.Transparency >= 1) then
					return
				end

				if math.abs(P - S) < n7 then
					return
				end
			else
				if P == 0 then
					return
				end
				local p = false

				for k in pairs(tbl3) do
					if math.abs(P - k) < n7 then
						p = true
					end
				end

				if not p then
					return
				end
			end

			if fn3(n, z) then
				return
			end
			pcall(fn2, n, S)
		end

		local function fn5(n, s, C, K, A)
			for S = s, C do
				fn4(n[S], K, A)
			end
		end

		local function fn6()
			local n = 0
			local v = table.pack(pairs(tbl2))
			local v6, v7, v8

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v6 = v[1]
				v7 = v[2]
				v8 = v[3]
			else
				v6 = nil
				v7 = nil
				v8 = nil
			end

			for _, v9 in v6, v7, v8 do
				if n < v9 then
					n = v9
				end
			end

			return n
		end

		local function fn7()
			local v = v5
			v5 = nil

			if v then
				v:Cancel()
			end
		end

		local function fn8()
			fn7()

			v5 = track(Jobs_.spawn(function(arg3)
				local descendants = workspace:GetDescendants()
				local humanoids = getHumanoids()
				local n = 1

				while n <= #descendants do
					local now = os.clock()
					local n9 = math.min(n + tbl.CHUNK - 1, #descendants)

					repeat
						local n10 = math.min(n + tbl.SLICE - 1, n9)
						fn5(descendants, n, n10, n8, humanoids)
						n = n10 + 1
						if n9 < n then
							break
						end
					until tbl.BUDGET < os.clock() - now

					if n <= #descendants then
						if arg3:sleep() then
							continue
						end
						return
					end
				end
			end, { name = "MapFade" }))
		end

		local function fn9(arg3)
			if arg3 then
				if connection then
					if not arg3 then
						if connection then
							connection:Disconnect()
							connection = nil
						end
					end
				else
					connection = track(workspace.DescendantAdded:Connect(function(n)
						if n8 > 0 then
							fn4(n, n8, getHumanoids())
						end
					end))
				end
			elseif not arg3 then
				if connection then
					connection:Disconnect()
					connection = nil
				end
			end
		end

		local function fn10()
			local v = fn6()
			if v == n8 then
				return
			end
			n8 = v

			if v > 0 then
				tbl3[v] = true
			end

			fn9(v > 0)
			fn8()
		end

		return {
			isCharacter = fn3,
			set = function(arg3, arg4)
				if flag then
					return
				end

				if type(arg4) ~= "number" then
					tbl2[arg3] = nil
				elseif not (arg4 > 0) then
					tbl2[arg3] = nil
				else
					tbl2[arg3] = math.min(arg4, 1)
				end

				fn10()
			end,
			level = function()
				return n8
			end,
			destroy = function()
				flag = true
				table.clear(tbl2)
				fn7()
				fn9(false)
				n8 = 0
				if next(tbl3) == nil then
					return
				end
				local humanoids = getHumanoids()

				pcall(function()
					local descendants = workspace:GetDescendants()
					fn5(descendants, 1, #descendants, 0, humanoids)
				end)
			end,
		}
	end

	return tbl
end)

