v4("Features/Visuals/Visuals/HidePlayers", function(arg)
	local Scheduler = arg("Utility/Scheduler")

	return function(arg2)
		local services = arg2.Services
		local references = arg2.References
		local toggles = arg2.Toggles
		local track = arg2.track
		local visualsGroup = arg2.VisualsGroup

		visualsGroup:AddToggle("CAM_HideSelf", {
			Text = "Hide My Character",
			Default = false,
			Tooltip = "Makes your own character invisible on your screen. Other players still see you",
		})

		visualsGroup:AddToggle("CAM_HideOthers", {
			Text = "Hide Other Players",
			Default = false,
			Tooltip = "Makes every other player invisible on your screen. Switch on both to hide everyone",
		})

		local tbl = { self = false, others = false }
		local tbl2 = {}
		local connections = {}
		local connection = nil
		local count = 0

		local function getPlayer()
			return references.player or services.Players.LocalPlayer
		end

		local function getPlayer2()
			local player = getPlayer()
			local player2 = player

			if player2 then
				player2 = player.UserId
			end

			return player2 or nil
		end

		local function fn2(player)
			if player.UserId == getPlayer2() then
				return tbl.self
			end
			return tbl.others
		end

		local function onDescendantAdded(descendant)
			if not descendant:IsA("BasePart") then
				if not descendant:IsA("Decal") then
					return
				end
			end

			pcall(function()
				if math.abs(descendant.LocalTransparencyModifier - 1) >= 0.001 then
					descendant.LocalTransparencyModifier = 1
				end
			end)
		end

		local function fn3(instance)
			local v = table.pack(pcall(instance.GetDescendants, instance))
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if not v5 then
				return
			end
			local v7 = table.pack(ipairs(v6))
			local v8, v9, v10

			if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
				v8 = v7[1]
				v9 = v7[2]
				v10 = v7[3]
			else
				v8 = nil
				v9 = nil
				v10 = nil
			end

			for _, v11 in v8, v9, v10 do
				onDescendantAdded(v11)
			end
		end

		local function fn4(instance)
			local v = table.pack(pcall(instance.GetDescendants, instance))
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if not v5 then
				return
			end
			local v7 = table.pack(ipairs(v6))
			local v8, v9, v10

			if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
				v8 = v7[1]
				v9 = v7[2]
				v10 = v7[3]
			else
				v8 = nil
				v9 = nil
				v10 = nil
			end

			for _, instance2 in v8, v9, v10 do
				if not instance2:IsA("BasePart") then
					if not instance2:IsA("Decal") then
						continue
					end
				end

				pcall(function()
					if math.abs(instance2.LocalTransparencyModifier - 1) < 0.001 then
						instance2.LocalTransparencyModifier = 0
					end
				end)
			end
		end

		local function fn5(arg3)
			local connection2 = tbl2[arg3]

			if connection2 then
				tbl2[arg3] = nil
				connection2:Disconnect()
				fn4(arg3)
			end
		end

		local function fn6(instance)
			if tbl2[instance] then
				return fn3(instance)
			end
			tbl2[instance] = instance.DescendantAdded:Connect(onDescendantAdded)
			fn3(instance)
		end

		local function fn7()
			local tbl3 = {}

			local v = table.pack(pcall(function()
				return services.Players:GetPlayers()
			end))

			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				local v7 = table.pack(ipairs(v6))
				local v8, v9, v10

				if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
					v8 = v7[1]
					v9 = v7[2]
					v10 = v7[3]
				else
					v8 = nil
					v9 = nil
					v10 = nil
				end

				for _, player in v8, v9, v10 do
					local character = player.Character
					if not character then
						continue
					end
					tbl3[character] = fn2(player)
					if not tbl3[character] then
						continue
					end
					fn6(character)
				end
			end

			local v7 = table.pack(pairs(tbl2))
			local v8, v9, v10

			if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
				v8 = v7[1]
				v9 = v7[2]
				v10 = v7[3]
			else
				v8 = nil
				v9 = nil
				v10 = nil
			end

			for k in v8, v9, v10 do
				if not tbl3[k] then
					fn5(k)
				end
			end
		end

		local function fn8()
			count += 1
			if count * 0.1 >= 1 then
				count = 0
				return fn7()
			end
			local player = getPlayer()
			local player2 = player

			if player2 then
				player2 = player.Character
			end

			if player2 then
				if tbl2[player2] then
					fn3(player2)
				end
			end
		end

		local function fn9()
			for i = #connections, 1, -1 do
				connections[i]:Disconnect()
				connections[i] = nil
			end

			if connection then
				connection:Disconnect()
				connection = nil
			end
		end

		local function fn10(player)
			connections[#connections + 1] = player.CharacterAdded:Connect(function()
				fn7()
			end)
		end

		local function fn11()
			if connection then
				return
			end

			connections[#connections + 1] = services.Players.PlayerAdded:Connect(function(player)
				fn10(player)
				fn7()
			end)

			connections[#connections + 1] = services.Players.PlayerRemoving:Connect(function()
				fn7()
			end)

			local v = table.pack(pcall(function()
				return services.Players:GetPlayers()
			end))

			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				local v7 = table.pack(ipairs(v6))
				local v8, v9, v10

				if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
					v8 = v7[1]
					v9 = v7[2]
					v10 = v7[3]
				else
					v8 = nil
					v9 = nil
					v10 = nil
				end

				for _, v11 in v8, v9, v10 do
					fn10(v11)
				end
			end

			connection = track(Scheduler.heartbeat(fn8, { name = "HidePlayers", interval = 0.1 }))
		end

		local function fn12()
			tbl.self = toggles.CAM_HideSelf.Value == true
			tbl.others = toggles.CAM_HideOthers.Value == true

			if tbl.self then
				fn11()
			elseif tbl.others then
				fn11()
			end

			fn7()

			if not tbl.self then
				if not tbl.others then
					fn9()
				end
			end
		end

		toggles.CAM_HideSelf:OnChanged(fn12)
		toggles.CAM_HideOthers:OnChanged(fn12)

		return { cleanup = function()
			tbl.self = false
			tbl.others = false
			fn9()
			local v = table.pack(pairs(tbl2))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for k in v5, v6, v7 do
				fn5(k)
				continue
			end
		end }
	end
end)

v4("Features/Visuals/Visuals/HideMap", function()
	return function(arg)
		local services = arg.Services
		local toggles = arg.Toggles
