				terrain.WaterReflectance = tbl.Terrain.WaterReflectance or terrain.WaterReflectance
				terrain.WaterTransparency = tbl.Terrain.WaterTransparency or terrain.WaterTransparency

				if tbl.Terrain.Decoration ~= nil then
					pcall(function()
						terrain.Decoration = tbl.Terrain.Decoration
					end)
				end
			end

			task.defer(function()
				local v8 = table.pack(ipairs(services.Workspace:GetDescendants()))
				local v9, v10, v11

				if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
					v9 = v8[1]
					v10 = v8[2]
					v11 = v8[3]
				else
