v4("Features/Player/Utils/Desync", function()
	return function(arg)
		local library = arg.Library
		local toggles = arg.Toggles

		arg.UtilsGroup:AddToggle("DesyncEnabled", {
			Text = "Desync",
			Default = false,
			Tooltip = "Perform movements and actions client-side without server recognition until re-synced",
		}):AddKeyPicker("DesyncKey", { Default = nil, SyncToggleState = true, Mode = "Toggle" })

		local flag = type(server_desync) == "function"
		local flag2 = type(setfflag) == "function"
		local flag3 = false
		local flag4 = false

		toggles.DesyncEnabled:OnChanged(function()
			if flag4 then
				return
			end
			local value = toggles.DesyncEnabled.Value

			if flag then
				server_desync(value)
				local library2 = library
				local notify = library.Notify
				local str = value

				if str then
					str = "enabled."
				end

				notify(library2, "Server Desync " .. (str or "disabled."), 2)
				return
			end

			if flag2 then
				if value then
					if not flag3 then
						flag3 = true
						flag4 = true
						toggles.DesyncEnabled:SetValue(false)
						flag4 = false

						library:Notify([[FFlag desync uses NextGenReplicatorEnabledWrite4.
It is unstable and potentially detectable.

Click the toggle again if you still want to enable it.]], 6)

						return
					end
				end

				local str = value

				if str then
					str = "true"
				end

				str = str or "false"

				local v = table.pack(pcall(function()
					setfflag("NextGenReplicatorEnabledWrite4", str)
				end))

				local v5, v6

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					v6 = v[2]
				else
					v5 = nil
					v6 = nil
				end

				if v5 then
					if value then
						library:Notify("FFlag Desync enabled (use with caution).", 4)
					else
						library:Notify("FFlag Desync disabled.", 2)
					end

					return
				end

				library:Notify("Failed to apply FFlag desync: " .. tostring(v6), 3)
				flag4 = true
				toggles.DesyncEnabled:SetValue(false)
				flag4 = false
				return
			end

			library:Notify("Desync not available (no server_desync / setfflag in this executor).", 3)

			if value then
				flag4 = true
				toggles.DesyncEnabled:SetValue(false)
				flag4 = false
			end
		end)

		local function fn2()
			if not toggles.DesyncEnabled then
				return
			end

			if toggles.DesyncEnabled.Value == true then
				if flag then
					pcall(server_desync, false)
				elseif flag2 then
					pcall(setfflag, "NextGenReplicatorEnabledWrite4", "false")
				end

				return
			end
		end

		return { cleanup = fn2 }
	end
end)

