	local Speed = arg("Features/Player/Movement/Speed")
	local Jump = arg("Features/Player/Movement/Jump")
	local ClickTp = arg("Features/Player/Movement/ClickTp")
	local ClickWalk = arg("Features/Player/Movement/ClickWalk")
