			local v10 = v.mount(ClickWalk, v5)
			local v11 = v.mount(PositionRewind, v5)

			local tbl = {
				startFlight = v6.startFlight,
				stopFlight = v6.stopFlight,
				startSpeed = v7.startSpeed,
				stopSpeed = v7.stopSpeed,
				startJumpMod = v8.startJumpMod,
				stopJumpMod = v8.stopJumpMod,
				startInfiniteJump = v8.startInfiniteJump,
				stopInfiniteJump = v8.stopInfiniteJump,
				startClickTP = v9.startClickTP,
				stopClickTP = v9.stopClickTP,
				stopClickWalk = v10.stopClickWalk,
				startRewind = v11.startRewind,
				stopRewind = v11.stopRewind,
			}

			v.onUnload(function()
