					tbl.stopClickWalk()
				end

				if tbl.stopFlight then
					tbl.stopFlight()
				end

				if tbl.stopSpeed then
					tbl.stopSpeed(true)
				end

				if tbl.stopJumpMod then
					tbl.stopJumpMod()
				end

				if tbl.stopInfiniteJump then
					tbl.stopInfiniteJump()
				end

				if tbl.stopClickTP then
					tbl.stopClickTP()
				end

				if tbl.stopRewind then
					tbl.stopRewind()
				end
			end)

			v.finalize()
			return tbl
		end
	end
end)

v4("Features/Player/Movement/PositionRewind", function(arg)
	local Scheduler = arg("Utility/Scheduler")
