				if rewindSampleMs then
					rewindSampleMs = options.RewindSampleMs.Value
				end

				rewindSampleMs = rewindSampleMs or 250
				return math.max(0.05, rewindSampleMs / 1000)
			end

			local function getRewindWindow()
				local rewindWindow = options.RewindWindow

				if rewindWindow then
					rewindWindow = options.RewindWindow.Value
				end

				return rewindWindow or 5
			end

			local function fn3()
				for i = 1, 600 do
					v5[i] = nil
				end

				n7 = 1
				count = 0
			end

			local function fn4()
				local humanoidRootPart = references.humanoidRootPart

				if humanoidRootPart then
					local tbl = v5[n7] or {}
					tbl.cf = humanoidRootPart.CFrame
					tbl.t = os.clock()
					v5[n7] = tbl
					n7 = n7 % 600 + 1

