				if connection then
					return
				end
				n8 = 0

				connection = track(Scheduler.heartbeat(function(n)
					if os.clock() < deadline then
						return
					end
					n8 = n8 + n
					if n8 < fn2() then
						return
					end
					n8 = 0
					fn4()
				end, { name = "PositionRewind" }))
			end

			local function fn9()
