				end

				fn3()
			end

			track(references.player.CharacterAdded:Connect(function()
				fn3()
				n8 = 0
			end))

			v:AddToggle("RewindEnabled", {
				Text = "Position Rewind",
				Default = false,
				Tooltip = "Press the rewind key to jump back to where you were a few seconds ago. Useful for falls, punts, and failed parkour.",
			})

			local v6 = v:AddDependencyBox()

			v6:AddLabel({
				Text = "<b>Tip:</b> Enable <b>Replication Lag</b> in Player Utils so the server accepts the rewind instead of snapping you forward.",
				DoesWrap = true,
			})

			local v7 = v6
			local addSlider = v6.AddSlider
			local rewindEnabled2 = "RewindWindow"
			local tbl = { Text = "Rewind Window" }

			while true do
