				tbl.Min = 1
				tbl.Max = 30
				tbl.Rounding = 0
				tbl.Suffix = "s"
				tbl.Tooltip = "How many seconds back the rewind key takes you."
				addSlider(v7, rewindEnabled2, tbl)
				addSlider = v6.AddSlider

				addSlider(v6, "RewindSampleMs", {
					Text = "Sample Interval",
					Default = 250,
					Min = 100,
					Max = 1000,
					Rounding = 0,
					Suffix = "ms",
					Tooltip = "How often your position is recorded. Lower = more precise rewinds at the cost of a tiny bit more work each frame. Default 250ms is plenty.",
				})

				addSlider = Enum
				addSlider = addSlider.KeyCode
				addSlider = addSlider.R

				v6:AddLabel("Rewind Key"):AddKeyPicker("RewindKey", {
					Default = "R",
					SyncToggleState = false,
					Mode = "Toggle",
					Text = "Rewind Now",
					NoUI = false,
					ChangedCallback = function(arg3)
