v4("Features/Player/Movement/JumpRules", function()
	local tbl = { GAME_POWER = 50, GRAVITY = 196.2 }

	tbl.heightFor = function(arg, arg2)
		if type(arg) ~= "number" then
			return 0
		end

		if arg ~= arg then
			return 0
		end

		if arg <= 0 then
			return 0
		end

		if type(arg2) ~= "number" then
			arg2 = tbl.GRAVITY
		elseif arg2 == arg2 then
			if arg2 <= 0 then
				arg2 = tbl.GRAVITY
			end
		else
			arg2 = tbl.GRAVITY
		end

		return arg * arg / (2 * arg2)
	end

	tbl.locked = function(arg)
		local flag = type(arg) == "number"

		if flag then
			flag = arg > 0
		end

		return not flag
	end

	tbl.decide = function(arg)
		if type(arg) ~= "table" then
			return nil
		end

		if not arg.jumpPower then
			if not arg.ignoreLock then
				return nil
			end
		end

		local v = tbl.locked(arg.gamePower)
		local n

		if arg.jumpPower then
			n = tonumber(arg.height) or 0
		else
			n = tbl.heightFor(tonumber(arg.freePower) or tbl.GAME_POWER, arg.gravity)
		end

		if v then
			if not arg.ignoreLock then
				n = 0
			end
		end

		if n < 0 then
			n = 0
		end

		return { useJumpPower = false, jumpHeight = n, locked = v }
	end

	tbl.lifts = function(arg, arg2, arg3)
		local v = arg

		if v then
			v = arg2
		end

		v = v or arg3
		local flag = type(v) == "number"

		if flag then
			flag = v > 0
		end

		return flag
	end

	tbl.hopAgain = function(arg)
		if type(arg) ~= "table" then
			return false
		end
		local flag = arg.on == true

		if flag then
			flag = arg.landed == true
		end

		if flag then
			flag = arg.held == true
		end

		if flag then
			flag = arg.typing ~= true
		end

		if flag then
			flag = arg.canJump ~= false
		end

		if flag then
			flag = arg.lifts ~= false
		end

		return flag
	end

	return tbl
end)

