v4("Features/Combat/KillAura/Words", function()
	local tbl = {
		off = "Off",
		loading = "Waiting for the game to load",
		character = "Waiting for your character",
		weapon = "Equip a weapon or fighting style to attack",
		nothing = "Nothing close enough to hit",
		busy = "Waiting until you can attack again",
		healing = "Paused while you use an item",
		moment = "Paused for a moment",
		itemInHand = "Waiting while you hold a healing item",
		rearmed = "Put your weapon back after healing",
		failed = "Couldn't attack just now, trying again",
	}

	tbl.counter = "Waiting - the closest target is ready to counter"
	tbl.noSkills = "Nothing on your skill bar. Skills come from what you're holding."
	tbl.noEngine = "Skills can't be read right now."
	tbl.unsure = "The game thinks you're moving, so it can't be sure where the swing points"
	tbl.PATHS = { punch = "Punch", direct = "Original" }

	local function clean(arg)
		return (tostring(arg):gsub("[<>]", ""))
	end

	tbl.clean = clean
	local tbl2 = { m1 = "punches", everything = "any attack", skills = "skills" }

	local function fn2(arg)
		return math.max(1, math.ceil(tonumber(arg) or 0))
	end

	tbl.attack = function(arg, arg2)
		return ("Attacking %s (%s)"):format(clean(arg), tbl.PATHS[arg2] or tbl.PATHS.punch)
	end

	tbl.attackDirect = function(arg, arg2)
		return ("Attacking %s. %s"):format(clean(arg), clean(arg2 or "Sending swings directly"))
	end

	tbl.join = function(arg, arg2)
		if type(arg2) == "string" then
			if arg2 ~= "" then
				return arg .. ". " .. arg2
			end
		end

		return arg
	end

	tbl.gate = function(arg)
		return "Can't attack: " .. clean(arg)
	end

	tbl.skill = function(arg, arg2)
		return ("Using %s on %s"):format(clean(arg), clean(arg2))
	end

	tbl.skillHit = function(arg, arg2)
		return ("Used %s on %s (hit)"):format(clean(arg), clean(arg2))
	end

	tbl.refused = function(arg, arg2)
		if type(arg2) == "string" then
			if arg2 ~= "" then
				return ("The game didn't take %s (%s)"):format(clean(arg), clean(arg2))
			end
		end

		return ("The game didn't take %s"):format(clean(arg))
	end

	tbl.finisher = function(arg, arg2)
		if arg then
			return ("Saving skills until it's under %d%%"):format(math.floor(arg + 0.5))
		end
		return ("Saving skills until it's under %d health"):format(math.floor((arg2 or 0) + 0.5))
	end

	tbl.m1sFirst = function(arg)
		local n = math.max(1, math.floor(tonumber(arg) or 1))
		if n ~= 1 then
			return ("%d more M1s before the next skill"):format(n)
		end
		return "1 more M1 before the next skill"
	end

	tbl.noReach = "No ready skill reaches it from here"
	tbl.skillsHeld = "It counters skills right now, so only M1s are used"

	tbl.counterWait = function(arg, arg2, arg3)
		return ("%s is ready to counter %s. Waiting %ds"):format(clean(arg), tbl2[arg2] or "attacks", fn2(arg3))
	end

	tbl.counterWaitOut = function(arg, arg2)
		return ("Waiting until %s stops getting ready to counter %s"):format(clean(arg), tbl2[arg2] or "attacks")
	end

	tbl.counterSkill = function(arg)
		return ("%s is ready to counter punches, so only skills are used"):format(clean(arg))
	end

	tbl.counterTake = function(arg)
		return ("Taking one counter from %s on purpose (you're above half health)"):format(clean(arg))
	end

	tbl.counterSwitch = function(arg)
		return ("Too hurt to take a counter from %s, so looking for another target"):format(clean(arg))
	end

	tbl.counterStuck = function(arg)
