v4("Features/Combat/KillAura/Counter", function()
	local tbl

	tbl = {
		PATIENCE = 4,
		HEALTHY = 0.5,
		SET_ASIDE = 6,
		HITS_M1 = { m1 = true, everything = true },
		HITS_SKILL = { skills = true, everything = true },
		tracker = function()
			local obj = setmetatable({}, { __mode = "k" })

			local tbl2 = {
				age = function(arg, arg2, arg3)
					if arg == nil then
						return 0
					end

					if arg2 == nil then
						obj[arg] = nil
						return 0
					end
					local tbl2 = obj[arg]

					if tbl2 then
						if tbl2.stance ~= arg2 then
							tbl2 = { stance = arg2, at = arg3 }
							obj[arg] = tbl2
						end
					else
						tbl2 = { stance = arg2, at = arg3 }
						obj[arg] = tbl2
					end

					return math.max(0, arg3 - tbl2.at)
				end,
				took = function(arg, at)
					local flag = arg ~= nil

					if flag then
						flag = obj[arg]
					end

					flag = flag or nil

					if flag then
						flag.at = at
					end
				end,
				forget = function(arg)
					if arg ~= nil then
						obj[arg] = nil
					end
				end,
			}

			return tbl2
		end,
		decide = function(arg)
			local stance = arg.stance

			if stance ~= nil then
				if not tbl.HITS_M1[stance] then
					if not tbl.HITS_SKILL[stance] then
						return { act = "hit", m1 = true, skills = true }
					end
				end

				if tbl.HITS_M1[stance] then
					local flag = arg.skills == true

					if flag then
						flag = not tbl.HITS_SKILL[stance]
					end

					local tbl2 = { m1 = false, skills = flag }

					if arg.waitOut ~= true then
						local left = tbl.PATIENCE - (tonumber(arg.age) or 0)

						if not (left > 0) then
							local num = tonumber(arg.health)
							local after = num ~= nil

							if after then
								after = num > tbl.HEALTHY
							end

							if after then
								after = "take"
							end

							tbl2.after = after or "switch"
							local act = flag

							if act then
								act = "skill"
							end

							tbl2.act = act or tbl2.after
							tbl2.m1 = tbl2.act == "take"
							return tbl2
						end

						local act = flag

						if act then
							act = "skill"
						end

						tbl2.act = act or "wait"
						tbl2.left = left
						return tbl2
					end

					local act = flag

					if act then
						act = "skill"
					end

					tbl2.act = act or "wait"
					return tbl2
				end

				return { act = "hit", m1 = true, skills = false }
			end

			return { act = "hit", m1 = true, skills = true }
		end,
	}

	return tbl
end)

