v4("Api/Parry/Anims", function()
	local function getMatch(arg)
		local v = table.pack(pcall(function()
			return arg.AnimationId
		end))

		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
		else
			v5 = nil
			v6 = nil
		end

		if v5 then
			if type(v6) == "string" then
				return v6:match("%d+")
			end
		end

		return nil
	end

	local function fn2(instance)
		local v = table.pack(pcall(instance.IsA, instance, "Animation"))
		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
		else
			v5 = nil
			v6 = nil
		end

		local v7 = v5

		if v7 then
			v7 = v6
		end

		return v7
	end

	local tbl = {
		build = function(instance, instance2, arg)
			local matches = {}

			if instance then
				local v = table.pack(ipairs(instance:GetChildren()))
				local v5, v6, v7

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					v6 = v[2]
					v7 = v[3]
				else
					v5 = nil
					v6 = nil
					v7 = nil
				end

				for _, instance3 in v5, v6, v7 do
					local match = instance3.Name:match("^(.+)_Combat_Anims$")
					if not match then
						continue
					end
					local v8 = table.pack(ipairs(instance3:GetChildren()))
					local v9, v10, v11

					if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
						v9 = v8[1]
						v10 = v8[2]
						v11 = v8[3]
					else
						v9 = nil
						v10 = nil
						v11 = nil
					end

					for _, v12 in v9, v10, v11 do
						local match2 = v12.Name:match("^Swing_(%d+)$")
						local run = v12.Name == "Run_Hit"
						local match3 = match2 or run

						if match3 then
							match3 = fn2(v12)
						end

						if match3 then
							match3 = getMatch(v12)
						end

						match3 = match3 or nil
						if not match3 then
							continue
						end
						local tbl = { kind = "m1", weapon = match }
						local match4 = match2

						if match4 then
							match4 = tonumber(match2)
						end

						tbl.index = match4 or 1
						tbl.run = run
						matches[match3] = tbl
					end
				end
			end

			if not instance2 then
				return matches
			end
			local v = table.pack(ipairs(instance2:GetChildren()))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, instance3 in v5, v6, v7 do
				if instance3.Name == arg.MISC_CATEGORY then
					continue
				end
				local v8 = table.pack(ipairs(instance3:GetChildren()))
				local v9, v10, v11

				if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
					v9 = v8[1]
					v10 = v8[2]
					v11 = v8[3]
				else
					v9 = nil
					v10 = nil
					v11 = nil
				end

				for _, instance4 in v9, v10, v11 do
					if arg.HARMLESS_SKILLS[instance4.Name] then
						continue
					end
					local v12 = table.pack(ipairs(instance4:GetDescendants()))
					local v13, v14, v15

					if select("#", table.unpack(v12, 1, v12.n)) ~= 0 then
						v13 = v12[1]
						v14 = v12[2]
						v15 = v12[3]
					else
						v13 = nil
						v14 = nil
						v15 = nil
					end

					for _, v16 in v13, v14, v15 do
						local match = fn2(v16)

						if match then
							match = getMatch(v16)
						end

						match = match or nil

						if match then
							if not matches[match] then
								matches[match] = { kind = "skill", skill = instance4.Name, category = instance3.Name }
							end
						end
					end
				end
			end

			return matches
		end,
		trackId = function(track)
			local v = table.pack(pcall(function()
				return track.Animation
			end))

			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				if v6 then
					return getMatch(v6)
				end
			end

			return nil
		end,
	}

	return tbl
end)

