v4("Features/Combat/AutoParry/Engine", function(arg)
	local Box = arg("Api/Parry/Box")
	local Rules = arg("Api/Parry/Rules")
	local Timing = arg("Api/Parry/Timing")

	local tbl = { new = function(arg2)
		local parry = arg2.parry
		local cfg = arg2.cfg
		local tbl = {}
		local tbl2 = {}
		local releaseAt = -math.huge
		local n = -math.huge
		local n7 = -math.huge
		local correction = { npc = 0, player = 0 }
		local lastError = { npc = nil, player = nil }
		local stats = { parried = 0, blocked = 0, hit = 0, clear = 0, late = 0, skipped = 0, dodged = 0 }
		local tbl3 = {}

		local function fn2()
