v4("Features/Combat/AutoHeal/Plan", function()
	local tbl = {
		["Health Potion"] = { many = "Health Potions", using = "Drinking a Health Potion", used = "Drank a Health Potion" },
		["Health Elixir"] = { many = "Health Elixirs", using = "Drinking a Health Elixir", used = "Drank a Health Elixir" },
		Bandage = { many = "Bandages", using = "Putting on a Bandage", used = "Put on a Bandage" },
		["Cooked Bear Meat"] = { many = "Cooked Bear Meat", using = "Eating Cooked Bear Meat", used = "Ate Cooked Bear Meat" },
	}

	local function fn2(arg)
		return tbl[arg] or { many = arg, using = "Using " .. arg, used = "Used " .. arg }
	end

	local function fn3(amount, name)
		if amount ~= 1 then
			return tostring(amount) .. " " .. fn2(name).many
		end
		return "1 " .. name
	end

	local tbl2

	tbl2 = {
		OFF = "Off",
		LOADING = "Waiting for the game to load",
		CHARACTER = "Waiting for your character",
		NOTHING_PICKED = "Pick at least one item to use",
		OUT = "You're out of the healing items you picked",
		low = function(arg, arg2, arg3)
			if type(arg) ~= "number" then
				return false
			end

			if type(arg2) ~= "number" then
				return false
			end

			if type(arg3) == "number" then
				if not (arg <= 0) then
					if not (arg2 <= 0) then
						return arg / arg2 * 100 < arg3
					end
				end

				return false
			end

			return false
		end,
		missing = function(arg, arg2, arg3)
			local v = nil
			local v5 = table.pack(ipairs(arg))
			local v6, v7, v8

			if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
				v6 = v5[1]
				v7 = v5[2]
				v8 = v5[3]
			else
				v6 = nil
				v7 = nil
				v8 = nil
			end

			for _, v9 in v6, v7, v8 do
				if not arg2[v9.name] then
					continue
				end

				if v ~= nil then
					if not (v.amount < v9.amount) then
						continue
					end
				end

				v = v9
			end

			if v then
				local flag = v.amount ~= 1

				if flag then
					flag = fn2(v.name).many ~= v.name
				end

				local str = "Put your %s on your hotbar so %s can use %s"
				local format = ("Put your %s on your hotbar so %s can use %s").format
				local many = flag

				if many then
					many = fn2(v.name).many
				end

				many = many or v.name
				local str2 = arg3 or "Auto Heal"
				local str3 = flag

				if str3 then
					str3 = "them"
				end

				return format(str, many, str2, str3 or "it")
			end

			return tbl2.OUT
		end,
		ready = function(arg, arg2, arg3)
			local n = 0
			local count = 0
			local v = nil
			local v5 = table.pack(ipairs(arg))
			local v6, v7, v8

			if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
				v6 = v5[1]
				v7 = v5[2]
				v8 = v5[3]
			else
				v6 = nil
				v7 = nil
				v8 = nil
			end

			for _, v9 in v6, v7, v8 do
				if arg2[v9.name] then
					if v9.slot then
						n += v9.amount
						count += 1
						v = v9
					end
				end
			end

			if count ~= 0 then
				if count ~= 1 then
					return ("Ready: %d healing items on your hotbar"):format(n)
				end
				return ("Ready: %s on your hotbar"):format(fn3(v.amount, v.name))
			end

			return tbl2.missing(arg, arg2, arg3)
		end,
	}

	tbl2.using = function(arg)
		return fn2(arg).using
	end

	tbl2.used = function(arg)
		return ("%s (+%d health). %d left"):format(fn2(arg.name).used, tonumber(arg.heal) or 0, tonumber(arg.left) or 0)
	end

	tbl2.failed = function(arg, arg2)
		if arg == arg2.INTERRUPTED then
			return "You were hit before it finished, so nothing was used. Trying again"
		end

		if arg == arg2.CANT_NOW then
			return "Waiting for a moment you can heal"
		end

		if arg == arg2.NOT_USED then
			return "The game didn't take it. Trying again"
		end

		if arg == arg2.NOT_IN_HAND then
			return "It didn't come out of your hotbar. Trying again"
		end

		if arg == arg2.HAND_BUSY then
			return "Waiting for your hands to be free"
		end

		if arg ~= arg2.BUSY then
			if arg ~= arg2.NO_CHARACTER then
				if arg == arg2.NO_INPUT then
					return "Your executor can't press the game's controls, so healing items can't be used", true
				end
				return "Couldn't heal just now. Trying again"
			end

			return tbl2.CHARACTER
		end

		return "Waiting for your hands to be free"
	end

	return tbl2
end)

