v4("Features/Main/MapReveal", function(arg)
	local Jobs_ = arg("Utility/Jobs")
	local Log = arg("Utility/Log")
	local Mount = arg("Utility/Mount")
	local Place = arg("UI/Place")
	local tbl = { "ComponentsHolder", "Minimap", "FadeMask", "PinsHolder" }
	local tbl2 = { "Regions", "Bosses" }
	local tbl3 = { "Teleports", "Navigation" }

	local tbl4 = { new = function(arg2)
		local ctx = arg2.ctx
		local notify = arg2.notify
		local track = arg2.track
		local tbl4 = { job = nil, holder = nil, sends = {}, warned = {}, lookup = nil }

		local function getApi(arg3)
			local api = ctx.Api
