			if v5 then
				if type(signal.Connect) == "function" then
					local v6 = table.pack(pcall(debug.getupvalues, signal.Connect))
					local v7, v8

					if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
						v7 = v6[1]
						v8 = v6[2]
					else
						v7 = nil
						v8 = nil
					end

					if not v7 then
						return nil
					end

					if type(v8) ~= "table" then
						return nil
					end
					local lookup = nil
					local count = 0
					local v9 = table.pack(pairs(v8))
					local v10, v11, v12

					if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
						v10 = v9[1]
						v11 = v9[2]
						v12 = v9[3]
					else
						v10 = nil
						v11 = nil
						v12 = nil
					end

					for _, v13 in v10, v11, v12 do
						if type(v13) == "function" then
							count += 1
							if debug.info(v13, "n") == "watchOf" then
								lookup = v13
								break
							end
							lookup = v13
						end
					end

					if lookup then
						if debug.info(lookup, "n") ~= "watchOf" then
							if count ~= 1 then
								lookup = nil
							end
						end
					end

					tbl4.lookup = lookup
					return lookup
				end
			end

			return nil
		end

		local function fn2(arg3)
			local lookup = getLookup()
			if not lookup then
				return nil
			end
			local v = table.pack(pcall(lookup, arg3))
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			local signal = v5

			if signal then
				signal = type(v6) == "table"
			end

			if signal then
				signal = v6.Signal
			end

			signal = signal or nil

			if type(signal) == "table" then
				if type(signal.Fire) == "function" then
					return v6
				end
			end

			return nil
		end

		local function getPlayerGui()
			local State = getApi("State")
			if not State then
				return nil
			end
			local v = table.pack(State.player())
			local v5, instance

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				instance = v[2]
			else
				v5 = nil
				instance = nil
			end

			if v5 then
				local playerGui = instance:FindFirstChildOfClass("PlayerGui")
				local v6 = table.pack(ipairs(tbl))
				local v7, v8, v9

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[1]
					v8 = v6[2]
					v9 = v6[3]
				else
					v7 = nil
					v8 = nil
					v9 = nil
				end

				for _, name in v7, v8, v9 do
					local playerGui2 = playerGui

					if playerGui2 then
						playerGui2 = playerGui:FindFirstChild(name)
					end

					playerGui = playerGui2
				end

				return playerGui
			end

			return nil
		end

		local function getNames(instance, name)
			local child = instance:FindFirstChild(name)
			local names = {}
			if not child then
				return names
			end
			local v = table.pack(ipairs(child:GetChildren()))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, instance2 in v5, v6, v7 do
				local label = instance2:FindFirstChild("Label")

				if label then
					if label:IsA("TextLabel") then
						if label.Text == "???" then
							names[#names + 1] = instance2.Name
						end
					end
				end
			end

			return names
		end

		local function fn3(arg3, names)
			local v = fn2(arg3)

			if v then
				if #names == 1 then
					names[2] = names[1]
				end

				local v5 = table.pack(pcall(v.Signal.Fire, v.Signal, names, names))
				local v6, v7

				if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
					v6 = v5[1]
					v7 = v5[2]
				else
					v6 = nil
					v7 = nil
				end

				if not v6 then
					Log.devwarn("MapReveal", "reveal %s failed: %s", arg3, tostring(v7))
				end

				return v6
			end

			return false
		end

		local function fn4()
			local playerGui = getPlayerGui()
			if not playerGui then
				return nil
			end

			if playerGui ~= tbl4.holder then
				tbl4.holder = playerGui
				tbl4.sends = {}
				tbl4.warned = {}
			end

			local n = 0
			local n7 = 0
			local v = table.pack(ipairs(tbl2))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				local names = getNames(playerGui, v8)
				local send = tbl4.sends[v8] or 0
				n += #names
				if not (#names > 0) then
					continue
				end

				if send < 3 then
					tbl4.sends[v8] = send + 1

					if fn3(v8, names) then
						n7 += #names
					end
				elseif not tbl4.warned[v8] then
					tbl4.warned[v8] = true
					Log.devwarn("MapReveal", "%d %s pins stayed hidden after %d reveals", #names, v8, 3)
				end
			end

			return n, n7
		end

		tbl4.start = function()
			if getLookup() then
				tbl4.sends = {}
				tbl4.warned = {}
				local v = table.pack(pcall(fn4))
				local v5, flag, v6

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					flag = v[2]
					v6 = v[3]
				else
					v5 = nil
					flag = nil
					v6 = nil
				end

				if not v5 then
					Log.devwarn("MapReveal", "reveal failed: %s", tostring(flag))
					flag = false
				end

				if flag == nil then
					notify("Your map hasn't loaded yet. The names will show as soon as it does.")
				elseif flag ~= 0 then
					if flag then
						if not (v6 > 0) then
							notify("Reveal Whole Map couldn't change your map this time. Try again in a moment.")
						else
							notify("Every area and boss name now shows on your map. Only you can see this, and it lasts until you rejoin.")
						end
					else
						notify("Reveal Whole Map couldn't change your map this time. Try again in a moment.")
					end
				else
					notify("Every area and boss name is already showing on your map.")
				end

				if tbl4.job then
					return true
				end

				local job = Jobs_.interval(2, function()
					local v7 = table.pack(pcall(fn4))
					local v8, v9

					if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
						v8 = v7[1]
						v9 = v7[2]
					else
						v8 = nil
						v9 = nil
					end

					if not v8 then
						Log.devwarn("MapReveal", "reveal watch failed: %s", tostring(v9))
					end
				end, { name = "MapReveal.watch" })

				if job then
