do
	v4("Features/Main/RemoteInteract/Flip", function()
		local tbl = {
			PAYOUT = 1.5,
			MAX_FLIPS = 5,
			GAP = 2.2,
			STOP = {
				TARGET = "target",
				MOST = "most",
				LOST = "lost",
				BROKE = "broke",
				ERROR = "error",
				CANCELLED = "cancelled",
			},
		}

		tbl.payout = function(arg)
			local flag = type(arg) == "table"

			if flag then
				flag = tonumber(arg.ratio)
			end

			flag = flag or nil

			if flag then
				if flag >= 1.01 then
					if flag <= 10 then
						return flag
					end
				end
			end

			return tbl.PAYOUT
		end

		tbl.winsNeeded = function(arg, arg2, arg3)
			local n = math.floor(tonumber(arg) or 0)
			local n7 = math.floor(tonumber(arg2) or 0)
			local payout = tonumber(arg3) or tbl.PAYOUT
			if n7 <= n then
				return 0
			end

			if n <= 0 then
				return nil
			end

			if not (payout <= 1) then
				local count = 0

				while n < n7 do
					local n8 = math.floor(n * payout)
					if n8 <= n then
						return nil
					end
					n = n8
					count += 1
					if not (count > 60) then
						continue
					end
					return nil
				end

				return count
			end

			return nil
		end

		tbl.after = function(arg, arg2, arg3)
			local n = math.floor(tonumber(arg) or 0)
			local payout = tonumber(arg3)
			local payout2

			while true do
				payout = payout or tbl.PAYOUT
				payout2 = payout
				break
			end

			local n7 = 1
			local max = math.max
			local n8 = 0
			local floor = math.floor
			local n9 = arg2 or 0

			for i = n7, max(n8, floor(n9)) do
				n = math.floor(n * payout2)
			end

			return n
		end

		tbl.chance = function(arg)
			if arg then
				return 0.5 ^ math.max(0, arg)
			end
			return 0
		end

		tbl.keeps = function(arg)
			return 0.5 * (tonumber(arg) or tbl.PAYOUT)
		end

		tbl.outlook = function(arg, arg2, arg3, arg4)
			local n = math.max(1, math.min(tbl.MAX_FLIPS, math.floor(tonumber(arg3) or 1)))
			local payout = tonumber(arg4) or tbl.PAYOUT
			local reach = tbl.winsNeeded(arg, arg2, payout)

			local tbl2 = {
				wen = math.floor(tonumber(arg) or 0),
				target = math.floor(tonumber(arg2) or 0),
				most = n,
				payout = payout,
				wins = reach,
			}

			if reach == nil then
				tbl2.chance = 0
				return tbl2
			end

			if reach <= n then
				tbl2.reach = reach
				tbl2.chance = tbl.chance(reach)
			else
				tbl2.chance = 0
				tbl2.stopsAt = tbl.after(arg, n, payout)
				tbl2.stopChance = tbl.chance(n)
			end

			return tbl2
		end

		tbl.record = function(arg, arg2)
			local tbl2 = {}
			local v = pairs
			local flag = type(arg) == "table"

			if flag then
				flag = arg
			end

			flag = flag or {}
			local v5 = table.pack(v(flag))
			local v6, v7, v8

			if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
				v6 = v5[1]
				v7 = v5[2]
				v8 = v5[3]
			else
