				v7 = nil
				v8 = nil
			end

			for k, v9 in v6, v7, v8 do
				tbl2[k] = v9
			end

			if type(arg2) ~= "table" then
				return tbl2
			end
			local n = tonumber(arg2.before) or 0
			local n7 = tonumber(arg2.after) or 0
			tbl2.flips = (tonumber(tbl2.flips) or 0) + 1
			tbl2.bet = (tonumber(tbl2.bet) or 0) + n
			tbl2.net = (tonumber(tbl2.net) or 0) + (n7 - n)

			if arg2.won then
				tbl2.wins = (tonumber(tbl2.wins) or 0) + 1

				if n > 0 then
					local ratio = n7 / n

					if ratio >= 1.01 then
						if ratio <= 10 then
							tbl2.ratio = ratio
						end
					end
				end
			else
				tbl2.losses = (tonumber(tbl2.losses) or 0) + 1
			end

			return tbl2
		end

		tbl.clean = function(arg)
			if type(arg) ~= "table" then
				return {}
			end
			local tbl2 = {}
			local v = table.pack(ipairs({ "flips", "wins", "losses", "net", "bet", "ratio" }))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				local num = tonumber(arg[v8])

				if num then
					if num == num then
						tbl2[v8] = num
					end
				end
			end

			return tbl2
		end

		tbl.run = function(arg, arg2)
			local economy = arg.Economy
			local errors = economy.Errors or {}
			local n = math.floor(tonumber(arg2.target) or 0)
			local n7 = math.max(1, math.min(tbl.MAX_FLIPS, math.floor(tonumber(arg2.most) or 1)))
			local tbl2 = { flips = 0, wins = 0, start = arg.wen(), target = n, most = n7, results = {} }

			local function fn2(stop, why, detail)
				tbl2.stop = stop
				tbl2.why = why
				tbl2.detail = detail
				tbl2.final = arg.wen()
				return true, tbl2
			end

			local v = nil
			local v5

			while true do
				if n <= arg.wen() then
					return fn2(tbl.STOP.TARGET)
				end

				if n7 <= tbl2.flips then
					return fn2(tbl.STOP.MOST)
				end
				local v6 = table.pack(economy.gambleCheck())
				local v7, v8, v9

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[1]
					v5 = v6[2]
					v8 = v6[3]
					v9 = v6[4]
				else
					v7 = nil
					v5 = nil
					v8 = nil
					v9 = nil
				end

				if not v7 then
					break
				end

				if v5 then
					if v then
						local n8 = tbl.GAP - (arg.now() - v)

						if n8 > 0 then
							if not arg.sleep(n8) then
								return fn2(tbl.STOP.CANCELLED)
							end
						end
					end

					local v10 = table.pack(economy.gamble())
					local v11, v12, v13

					if select("#", table.unpack(v10, 1, v10.n)) ~= 0 then
						v11 = v10[1]
						v12 = v10[2]
						v13 = v10[3]
					else
						v11 = nil
						v12 = nil
						v13 = nil
					end

					v = arg.now()

					if v11 then
						tbl2.flips += 1
						tbl2.results[#tbl2.results + 1] = v12
						arg.record(v12)

						if v12.won then
							tbl2.wins += 1

							if arg.alive then
								if arg.alive() then
									continue
								end
								return fn2(tbl.STOP.CANCELLED)
							end

							continue
						end

						return fn2(tbl.STOP.LOST)
					end

					if tbl2.flips ~= 0 then
						return fn2(tbl.STOP.ERROR, v12, v13)
					end
					return false, v12, v13
				end

				if v8 == errors.BROKE then
					if tbl2.flips ~= 0 then
						return fn2(tbl.STOP.BROKE)
					end
					return false, v8
				end

				if tbl2.flips ~= 0 then
					return fn2(tbl.STOP.ERROR, v8, v9)
				end
				return false, v8, v9
			end

			if tbl2.flips ~= 0 then
				return fn2(tbl.STOP.ERROR, v5)
			end
			return false, v5
		end

		return tbl
	end)
end

do
	v4("Features/Main/RemoteInteract/Errand", function(arg)
		local Jobs_ = arg("Utility/Jobs")
		local tbl = {}
		tbl.TRAVEL = "remote_interact/travel"

		local function getPosition(position, arg2)
			if not arg2 then
				return position
			end
			local vector = Vector3.new(arg2.X - position.X, 0, arg2.Z - position.Z)
			local magnitude = vector.Magnitude
			if magnitude < 0.01 then
				return position
			end
			return position + vector.Unit * math.min(4, magnitude)
		end

		tbl.new = function(arg2)
			local api = arg2.Api
			local notify = arg2.notify
			local v = nil
			local v5 = nil
			local flag = false

			local function getApi(arg3)
				local api2 = api

				if api2 then
