			end

			local function fn2()
				local State = getApi("State")

				if State then
					local v6 = table.pack(State.position())
					local v7, v8

					if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
						v7 = v6[1]
						v8 = v6[2]
					else
						v7 = nil
						v8 = nil
					end

					if v7 then
						if typeof(v8) == "Vector3" then
							return v8
						end
					end

					return nil
				end

				return nil
			end

			local function fn3(arg3)
				local Movement = getApi("Movement")
				if not Movement then
					return "Couldn't teleport there."
				end

				if type(Movement.explain) ~= "function" then
					return "Couldn't teleport there."
				end
				local v6 = table.pack(pcall(Movement.explain, arg3))
				local v7, v8, v9

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[1]
					v8 = v6[2]
					v9 = v6[3]
				else
					v7 = nil
					v8 = nil
					v9 = nil
				end

				if v7 then
					if v8 then
						if type(v9) == "string" then
							return v9
						end
					end
				end

				return "Couldn't teleport there."
			end

			local function fn4(arg3, arg4)
				local Movement = getApi("Movement")
				if not Movement then
					return false, "The game is still loading. Try again in a moment."
				end
				local v6 = table.pack(Movement.moveTo(arg4, { mover = "instant" }))
				local v7, v8

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[1]
					v8 = v6[2]
				else
					v7 = nil
					v8 = nil
				end

				if v7 then
					v5 = v8
					local deadline = os.clock() + 25

					while not v8.done do
						if os.clock() < deadline then
							if arg3:sleep(0.1) then
								continue
							end
						end

						break
					end

					v5 = nil

					if v8.done then
						if v8.ok then
							return true
						end
						return false, fn3(v8.reason)
					end

					pcall(v8.stop)
					return false, "The teleport took too long."
				end

				return false, fn3(v8)
			end

			local function fn5(arg3, arg4)
				local v6 = table.pack(arg4.attempt(arg3))
				local flag2 = not v6[1]

				if flag2 then
					flag2 = v6[2] == arg4.notNear
				end

				if flag2 then
					flag2 = type(v6[3]) == "table"
				end

				if flag2 then
					flag2 = typeof(v6[3].position) == "Vector3"
				end

				if flag2 then
					if arg4.travel then
						local v7 = fn2()

						if v7 then
							local v8 = v6[3]
							notify(("Teleporting to %s..."):format(v8.merchant or arg4.label or "the shop"))
							local v9 = table.pack(fn4(arg3, getPosition(v8.position, v7)))
							local v10, v11

							if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
								v10 = v9[1]
								v11 = v9[2]
							else
								v10 = nil
								v11 = nil
							end

							if not arg3.alive then
								return
							end

							if v10 then
								if arg4.arriveOnly then
									arg4.report(true)
								else
									local deadline = os.clock() + 6
									local v12

									while true do
										v12 = table.pack(arg4.attempt(arg3))
										if v12[1] then
											break
										end

										if v12[2] == arg4.notNear then
											if arg3:sleep(0.25) then
												if not (deadline <= os.clock()) then
													continue
												end
											end
										end

										break
									end

									if not arg3.alive then
										return
									end

									if v12[1] then
										arg4.report(table.unpack(v12, 1, v12.n))
									elseif v12[2] == arg4.notNear then
										arg4.report(false, tbl.TRAVEL, ("You got to %s, but couldn't reach them. They may not have loaded in yet, so try again."):format(v8.merchant or arg4.label or "the shop"))
									else
										arg4.report(table.unpack(v12, 1, v12.n))
									end
								end

								if arg4.comeBack then
									if arg3.alive then
										local v12 = table.pack(fn4(arg3, v7))
										local v13, v14

										if select("#", table.unpack(v12, 1, v12.n)) ~= 0 then
											v13 = v12[1]
											v14 = v12[2]
										else
											v13 = nil
											v14 = nil
										end

										if not v13 then
											if arg3.alive then
												notify(("Couldn't take you back: %s"):format(v14))
											end
										end
									end
								end

								return
							end

							return arg4.report(false, tbl.TRAVEL, v11)
						end

						return arg4.report(false, tbl.TRAVEL, "Your character isn't in the world right now.")
					end
				end

				return arg4.report(table.unpack(v6, 1, v6.n))
			end

			local tbl2 = {
				busy = function()
					return flag
				end,
				run = function(arg3)
					if flag then
						return false
					end
					flag = true

					v = Jobs_.spawn(function(arg4)
						local v6 = table.pack(pcall(fn5, arg4, arg3))
						local v7, v8

						if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
							v7 = v6[1]
							v8 = v6[2]
						else
							v7 = nil
							v8 = nil
						end

						flag = false

						if v == arg4 then
							v = nil
						end

						if not v7 then
							notify("Something went wrong.")
							error(v8, 0)
						end
					end, { name = "RemoteInteract.errand" })

					if v then
						if not v.alive then
							v = nil
						end
					end

					return true
				end,
			}

			tbl2.go = function(arg3, arg4, arg5)
				return tbl2.run({
					label = arg4,
					notNear = "far",
					travel = true,
					arriveOnly = true,
					attempt = function()
						return false, "far", { position = arg3, merchant = arg4 }
					end,
					report = arg5,
				})
			end

			tbl2.kill = function()
				flag = false

				if v then
					v:Cancel()
				end

				v = nil
				local v6 = v5
				v5 = nil

				if v6 then
					if not v6.done then
						pcall(v6.stop)
					end
				end
			end

			return tbl2
		end

		return tbl
	end)
end

v4("Features/Main/RemoteInteract/AutoSell", function(arg)
	local Errand = arg("Features/Main/RemoteInteract/Errand")
	local Words = arg("Features/Main/RemoteInteract/Words")

	local tbl = {
		COINS = { "Coin", "Coin Stack", "Coin Pile", "Coin Pouch" },
		MAX_EACH = 999,
		IDLE = 5,
		RETRY = 30,
		LOCKED_WAIT = 30,
		TRIP_WAIT = 90,
		TRIP_POLL = 0.25,
	}

	tbl.WEN_WAIT = 3
	tbl.WEN_POLL = 0.25
	tbl.WEN_SHARE = 0.5

	local tbl2 = {}
	local v = table.pack(ipairs(tbl.COINS))
	local v5, v6, v7

	if select("#", table.unpack(v, 1, v.n)) ~= 0 then
		v5 = v[1]
		v6 = v[2]
		v7 = v[3]
	else
		v5 = nil
		v6 = nil
		v7 = nil
	end

	for _, v8 in v5, v6, v7 do
		tbl2[v8] = true
	end

	tbl.coins = function(arg2)
		local tbl3 = {}
		local n = 0
		local n7 = 0
		local v8 = ipairs
		local flag = type(arg2) == "table"

		if flag then
			flag = arg2
		end

		flag = flag or {}
		local v9 = table.pack(v8(flag))
		local v10, v11, v12

		if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
			v10 = v9[1]
			v11 = v9[2]
			v12 = v9[3]
		else
			v10 = nil
			v11 = nil
			v12 = nil
		end

		for _, v13 in v10, v11, v12 do
			local flag2 = type(v13) == "table"

			if flag2 then
				flag2 = type(v13.payout) == "table"
			end

			if flag2 then
				flag2 = tonumber(v13.payout.Wen)
			end

			flag2 = flag2 or nil
			local flag3 = type(v13) == "table"

			if flag3 then
				flag3 = math.floor(tonumber(v13.owned) or 0)
			end

			flag3 = flag3 or 0
			if not tbl2[v13.name] then
				continue
			end

			if not flag2 then
				continue
			end

			if flag2 > 0 then
				if flag3 > 0 then
					local n8 = math.min(flag3, tbl.MAX_EACH)
					tbl3[v13.name] = n8
					n += n8 * flag2
					n7 += n8
				end
			end
		end

		if n7 ~= 0 then
			return tbl3, n, n7
		end
		return nil, 0, 0
	end

	tbl.new = function(arg2)
		local economy = arg2.Economy
		local economy2 = economy

		if economy2 then
			economy2 = economy.Errors
		end

		economy2 = economy2 or {}
		local errand = arg2.errand
		local control = arg2.control
		local tbl3 = {}
		local flag = false
		local v8 = nil

		local function fn2(arg3, arg4)
			if v8 == arg3 then
				return
			end
			v8 = arg3
			arg2.notify(arg4)
		end

		local function release()
			if flag then
				flag = false
				errand.kill()
			end

			control.want(false)
		end

		tbl3.release = release

		local function fn3(arg3, arg4)
			return Words.describe(economy, arg3, arg4)
		end

		local function fn4(arg3, arg4, arg5)
			if arg5 <= 0 then
				return true
			end
			local deadline = os.clock() + tbl.WEN_WAIT

			repeat
				local v9 = arg2.wen()

				if v9 then
					if arg4 then
						if arg5 * tbl.WEN_SHARE <= v9 - arg4 then
							return true
						end
					end
				end

				if deadline <= os.clock() then
					return false, v9
				end
			until not arg3:sleep(tbl.WEN_POLL)

			return true
		end

		tbl3.step = function(arg3)
			if arg2.locked() then
				release()
				return tbl.IDLE * 2, "Auto Sell Coins is a premium feature."
			end

			if economy then
				local v9 = table.pack(economy.sellables())
				local v10, v11

				if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
					v10 = v9[1]
					v11 = v9[2]
				else
					v10 = nil
					v11 = nil
				end

				if v10 then
					local v12 = table.pack(tbl.coins(v11))
					local v13, v14

					if select("#", table.unpack(v12, 1, v12.n)) ~= 0 then
						v13 = v12[1]
						v14 = v12[2]
					else
						v13 = nil
						v14 = nil
					end

					local n = math.max(0, math.floor(tonumber(arg2.threshold()) or 0))

					if v13 then
						if v14 < n then
							v8 = nil
							return tbl.IDLE, ("Your coins are worth %s of the %s Wen it waits for."):format(Words.commas(v14), Words.commas(n))
						end
						local v15 = table.pack(economy.sellCheck())
						local v16, v17, v18, v19

						if select("#", table.unpack(v15, 1, v15.n)) ~= 0 then
							v16 = v15[1]
							v17 = v15[2]
							v18 = v15[3]
							v19 = v15[4]
						else
							v16 = nil
							v17 = nil
							v18 = nil
							v19 = nil
						end

						if v16 then
							if not v17 then
								if v18 == economy2.QUEST_LOCKED then
									local quest = type(v19) == "table"

									if quest then
										quest = v19.quest
									end

									local autoSellCoins = ("Ginzo only buys once you finish the quest \"%s\"."):format(quest or "his quest")
									fn2("quest", "Auto Sell Coins: " .. autoSellCoins)
									return tbl.LOCKED_WAIT, autoSellCoins
								end

								if v18 ~= economy2.NOT_NEAR then
									if v18 ~= economy2.DEAD then
										if v18 ~= economy2.NO_CHARACTER then
