								return tbl.IDLE, ("Waiting while %s runs. It sells once nothing else is moving your character."):format(v20)
							end

							if errand.busy() then
								return 1, "Waiting for your last order to finish."
							end
							local v21 = table.pack(control.want(true))
							local v22

							if select("#", table.unpack(v21, 1, v21.n)) ~= 0 then
								v22 = v21[2]
							else
								v22 = nil
							end

							if v22 then
								control.want(false)
								return tbl.IDLE, ("Waiting while %s runs. It sells once nothing else is moving your character."):format(v22)
							end
							local v23 = arg2.wen()
							local v24 = nil

							flag = errand.run({
								label = "Ginzo",
								notNear = economy2.NOT_NEAR,
								travel = arg2.travel(),
								comeBack = true,
								attempt = function()
									return economy.sell(v13)
								end,
								report = function(...)
									v24 = table.pack(...)
								end,
							}) == true

							if flag then
								local deadline = os.clock() + tbl.TRIP_WAIT
								local str = nil
								local exitTo = nil

								while true do
									if not errand.busy() then
										exitTo = 1
										break
									end

									if not control.active() then
										break
									end

									if deadline <= os.clock() then
										exitTo = 1
										break
									elseif arg3:sleep(tbl.TRIP_POLL) then
									else
										exitTo = 2
										break
									end
								end

								if exitTo ~= 1 then
									if exitTo == 2 then
										release()
										return 0, nil
									end
									str = control.blocker() or "another farm"
								end

								if errand.busy() then
									release()
									if str then
										return tbl.IDLE, ("Stopped the trip to Ginzo: %s started."):format(str)
									end
									return tbl.RETRY, "The trip to Ginzo took too long, so it stopped. It will try again."
								end

								flag = false
								control.want(false)

								if v24 then
									if v24[1] then
										local v25 = v24[2]
										local n7 = 0
										local v26 = pairs
										local sold = type(v25) == "table"

										if sold then
											sold = v25.sold
										end

										sold = sold or {}
										local v27 = table.pack(v26(sold))
										local v28, v29, v30

										if select("#", table.unpack(v27, 1, v27.n)) ~= 0 then
											v28 = v27[1]
											v29 = v27[2]
											v30 = v27[3]
										else
											v28 = nil
											v29 = nil
											v30 = nil
										end

										for _, v31 in v28, v29, v30 do
											n7 += v31
										end

										local flag2 = type(v25) == "table"

										if flag2 then
											flag2 = type(v25.received) == "table"
										end

										if flag2 then
											flag2 = tonumber(v25.received.Wen)
										end

										flag2 = flag2 or 0
										local v31 = table.pack(fn4(arg3, v23, flag2))
										local v32, v33

										if select("#", table.unpack(v31, 1, v31.n)) ~= 0 then
											v32 = v31[1]
											v33 = v31[2]
										else
											v32 = nil
											v33 = nil
										end

										if v32 then
											v8 = nil
