		for k, v8 in v5, v6, v7 do
			if type(v8) == "table" then
				tbl4[k] = math.max(0, (tonumber(v8.need) or 0) - (tonumber(v8.have) or 0))
			end
		end

		return price(tbl4)
	end

	tbl3.rod = function(arg)
		if type(arg) ~= "table" then
			return "Checking your rods"
		end

		if arg.best then
			local str = ("Your rod: %s."):format(arg.best)

			if arg.next == "upgrade" then
				if arg.rare then
					local str2 = price(arg.rare.price) or "10,000 Wen and 5 Golden Fish"

					if arg.rare.ready then
						str = ("%s The Rare Fishing Rod (%s) is ready to buy."):format(str, str2)
					else
						local v = fn5(arg.rare.short)

						if v then
							str = ("%s The Rare Fishing Rod costs %s. You still need %s."):format(str, str2, v)
						else
							str = ("%s The Rare Fishing Rod costs %s."):format(str, str2)
						end
					end
				end
			end

			return str
		end

		local basic = arg.basic

		if basic then
			basic = arg.basic.price
		end

		if basic then
			basic = arg.basic.price.Wen
		end

		basic = basic or 3500
		if arg.permit ~= "Done" then
			return ("No rod yet. Get Fishing Rod takes Dock Master Sofen's permit quest (5,000 Wen), then buys the Basic Fishing Rod (%s Wen)."):format(tbl3.number(basic))
		end
		return ("No rod yet. Get Fishing Rod buys the Basic Fishing Rod from Fisherman Jeso for %s Wen."):format(tbl3.number(basic))
	end

	tbl3.rodResult = function(arg, arg2, arg3, arg4, arg5)
		if arg then
			if type(arg2) ~= "table" then
				return "Done."
			end

			if arg2.owned then
				return ("You already have the %s. It's on your hotbar in slot %d."):format(arg2.rod, arg2.slot or 0)
			end
			return ("Got the %s. It's on your hotbar in slot %d."):format(arg2.rod, arg2.slot or 0)
		end

		local flag = type(arg5) == "table"

		if flag then
			flag = arg5
		end

		local tbl4 = flag or {}
		local flag2 = type(arg3) == "table"

		if flag2 then
			flag2 = arg3
		end

		local tbl5 = flag2 or {}

		if arg2 == tbl4.NEED_LEVEL then
			if tbl5.have then
				return ("You need to be level %d for the fishing permit. You're level %d."):format(tbl5.level or 45, tbl5.have)
			end
			return ("You need to be level %d for the fishing permit."):format(tbl5.level or 45)
		end

		if arg2 == tbl4.NEED_WEN then
			if tbl5.permit then
				if tbl5.rod then
					return ("You need %s Wen: %s for the permit and %s for the rod. You have %s."):format(tbl3.number(tbl5.need), tbl3.number(tbl5.permit), tbl3.number(tbl5.rod), tbl3.number(tbl5.have))
				end
			end

			return ("The rod costs %s Wen. You have %s."):format(tbl3.number(tbl5.need), tbl3.number(tbl5.have))
		end

		if arg2 == tbl4.CANT_AFFORD then
			local v = price(tbl5.price)
			local v5 = fn5(tbl5.short)

			if v then
				if v5 then
					return ("The %s costs %s. You still need %s."):format(tbl5.item or "rod", v, v5)
				end
			end
		end

		if arg2 == tbl4.QUEST_IN_WAY then
			if tbl5.quest then
				return ("Finish \"%s\" first. You can only have one fishing quest at a time."):format(tbl5.quest)
			end
		end

		local v = fn3(arg2, tbl5.npc, tbl4)
		if v then
			return v
		end

		if type(arg4) == "function" then
			local v5 = table.pack(arg4(arg2))
			local v6, v7

			if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
				v6 = v5[1]
				v7 = v5[2]
			else
				v6 = nil
				v7 = nil
			end

			if v6 then
				if type(v7) == "string" then
					return v7
				end
			end
		end

		return "That didn't work. Try again in a moment."
	end

	tbl3.questsNone = function(arg)
		if type(arg) ~= "table" then
			return nil
		end

		if arg.why == "level" then
			if arg.level then
				return ("Fish quests start at level %d."):format(arg.level)
			end
		end

		if arg.why == "in_way" then
			if arg.quest then
				return ("Finish \"%s\" first. You can only have one fishing quest at a time."):format(arg.quest)
			end
		end

		if arg.why == "picked" then
			return "None of the fish quests you picked can be taken."
		end

		if arg.why ~= "loading" then
			if arg.why ~= "done" then
				return nil
			end
			return "There's no fish quest you can take right now."
		end

		return "The game's quests haven't loaded yet."
	end

	local function fn6(need)
		if type(need) ~= "table" then
			return nil
		end
		local tbl4 = {}
		local v = table.pack(pairs(need))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for k in v5, v6, v7 do
			tbl4[#tbl4 + 1] = k
		end

		table.sort(tbl4)
		local tbl5 = {}
		local v8 = table.pack(ipairs(tbl4))
		local v9, v10, v11

		if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
			v9 = v8[1]
			v10 = v8[2]
			v11 = v8[3]
		else
			v9 = nil
			v10 = nil
			v11 = nil
		end

		for _, v12 in v9, v10, v11 do
			tbl5[#tbl5 + 1] = ("%d %s"):format(need[v12], v12)
		end

		if #tbl5 ~= 0 then
			if #tbl5 ~= 1 then
				return table.concat(tbl5, ", ", 1, #tbl5 - 1) .. " and " .. tbl5[#tbl5]
			end
			return tbl5[1]
		end

		return nil
	end

	tbl3.quest = function(arg, arg2, arg3, arg4)
		if not arg2 then
			return "Off"
		end

		if type(arg) ~= "table" then
			return "Off"
		end
		local n = tonumber(arg.questsDone) or 0
		local quest = arg.quest
		local line = nil

		if type(quest) == "table" then
			if quest.failed then
				local text = quest.text

				if not text then
					local v = fn3
					local error_ = quest.error
					local npc = type(quest.detail) == "table"

					if npc then
						npc = quest.detail.npc
					end

					text = v(error_, npc or nil, arg4)
				end

				if not text then
					if type(arg3) == "function" then
						local v = table.pack(arg3(quest.error))
						local v5, v6

						if select("#", table.unpack(v, 1, v.n)) ~= 0 then
							v5 = v[1]
							v6 = v[2]
						else
							v5 = nil
							v6 = nil
						end

						if v5 then
							text = v6
						end
					end
				end

				line = ("Couldn't finish a step of %s. %s"):format(tostring(quest.name), text or "It will try again.")
			elseif quest.line then
				line = quest.line
			elseif quest.kind ~= "fish" then
				if quest.kind ~= "accept" then
					if quest.kind ~= "deposit" then
						if quest.kind ~= "deliver" then
							if quest.kind ~= "wait" then
								if quest.kind == "none" then
									line = tbl3.questsNone(quest) or "There's no fish quest you can take right now."

									if arg.running then
										line ..= " Fishing on meanwhile."
									end
								end
							else
								line = ("Waiting for %s to finish"):format(tostring(quest.name))
							end
						else
							line = ("Handing in %s to %s"):format(tostring(quest.name), tostring(quest.npc))
						end
					else
						line = ("Putting the fish in the crate for %s"):format(tostring(quest.name))
					end
				else
					line = ("Taking %s from %s"):format(tostring(quest.name), tostring(quest.giver))
				end
			else
				local v = fn6(quest.need)
				local str = v

				if str then
					str = ("Fishing for %s. Still need %s."):format(tostring(quest.name), v)
				end

				line = str or ("Fishing for %s."):format(tostring(quest.name))
			end
		end

		if not line then
			if not arg.running then
				return "Waiting to start"
			end
			line = "Starting"
		end

		if n > 0 then
			if line:sub(-1) ~= "." then
				line ..= "."
			end

			line = ("%s %s done so far."):format(line, fn4(n, "quest", "quests"))
		end

		return line
	end

	tbl3.spot = function(arg)
		if type(arg) ~= "table" then
			return "Pick a spot"
		end
		local distance = arg.distance

		if distance then
			distance = (" %s studs away."):format(tbl3.number(arg.distance))
		end

		distance = distance or ""

		if arg.kind ~= "npc" then
			if arg.kind ~= "saved" then
				return ("%s: a ledge over the water.%s"):format(arg.name, distance)
			end
			return ("%s: a spot you saved.%s"):format(arg.name, distance)
		end

		return ("%s: the dock by %s.%s"):format(arg.name, tostring(arg.npc), distance)
	end

	tbl3.loose = function(arg)
		if type(arg) ~= "table" then
			return nil
		end

		if #arg ~= 0 then
			local tbl4 = {}
			local v = table.pack(ipairs(arg))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				tbl4[#tbl4 + 1] = tostring(v8.item)
			end

			if #tbl4 ~= 1 then
				return ("Picked up %d loose catches: %s."):format(#tbl4, table.concat(tbl4, ", "))
			end
			return ("Picked up a loose %s."):format(tbl4[1])
		end

		return nil
	end

	return tbl3
end)

v4("Features/Auto/Fishing/Ui", function(arg)
	local Identity = arg("Utility/Identity")
	local Log = arg("Utility/Log")
	local Place = arg("UI/Place")

	local tbl = {
		TABBOX = "Auto Fishing",
		FALLBACK = "Auto",
		SIDE = "Left",
		BEST_ROD = "Best Rod You Own",
		KEEP_BAIT = "Keep What's On",
	}

	local whenTheBaitRunsOuts = { ["Stop Fishing"] = "stop", ["Keep Fishing Without It"] = "bare", ["Buy More"] = "buy" }

	local function fn2(arg2, arg3, arg4, arg5)
		local toggles = arg3.Toggles

		arg2:AddToggle("AF_Enabled", {
			Text = "Auto Fishing",
			Default = false,
			Disabled = arg4.ready ~= true,
			Tooltip = "Casts, answers the bite and puts every catch in your bag, over and over. Turning it off puts the last catch away first. You need a fishing rod.",
			Callback = function(autoFishing)
				arg4.onToggle(autoFishing == true)
			end,
		}):AddKeyPicker("AF_Key", { Default = "None", Mode = "Toggle", Text = "Auto Fishing", SyncToggleState = true })

		arg5.status = arg2:AddLabel("Off", true)
		arg5.tally = arg2:AddLabel("", true)
		arg2:AddDivider()

		arg2:AddDropdown("AF_Rod", {
			Text = "Rod",
			Values = arg4.rods or { tbl.BEST_ROD },
			Default = tbl.BEST_ROD,
			Tooltip = "Which rod to fish with. The best one you own is picked for you unless you name one.",
			Callback = function(rod)
				local configure = arg4.configure
				local tbl2 = {}
				local rod2 = rod == tbl.BEST_ROD

				if rod2 then
					rod2 = "best"
				end

				tbl2.rod = rod2 or rod
				configure(tbl2)
			end,
		})

		arg2:AddDropdown("AF_Bait", {
			Text = "Bait",
			Values = arg4.baits or { tbl.KEEP_BAIT },
			Default = tbl.KEEP_BAIT,
			Tooltip = "Which bait to put on. Keep What's On leaves whatever you already have equipped alone until it runs out.",
			Callback = function(bait)
				local configure = arg4.configure
				local tbl2 = {}
				local bait2 = bait == tbl.KEEP_BAIT

				if bait2 then
					bait2 = "keep"
				end

				tbl2.bait = bait2 or bait
				configure(tbl2)
			end,
		})

		arg2:AddDropdown("AF_OutOfBait", {
			Text = "When The Bait Runs Out",
			Values = { "Stop Fishing", "Keep Fishing Without It", "Buy More" },
			Default = "Stop Fishing",
			Tooltip = "Bare hooks still catch things, just worse ones. Buy More walks to whoever sells that bait, buys more and walks back. Fisherman Jeso only sells Worms once you have the fishing permit.",
			Callback = function(whenTheBaitRunsOut)
				arg4.configure({ outOfBait = whenTheBaitRunsOuts[whenTheBaitRunsOut] or "stop" })
			end,
		})

		local v = arg2:AddDependencyBox()

		v:AddSlider("AF_BuyAmount", {
			Text = "How Many To Buy",
			Default = 20,
			Min = 1,
			Max = 99,
			Rounding = 0,
			Tooltip = "How many it buys each time the bait runs out.",
			Callback = function(howManyToBuy)
				arg4.configure({ buyAmount = math.floor(tonumber(howManyToBuy) or 20) })
			end,
		})

		if arg3.Options then
			if arg3.Options.AF_OutOfBait then
				v:SetupDependencies({ { arg3.Options.AF_OutOfBait, "Buy More" } })
			end
		end

		arg2:AddDropdown("AF_Mode", {
			Text = "How To Answer The Bite",
			Values = { "Instantly", "Play It Out" },
			Default = "Instantly",
			Tooltip = "Instantly answers the bite straight away. Play It Out plays the game's own bite bar instead.",
			Callback = function(howToAnswerTheBite)
				local configure = arg4.configure
				local tbl2 = {}
				local mode = howToAnswerTheBite == "Play It Out"

				if mode then
					mode = "legit"
				end

				tbl2.mode = mode or "direct"
				configure(tbl2)
			end,
		})

		arg2:AddToggle("AF_Collect", {
			Text = "Pick Up What You Catch",
			Default = true,
			Tooltip = "Takes each catch the moment it comes up, and picks up any that fell off your line before the next cast. Turn it off and it stays hanging there.",
			Callback = function(pickUpWhatYouCatch)
				arg4.configure({ collect = pickUpWhatYouCatch == true })
			end,
		})

		arg2:AddToggle("AF_Travel", {
			Text = "Go To The Fishing Spot",
			Default = true,
			Tooltip = "Takes you to the spot picked on the Spots page before it starts (Fisherman Jeso's dock at Mistfall Harbor unless you pick another). Turn it off to fish where you already are.",
			Callback = function(goToTheFishingSpot)
				arg4.configure({ travel = goToTheFishingSpot == true })
			end,
		})

		arg2:AddDivider()

		arg2:AddToggle("AF_LooseFish", {
			Text = "Pick Up Loose Fish",
			Default = false,
			Premium = true,
			Tooltip = "Picks up fish lying loose near you that fell off a line, yours first. It never takes a fish still hanging on someone's line. Other players' loose fish count too, so it's off to start with.",
			Callback = function(pickUpLooseFish)
				arg4.onLoose(pickUpLooseFish == true)
			end,
		})

		local v5 = arg2:AddDependencyBox()

		v5:AddSlider("AF_LooseRange", {
			Text = "How Far To Look",
			Default = 50,
			Premium = true,
			Min = 10,
			Max = 200,
			Rounding = 0,
			Suffix = " studs",
			Tooltip = "Only loose fish this close to you are picked up.",
			Callback = function(howFarToLook)
				arg4.onLooseRange(math.floor(tonumber(howFarToLook) or 50))
			end,
		})

		if toggles.AF_LooseFish then
			v5:SetupDependencies({ { toggles.AF_LooseFish, true } })
		end
	end

	local function fn3(arg2, arg3, arg4, arg5)
		arg5.rod = arg2:AddLabel("Checking your rods", true)

		arg2:AddButton("AF_GetRod", {
			Text = "Get Fishing Rod",
			DoubleClick = true,
			Premium = true,
			Disabled = arg4.rodReady ~= true,
			Tooltip = "Takes Dock Master Sofen's fishing permit quest (5,000 Wen, level 45), picks up the stamp on the docks, hands it back, then buys the Basic Fishing Rod from Fisherman Jeso (3,500 Wen) and puts it on your hotbar. Click twice to start, and twice again to stop.",
			Func = function()
				arg4.getRod()
			end,
		})

		arg2:AddToggle("AF_UpgradeRod", {
			Text = "Auto Upgrade Rod",
			Default = false,
			Premium = true,
			Disabled = arg4.rodReady ~= true,
			Tooltip = "Buys the Rare Fishing Rod from Fisherman Jeso as soon as you have 10,000 Wen and 5 Golden Fish, and puts it where your old rod was. While fishing it goes between casts and comes back.",
			Callback = function(autoUpgradeRod)
				arg4.onUpgrade(autoUpgradeRod == true)
			end,
		})

		arg5.rodStatus = arg2:AddLabel("", true)
		arg2:AddDivider()

		arg2:AddToggle("AF_FishQuests", {
			Text = "Auto Fish Quests",
			Default = false,
			Premium = true,
			Disabled = arg4.questsReady ~= true,
			Tooltip = "Takes the fish quests (Angler Runo, Shiori, Iceveil Guard Shiro, Shrine Messenger Akio), fishes until you have every fish they want, puts them in the crate and hands the quest in, then takes the next one. You need a fishing rod.",
			Callback = function(autoFishQuests)
				arg4.onQuests(autoFishQuests == true)
			end,
		})

		arg2:AddDropdown("AF_FishQuestPick", {
			Text = "Only These Quests",
			Values = arg4.questLabels or {},
			Default = {},
			Multi = true,
			AllowNull = true,
			Premium = true,
			Tooltip = "Leave empty to do any fish quest you can take. It picks the one you're closest to finishing, counting rarer fish as more work.",
			Callback = function(onlyTheseQuests)
				arg4.onQuestPick(onlyTheseQuests)
			end,
		})

		arg5.quest = arg2:AddLabel("Off", true)
	end

	tbl.PAGES = {
		{ name = "Auto Fishing", icon = "fish", build = fn2, side = "Left" },
		{
			name = "Fishing Spots",
			icon = "map-pin",
			build = function(arg2, arg3, arg4, arg5)
				arg2:AddDropdown("AF_Spot", {
					Text = "Fishing Spot",
					Values = arg4.spots or { "Mistfall Harbor" },
					Default = "Mistfall Harbor",
					Tooltip = "Where Auto Fishing goes when Go To The Fishing Spot is on, and where Go There takes you. Spots you save show up here too.",
					Callback = function(fishingSpot)
						arg4.onSpot(fishingSpot)
					end,
				})

				arg5.spot = arg2:AddLabel("", true)

				arg2:AddButton("AF_GoThere", {
					Text = "Go There",
					Tooltip = "Teleports you to the picked spot and checks there's water to cast into from it.",
					Func = function()
						arg4.goThere()
					end,
				})

				arg2:AddDivider()

				arg2:AddInput("AF_SpotName", {
					Text = "Spot Name",
					Default = "",
					Placeholder = "My Fishing Spot",
					Finished = false,
					Tooltip = "The name to save the spot under. Leave it empty for Spot 1, Spot 2 and so on.",
				})

				arg2:AddButton("AF_SaveSpot", {
					Text = "Save Where You're Standing",
					Tooltip = "Saves where you stand as a fishing spot. Face the water first, since it casts the way you were facing.",
					Func = function()
						arg4.saveSpot()
					end,
				})

				arg2:AddButton("AF_DeleteSpot", {
					Text = "Delete This Spot",
					DoubleClick = true,
					Tooltip = "Deletes the picked spot if it's one you saved. Click twice.",
					Func = function()
						arg4.deleteSpot()
					end,
				})
			end,
			side = "Left",
		},
		{ name = "Rod & Quests", icon = "trophy", build = fn3, side = "Right" },
	}

	tbl.build = function(arg2, arg3)
		if type(arg2) ~= "table" then
			return nil
		end

		if type(arg2.Tabs) ~= "table" then
			return nil
		end

		if not arg2.Toggles then
			return nil
		end
		local tbl2 = {}
		local count = 0
		local v = table.pack(ipairs(tbl.PAGES))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for _, v8 in v5, v6, v7 do
			Identity.elevate()
			local v9 = pcall
			local groupbox = Place.groupbox
			local v10 = arg2
			local name = v8.name
			local icon = v8.icon
			local tbl3 = { fallback = tbl.FALLBACK, side = v8.side or tbl.SIDE }
			local v11 = table.pack(v9(groupbox, v10, name, icon, tbl3))
			local v12, v13

			if select("#", table.unpack(v11, 1, v11.n)) ~= 0 then
				v12 = v11[1]
				v13 = v11[2]
			else
				v12 = nil
				v13 = nil
			end

			if v12 then
				if v13 then
					count += 1
				end
			end

			local flag = false
			local v14 = v13

			if v12 then
				if v13 then
					local v15 = table.pack(pcall(v8.build, v13, arg2, arg3, tbl2))
					local v16, v17

					if select("#", table.unpack(v15, 1, v15.n)) ~= 0 then
						v16 = v15[1]
						v17 = v15[2]
					else
						v16 = nil
						v17 = nil
					end

					flag = v16
					v14 = v17
				end
			end

			if not flag then
				Log.devwarn("AutoFishing", "the %s page didn't build: %s", tostring(v8.name), tostring(v14))
			end
		end

		if count ~= 0 then
			local tbl3 = {}

			local function fn4(arg4, arg5)
				local v8 = tbl2[arg4]
				local str = arg5 or ""

				if v8 then
					if tbl3[arg4] ~= str then
						Identity.elevate()

						if pcall(v8.SetText, v8, str) then
							tbl3[arg4] = str
						end

						return
					end
				end
			end

			local function fn5(arg4, arg5)
				local options = arg2.Options

				if options then
					options = arg2.Options[arg4]
