			local v13 = table.pack(ipairs(tbl3))
			local v14, v15, v16

			if select("#", table.unpack(v13, 1, v13.n)) ~= 0 then
				v14 = v13[1]
				v15 = v13[2]
				v16 = v13[3]
			else
				v14 = nil
				v15 = nil
				v16 = nil
			end

			for _, v17 in v14, v15, v16 do
				tbl5[#tbl5 + 1] = v17
			end

			v6:AddDropdown("CS_AnyTier", {
				Text = "Or Any Clan Of This Tier Or Better",
				Values = tbl5,
				Default = "Off",
				Premium = true,
				Tooltip = "Also stops on any clan this rare or rarer. Legendary means any Legendary, Mythic or Supreme clan.",
				Callback = fn13,
			})

			v6:AddSlider("CS_Budget", {
				Text = "Spin Budget",
				Default = 20,
				Min = 1,
				Max = 500,
				Rounding = 0,
				Suffix = " spins",
				Premium = true,
				Tooltip = "The most spins it uses in one go.",
				Callback = fn13,
			})

			v6:AddToggle("CS_SaveFirst", {
				Text = "Save My Clan First (VIP)",
				Default = false,
				Premium = true,
				Tooltip = "Needs VIP. Saves your clan to a free save slot before the first spin, so you can load it back from the game's spin menu.",
				Callback = fn13,
			})

			v6:AddToggle("CS_StopRare", {
				Text = "Stop On Any Legendary Or Better",
				Default = true,
				Premium = true,
				Tooltip = "Stops when a spin lands a Legendary, Mythic or Supreme clan you didn't pick, so you can decide whether to keep it. The game's own wheel asks before spinning over one of those too.",
				Callback = fn13,
			})

			v12 = v6:AddLabel(fn9(), true)

			if v5 then
				v6:AddButton({
					Text = "Start Spinning",
					DoubleClick = true,
					Risky = true,
					Premium = true,
					Disabled = Spins == nil,
					Tooltip = "Every spin replaces your clan. The first press shows what you'd lose, the second one starts.",
					Func = fn16,
				})

				v6:AddButton({ Text = "Stop", Tooltip = "Stops after the spin that's happening now.", Func = fn17 })
			else
				v6:AddButton({
					Text = "Back To Slot Select",
					DoubleClick = true,
					Tooltip = "Leaves this server for the slot-select screen, where the clan wheel is. Click twice to confirm.",
					Func = fn18,
				})
			end

			local flag = false

			local function fn19()
				if flag then
					return
				end

				if not Spins then
					return
				end
				local v17 = table.pack(Spins.pool("Clan"))
				local v18, v19

				if select("#", table.unpack(v17, 1, v17.n)) ~= 0 then
					v18 = v17[1]
					v19 = v17[2]
				else
					v18 = nil
					v19 = nil
				end

				if not v18 then
					return
				end

				if #v19 ~= 0 then
					flag = true
					local flag2 = #v19 == #tbl2
					local v20 = table.pack(ipairs(v19))
					local v21, v22, v23

					if select("#", table.unpack(v20, 1, v20.n)) ~= 0 then
						v21 = v20[1]
						v22 = v20[2]
						v23 = v20[3]
					else
						v21 = nil
						v22 = nil
						v23 = nil
					end

					for k, v24 in v21, v22, v23 do
						if tbl2[k] ~= v24 then
							flag2 = false
						end
					end

					if flag2 then
						return
					end
					local csClans = options.CS_Clans

					if csClans then
						Identity.elevate()

						pcall(function()
							local tbl6 = {}
							local v24 = pairs
							local tbl7 = csClans.Value or {}
							local v25 = table.pack(v24(tbl7))
							local v26, v27, v28

							if select("#", table.unpack(v25, 1, v25.n)) ~= 0 then
								v26 = v25[1]
								v27 = v25[2]
								v28 = v25[3]
							else
								v26 = nil
								v27 = nil
								v28 = nil
							end

							for k, v29 in v26, v27, v28 do
								if v29 then
									if table.find(v19, k) then
										tbl6[#tbl6 + 1] = k
									end
								end
							end

							csClans:SetValues(v19)
							csClans:SetValue(tbl6)
						end)

						return
					end

					return
				end
			end

			v.track(Jobs_.interval(1, function()
				pcall(fn19)
				pcall(fn12)
			end, { name = "ClanSpinner.refresh", immediate = true }))

			v.maid:GiveTask(function()
				deadline = nil

				if v7 then
					v7:Cancel()
				end

				v7 = nil

				if v8 then
					v8:Cancel()
				end

				v8 = nil
			end)

			v.finalize()
			return {}
		end

		return {}
	end
end)

v4("Features/Main/ClanSpinner/Words", function(arg)
	local Words = arg("Features/Main/RemoteInteract/Words")
	local Runner = arg("Features/Main/ClanSpinner/Runner")
	local tbl = {}
	local red = Words.RED
	local green = Words.GREEN
	local grey = Words.GREY

	tbl.YELLOW = Words.YELLOW
	tbl.RED = red
	tbl.GREEN = green
	tbl.GREY = grey

	local paint = Words.paint
	local bold = Words.bold
	local commas = Words.commas
	local percent = Words.percent

	tbl.escape = Words.escape
	tbl.paint = paint
	tbl.bold = bold
	tbl.commas = commas
	tbl.percent = percent

	local function fn2(arg2, arg3)
		local str = "%s %s%s"
		local format = ("%s %s%s").format
		local v = Words.commas(arg2)
		local v5 = arg3
		local flag = arg2 == 1

		if flag then
			flag = ""
		end

		return format(str, v, v5, flag or "s")
	end

	tbl.plain = function(arg2)
		return (tostring(arg2):gsub("<[^>]*>", ""):gsub("&lt;", "<"):gsub("&gt;", ">"):gsub("&amp;", "&"))
	end

	tbl.clan = function(arg2, arg3)
		if arg2 then
			local v = Words.bold(Words.escape(arg2))

			if arg3 then
				v ..= " (" .. Words.escape(arg3) .. ")"
			end

			return v
		end

		return "no clan"
	end

	local function fn3(arg2)
		return math.max(1, math.floor(arg2 + 0.5))
	end

	tbl.odds = function(arg2, arg3)
		if type(arg2) ~= "table" then
			return Words.paint(tbl.GREY, "Pick the clans you want to see your odds.")
		end
		local tbl2 = {}

		if arg2.have then
			tbl2[#tbl2 + 1] = Words.paint(tbl.GREEN, "You already have one of the clans you picked.")
		end

		local num = tonumber(arg2.expectedSpins)

		if num then
			if num ~= math.huge then
				local v = Words.paint(tbl.YELLOW, Words.bold(Words.percent(arg2.chanceInBudget)))
				tbl2[#tbl2 + 1] = ("About %s on average. %s chance within %s."):format(fn2(fn3(num), "spin"), v, fn2(math.floor(tonumber(arg2.budget) or 0), "spin"))

				if type(arg3) == "table" then
					if tonumber(arg3.rolls) then
						if tonumber(arg2.budgetRolls) then
							if arg3.rolls < arg2.budgetRolls then
								local n = tonumber(arg2.chancePerRoll) or 0
								local flag = arg3.rolls > 0

								if flag then
									flag = 1 - (1 - n) ^ arg3.rolls
								end

								flag = flag or 0
								tbl2[#tbl2 + 1] = Words.paint(tbl.GREY, ("You have %s, which gives a %s chance."):format(fn2(math.floor(arg3.total or 0), "spin"), Words.percent(flag)))
							end
						end
					end
				end

				local cheapest = arg2.cheapest

				if type(cheapest) == "table" then
					if cheapest.name then
						if tonumber(cheapest.spins) then
							local str = ("Buying %s costs %s."):format(Words.escape(cheapest.name), fn2(cheapest.spins, "spin"))

							if cheapest.spins <= num then
								str ..= " That's no more than spinning for it on average."
							end

							tbl2[#tbl2 + 1] = Words.paint(tbl.GREY, str)
						end
					end
				end

				return table.concat(tbl2, "\n")
			end
		end

		tbl2[#tbl2 + 1] = Words.paint(tbl.YELLOW, "None of the clans you picked can come up on the wheel right now.")
		return table.concat(tbl2, "\n")
	end

	tbl.arm = function(arg2, arg3)
		local tbl2 = arg3 or {}
		local tbl3 = {}
		local clan = type(arg2) == "table"

		if clan then
			clan = arg2.clan
		end

		clan = clan or nil
		local tier = type(arg2) == "table"

		if tier then
			tier = arg2.tier
		end

		tier = tier or nil
		tbl3[#tbl3 + 1] = ("Every spin replaces your clan. You have %s."):format(tbl.clan(clan, tier))

		if clan then
			if Runner.RARE[tier or ""] then
				if tbl2.saveFirst then
					if tbl2.saveFirst then
						if clan then
							local n = #tbl3 + 1
							tbl3[n] = Words.paint(tbl.GREY, "It gets saved to a free save slot first.")
						end
					end
				else
					tbl3[#tbl3 + 1] = Words.paint(tbl.RED, ("%s is a %s clan. Without Save My Clan First it's gone for good once you spin."):format(Words.escape(clan), Words.escape(tier)))
				end
			elseif tbl2.saveFirst then
				if clan then
					tbl3[#tbl3 + 1] = Words.paint(tbl.GREY, "It gets saved to a free save slot first.")
				end
			end
		elseif tbl2.saveFirst then
			if clan then
				tbl3[#tbl3 + 1] = Words.paint(tbl.GREY, "It gets saved to a free save slot first.")
			end
		end

		tbl3[#tbl3 + 1] = Words.paint(tbl.YELLOW, ("Press Start Spinning again within %d seconds to begin."):format(tbl2.window or 15))
		return table.concat(tbl3, "\n")
	end

	tbl.progress = function(arg2, arg3, arg4)
		local flag = type(arg3) == "table"

		if flag then
			flag = arg3.result

			if flag then
				flag = tbl.clan(arg3.result, arg3.tier)
			end

			flag = flag or "nothing"
		end

		flag = flag or "nothing yet"
		return ("Spinning: %s of %s used. Last spin: %s."):format(Words.commas(arg2.spent or 0), fn2(math.floor(tonumber(arg4) or 0), "spin"), flag)
	end

	local function fn4(arg2)
		local saved = arg2.saved
		if type(saved) ~= "table" then
			return ""
		end
		return (" Your old clan %s is saved in slot %s."):format(Words.escape(saved.clan), Words.escape(saved.slot))
	end

	tbl.stop = function(arg2, arg3)
		local v = fn2(arg2.rolls or 0, "spin")
		local v5 = tbl.clan(arg2.clan, arg2.tier)
		local stop = arg2.stop

		if stop == Runner.STOP.HIT then
			if (arg2.rolls or 0) == 0 then
				if arg2.committed then
					return Words.paint(tbl.GREEN, ("Your unfinished spin had landed %s, one of your picks."):format(v5)) .. fn4(arg2)
				end
			end

			return Words.paint(tbl.GREEN, ("Got %s after %s!"):format(v5, v)) .. fn4(arg2)
		end

		if stop == Runner.STOP.HAVE then
			return Words.paint(tbl.GREEN, ("You already have %s, one of your picks, so nothing was spun."):format(v5))
		end

		if stop == Runner.STOP.BUDGET then
			return ("Used your budget of %s without landing a clan you picked. You have %s now."):format(fn2(math.floor(tonumber(arg3) or 0), "spin"), v5) .. fn4(arg2)
		end

		if stop == Runner.STOP.OUT then
			return ("Out of clan spins after %s. You have %s now."):format(v, v5) .. fn4(arg2)
		end

		if stop == Runner.STOP.RARE then
			return Words.paint(tbl.YELLOW, ("Landed %s, which isn't one of your picks. Stopped so you can decide whether to keep it. Start again to spin over it."):format(v5)) .. fn4(arg2)
		end

		if stop == Runner.STOP.CANCELLED then
			if arg2.inFlight then
				return ("Stopped after %s. One more spin was already on its way and still lands, so check your clan in a moment."):format(v) .. fn4(arg2)
			end
			return ("Stopped after %s. You have %s now."):format(v, v5) .. fn4(arg2)
		end

		return ("Stopped after %s."):format(v)
	end

	tbl.failed = function(arg2, arg3, arg4, arg5)
		local message = Runner.MESSAGES[arg3]

		if not message then
			if arg2 then
				if type(arg2.explain) == "function" then
					local v = table.pack(arg2.explain(arg3))
					local v5, v6

					if select("#", table.unpack(v, 1, v.n)) ~= 0 then
						v5 = v[1]
						v6 = v[2]
					else
						v5 = nil
						v6 = nil
					end

					if v5 then
						if type(v6) == "string" then
							message = v6
						end
					end
				end
			end
		end

		local str = Words.escape(message or "Something went wrong with the wheel.")

		if type(arg4) == "string" then
			local errors = arg2

			if errors then
				errors = arg2.Errors
			end

			if errors then
				errors = arg2.Errors.UNKNOWN_NAME
			end

			if arg3 == errors then
				str = ("%s isn't on the wheel."):format(Words.escape(arg4))
			end
		end

		local rolls = type(arg5) == "table"

		if rolls then
			rolls = arg5.rolls
		end

		rolls = rolls or 0

		if rolls > 0 then
			str = ("Stopped after %s: %s"):format(fn2(rolls, "spin"), str)
		end

		local str2 = ""

		if rolls > 0 then
			if arg5.clan then
				str2 = (" You have %s now."):format(tbl.clan(arg5.clan, arg5.tier))
			end
		end

		local v = Words.paint(tbl.RED, str)
		local flag = type(arg5) == "table"

		if flag then
			flag = fn4(arg5)
		end

		return v .. str2 .. (flag or "")
	end

	return tbl
end)

v4("Features/Main/ClanSpinner/Runner", function()
	local tbl = {
		STOP = {
			HIT = "hit",
			HAVE = "have",
			BUDGET = "budget",
			OUT = "out",
			RARE = "rare",
			CANCELLED = "cancelled",
			ERROR = "error",
		},
		Errors = {
			BAGS_FULL = "clanspinner/bags_full",
			STILL_PENDING = "clanspinner/still_pending",
			SAVE_PENDING = "clanspinner/save_pending",
			LOCKED = "clanspinner/locked",
		},
	}

	tbl.MESSAGES = {
		[tbl.Errors.BAGS_FULL] = "Your three clan save slots are all full. Free one in the game's spin menu, or turn off Save My Clan First.",
		[tbl.Errors.STILL_PENDING] = "The game is still finishing your last spin. Wait a moment and try again.",
		[tbl.Errors.SAVE_PENDING] = "Your last spin hasn't finished yet, and finishing it could change your clan before it can be saved. Turn off Save My Clan First to let it finish.",
		[tbl.Errors.LOCKED] = "Clan Spinner is a premium feature.",
	}

	tbl.RARE = { Legendary = true, Mythic = true, Supreme = true }
	tbl.PENDING_WAIT = 8
	tbl.POLL = 0.2
	tbl.BETWEEN = 0.25

	tbl.bagSlot = function(arg, arg2)
		local slots = type(arg) == "table"

		if slots then
			slots = type(arg.slots) == "table"
		end

		if slots then
			slots = arg.slots
		end

		slots = slots or {}
		local v = table.pack(ipairs(slots))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for _, v8 in v5, v6, v7 do
			if v8.value == nil then
				continue
			end

			if v8.value == arg2 then
				return v8.slot, false
			end
		end

		local v8 = table.pack(ipairs(slots))
		local v9, v10, v11

		if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
			v9 = v8[1]
			v10 = v8[2]
			v11 = v8[3]
		else
			v9 = nil
			v10 = nil
			v11 = nil
		end

		for _, v12 in v9, v10, v11 do
			if v12.value == nil then
				return v12.slot, true
			end
		end

		return nil
	end

	tbl.run = function(arg, arg2)
		local spins = arg.Spins
		local job = arg.job
		local errors = spins.Errors or {}
		local tbl2 = { rolls = 0, spent = 0, results = {} }

		local function fn2(stop)
			tbl2.stop = stop
			local v = table.pack(spins.current())
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				local tier = v6.tier
				tbl2.clan = v6.clan
				tbl2.tier = tier
			end

			return true, tbl2
		end

		local function fn3(why, detail)
			tbl2.stop = tbl.STOP.ERROR
			tbl2.why = why
			tbl2.detail = detail
			local v = table.pack(spins.current())
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				local tier = v6.tier
				tbl2.clan = v6.clan
				tbl2.tier = tier
			end

			return false, why, detail, tbl2
		end

		local function fn4()
			local flag = arg.locked ~= nil

			if flag then
				flag = arg.locked() == true
			end

			return flag
		end

		local function fn5()
			local v = table.pack(spins.pending())
			local v5

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[2]
			else
				v5 = nil
			end

			if not v5 then
				return true
			end
			local n = arg.now() + tbl.PENDING_WAIT

			while job:sleep(tbl.POLL) do
				local v6 = table.pack(spins.pending())
				local v7

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[2]
				else
					v7 = nil
				end

				if v7 then
					if n <= arg.now() then
						return false, tbl.Errors.STILL_PENDING
					end
					continue
				end

				return true
			end

			return false, tbl.STOP.CANCELLED
		end

		if fn4() then
			return fn3(tbl.Errors.LOCKED)
		end
		local v = table.pack(spins.isMenu())
		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
		else
			v5 = nil
			v6 = nil
		end

		if v5 then
			if v6 == true then
				local v7 = table.pack(spins.plan({ kind = "Clan", want = arg2.want, anyTier = arg2.anyTier, budget = arg2.budget }))
				local v8, v9, v10

				if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
					v8 = v7[1]
					v9 = v7[2]
					v10 = v7[3]
				else
					v8 = nil
					v9 = nil
					v10 = nil
				end

				if v8 then
					local tbl3 = {}
					local v11 = ipairs
					local wanted = v9.wanted or {}
					local v12 = table.pack(v11(wanted))
					local v13, v14, v15

					if select("#", table.unpack(v12, 1, v12.n)) ~= 0 then
						v13 = v12[1]
						v14 = v12[2]
						v15 = v12[3]
					else
						v13 = nil
						v14 = nil
						v15 = nil
					end

					for _, v16 in v13, v14, v15 do
						tbl3[v16] = true
					end

					tbl2.wanted = v9.wanted
					local v16 = table.pack(spins.current())
					local v17, v18

					if select("#", table.unpack(v16, 1, v16.n)) ~= 0 then
						v17 = v16[1]
						v18 = v16[2]
					else
						v17 = nil
						v18 = nil
					end

					if v17 then
						local v19, v20
						local tier = v18.tier
						tbl2.start = v18.clan
						tbl2.startTier = tier

						if v18.clan then
							if tbl3[v18.clan] then
								return fn2(tbl.STOP.HAVE)
							end
						end

						local v21 = table.pack(spins.pending())
						local v22

						if select("#", table.unpack(v21, 1, v21.n)) ~= 0 then
							v22 = v21[2]
						else
							v22 = nil
						end

						if v22 then
							local v23 = table.pack(spins.busy())
							local v24

							if select("#", table.unpack(v23, 1, v23.n)) ~= 0 then
								v24 = v23[2]
							else
								v24 = nil
							end

							if v24 then
								return fn3(errors.BUSY)
							end
							local v25 = table.pack(spins.check("Clan"))
							local v26, v27

							if select("#", table.unpack(v25, 1, v25.n)) ~= 0 then
								v26 = v25[1]
								v27 = v25[2]
							else
								v26 = nil
								v27 = nil
							end

							if not v26 then
								if v27 == errors.WHEEL_OPEN then
									return fn3(v27)
								end
							end

							if arg2.saveFirst then
								return fn3(tbl.Errors.SAVE_PENDING)
							end
							local v28 = table.pack(spins.commit("Clan"))
							local v29, v30, v31

							if select("#", table.unpack(v28, 1, v28.n)) ~= 0 then
								v29 = v28[1]
								v30 = v28[2]
								v31 = v28[3]
							else
								v29 = nil
								v30 = nil
								v31 = nil
							end

							if not v29 then
								if v30 ~= errors.NOT_PENDING then
									return fn3(v30, v31)
								end
							end

							tbl2.committed = true
