				end
				return {}
			end

			return {}
		end

		local v5 = v.track(Control.register("Auto Training"))
		local v6 = nil
		local v7 = nil

		local v8 = Runner.new({
			api = getApi,
			cfg = tbl,
			blocked = Runner.standAside(v5, Control, "Auto Training"),
			locked = Premium.isLocked,
			report = function(arg3)
				if v6 then
					v6.setStatus(arg3)
				end
			end,
		})

		local function fn3(arg3)
			if v7 then
				v7:Cancel()
				v7 = nil
			end

			if v8.busy() then
