			local tbl3 = {}

			local function fn2(Off2, arg5, arg6)
				if tbl3[arg5] == arg6 then
					return
				end
				Identity.elevate()

				if pcall(Off2.SetText, Off2, arg6) then
					tbl3[arg5] = arg6
				end
			end

			return {
