				v7 = nil
				v8 = nil
			end

			for _, v9 in v6, v7, v8 do
				if v9.kind ~= "training" then
					continue
				end

				if v9.station ~= true then
					continue
				end

				if v9.direct ~= true then
					if v9.legit ~= true then
						continue
					end
				end

