				local v6 = table.pack(v5(order))
				local v7, v8, v9

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[1]
					v8 = v6[2]
					v9 = v6[3]
				else
					v7 = nil
					v8 = nil
					v9 = nil
				end

				for _, v10 in v7, v8, v9 do
