					end
					local v5 = table.pack(State.alive())
					local v6, v7

					if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
						v6 = v5[1]
						v7 = v5[2]
					else
						v6 = nil
						v7 = nil
					end

					if v6 then
						if v7 then
							local v8 = table.pack(fn7())
							local v9, v10

							if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
								v9 = v8[1]
								v10 = v8[2]
							else
								v9 = nil
								v10 = nil
							end

							if v9 then
								report(("Heading for %s"):format(v9))
								flag = true

								local v11 = table.pack(Minigame.run(v9, {
									mode = fn3(),
									travel = true,
									timeout = tbl2.timeoutFor(v9, fn3()),
									job = arg2,
									stop = function()
										return blocked() ~= nil
									end,
									leaveOnStop = true,
								}))

								local v12, v13

								if select("#", table.unpack(v11, 1, v11.n)) ~= 0 then
									v12 = v11[1]
									v13 = v11[2]
								else
									v12 = nil
									v13 = nil
								end

								flag = false
								if not arg2.alive then
									return 0
								end

								if v12 then
									local outcome = type(v13) == "table"

									if outcome then
										outcome = v13.outcome
									end

									outcome = outcome or nil
									tbl4.done += 1

									if outcome ~= "won" then
										if outcome == "lost" then
											tbl4.lost += 1
										end
									else
										tbl4.won += 1
									end

									if outcome ~= "won" then
										if outcome ~= "lost" then
											return 0.5, ("Finished %s, but the game never said how it went"):format(v9)
										end
										return 0.5, ("Lost %s, trying the next one"):format(v9)
									end

									return 0.5, ("Finished %s"):format(v9)
								end

								local errors = Minigame.Errors

								if v13 == errors.CANCELLED then
									local v14 = blocked()
									if v14 then
										return 1, v14
									end
									return 1, ("Stopped %s"):format(v9)
								end

								if v13 == errors.BUSY then
									if fn9(arg2) then
										return 0.5, "Finished the training you already had open"
									end
									return 0.5, "Waiting for the training already running to end"
								end

								if v13 == errors.DIED then
									return 1, "Waiting for your character"
								end

								if v13 == errors.NO_INPUT then
									return 1, "Your executor can't press prompts, so Auto Training can't open a station"
								end

								if v13 == errors.LOCKED then
									fn4(v9, 600)
									return 0.5, ("%s: %s"):format(v9, fn2(v13))
								end
								fn4(v9)
								if fn8(v9) then
									return 0.5, ("%s: %s Left it for now"):format(v9, fn2(v13))
								end
								return 0.5, ("%s: %s"):format(v9, fn2(v13))
							end

							if v10 ~= "benched" then
								if v10 ~= "premium" then
									return 1, "No training station this script can use"
								end
								return 1, "The Parkour Dungeon is a premium feature. Pick another training"
							end

							return 1, "Every training you picked is being left alone for a moment"
						end
					end

					return 1, "Waiting for your character"
				end,
			}

			return tbl5
		end,
	}

	return tbl2
end)

v4("Features/Auto/AutoStat", function(arg)
	local Jobs_ = arg("Utility/Jobs")
	local Mount = arg("Utility/Mount")
	local Store = arg("Utility/Store")
	local Place = arg("UI/Place")
	local Plan = arg("Features/Auto/AutoStat/Plan")
	local tbl = { "Auto", "Training" }

	return function(arg2)
		local v = Mount.orchestrator(arg2, "AutoStat")
		if not v then
			return
		end
		local library = arg2.Library
		local options = arg2.Options
		local api = arg2.Api

		if api then
			api = arg2.Api.Stats
		end

		if not options then
			return
		end

		if not Place.tab(arg2, tbl) then
			return
		end
		local tbl2 = {}
		local v5 = Store.read(Store.GAME, "autostat", nil)
		local limits = type(v5) == "table"

		if limits then
			limits = v5.limits
		end

		limits = limits or nil

		if type(limits) == "table" then
			local v6 = table.pack(pairs(limits))
			local v7, v8, v9

			if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
				v7 = v6[1]
				v8 = v6[2]
				v9 = v6[3]
			else
				v7 = nil
				v8 = nil
				v9 = nil
			end

			for k, v10 in v7, v8, v9 do
				if type(k) == "string" then
					if type(v10) == "number" then
						if v10 >= 1 then
							tbl2[k] = math.floor(v10)
						end
					end
				end
			end
		end

		local function fn2()
			pcall(Store.write, Store.GAME, "autostat", { limits = tbl2 })
		end

		local stats = {}
		local names2 = {}
		local tbl3 = {}
		local stat3 = nil
		local flag = false
		local v6 = nil
		local v7 = nil
		local tbl4 = {}

		local function fn3(arg3, arg4, arg5)
			if arg3 then
				if tbl4[arg4] ~= arg5 then
					if pcall(arg3.SetText, arg3, arg5) then
						tbl4[arg4] = arg5
					end
				end
			end
		end

		local function fn4()
			if not api then
				return nil
			end
			local v8 = table.pack(api.tree())
			local v9, v10

			if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
				v9 = v8[1]
				v10 = v8[2]
			else
				v9 = nil
				v10 = nil
			end

			local names, v11, v12, v13

			if v9 then
				if type(v10) == "table" then
					table.clear(stats)
					names = {}
					local v14 = table.pack(ipairs(v10.lines))

					if select("#", table.unpack(v14, 1, v14.n)) ~= 0 then
						v11 = v14[1]
						v12 = v14[2]
						v13 = v14[3]
					else
						v11 = nil
						v12 = nil
						v13 = nil
					end

					for _, v15 in v11, v12, v13 do
						stats[v15.name] = v15
						names[#names + 1] = v15.name
					end

					names2 = names
					return v10
				end
			end

			return nil
		end

		local function fn5()
			local stat = stat3

			if stat then
				stat = stats[stat3]
			end

			if stat then
				fn3(v7, "info", Plan.describeLine(stat, tbl2[stat3], api.format))
				return
			end
			return fn3(v7, "info", "Pick a stat above to see its level.")
		end

		local function fn6()
			local tbl5 = {}
			local v8 = table.pack(ipairs(names2))
			local v9, v10, v11

			if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
				v9 = v8[1]
				v10 = v8[2]
				v11 = v8[3]
			else
				v9 = nil
				v10 = nil
				v11 = nil
			end

			for _, v12 in v9, v10, v11 do
				if tbl2[v12] then
					tbl5[#tbl5 + 1] = v12
				end
			end

			return tbl5
		end

		local function fn7()
			local asUpgrade = options.AS_Upgrade
			if not asUpgrade then
				return
			end
			pcall(asUpgrade.SetValues, asUpgrade, fn6())
			local flag2 = type(asUpgrade.Value) == "table"

			if flag2 then
				flag2 = asUpgrade.Value
			end

			flag2 = flag2 or {}
			local tbl5 = {}
			local flag3 = false
			local v8 = table.pack(pairs(flag2))
			local v9, v10, v11

			if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
				v9 = v8[1]
				v10 = v8[2]
				v11 = v8[3]
			else
				v9 = nil
				v10 = nil
				v11 = nil
			end

			for k, v12 in v9, v10, v11 do
				if v12 then
					if tbl2[k] then
						tbl5[k] = true
					elseif v12 then
						flag3 = true
					end
				elseif v12 then
					flag3 = true
				end
			end

			if flag3 then
				pcall(asUpgrade.SetValue, asUpgrade, tbl5)
			end
		end

		local function fn8(stat, arg3)
			local n = math.floor(tonumber(arg3) or 0)

			if not (n >= 1) then
				tbl2[stat] = nil
			else
				tbl2[stat] = n
			end

			fn2()
			fn7()
			fn5()
		end

		local function fn9(stat)
			if type(stat) ~= "string" then
				return
			end
			stat3 = stat
			local stat2 = stats[stat]
			local asLimit = options.AS_Limit

			if asLimit then
				if stat2 then
					flag = true

					pcall(function()
						asLimit:SetMax(math.max(stat2.maxNodes, 1))
						asLimit:SetValue(tbl2[stat] or 0)
					end)

					flag = false
				end
			end

			fn5()
		end

		local tbl5 = {}
		local n = 0

		local function fn10()
			if next(tbl5) == nil then
				return
			end
			local tbl6 = {}
			local v8 = table.pack(ipairs(names2))
			local v9, v10, v11

			if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
				v9 = v8[1]
				v10 = v8[2]
				v11 = v8[3]
			else
				v9 = nil
				v10 = nil
				v11 = nil
			end

			for _, v12 in v9, v10, v11 do
				if tbl5[v12] then
					tbl6[#tbl6 + 1] = ("%s +%d"):format(v12, tbl5[v12])
				end
			end

			local str = ("Auto Stat spent %d skill points: %s."):format(n, table.concat(tbl6, ", "))

			pcall(function()
				library:Notify(str, 6)
			end)

			table.clear(tbl5)
			n = 0
		end

		local function fn11(arg3)
			while arg3.alive do
				local n7 = 2
				local v8 = fn4()

				if v8 then
					fn5()
					local v9 = Plan.next(v8, tbl2, tbl3)

					if v9.kind ~= "buy" then
						fn10()
					else
						local line = v9.line
						local v10 = api.unlock(line.name)
						if not arg3.alive then
							return
						end

						if v10 then
							tbl5[line.name] = (tbl5[line.name] or 0) + 1
							n += line.nextCost
							n7 = 0.6
						else
							fn10()
							n7 = 5
						end
					end
				end

				if arg3:sleep(n7) then
					continue
				end
				return
			end
		end

		local function fn12(arg3)
			if arg3 then
				if v6 then
					if v6.alive then
						if not arg3 then
							if v6 then
								v6:Cancel()
								v6 = nil
								fn10()
							end
						end
					else
						if not api then
							return
						end
						v6 = v.track(Jobs_.spawn(fn11, { name = "AutoStat" }))
					end
				else
					if not api then
						return
					end
					v6 = v.track(Jobs_.spawn(fn11, { name = "AutoStat" }))
				end
			elseif not arg3 then
				if v6 then
					v6:Cancel()
					v6 = nil
					fn10()
				end
			end
		end

		fn4()
		stat3 = names2[1]
		local stat2 = stat3

		if stat2 then
			stat2 = stats[stat3]
		end

		stat2 = stat2 or nil
		local v8 = Place.groupbox(arg2, "Auto Stat", "trending-up", { fallback = tbl, side = "Right" })

		if v8 then
			v8:AddDropdown("AS_Stat", {
				Text = "Stat",
				Values = table.move(names2, 1, #names2, 1, {}),
				Default = stat3,
				Tooltip = "Pick a stat to set the highest level Auto Stat may take it to.",
				Callback = function(stat)
					fn9(stat)
				end,
			})

			local v9 = v8
			local addSlider = v8.AddSlider
			local str = "AS_Limit"
			local tbl6 = { Text = "Level Limit" }
			local stat = stat3

			if stat then
				stat = tbl2[stat3]
			end

			tbl6.Default = stat or 0
			tbl6.Min = 0
			local stat4 = stat2

			if stat4 then
				stat4 = math.max(stat2.maxNodes, 1)
			end

			tbl6.Max = stat4 or 1
			tbl6.Rounding = 0
			tbl6.Tooltip = "Auto Stat never takes this stat past this level. Set it above 0 to add the stat to Stats To Upgrade."

			tbl6.FormatDisplayValue = function(arg3, arg4)
				return ("%d / %d"):format(math.floor(tonumber(arg4) or 0), math.floor(tonumber(arg3.Max) or 0))
			end

			tbl6.Callback = function(arg3)
				if not flag then
					if stat3 then
						fn8(stat3, arg3)
						return
					end
				end
			end

			addSlider(v9, str, tbl6)
			v7 = v8:AddLabel("", true)
			v8:AddDivider()

			v8:AddDropdown("AS_Upgrade", {
				Text = "Stats To Upgrade",
				Values = fn6(),
				Default = {},
				Multi = true,
				Tooltip = "Tick the stats Auto Stat should spend your skill points on. Only stats with a level limit show up here.",
				Callback = function(statsToUpgrade)
					local tbl7 = {}
					local v10 = pairs
					local statsToUpgrade2 = statsToUpgrade or {}
					local v11 = table.pack(v10(statsToUpgrade2))
					local v12, v13, v14

					if select("#", table.unpack(v11, 1, v11.n)) ~= 0 then
						v12 = v11[1]
						v13 = v11[2]
						v14 = v11[3]
					else
						v12 = nil
						v13 = nil
						v14 = nil
					end

					for k, v15 in v12, v13, v14 do
						if v15 then
							if tbl2[k] then
								tbl7[k] = true
							end
						end
					end

					tbl3 = tbl7
				end,
			})

			v8:AddToggle("AS_Toggle", {
				Text = "Auto Stat",
				Default = false,
				Disabled = api == nil,
				Tooltip = "Spends your skill points on the stats you ticked, always on the one furthest below its limit. It never goes past a limit.",
				Callback = function(autoStat)
					fn12(autoStat == true)
				end,
			})

			fn5()
			local saveManager = arg2.SaveManager

			if saveManager then
				if type(saveManager.SetIgnoreIndexes) == "function" then
					pcall(saveManager.SetIgnoreIndexes, saveManager, { "AS_Stat", "AS_Limit" })
				end
			end

			if #names2 == 0 then
				if api then
					local count = 0

					v.track(Jobs_.interval(2, function(arg3)
						count += 1

						if fn4() then
							if not (#names2 > 0) then
								if not (count >= 30) then
									return
								end
								arg3:Cancel()
							else
								pcall(function()
									options.AS_Stat:SetValues(table.move(names2, 1, #names2, 1, {}))
								end)

								pcall(function()
									options.AS_Stat:SetValue(names2[1])
								end)

								fn7()
								arg3:Cancel()
							end
						else
							if not (count >= 30) then
								return
							end
							arg3:Cancel()
						end
					end, { name = "AutoStat.lines" }))
				end
			end

			v.onUnload(function()
				if v6 then
					v6:Cancel()
				end

				v6 = nil
			end)

			v.finalize()
			return {}
		end

		return {}
	end
end)

v4("Features/Auto/AutoStat/Plan", function()
	local function fn2(arg, arg2)
		return math.min(arg2, arg.maxNodes)
	end

	local tbl

	tbl = {
		costTo = function(arg, arg2)
			local n = 0

			for i = arg.nodes + 1, math.min(arg2, arg.maxNodes) do
				local costs = arg.costs

				if costs then
					costs = arg.costs[i]
				end

				if costs then
					n += costs
					continue
				end
				return nil
			end

			return n
		end,
		next = function(arg, arg2, arg3)
			local v = nil
			local n = 0
			local flag = false
			local v5 = table.pack(ipairs(arg.lines))
			local v6, v7, v8

			if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
				v6 = v5[1]
				v7 = v5[2]
				v8 = v5[3]
			else
				v6 = nil
				v7 = nil
				v8 = nil
			end

			for _, v9 in v6, v7, v8 do
				local v10 = arg2[v9.name]
				if not arg3[v9.name] then
					continue
				end

				if not v10 then
					continue
				end

				if not (v10 > 0) then
					continue
				end
				flag = true
				local n7 = fn2(v9, v10) - v9.nodes
				if not (n7 > 0) then
					continue
				end

				if not v9.nextCost then
					continue
				end

				if not (n < n7) then
					if n7 ~= n then
						continue
					end

					if not (v9.nextCost < v.nextCost) then
						continue
					end
				end

				v = v9
				n = n7
			end

			if flag then
				if v then
					if v.nextCost <= arg.points then
						return { kind = "buy", line = v, gap = n }
					end
					return { kind = "save", line = v, gap = n, need = v.nextCost, have = arg.points }
				end

				return { kind = "done" }
			end

			return { kind = "none" }
		end,
		describeLine = function(arg, arg2, arg3)
			local str = ("%s is level 0 of %d."):format(arg.name, arg.maxNodes)

			if arg.nodes > 0 then
				str = ("%s is level %d of %d (%s)."):format(arg.name, arg.nodes, arg.maxNodes, arg.text)
			end

			if arg2 then
				if not (arg2 <= 0) then
					local v = fn2(arg, arg2)
					if v <= arg.nodes then
						return str .. " It's already at your limit."
					end
					local v5 = tbl.costTo(arg, v)
					local bonuses = arg.bonuses

					if bonuses then
						bonuses = arg.bonuses[v]
					end

					local flag = bonuses ~= nil

					if flag then
						flag = arg3
					end

					if flag then
						flag = arg3(arg.name, bonuses)
					end

					flag = flag or nil

					if flag then
						if v5 then
							return str .. (" Level %d gives %s and costs %d more skill points."):format(v, flag, v5)
						end
					end

					return str .. (" Your limit is level %d."):format(v)
				end
			end

			return str .. " Set a limit above 0 to let Auto Stat upgrade it."
		end,
	}

	return tbl
end)

v4("Features/Auto/Horse", function(arg)
	local Control = arg("Utility/Control")
	local Identity = arg("Utility/Identity")
	local Jobs_ = arg("Utility/Jobs")
	local Mount = arg("Utility/Mount")
	local Runner = arg("Features/Auto/Horse/Runner")
	local Ui = arg("Features/Auto/Horse/Ui")

	return function(arg2)
		local v = Mount.orchestrator(arg2, "AutoHorse")

		if v then
			local library = arg2.Library

			local function getApi(arg3)
				local api = arg2.Api
				local api2 = api

				if api2 then
					api2 = api[arg3]
				end

				local api3 = type(api2) == "table"

				if api3 then
					api3 = api2
				end

				return api3 or nil
			end

			local tbl = { buy = false, keepWen = 0 }
			local v5 = v.track(Control.register("Horse Taming", { priority = 150, label = "Horse Taming" }))

			local function fn2()
				if v5.active() then
					return nil
				end
				return Control.why("Horse Taming") or "Waiting for another feature to finish"
			end

			local v6 = nil
			local v7 = nil

			local v8 = Runner.new({
				api = getApi,
				cfg = tbl,
				blocked = fn2,
				report = function(arg3)
					if v6 then
						v6.setStatus(arg3)
					end
				end,
				notify = function(arg3)
					Identity.elevate()

					pcall(function()
						library:Notify(arg3, 6)
					end)
				end,
			})

			local function fn3(arg3)
				if v7 then
					v7:Cancel()
					v7 = nil
				end

				if v8.busy() then
					local Minigame = getApi("Minigame")

					if Minigame then
						pcall(Minigame.cancel)
					end

					v8.reset()
				end

				if v6 then
					v6.setStatus(arg3 or "Off")
				end
			end

			local function fn4()
				if v7 then
					if v7.alive then
						return
					end
				end

				v8.reset()

				v7 = Jobs_.spawn(function(arg3)
					while arg3.alive do
						local v9 = table.pack(v8.step(arg3))
						local v10, v11

						if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
							v10 = v9[1]
							v11 = v9[2]
						else
							v10 = nil
							v11 = nil
						end

						if not arg3.alive then
							return
						end

						if v11 then
							if v6 then
								v6.setStatus(v11)
							end
						end

						if arg3:sleep(math.max(tonumber(v10) or 1, 0.1)) then
							continue
						end
						return
					end
				end, { name = "AutoHorse" })
			end

			local flag = getApi("Minigame") ~= nil

			if flag then
				flag = getApi("State") ~= nil
			end

			if flag then
				flag = getApi("World") ~= nil
			end

			if flag then
				flag = getApi("Movement") ~= nil
			end

			v6 = Ui(arg2, tbl, {
				ready = flag,
				onToggle = function(arg3)
					local flag2 = arg3 == true

					if flag2 then
						flag2 = flag
					end

					v5.want(flag2)

					if flag2 then
						fn4()
					else
						fn3()
					end
				end,
			})

			v.onUnload(function()
