v4("Features/Auto/Horse/Runner", function()
	local tbl

	tbl = {
		NO_HORSE_FOR = 30,
		wen = function(arg)
			local n = math.floor(tonumber(arg) or 0)
			local str = tostring(math.abs(n))
			local str2 = str:reverse():gsub("(%d%d%d)", "%1,"):reverse()

			if str2:sub(1, 1) == "," then
				str2 = str2:sub(2)
			end

			local flag = n < 0

			if flag then
				flag = "-"
			end

			return (flag or "") .. str2
		end,
		cantAfford = function(arg, arg2, arg3)
			if arg == nil then
				return "Couldn't read what a horse costs, so Auto Buy is waiting"
			end

			if arg2 == nil then
				return "Couldn't read your Wen, so Auto Buy is waiting"
			end
			local n = math.max(0, tonumber(arg3) or 0)
			if arg + n <= arg2 then
				return nil
			end

			if not (n > 0) then
				return ("A horse costs %s Wen. You have %s"):format(tbl.wen(arg), tbl.wen(arg2))
			end
			return ("A horse costs %s Wen and you keep %s, so you need %s. You have %s"):format(tbl.wen(arg), tbl.wen(n), tbl.wen(arg + n), tbl.wen(arg2))
		end,
		tooPoor = function(arg, arg2)
			return ("A horse costs %s Wen and you have %s. The game only offers to sell it once you can afford it, so taming waits until then"):format(tbl.wen(arg), tbl.wen(arg2))
		end,
		new = function(arg)
			local api = arg.api
			local cfg = arg.cfg

			local report = arg.report or function()
			end

			local notify = arg.notify or function()
			end

			local blocked = arg.blocked or function()
				return nil
			end

			local deadline = 0
			local v = nil
			local flag = false
			local tbl2 = { tamed = 0, bought = 0 }
			local flag2 = false

			local function fn2(arg2, arg3)
				deadline = os.clock() + arg2
				v = arg3
			end

			local function fn3(arg2)
				local Minigame = api("Minigame")

				if Minigame then
					local v5 = table.pack(Minigame.explain(arg2))
					local v6, v7

					if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
						v6 = v5[1]
						v7 = v5[2]
					else
						v6 = nil
						v7 = nil
					end

					if v6 then
						if type(v7) == "string" then
							return v7
						end
					end
				end

				return "That didn't work"
			end

			local tbl3 = {
				reset = function()
					deadline = 0
					v = nil
					flag = false
					flag2 = false
					tbl2 = { tamed = 0, bought = 0 }
				end,
				busy = function()
					return flag2
				end,
				tally = function()
					return { tamed = tbl2.tamed, bought = tbl2.bought }
				end,
				step = function(arg2)
					local Minigame = api("Minigame")
					local State = api("State")
					if not Minigame then
						return 1, "Waiting for the game to load"
					end

					if not State then
						return 1, "Waiting for the game to load"
					end
					local v5 = blocked()
					if v5 then
						return 1, v5
					end
					local v6 = table.pack(State.alive())
					local v7, v8

					if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
						v7 = v6[1]
						v8 = v6[2]
					else
						v7 = nil
						v8 = nil
					end

					if v7 then
						if v8 then
							local v9 = table.pack(Minigame.horses())
							local v10, v11

							if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
								v10 = v9[1]
								v11 = v9[2]
							else
								v10 = nil
								v11 = nil
							end

							local flag3 = v10

							if flag3 then
								flag3 = type(v11) == "table"
							end

							if flag3 then
								flag3 = v11
							end

							local tbl3 = flag3 or {}
							if tbl3.owned == true then
								return 1, "You already own a horse, so there's nothing to tame"
							end

							if cfg.buy then
								flag = false
								local v12 = tbl.cantAfford(tbl3.price, tbl3.wen, cfg.keepWen)
								if v12 then
									return 1, v12
								end
							else
								if flag then
									return 1, "Tamed the horse, but it wasn't bought. Turn on Auto Buy The Horse to buy it next time"
								end

								if type(tbl3.price) == "number" then
									if type(tbl3.wen) == "number" then
										if tbl3.wen < tbl3.price then
											return 1, tbl.tooPoor(tbl3.price, tbl3.wen)
										end
									end
								end
							end

							local n = deadline - os.clock()
							if n > 0 then
								return math.min(1, n), ("%s. Trying again in %ds"):format(v or "Waiting", math.ceil(n))
							end
							flag2 = true
							local tame = Minigame.tame

							local tbl4 = {
								job = arg2,
								mode = "direct",
								travel = true,
								buy = cfg.buy == true,
								keepWen = math.max(0, tonumber(cfg.keepWen) or 0),
								stop = function()
									return blocked() ~= nil
								end,
								onStep = report,
							}

							local v12 = table.pack(tame(tbl4))
							local v13, v14

							if select("#", table.unpack(v12, 1, v12.n)) ~= 0 then
								v13 = v12[1]
								v14 = v12[2]
							else
								v13 = nil
								v14 = nil
							end

							flag2 = false
							if not arg2.alive then
								return 0
							end
							local errors = Minigame.Errors

							if not v13 then
								if v14 == errors.OWNED then
									return 1, "You already own a horse, so there's nothing to tame"
								end

								if v14 == errors.CANCELLED then
									return 1, blocked() or "Stopped"
								end

								if v14 == errors.DIED then
									return 1, "Waiting for your character"
								end

								if v14 == errors.BUSY then
									return 1, "Waiting for the training you have open to end"
								end

								if v14 == errors.NO_INPUT then
									return 1, "Your executor can't press prompts, so it can't tame the horse"
								end

								if v14 == errors.NO_HORSE then
									fn2(30, "No wild horse is out right now")
									return 1, "No wild horse is out right now. Looking again soon"
								end

								if v14 == errors.HORSE_BUSY then
									fn2(10, "Someone else is taming the horse")
									return 1, "Someone else is taming the horse. Waiting for them"
								end
								local v15 = fn3(v14)
								fn2(20, v15)
								return 1, v15
							end

							if not v14.bought then
								if v14.outcome == "lost" then
									if not v14.offered then
										return 1, "The horse threw you off. Trying again"
									end
								end

								tbl2.tamed += 1

								if v14.offered then
									if cfg.buy then
										fn2(20, "Tamed the horse, but it wasn't bought")
										return 1, "Tamed the horse, but it wasn't bought"
									end
									flag = true
									return 1, "Tamed the horse, but it wasn't bought. Turn on Auto Buy The Horse to buy it next time"
								end

								fn2(20, "Tamed the horse, but the game didn't offer to sell it. You may not have enough Wen")
								return 1, "Tamed the horse, but the game didn't offer to sell it. You may not have enough Wen"
							end

							local bought = tbl2.bought + 1
							tbl2.tamed += 1
							tbl2.bought = bought
							notify("You bought the horse. It's in your inventory now")
							return 1, "Bought the horse. It's in your inventory now"
						end
					end

					return 1, "Waiting for your character"
				end,
			}

			return tbl3
		end,
	}

	return tbl
end)

do
	v4("Features/Auto/Gourd", function(arg)
		local Control = arg("Utility/Control")
		local Identity = arg("Utility/Identity")
		local Jobs_ = arg("Utility/Jobs")
		local Mount = arg("Utility/Mount")
		local Premium = arg("UI/Premium")
		local Runner = arg("Features/Auto/Gourd/Runner")
		local Ui = arg("Features/Auto/Gourd/Ui")
		local Words = arg("Features/Auto/Gourd/Words")

		return function(arg2)
			local v = Mount.orchestrator(arg2, "AutoGourd")

			if v then
				local library = arg2.Library

				local function getApi(arg3)
					local api = arg2.Api
					local api2 = api

					if api2 then
						api2 = api[arg3]
					end

					local api3 = type(api2) == "table"

					if api3 then
						api3 = api2
					end

					return api3 or nil
				end

				local function fn2(arg3)
					Identity.elevate()

					pcall(function()
						library:Notify(arg3, 6)
					end)
				end

				local tbl = { slot = nil, buy = false, pick = "Large Gourd", keepWen = 0 }
				local v5 = nil
				local v6 = nil
				local v7 = v.track(Control.register("Auto Gourd", { priority = 150, label = "Auto Gourd" }))

				local v8 = Runner.new({
					api = getApi,
					control = v7,
					cfg = tbl,
					locked = Premium.isLocked,
					report = function(arg3)
						if v5 then
							v5.setStatus(arg3)
						end
					end,
				})

				local function fn3(arg3)
					if v6 then
						v6:Cancel()
						v6 = nil
					end

					v8.release()
					v7.want(false)

					if v5 then
						v5.setStatus(arg3 or Words.OFF)
					end
				end

				local function fn4()
					if v6 then
						if v6.alive then
							return
						end
					end

					v8.reset()
					v7.want(true)

					v6 = Jobs_.spawn(function(arg3)
						while arg3.alive do
							local v9 = table.pack(v8.step(arg3))
							local v10, autoGourd, v11

							if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
								v10 = v9[1]
								autoGourd = v9[2]
								v11 = v9[3]
							else
								v10 = nil
								autoGourd = nil
								v11 = nil
							end

							if not arg3.alive then
								return
							end

							if autoGourd then
								if v5 then
									v5.setStatus(autoGourd)
								end
							end

							if v11 then
								v8.release()
								v7.want(false)

								if autoGourd then
									fn2("Auto Gourd: " .. autoGourd)
								end

								return
							end

							if arg3:sleep(math.max(tonumber(v10) or 1, 0)) then
								continue
							end
							return
						end
					end, { name = "AutoGourd" })

					if v6 then
						if not v6.alive then
							v6 = nil
						end
					end
				end

				local flag = getApi("State") ~= nil

				if flag then
					flag = getApi("Consumables") ~= nil
				end

				if flag then
					flag = getApi("Economy") ~= nil
				end

				if flag then
					flag = getApi("Movement") ~= nil
				end

				v5 = Ui(arg2, tbl, {
					ready = flag,
					onToggle = function(arg3)
						if not arg3 then
							fn3()
							return
						end

						if not flag then
							fn3()
							return
						end

						if Premium.isLocked() then
							fn3()
						else
							fn4()
						end
					end,
				})

				v.onUnload(function()
					fn3()
				end)

				v.finalize()
				return {}
			end
		end
	end)
end

v4("Features/Auto/Gourd/Words", function()
	local tbl = {
		OFF = "Off",
		LOADING = "The game is still loading. Trying again in a moment.",
		NOT_SLAYER = "Gourds are for Slayers. Demons fill their bar with souls instead.",
		FULL = "Your Slayer bar is full. There's nothing left for gourds to do.",
		PREMIUM = "Auto Gourd is a premium feature.",
		OUT = "You're out of gourds. Turn on Buy More When You Run Out, or buy some from Ren at Butterfly Estate.",
		HANDS = "Waiting for your hands to be free.",
		NO_SELLER = "Couldn't find Ren's gourd stand. Trying again soon.",
		TRAVEL = "Couldn't get to Ren's gourd stand. Trying again soon.",
		NOT_CREDITED = "The game took a gourd but your Slayer bar didn't go up, so Auto Gourd stopped to keep the rest.",
		number = function(arg)
			local str = tostring(math.floor(tonumber(arg) or 0))
			local v = table.pack(str:match("^(%-?)(%d+)$"))
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v6 then
				local str2 = v6:reverse():gsub("(%d%d%d)", "%1,"):reverse()

				if str2:sub(1, 1) == "," then
					str2 = str2:sub(2)
				end

				return v5 .. str2
			end

			return str
		end,
	}

	local function plural(arg, arg2)
		if arg ~= 1 then
			return ("%s %ss"):format(tbl.number(arg), arg2)
		end
		return ("1 %s"):format(arg2)
	end

	tbl.plural = plural

	tbl.stopped = function(arg)
		return "Stopped: " .. tostring(arg)
	end

	tbl.bar = function(arg)
		if type(arg) == "table" then
			if arg.level then
				return ("Slayer bar level %d: %s / %s"):format(arg.level, tbl.number(arg.current), tbl.number(arg.max))
			end
		end

		return nil
	end

	tbl.using = function(arg, arg2)
		return ("Using a %s (+%s)."):format(tostring(arg), tbl.number(arg2))
	end

	tbl.progress = function(arg, arg2, arg3)
		local tbl2 = {}

		if arg.used > 0 then
			tbl2[#tbl2 + 1] = ("Used %s (+%s)."):format(plural(arg.used, "gourd"), tbl.number(arg.points))
		end

		local v = tbl.bar(arg2)

		if v then
			tbl2[#tbl2 + 1] = v .. "."
		end

		if arg3 then
			if arg3 > 0 then
				tbl2[#tbl2 + 1] = ("%s left."):format(plural(arg3, "gourd"))
			end
		end

		return table.concat(tbl2, " ")
	end

	tbl.waitingWen = function(arg, arg2, arg3)
		return ("Waiting for Wen: a %s costs %s, and you keep %s."):format(tostring(arg), tbl.number(arg2), tbl.number(arg3))
	end

	tbl.buying = function(arg, arg2)
		return ("Buying %s from Ren..."):format(plural(arg, arg2))
	end

	tbl.bought = function(arg, arg2, arg3)
		return ("Bought %s for %s Wen."):format(plural(arg, arg2), tbl.number(arg3))
	end

	return tbl
end)

