v4("Features/Auto/Gourd/Runner", function(arg)
	local Plan = arg("Features/Auto/Gourd/Plan")
	local Words = arg("Features/Auto/Gourd/Words")
	local tbl = { "Small Gourd", "Medium Gourd", "Large Gourd" }

	return { new = function(arg2)
		local api = arg2.api
		local control = arg2.control
		local cfg = arg2.cfg

		local report = arg2.report or function()
		end

		local tbl2 = { lend = nil, trip = nil }
		local tbl3 = { used = 0, points = 0, bought = 0, misses = 0 }

		local function fn2(arg3, arg4)
			local v = api(arg3)

			if v then
				if type(v.explain) == "function" then
					local v5 = table.pack(pcall(v.explain, arg4))
					local v6, v7, v8

					if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
						v6 = v5[1]
						v7 = v5[2]
						v8 = v5[3]
					else
						v6 = nil
						v7 = nil
						v8 = nil
					end

					if v6 then
						if v7 then
							if type(v8) == "string" then
								return v8
							end
						end
					end
				end
			end

			return tostring(arg4)
		end

		local function fn3()
			local State = api("State")
			if not State then
				return nil
			end
