						if v12 ~= "elsewhere" then
							local v13 = table.pack(Dungeons.points())
							local v14, v15

							if select("#", table.unpack(v13, 1, v13.n)) ~= 0 then
								v14 = v13[1]
								v15 = v13[2]
							else
