				flag2 = fn15()
			end

			flag2 = flag2 or false

			v6 = Ui.build(arg2, tbl, {
				ready = flag,
				stock = fn14(),
				weapons = getNames(),
				recipes = fn16(),
				kinds = Cards.kinds(flag2),
				onToggle = function(arg3)
					if arg3 then
						if flag then
							if Premium.isLocked() then
								local v10 = fn9
								local v11 = nil
								local str2 = str or "off"
								v10(v11, str2)
							else
								fn11()
							end
						else
							fn9(nil, str or "off")
						end
					else
