			if v6 then
				if flag then
					local str2 = ""
					local str3 = ""
					local str4 = ""

					v.track(Jobs_.interval(5, function()
						pcall(function()
							local v10 = fn16()
							local str5 = table.concat(v10, ",")

							if str5 ~= str4 then
								if #v10 > 0 then
