v4("Features/Auto/AutoDungeon/Ui", function(arg)
	local Identity = arg("Utility/Identity")
	local Log = arg("Utility/Log")
	local Place = arg("UI/Place")
	local Cards = arg("Features/Auto/AutoDungeon/Pages/Cards")
	local Craft = arg("Features/Auto/AutoDungeon/Pages/Craft")
	local Shop = arg("Features/Auto/AutoDungeon/Pages/Shop")
	local tbl = { FALLBACK = { "Tower", "Auto" }, RUN_BOX = "Auto Dungeon", TABBOX = "Auto Dungeon Pages" }

	tbl.PAGES = {
		{ name = "Cards", icon = "layers", build = Cards, side = "Right" },
		{ name = "Shop & Chest", icon = "store", build = Shop, side = "Right" },
		{ name = "Craft & Report", icon = "anvil", build = Craft, side = "Left" },
	}

	tbl.pickedSet = function(arg2)
		local tbl2 = nil
		local v = pairs
		local tbl3 = arg2 or {}
		local v5 = table.pack(v(tbl3))
		local v6, v7, v8

		if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
			v6 = v5[1]
			v7 = v5[2]
			v8 = v5[3]
		else
			v6 = nil
			v7 = nil
			v8 = nil
		end

		for k, v9 in v6, v7, v8 do
			if v9 then
				tbl2 = tbl2 or {}
				tbl2[k] = true
			end
		end

		return tbl2
	end

	local function fn2(arg2)
		local v = table.pack(Place.tab(arg2, tbl.FALLBACK))
		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
		else
			v5 = nil
			v6 = nil
		end

		local flag = not v6

		if flag then
			flag = type(arg2.Tabs) == "table"
		end

		if flag then
			flag = v5 ~= nil
		end

		if flag then
			flag = v5 == arg2.Tabs.Auto
		end

		if flag then
			return "Right", "Right"
		end
		return "Left", "Right"
	end

	local function getOff(arg2, arg3, arg4, arg5)
		local toggles = arg3.Toggles

		arg2:AddToggle("AD_Enabled", {
			Text = "Auto Dungeon",
			Default = false,
			Premium = true,
			Disabled = arg5.ready ~= true,
			Tooltip = "Climbs Ouwigahara for you: goes in through the portal, readies up, fights every floor from underneath the enemies and picks your reward cards.",
			Callback = function(autoDungeon)
				arg5.onToggle(autoDungeon == true)
			end,
		}):AddKeyPicker("AD_Key", { Default = "None", Premium = true, Mode = "Toggle", Text = "Auto Dungeon", SyncToggleState = true })

		local v = arg2:AddDependencyBox()
		local Off = v:AddLabel("Off", true)
		v:AddDivider()

		v:AddToggle("AD_Enter", {
			Text = "Go In From The Open World",
			Default = arg4.enter,
			Premium = true,
			Tooltip = "Takes Blacksmith Togane's quest if you haven't yet, then goes through the Ouwigahara portal. You need to be level 65.",
			Callback = function(goInFromTheOpenWorld)
				arg4.enter = goInFromTheOpenWorld == true
			end,
		})

		v:AddToggle("AD_Again", {
			Text = "Keep Climbing",
			Default = arg4.keepClimbing,
			Premium = true,
			Tooltip = "Leaves as soon as a climb ends and goes straight back in for the next one. Points you haven't spent are lost when you leave. Turn it off to stay in the shops and spend them.",
			Callback = function(keepClimbing)
				arg4.keepClimbing = keepClimbing == true
			end,
		})

		v:AddToggle("AD_SkipBreaks", {
			Text = "Skip The Break Between Floors",
			Default = arg4.skipBreaks,
			Premium = true,
			Tooltip = "Votes to start the next floor right away instead of waiting 10 seconds.",
			Callback = function(skipTheBreakBetweenFloors)
				arg4.skipBreaks = skipTheBreakBetweenFloors == true
			end,
		})

		v:AddDropdown("AD_Side", {
			Text = "Position",
			Values = { "Above (Recommended)", "Below", "Use Autofarm Settings" },
			Default = "Above (Recommended)",
			Premium = true,
			Tooltip = "Which side of the enemy to fight from. Above is recommended in the tower: from below you end up under the arena floor, and swings from there often don't land.",
			Callback = function(position)
				if position ~= "Below" then
					if position ~= "Use Autofarm Settings" then
						arg4.side = "Above"
					else
						arg4.side = nil
					end
				else
					arg4.side = "Below"
				end
			end,
		})

		v:AddToggle("AD_Elites", {
			Text = "Fight Elites First",
			Default = arg4.preferElites,
			Premium = true,
			Tooltip = "Goes for elites and floor bosses before the ordinary enemies. They're worth more points.",
			Callback = function(fightElitesFirst)
				arg4.preferElites = fightElitesFirst == true
			end,
		})

		v:AddSlider("AD_StopAtFloor", {
			Text = "Stop At Floor",
			Default = arg4.stopAtFloor,
			Premium = true,
			Min = 0,
			Max = 100,
