			Callback = function(stopAtFloor)
				arg4.stopAtFloor = tonumber(stopAtFloor) or arg4.stopAtFloor
			end,
		})

		v:AddSlider("AD_StopAtPoints", {
			Text = "Stop At Points",
			Default = arg4.stopAtPoints,
			Min = 0,
			Max = 200000,
			Rounding = 0,
			Premium = true,
			Tooltip = "Ends the climb once the run has banked this many points, so they get spent instead of lost to a death. Leave it at 0 to climb until you run out of hearts.",
			Callback = function(stopAtPoints)
				arg4.stopAtPoints = tonumber(stopAtPoints) or arg4.stopAtPoints
			end,
		})

		v:AddToggle("AD_EndFaster", {
			Text = "End The Run Faster",
			Default = arg4.endFaster == true,
			Premium = true,
			Risky = true,
			Tooltip = "Once you reach Stop At Floor or Stop At Points, resets your character instead of waiting for the enemies to finish you, so the climb ends and the shops open sooner. Each reset costs a heart, the same as any death. It does nothing unless one of the stop marks above is set.",
			Callback = function(endTheRunFaster)
				arg4.endFaster = endTheRunFaster == true
			end,
		})

		v:AddDropdown("AD_Weapon", {
			Text = "Fighting Method",
			Values = arg5.weapons or { "Anything That Fights" },
			Default = "Anything That Fights",
			Searchable = true,
			Premium = true,
			Tooltip = "Which weapon or fighting style to hold while it fights. Anything That Fights takes the first one on your hotbar.",
			Callback = function(fightingMethod)
				local fightingMethod2 = fightingMethod ~= "Anything That Fights"

				if fightingMethod2 then
					fightingMethod2 = fightingMethod
				end

				arg4.weapon = fightingMethod2 or nil
			end,
		})

		v:AddToggle("AD_Retry", {
			Text = "Keep Trying To Get Back In",
			Default = arg4.retry,
			Premium = true,
			Tooltip = "If it ends up somewhere it doesn't recognise, it keeps trying to get back into a climb instead of sitting there.",
			Callback = function(keepTryingToGetBackIn)
				arg4.retry = keepTryingToGetBackIn == true
			end,
		})

		v:SetupDependencies({ { toggles.AD_Enabled, true } })
		return Off
	end

	tbl.build = function(arg2, arg3, arg4)
		local toggles = arg2.Toggles
		if type(arg2.Tabs) ~= "table" then
			return nil
		end

		if not toggles then
			return nil
		end
		local v = table.pack(fn2(arg2))
		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
		else
			v5 = nil
			v6 = nil
		end

		local v7 = Place.groupbox(arg2, tbl.RUN_BOX, "castle", { fallback = tbl.FALLBACK, side = v5 })

		if v7 then
			local tbl2 = {}

			local function fn3(arg5, arg6, arg7)
				if arg5 ~= nil then
					if tbl2[arg6] ~= arg7 then
						Identity.elevate()

						if pcall(arg5.SetText, arg5, arg7) then
							tbl2[arg6] = arg7
						end

						return
					end
				end
			end

			local function fn4(arg5, arg6)
				local options = arg2.Options

				if options then
					options = arg2.Options[arg5]
				end

				if options then
					Identity.elevate()
					pcall(options.SetValues, options, arg6)
					return
				end
			end

			local off = getOff(v7, arg2, arg3, arg4)

			local tbl3 = {
				setStatus = function(arg5)
					fn3(off, "status", arg5)
				end,
				setWeapons = function(arg5)
					fn4("AD_Weapon", arg5)
				end,
				setStock = function(arg5)
					fn4("AD_Spend", arg5)
				end,
			}

			local tbl4 = { env = arg2, cfg = arg3, hooks = arg4, write = fn3, setList = fn4, pickedSet = tbl.pickedSet }
			local v8 = table.pack(ipairs(tbl.PAGES))
			local v9, v10, v11

			if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
				v9 = v8[1]
				v10 = v8[2]
				v11 = v8[3]
			else
				v9 = nil
				v10 = nil
				v11 = nil
			end

			for _, v12 in v9, v10, v11 do
				Identity.elevate()
				local flag = v6 == v5

				if flag then
					flag = v6
				end

				local side = flag or v12.side or v6
				local v13 = table.pack(pcall(Place.groupbox, arg2, v12.name, v12.icon, { fallback = tbl.FALLBACK, side = side }))
				local v14, v15

				if select("#", table.unpack(v13, 1, v13.n)) ~= 0 then
					v14 = v13[1]
					v15 = v13[2]
				else
					v14 = nil
					v15 = nil
				end

				local flag2 = false
				local v16 = nil

				if v14 then
					if v15 then
						local v17 = table.pack(pcall(v12.build, v15, tbl4))
						local v18, v19

						if select("#", table.unpack(v17, 1, v17.n)) ~= 0 then
							v18 = v17[1]
							v19 = v17[2]
						else
							v18 = nil
							v19 = nil
						end

						flag2 = v18
						v16 = v19
					end
				end

				local devwarn, str, str2, str3, v17, v18

				if flag2 then
					if type(v16) ~= "table" then
						if flag2 then
							continue
						end
						devwarn = Log.devwarn
						str = "AutoDungeon"
						str2 = "the %s page didn't build: %s"
						str3 = tostring(v12.name)
						v17 = tostring
						v18 = v14

						if v18 then
							v18 = v16
						end

						v18 = v18 or v15
						devwarn(str, str2, str3, v17(v18))
					else
						local v19 = table.pack(pairs(v16))
						local v20, v21, v22

						if select("#", table.unpack(v19, 1, v19.n)) ~= 0 then
							v20 = v19[1]
							v21 = v19[2]
							v22 = v19[3]
						else
							v20 = nil
							v21 = nil
							v22 = nil
						end

						for k, v23 in v20, v21, v22 do
							if tbl3[k] == nil then
								tbl3[k] = v23
							end
						end
					end
				else
					if flag2 then
						continue
					end
					devwarn = Log.devwarn
					str = "AutoDungeon"
					str2 = "the %s page didn't build: %s"
					str3 = tostring(v12.name)
					v17 = tostring
					v18 = v14

					if v18 then
						v18 = v16
					end

					v18 = v18 or v15
					devwarn(str, str2, str3, v17(v18))
				end
			end

			return tbl3
		end

		return nil
	end

	return tbl
end)

v4("Features/Auto/AutoDungeon/Pages/Shop", function()
	return function(arg, arg2)
		local cfg = arg2.cfg
		local hooks = arg2.hooks
		local write = arg2.write

		arg:AddDropdown("AD_Spend", {
			Text = "Spend Points On",
			Premium = true,
			Values = hooks.stock or {},
			Default = {},
			Multi = true,
			Searchable = true,
			Tooltip = "What to buy before leaving the tower, since unspent points are lost on the way out: Exp and masteries from the Tower Crystal, Wen and Refinement Ore (Mythic too) from Changer Zeni, and the Ouwigahara Chest. The dearest pick is bought first. Leave it empty and it buys Exp. The list fills in once you are in the tower.",
			Callback = function(spendPointsOn)
				local spend = nil
				local v = pairs
				local spendPointsOn2 = spendPointsOn or {}
				local v5 = table.pack(v(spendPointsOn2))
				local v6, v7, v8

				if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
					v6 = v5[1]
					v7 = v5[2]
					v8 = v5[3]
				else
					v6 = nil
					v7 = nil
					v8 = nil
				end

				for k, v9 in v6, v7, v8 do
					if v9 then
						spend = spend or {}
						spend[#spend + 1] = k
					end
				end

				if spend then
					table.sort(spend)
				end

				cfg.spend = spend
			end,
		})

		arg:AddSlider("AD_LeaveDelay", {
			Text = "Wait Before Leaving",
			Default = cfg.leaveDelay or 0,
			Min = 0,
			Max = 600,
			Rounding = 0,
			Suffix = "s",
			Premium = true,
			Tooltip = "With Keep Climbing on, how long to stay in the shops after a climb before leaving for the next one. Use it to buy something yourself first. 0 leaves as soon as the shopping is done.",
			Callback = function(waitBeforeLeaving)
				cfg.leaveDelay = tonumber(waitBeforeLeaving) or cfg.leaveDelay
			end,
		})

		local v = arg:AddLabel("Your run points show here once you are in the tower.", true)

		arg:AddButton({
			Text = "Buy Now",
			Premium = true,
			Tooltip = "Spends your points on the picks above right now, the same way the farm does before it leaves. Only in the shops, once your climb is over.",
			Func = function()
				if hooks.buyNow then
					hooks.buyNow()
				end
			end,
		})

		arg:AddButton({
			Text = "Leave The Tower",
			Premium = true,
			DoubleClick = true,
			Risky = true,
			Tooltip = "Leaves Ouwigahara right now and takes you back to the server you came from. Points you haven't spent are lost. Click twice to confirm.",
			Func = function()
				if hooks.leaveNow then
					hooks.leaveNow()
				end
			end,
		})

		arg:AddButton({
			Text = "Unlock The Tower (Lv 65)",
			Premium = true,
			DoubleClick = true,
			Tooltip = "Takes Blacksmith Togane's forge quest in Hidden Mist Village, then goes through the Ouwigahara portal, which finishes the quest and takes you into the tower. You need to be level 65. Click twice to confirm.",
			Func = function()
				if hooks.unlock then
					hooks.unlock()
				end
			end,
		})

		return { setPoints = function(arg3)
			write(v, "points", arg3)
		end }
	end
end)

do
	v4("Features/Auto/AutoDungeon/Pages/Craft", function()
		return function(arg, arg2)
