				{ label = "Cooldown Reduction", stat = "Cooldown Reduction Factor" },
				{ label = "Max Stamina", stat = "Max Stamina" },
				{ label = "Stamina Regen", stat = "Stamina Regen Speed" },
				{ label = "Move Speed", stat = "Movement Speed Factor" },
				{ label = "Block Points", stat = "Block Points" },
			},
			KINDS = { "Points", "Fortune", "Stat", "Reroll", "Revive", "SwapMap", "SkipFloor", "Skip", "Event" },
		}

		tbl3.ROGUE_KINDS = { "Potion", "Weapon", "Skill", "Clan", "AscendClan", "Forge", "Trade", "SkillSwap" }

		tbl3.EVENT_HAND = {
			{ label = "Only If It Helps", value = "helps" },
			{ label = "Never Add An Event", value = "never" },
			{ label = "Always Add One", value = "always" },
		}

		tbl3.EVENT_HAND_DEFAULT = "Only If It Helps"

		local function fn2(arg2, arg3)
			if type(arg2) == "number" then
				if arg2 == arg2 then
					return arg2
				end
			end

			return arg3
		end

		local function fn3(arg2, arg3)
			local flag = type(arg2) == "table"

			if flag then
				flag = arg3 ~= nil
			end

			if flag then
				flag = arg2[arg3] == true
			end

			return flag
		end

		local function fn4(arg2, arg3, arg4)
			return math.max(arg3, math.min(arg4, arg2))
		end

		local function fn5(arg2)
			return math.min(arg2, 480)
		end

		local function fn6(arg2)
			return -1000 + fn4(arg2, -500, 500) / 10
		end

		tbl3.kinds = function(arg2)
			local tbl4 = {}
			local v = table.pack(ipairs(tbl3.KINDS))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
