			end

			if arg2 then
				local v8 = table.pack(ipairs(tbl3.ROGUE_KINDS))
				local v9, v10, v11

				if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
					v9 = v8[1]
					v10 = v8[2]
					v11 = v8[3]
				else
					v9 = nil
					v10 = nil
					v11 = nil
				end

				for _, v12 in v9, v10, v11 do
