		end

		tbl3.statLabels = function()
			local labels = {}
			local v = table.pack(ipairs(tbl3.STATS))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				labels[#labels + 1] = v8.label
			end

			return labels
		end

		tbl3.statSet = function(arg2)
			if type(arg2) ~= "table" then
