			end
			local tbl4 = nil
			local v = table.pack(ipairs(tbl3.STATS))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				if arg2[v8.label] then
					tbl4 = tbl4 or {}
					tbl4[v8.stat] = true
				end
			end

			return tbl4
		end

		tbl3.eventHandLabels = function()
			local labels = {}
			local v = table.pack(ipairs(tbl3.EVENT_HAND))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				labels[#labels + 1] = v8.label
				continue
			end

			return labels
		end

		tbl3.eventHandPolicy = function(arg2)
			local v = table.pack(ipairs(tbl3.EVENT_HAND))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				if v8.label == arg2 then
					return v8.value
				end

				if v8.value == arg2 then
					return v8.value
				end
			end

			return "helps"
		end

		local function fn7(arg2)
			return fn2(arg2.health, 1) < fn2(arg2.healBelow, 0)
		end

		local function fn8(arg2)
			return fn2(arg2.hearts, 0) < fn2(arg2.maxHearts, 0)
		end

		local function fn9(arg2)
			if fn7(arg2) then
				return true
			end
			local v = fn2(arg2.hearts, nil)
			local v5 = fn2(arg2.maxHearts, nil)
			local flag = v ~= nil

			if flag then
				flag = v5 ~= nil
			end

			if flag then
				flag = v5 >= 2
			end

			if flag then
				flag = v <= 1
			end

			return flag
		end

		local function fn10(arg2)
			local v = fn2(arg2.lastDeathFloor, nil)
			if v == nil then
				return false
			end
			local v5 = fn2(arg2.floor, nil)
			if v5 == nil then
				return true
			end
			return v5 - v < 3
		end

		tbl3.wagerSafe = function(arg2)
			local tbl4 = arg2 or {}
			local flag = fn2(tbl4.hearts, 0) >= 2

			if flag then
