			end

			return flag
		end

		local function fn11(arg2, arg3)
			if arg2 == "Pacifist" then
				if arg3.skills then
					return -30, 0
				end
			end

			local n = fn2(tbl[arg2], 0)

			if arg2 == "Wager" then
				local n7 = tbl3.wagerSafe(arg3)

				if n7 then
					n7 = 20
				end

				n = n7 or -30
			end

			if arg3.skills then
				n += fn2(tbl2[arg2], 0)
			end

			local points = 0
			local v = Events.get(arg2)

			if arg3.greedy then
				if v then
					if v.scope == "Floor" then
						if type(v.points) == "number" then
							if not fn9(arg3) then
								points = 60 * (v.points - 1)
								n += points
							end
						end
					end
				end
			end

			return n, points
		end

		local function fn12(event, arg2, arg3)
			local v = table.pack(fn11(event, arg2))
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if not fn3(arg2.avoid, "Event") then
				if not fn3(arg2.eventAvoid, event) then
					if events[event] then
						if arg3 then
							return 999, "hurt"
						end
					end

					if fn3(arg2.eventPrefer, event) then
						return 400 + fn4(v5, -200, 200) / 10, "named"
					end

					if v5 >= 0 then
						if fn3(arg2.prefer, "Event") then
							return fn5(v5 + 200), "kind"
						end
					end

					if event == "Wager" then
						if v5 > 0 then
							return v5, "wager"
						end
					end

					if v6 > 0 then
						if v5 > 0 then
							return fn5(v5), "greedy"
						end
					end

					return fn5(v5), "best"
				end
			end

			return fn6(v5), "avoided"
		end

		local function fn13(stat, arg2)
			local v = fn2(stats[stat], 0)

			if arg2.skills then
				v += fn2(stats2[stat], 0)
			end

			return v
		end

		local function getData(arg2)
			local data = type(arg2.data) == "table"

			if data then
				data = arg2.data
			end

			return data or {}
		end

		tbl3.score = function(arg2, arg3)
			local tbl4 = arg3 or {}
			local type_ = arg2.type
			local data = getData(arg2)
			local v = fn2(arg2.rarity, 1)
			local v5 = fn7(tbl4)

			if type_ ~= "Heal" then
				if type_ ~= "ExtraLife" then
					if type_ ~= "Event" then
						local v6 = types[type_]
						local n = 0

						if v6 then
							local n7 = v6.base + v6.perRarity * v
							local skills = tbl4.skills

							if skills then
								skills = fn2(v6.skills, 0)
							end

							n = n7 + (skills or 0)
						end

						local stat = arg2.stat or data.Stat

						if type_ == "Stat" then
							n += fn13(stat, tbl4)
						end

						if fn3(tbl4.avoid, type_) then
							return fn6(n), "avoided"
						end

						if type_ == "Stat" then
							if fn3(tbl4.statPrefer, stat) then
								return fn5(n + 200), "stat"
							end
						end

						if fn3(tbl4.prefer, type_) then
							return fn5(n + 200), "kind"
						end
						return fn5(n), "best"
					end

					return fn12(arg2.event or data.Event, tbl4, v5)
				end

				if fn8(tbl4) then
					return 500, "heart"
				end
				return -1, "best"
			end

			if v5 then
				return 1000, "hurt"
			end
			return 2, "best"
		end

		local function fn14(arg2, arg3)
			local v = nil
			local v5 = nil
			local v6 = nil
			local str = nil
			local v7 = table.pack(ipairs(arg2.cards))
			local v8, v9, v10

			if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
				v8 = v7[1]
				v9 = v7[2]
				v10 = v7[3]
			else
				v8 = nil
				v9 = nil
				v10 = nil
			end

			for _, v11 in v8, v9, v10 do
				if v11.type == "Skip" then
					v = v or v11
					continue
				end
				local v12 = table.pack(tbl3.score(v11, arg3))
				local v13, v14

				if select("#", table.unpack(v12, 1, v12.n)) ~= 0 then
					v13 = v12[1]
					v14 = v12[2]
				else
					v13 = nil
					v14 = nil
				end

				if v5 ~= nil then
					if not (v6 < v13) then
