				end
			end

			if v then
				return v, 0, "skipAvoided"
			end

			if v5 then
				return v5, v6, str
			end
			return arg2.cards[1], 0, "best"
		end

		tbl3.choose = function(arg2, arg3)
			if type(arg2) ~= "table" then
				return nil, "empty"
			end

			if type(arg2.cards) ~= "table" then
				return nil, "empty"
			end

			if #arg2.cards == 0 then
				return nil, "empty"
			end
			local tbl4 = arg3 or {}
			if arg2.eventHand then
				return fn14(arg2, tbl4)
			end
			local v = nil
			local v5 = nil
			local str = nil
			local v6 = nil
			local flag = true
			local count = 0
			local v7 = table.pack(ipairs(arg2.cards))
