				v8 = v7[1]
				v9 = v7[2]
				v10 = v7[3]
			else
				v8 = nil
				v9 = nil
				v10 = nil
			end

			for _, v11 in v8, v9, v10 do
				local v12 = table.pack(tbl3.score(v11, tbl4))
				local v13, v14

				if select("#", table.unpack(v12, 1, v12.n)) ~= 0 then
					v13 = v12[1]
					v14 = v12[2]
				else
					v13 = nil
					v14 = nil
				end

				if v == nil then
					v = v11
					v5 = v13
					str = v14
				elseif v5 < v13 then
					v = v11
					v5 = v13
					str = v14
				end

