	local DemonProgression = arg("Features/Auto/DemonProgression")
	local EvilArt = arg("Features/Auto/EvilArt")
	local FinalSelection = arg("Features/Main/FinalSelection")
	local Host = arg("Tabs/Host")
	local PowerQuests = arg("Features/Auto/PowerQuests")
	local Questlines = arg("Features/Auto/Questlines")
	local Schematics = arg("Features/Main/Schematics")

	return function(arg2)
		local config = arg2.Config
		local api = arg2.Api or {}
		local quests = arg2.Tabs.Quests

		if config.AutoQuest then
			Quest(Host.at(arg2, quests, "Left", api.Quests))
		end

		if config.Questlines then
			Questlines(Host.at(arg2, quests, "Left"))
		end

		if config.PowerQuests then
			PowerQuests(Host.at(arg2, quests, "Left", api.Quests))
		end

		if config.AutoPickup then
			AutoPickup(Host.at(arg2, quests, "Left"))
		end

		if config.DemonProgression then
			local v = Host.at(arg2, quests, "Right", api.Demon)
			v.SaveManager = arg2.SaveManager
			DemonProgression(v)
		end

		if config.EvilArt then
			EvilArt(Host.at(arg2, quests, "Right"))
		end

		if config.FinalSelection then
			FinalSelection(Host.at(arg2, quests, "Right", api.FinalSelection))
		end

		if config.Schematics then
			Schematics(Host.at(arg2, quests, "Right"))
		end
	end
end)

