					end
				elseif tbl2.need then
					tbl3[#tbl3 + 1] = ("Needs level %d."):format(tbl2.need)
				end
			elseif tbl2.need then
				tbl3[#tbl3 + 1] = ("Needs level %d."):format(tbl2.need)
			end

