	tbl.pays = function(arg, arg2)
		if type(arg) ~= "table" then
			return nil
		end
		local tbl2 = {}

		if tonumber(arg.exp) then
			tbl2[#tbl2 + 1] = ("%s exp"):format(tbl.number(arg.exp))
		end

		if tonumber(arg.wen) then
			tbl2[#tbl2 + 1] = ("%s Wen"):format(tbl.number(arg.wen))
