v4("Features/Auto/PowerQuests/Catalog", function()
	local tbl = { BREATHING = "Breathing", STYLE = "Fighting Style" }
	tbl.KINDS = { tbl.BREATHING, tbl.STYLE }

	local tbl2 = {
		[tbl.BREATHING] = "^Ill learn (.+) Breathing%(Lv (%d+)%)$",
		[tbl.STYLE] = "^Ill learn the (.+) Style%(Lv (%d+)%)$",
	}

