		local v5 = table.pack(v(flag))
		local v6, v7, v8

		if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
			v6 = v5[1]
			v7 = v5[2]
			v8 = v5[3]
		else
			v6 = nil
			v7 = nil
			v8 = nil
		end

		for _, v9 in v6, v7, v8 do
			local parse = tbl.parse
			local v10 = arg2
			local flag2 = type(v9) == "table"

			if flag2 then
				flag2 = v9.key
			end

			flag2 = flag2 or nil
			local v11 = table.pack(parse(v10, flag2))
			local v12, v13

			if select("#", table.unpack(v11, 1, v11.n)) ~= 0 then
				v12 = v11[1]
				v13 = v11[2]
			else
				v12 = nil
				v13 = nil
			end

			if v12 then
				tbl4[#tbl4 + 1] = { name = v12, key = v9.key, level = v13, giver = v9.giver }
			end
		end

		table.sort(tbl4, function(arg3, arg4)
			if (arg3.level or 0) == (arg4.level or 0) then
