		end)

		return tbl4
	end

	tbl.names = function(arg, arg2)
		local v = tbl.list(arg, arg2)

		if #v ~= 0 then
			local names = {}
			local v5 = table.pack(ipairs(v))
			local v6, v7, v8

			if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
				v6 = v5[1]
				v7 = v5[2]
				v8 = v5[3]
			else
				v6 = nil
				v7 = nil
				v8 = nil
			end

			for _, v9 in v6, v7, v8 do
				names[#names + 1] = v9.name
			end

			return names
		end

		return table.move(tbl.FALLBACK[arg2] or {}, 1, #(tbl.FALLBACK[arg2] or {}), 1, {})
	end

	tbl.find = function(arg, arg2, arg3)
		local v = table.pack(ipairs(tbl.list(arg, arg2)))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for _, v8 in v5, v6, v7 do
			if v8.name == arg3 then
				return v8
			end
		end

		return nil
	end

	tbl.label = function(arg, arg2)
		if arg == tbl.STYLE then
			return ("the %s Style"):format(tostring(arg2))
		end
