v4("Features/Auto/PowerQuests/Plan", function(arg)
	local n = 273110416
	local Words = arg("Features/Auto/PowerQuests/Words")
	local tbl = { on_cooldown = true, not_near = true }

	local function getMatch(reason)
		local match = type(reason) == "string"

		if match then
			match = reason:match("[^/]+$")
		end

		return match or reason
	end

	local function fn2(arg2)
		local v = ipairs
		local objectives = type(arg2.objectives) == "table"

		if objectives then
			objectives = arg2.objectives
		end

		objectives = objectives or {}
		local v5 = table.pack(v(objectives))
		local v6, v7, v8

		if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
			v6 = v5[1]
			v7 = v5[2]
			v8 = v5[3]
		else
			v6 = nil
			v7 = nil
			v8 = nil
		end

		for _, v9 in v6, v7, v8 do
			if type(v9) ~= "table" then
				continue
			end

			if v9.kind ~= "deliver" then
				continue
			end

			if type(v9.anyOf) ~= "table" then
				continue
			end

			if not (#v9.anyOf > 0) then
				continue
			end
			local n7 = 0
			local v10 = table.pack(ipairs(v9.anyOf))
			local v11, v12, v13

			if select("#", table.unpack(v10, 1, v10.n)) ~= 0 then
				v11 = v10[1]
				v12 = v10[2]
				v13 = v10[3]
			else
				v11 = nil
				v12 = nil
				v13 = nil
			end

			for _, v14 in v11, v12, v13 do
				local v15 = tonumber
				local held = arg2.held

				if held then
					held = arg2.held(v14)
				end

				n7 += v15(held) or 0
			end

			return {
				need = tonumber(v9.remaining) or tonumber(v9.count) or 0,
				have = n7,
				npc = v9.npc,
				task = v9.task,
			}
		end

		return nil
	end

	local tbl2 = { step = function(arg2)
		if type(arg2) ~= "table" then
			return { kind = "wait", line = Words.LOADING }
		end

		if not arg2.key then
			return { kind = "blocked", line = Words.NO_QUEST }
		end

		if arg2.status == nil then
			return { kind = "wait", line = Words.LOADING }
		end
		local v = n

		if arg2.status ~= "Done" then
			if arg2.status ~= "None" then
				local v5 = fn2(arg2)

				if v5 then
					if v5.have < v5.need then
						local fishing = type(arg2.fishing) == "table"

						if fishing then
							fishing = arg2.fishing
						end

						fishing = fishing or {}

						if fishing.available then
							if fishing.rod then
								return {
									kind = "fish",
									line = Words.fishing(v5.have, v5.need),
									need = v5.need,
									have = v5.have,
								}
							end

							return { kind = "blocked", line = Words.noRod(v5.need - v5.have) }
						end

						return { kind = "blocked", line = Words.noFishing(v5.need - v5.have) }
					end
				end

				return { kind = "quest", line = Words.working(arg2.label) }
			end

			local check = arg2.check
			if type(check) ~= "table" then
				return { kind = "wait", line = Words.LOADING }
			end

			if not check.acceptable then
				if not tbl[getMatch(check.reason)] then
					return { kind = "blocked", line = Words.refused(arg2.label, check.text, check.detail) }
				end
			end

			return { kind = "quest", line = Words.taking(arg2.label) }
		end

		return { kind = "done", line = Words.already(arg2.label) }
	end }

	return tbl2
end)

