v4("Features/Main/FinalSelection/Words", function()
	local tbl

	tbl = {
		OFF = "Off",
		PREMIUM = "Auto Final Selection is a premium feature",
		LOADING = "Waiting for the game to load",
		WARNING = "Passing Final Selection turns you from a Human into a Slayer, and that can't be undone.",
		DONE = "Final Selection is done",
		INSIDE = "Inside Final Selection",
		clock = function(arg)
			local n = math.max(0, math.floor(tonumber(arg) or 0))
			local n7 = math.floor(n / 3600)
			local n8 = math.floor(n % 3600 / 60)
			local n9 = n % 60
			if n7 > 0 then
				return ("%dh %02dm"):format(n7, n8)
			end

			if n8 > 0 then
				return ("%dm %02ds"):format(n8, n9)
			end
			return ("%ds"):format(n9)
		end,
		outside = function(arg, arg2)
			if type(arg) ~= "table" then
				return tbl.LOADING
			end

			if arg.blocked == "race" then
				return "Only a Human can take Final Selection"
			end

			if arg.blocked ~= "level" then
				local v = tbl.clock(arg.startsIn)
				if arg.waiting then
					return ("Waiting at the gathering spot. Final Selection starts in %s"):format(v)
				end

				if arg2 then
					return ("Going to the gathering spot. Final Selection starts in %s"):format(v)
				end
				return ("Final Selection starts in %s. It goes to the gathering spot shortly before"):format(v)
			end

			return ("You need to be level %d to take Final Selection (you're level %d)"):format(tonumber(arg.needsLevel) or 45, tonumber(arg.level) or 0)
		end,
		stopped = function(arg)
			return ("Stopped: %s"):format(tostring(arg))
		end,
	}

	return tbl
end)

