v4("Features/Auto/EvilArt/Ui", function(arg)
	local Identity = arg("Utility/Identity")
	local Place = arg("UI/Place")
	local Words = arg("Features/Auto/EvilArt/Words")

	return function(arg2, arg3, arg4)
		local toggles = arg2.Toggles
		if not arg2.Options then
			return nil
		end

		if toggles then
			local v = Place.groupbox(arg2, "Evil Art & Souls", "ghost", { fallback = { "Quests", "Auto" }, side = "Right" })

			if v then
				local v5 = v:AddLabel(Words.LOADING, true)

				v:AddDropdown("EA_Arts", {
					Text = "Evil Arts You Want",
					Values = arg4.arts or {},
					Default = {},
					Multi = true,
					Searchable = true,
					AllowNull = true,
					Premium = true,
					Tooltip = "The Evil Arts you'd be happy with. Buying needs exactly one. Spinning stops as soon as it lands any of them.",
					Callback = function(evilArtsYouWant)
						local onArts = arg4.onArts
						local evilArtsYouWant2 = type(evilArtsYouWant) == "table"

						if evilArtsYouWant2 then
							evilArtsYouWant2 = evilArtsYouWant
						end

						onArts(evilArtsYouWant2 or {})
					end,
				})

				local wayLabels = {}
				local howToGetIts = {}
				local v6 = table.pack(ipairs(Words.WAY_ORDER))
				local v7, v8, v9

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[1]
					v8 = v6[2]
					v9 = v6[3]
				else
					v7 = nil
					v8 = nil
					v9 = nil
				end

				for _, v10 in v7, v8, v9 do
					wayLabels[#wayLabels + 1] = Words.WAY_LABELS[v10]
					howToGetIts[Words.WAY_LABELS[v10]] = v10
				end

				v:AddDropdown("EA_Way", {
					Text = "How To Get It",
					Values = wayLabels,
					Default = Words.WAY_LABELS[arg3.way] or Words.WAY_LABELS.best,
					Premium = true,
					Tooltip = "Best Way buys the art when you pick one, and spins when you pick several, since a hit on any of them comes sooner. For one art, buying costs the same as spinning does on average, but never more.",
					Callback = function(howToGetIt)
						arg4.onWay(howToGetIts[howToGetIt] or "best")
					end,
				})

				v:AddSlider("EA_Budget", {
					Text = "Most Spins To Spend",
					Default = arg3.budget,
					Min = 3,
					Max = 300,
					Rounding = 0,
					Suffix = " spins",
					Premium = true,
					Tooltip = "The most spins it uses in one go. Each spin costs 3, and buying an art costs 54.",
					Callback = function(mostSpinsToSpend)
						arg4.onBudget(tonumber(mostSpinsToSpend) or arg3.budget)
					end,
				})

				local v10 = v:AddLabel("", true)

				v:AddToggle("EA_Train", {
					Text = "Train It Right Away",
					Default = arg3.train,
					Premium = true,
					Tooltip = "After getting the orb, squeeze it and let Auto Quest do its core training: the trainings, then 5 Mizunotos. The game doesn't save core training, so stay in the game until it's done.",
					Callback = function(trainItRightAway)
						arg4.onTrain(trainItRightAway == true)
					end,
				})

				v:AddButton({
					Text = "Get My Evil Art",
					DoubleClick = true,
					Risky = true,
					Premium = true,
					Disabled = arg4.ready ~= true,
					Tooltip = "Rings the Biwa Bell into Muzan's lair and gets an art you picked, then trains it. Every trip into the lair raises your reputation by 5. Click twice, since it spends spins.",
					Func = function()
						arg4.onGet()
					end,
				})

				v:AddButton({
					Text = "Stop",
					Tooltip = "Stops getting or training the art. A spin already on its way still lands.",
					Func = function()
						arg4.onStop()
					end,
				})

				local v11 = v:AddLabel(Words.OFF, true)
				v:AddDivider()

				v:AddToggle("EA_Souls", {
					Text = "Eat Souls",
					Default = false,
					Premium = true,
					Disabled = arg4.soulReady ~= true,
					Tooltip = "Fights the monsters you pick, pinned under each one like the other farms, and eats the souls they leave. Souls fill your demon bar. Only Demons can eat them.",
					Callback = function(eatSouls)
						arg4.onSouls(eatSouls == true)
					end,
				}):AddKeyPicker("EA_SoulsKey", {
					Default = "None",
					Premium = true,
					Mode = "Toggle",
					Text = "Eat Souls",
					SyncToggleState = true,
				})

				local v12 = v:AddDependencyBox()

				local EA_SoulMobs = v12:AddDropdown("EA_SoulMobs", {
					Text = "Monsters To Farm",
					Values = arg4.monsters or {},
					Default = {},
					Multi = true,
					Searchable = true,
					AllowNull = true,
					Premium = true,
					Tooltip = "Which monsters to farm. It goes to the nearest one of them that's around. Leave it empty for Bear Cubs, which come back quickly.",
					Callback = function(monstersToFarm)
						local onMonsters = arg4.onMonsters
						local monstersToFarm2 = type(monstersToFarm) == "table"

						if monstersToFarm2 then
							monstersToFarm2 = monstersToFarm
						end

						onMonsters(monstersToFarm2 or {})
					end,
				})

				v12:AddToggle("EA_SoulStop", {
					Text = "Stop When The Bar Is Full",
					Default = arg3.soulStop,
					Premium = true,
					Tooltip = "Stops once your demon bar fills up and you go up a demon level. Off, it keeps going until the last level.",
					Callback = function(stopWhenTheBarIsFull)
						arg4.onSoulStop(stopWhenTheBarIsFull == true)
					end,
				})

				local v13 = v12:AddLabel(Words.OFF, true)
				v12:SetupDependencies({ { toggles.EA_Souls, true } })
				local tbl = {}

				local function fn2(arg5, arg6, arg7)
					if tbl[arg6] == arg7 then
						return
					end
					Identity.elevate()

					if pcall(arg5.SetText, arg5, arg7) then
						tbl[arg6] = arg7
					end
				end

				return {
					setRoad = function(arg5)
						fn2(v5, "road", arg5)
					end,
					setOdds = function(arg5)
						fn2(v10, "odds", arg5)
					end,
					setArtStatus = function(arg5)
						fn2(v11, "art", arg5)
					end,
					setSoulStatus = function(arg5)
						fn2(v13, "soul", arg5)
					end,
					setMonsters = function(arg5)
						Identity.elevate()
						pcall(EA_SoulMobs.SetValues, EA_SoulMobs, arg5)
					end,
					soulsOff = function()
						local eaSouls = toggles.EA_Souls

						if eaSouls then
							Identity.elevate()
							pcall(eaSouls.SetValue, eaSouls, false)
							return
						end
					end,
				}
			end

			return nil
		end

		return nil
	end
end)

v4("Features/Auto/EvilArt/Souls", function(arg)
	local Words = arg("Features/Auto/EvilArt/Words")
	local tbl = { CLAIM_RADIUS = 30, SETTLE = 0.5, DRY_AFTER = 5, DEFAULT_KIND = "Bear Cub" }

	tbl.new = function(arg2)
		local cfg = arg2.cfg
		local api = arg2.api
		local pilot = arg2.pilot
		local str = tostring(arg2.owner or "Eat Souls")
		local tbl2 = { target = nil, kills = 0, souls = 0, benched = {}, lastReport = -math.huge, dry = {} }

		local function fn2(target)
			local model = target.model

			if model.Parent then
				if model.Parent == target.slot then
					return model:FindFirstChildOfClass("Humanoid") == nil
				end
			end

			return true
		end

		local function fn3(instance)
			local tbl3 = {}

			local v = table.pack(pcall(function()
				local dmg = instance:FindFirstChild("DMG")
				local dmg2 = dmg

				if dmg2 then
					dmg2 = dmg:GetChildren()
				end

				return dmg2 or {}
			end))

			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			local v7 = ipairs
			local tbl4 = v5

			if tbl4 then
				tbl4 = v6
			end

			tbl4 = tbl4 or {}
			local v8 = table.pack(v7(tbl4))
			local v9, v10, v11

			if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
				v9 = v8[1]
				v10 = v8[2]
				v11 = v8[3]
			else
				v9 = nil
				v10 = nil
				v11 = nil
			end

			for _, v12 in v9, v10, v11 do
				local v13 = table.pack(pcall(function()
					return v12.Value
				end))

				local v14, v15

				if select("#", table.unpack(v13, 1, v13.n)) ~= 0 then
					v14 = v13[1]
					v15 = v13[2]
				else
					v14 = nil
					v15 = nil
				end

				if v14 then
					if type(v15) == "number" then
						if v15 > 0 then
							tbl3[v12.Name] = v15
						end
					end
				end

				continue
			end

			return tbl3
		end

		local function fn4(model)
			return fn3(model)[arg2.player()] or 0
		end

		local function fn5(model)
			local v = fn3(model)
			if v[arg2.player()] then
				return false
			end
			return next(v) ~= nil
		end

		local function fn6(model)
			local v = tbl2.benched[model]

			if v then
				if os.clock() < v then
					return true
				end
			end

			tbl2.benched[model] = nil
			return false
		end

		local function fn7(model)
			tbl2.benched[model] = os.clock() + 60
		end

		local function fn8()
			local tbl3 = {}
			local v = pairs
			local picked = cfg.picked or {}
			local v5 = table.pack(v(picked))
			local v6, v7, v8

			if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
				v6 = v5[1]
				v7 = v5[2]
				v8 = v5[3]
			else
				v6 = nil
				v7 = nil
				v8 = nil
			end

			for k, v9 in v6, v7, v8 do
				if v9 then
					tbl3[#tbl3 + 1] = k
				end
			end

			table.sort(tbl3)
			if #tbl3 ~= 0 then
				return tbl3, false
			end
			return { tbl.DEFAULT_KIND }, true
		end

		local function fn9()
			local State = api("State")
			if not State then
				return nil
			end
			local v = table.pack(State.position())
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			local v7 = v5

			if v7 then
				v7 = v6
			end

			return v7 or nil
		end

		local function fn10(target)
			local v = table.pack(pcall(function()
				return target.root.Position
			end))

			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				if v6 then
					return v6
				end
			end

			return nil
		end

