					local flag = #picks == 1

					if flag then
						flag = "buy"
					end

					way = flag or "spin"
				end
			end

			if way ~= "buy" then
				if n < rollCost then
					return nil, { why = "budget_below_roll", need = rollCost, budget = n }
				end

				if n7 < rollCost then
					return nil, { why = "no_spins", need = rollCost, have = n7 }
				end
				return { via = "spin", arts = table.move(picks, 1, #picks, 1, {}), budget = n, cost = rollCost }
			end

			if #picks ~= 1 then
				return nil, { why = "buy_one", count = #picks }
			end

			if n < buyPrice then
				return nil, { why = "over_budget", art = picks[1], need = buyPrice, budget = n }
			end

			if n7 < buyPrice then
				return nil, { why = "no_spins", need = buyPrice, have = n7 }
			end
			return { via = "buy", arts = { picks[1] }, art = picks[1], budget = n, price = buyPrice }
		end

