v4("Features/Auto/DemonProgression/Words", function(arg)
	local tbl = {
		duration = arg("Api/Demon/Words").duration,
		OFF = "Off",
		LOADING = "Waiting for the game to load.",
		PREMIUM = "Become A Demon is a premium feature.",
		REP_LOADING = "Waiting for your reputation to load.",
		NO_CHARACTER = "Waiting for your character.",
		OWN_AURA = "Turn off your own Kill Aura on the Combat tab. Become A Demon runs it for you while it fights.",
		NONE_AROUND = "Nobody whose death lowers your reputation is around right now.",
		NO_WEAPON = "Put a weapon or your fists on your hotbar so Become A Demon can fight.",
		OTHER_STEP = "Waiting for another demon step to finish.",
		PAUSED = "Paused while another farm is moving your character.",
