			if arg2.race ~= "Demon" then
				if arg2.race ~= "Hybrid" then
					if type(arg2.race) ~= "string" then
						return tbl.LOADING
					end
					return ("Only Humans can become Demons. You're a %s, and your reputation is %s."):format(arg2.race, v)
				end
			end

			local str = ""

			if type(arg2.reputation) == "number" then
				if type(arg2.lairAt) == "number" then
					if arg2.reputation < arg2.lairAt then
						str = " You can enter Muzan's lair."
					else
						str = (" Muzan's lair needs it under %d."):format(arg2.lairAt)
					end
				end
			end

			return ("You're already a %s. Your reputation is %s.%s"):format(arg2.race, v, str)
		end

		return arg2.stepLine or tbl.LOADING
	end

	tbl.wait = function(arg2, arg3)
