		return "Everyone whose death lowers your reputation hits too hard for you right now."
	end

	tbl.doing = function(arg2, arg3)
		if arg2 ~= "get_bell" then
			if arg2 ~= "assign" then
				if arg2 ~= "lilies" then
					return tbl.LOADING
				end
				local muzanQuest = type(arg3) == "table"

				if muzanQuest then
					muzanQuest = arg3.muzanQuest
				end

				if muzanQuest then
					muzanQuest = arg3.muzanQuest.lilies
				end

				muzanQuest = muzanQuest or nil
				if muzanQuest then
					return ("Picking Spider Lilies (%d of %d)."):format(tonumber(muzanQuest.value) or 0, tonumber(muzanQuest.max) or 9)
				end
				return "Picking Spider Lilies."
			end

			return "Ringing the Biwa Bell to take Muzan's quest in his lair."
		end

		return "Finding Muzan to take his Biwa Bell."
	end

	tbl.lilyProgress = function(arg2)
		if type(arg2) == "table" then
			if arg2.value then
				return ("Picking Spider Lilies (%d of %d)."):format(tonumber(arg2.value) or 0, tonumber(arg2.max) or 9)
			end
		end

		return "Picking Spider Lilies."
	end

	tbl.stepDone = function(arg2, arg3)
		if arg2 == "get_bell" then
			return "Muzan gave you the Biwa Bell."
		end

		if arg2 ~= "assign" then
			if arg2 == "lilies" then
				return "You have all 9 Spider Lilies."
			end
			return "Done."
		end

		local flag = type(arg3) == "table"

		if flag then
			flag = type(arg3.warning) == "string"
		end

		if flag then
			flag = " " .. arg3.warning
		end

		return "Muzan gave you his quest. Next: pick 9 Spider Lilies." .. (flag or "")
	end

	tbl.retry = function(arg2, arg3)
		return ("%s Trying again in %s."):format(arg2, tbl.duration(arg3))
	end

	tbl.stopped = function(doTheNextStepStopped)
