		local estimate = arg2.estimate

		if estimate then
			estimate = "about "
		end

		return ("Finishing %s raises your reputation by %s%s, to %s. That's past your %s line, so Keep Me Evil will lower it again."):format(arg2.name, estimate or "", tbl.number(arg2.delta), tbl.number(arg2.after), tbl.number(arg3))
	end

	tbl.DRINK_SWITCH_FIRST = "Turn on Drink Muzan's Blood When Ready first."
	tbl.DRINK_ALREADY = "Already drinking Muzan's Blood."
	tbl.DRINK_DONE = "You're a Demon now."
	tbl.DRINK_IDLE = "Double-click Drink It to say yes. It turns you into a Demon and can't be undone."
	tbl.DRINK_READY = "Ready. Double-click Drink It to become a Demon. It can't be undone."
	tbl.DRINKING_NOW = "Drinking Muzan's Blood. Don't get hit."

