v4("Api/Demon/Words", function(arg)
	local Errors = arg("Api/Demon/Errors")

	local function fn2(demon, arg2)
		local v = table.pack(ipairs(demon))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for k, v8 in v5, v6, v7 do
			if v8 == arg2 then
				return k
			end
		end

		return nil
	end

	local tbl = {
		HUMAN = { "lower_rep", "get_bell", "take_quest", "lilies", "higoshima", "drink" },
		DEMON = { "get_art", "squeeze", "train", "done" },
		duration = function(arg2)
			local n = math.max(0, math.floor((tonumber(arg2) or 0) + 0.5))
			local n8 = math.floor(n / 3600)
			local n9 = math.floor(n % 3600 / 60)
			local n10 = n % 60

			if not (n8 > 0) then
				if not (n9 > 0) then
					return ("%ds"):format(n10)
				end
				return ("%dm %ds"):format(n9, n10)
			end

			return ("%dh %dm"):format(n8, n9)
		end,
		toBell = function(arg2, arg3)
			if type(arg2) ~= "number" then
				return nil
			end
			return math.max(0, arg2 - arg3)
		end,
		toLair = function(arg2, arg3)
			if type(arg2) ~= "number" then
				return nil
			end

			if arg2 < arg3 then
				return 0
			end
			return math.floor(arg2 - arg3) + 1
		end,
		lairTrips = function(arg2, arg3, arg4)
			if type(arg2) ~= "number" then
				return 0
			end

			if not (arg3 <= arg2) then
				if not (arg4 <= 0) then
					return math.ceil((arg3 - arg2) / arg4)
				end
				return math.huge
			end

			return 0
		end,
	}

	local function fn3(muzan)
		if type(muzan) ~= "table" then
			return ""
		end

		if muzan.status ~= "up" then
			if muzan.status == "waiting" then
				if muzan.comesOutIn then
					return (" He comes out in %s."):format(tbl.duration(muzan.comesOutIn))
				end
			end

			if muzan.leavesIn then
				return (" He's out for another %s."):format(tbl.duration(muzan.leavesIn))
			end
			return ""
		end

		return " He's out now."
	end

	local function fn4(open)
		if type(open) ~= "table" then
			return nil
		end
		local n = tonumber(open.max) or 1
		if not (n > 1) then
			return open.name
		end
		return ("%s (%d of %d)"):format(open.name, tonumber(open.value) or 0, n)
	end

	local function fn5(arg2)
		local race = arg2.race

		if race ~= "Demon" then
			if race ~= "Hybrid" then
				if race ~= "Human" then
					return "not_human", "Only Humans can become Demons."
				end

				if arg2.hasBlood then
					return "drink", "Drink Muzan's Blood to become a Demon."
				end
				local muzanQuest = arg2.muzanQuest

				if muzanQuest then
					if muzanQuest.state == "Doing" then
						local lilies = muzanQuest.lilies

						if lilies then
							if (tonumber(lilies.value) or 0) < (tonumber(lilies.max) or 9) then
								return "lilies", ("Pick Spider Lilies (%d of %d)."):format(tonumber(lilies.value) or 0, tonumber(lilies.max) or 9)
							end
						end

						return "higoshima", "Deliver Dr. Higoshima. This step can't be done for you yet."
					end
				end

				if muzanQuest then
					if muzanQuest.state == "Done" then
						return "drink", "You finished Muzan's quest, but you have no Muzan's Blood."
					end
				end

				if arg2.hasBell then
					local v = tbl.toLair(arg2.reputation, arg2.lairAt)

					if v then
						if v > 0 then
							if not arg2.inLair then
								return "take_quest", ("Lower your reputation below %d to enter Muzan's lair (%d to go)."):format(arg2.lairAt, v)
							end
						end
					end

					if arg2.inLair then
						return "take_quest", "Talk to Muzan in his lair to take his quest."
					end
					return "take_quest", ("Ring the Biwa Bell to enter Muzan's lair and take his quest. Entering raises your reputation by %d."):format(arg2.lairCost)
				end

				local v = tbl.toBell(arg2.reputation, arg2.eligibleAt)
				if v == nil then
					return "lower_rep", "Lower your reputation."
				end

				if not (v > 0) then
					if arg2.night then
						return "get_bell", "Find Muzan and take his Biwa Bell." .. fn3(arg2.muzan)
					end
					return "get_bell", "Find Muzan tonight." .. fn3(arg2.muzan)
				end

				return "lower_rep", ("Lower your reputation to %d (%d to go)."):format(arg2.eligibleAt, v)
			end
		end

		local coreQuest = arg2.coreQuest

		if coreQuest then
			if coreQuest.open then
				return "train", ("Train your %s core: %s."):format(coreQuest.art, fn4(coreQuest.open) or coreQuest.open.name)
			end
		end

		if arg2.demonArt then
			return "done", ("You're a Demon with %s."):format(arg2.demonArt)
		end

		if coreQuest then
			return "train", ("Finish your %s core training."):format(coreQuest.art)
		end
		local v = ipairs
		local artsHeld = arg2.artsHeld or {}
		local v5 = table.pack(v(artsHeld))
		local v6, v7, v8

		if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
			v6 = v5[1]
			v7 = v5[2]
			v8 = v5[3]
		else
			v6 = nil
			v7 = nil
			v8 = nil
		end

		for _, v9 in v6, v7, v8 do
			return "squeeze", ("Squeeze your %s Orb to start its core training."):format(v9)
		end

		local v9 = tbl.toLair(arg2.reputation, arg2.lairAt)

		if v9 then
			if v9 > 0 then
				if not arg2.inLair then
					return "get_art", ("Lower your reputation below %d to enter Muzan's lair (%d to go)."):format(arg2.lairAt, v9)
				end
			end
		end

		return "get_art", "Get an Evil Art orb from Muzan's lair."
	end

	tbl.next = function(arg2)
		local v = table.pack(fn5(arg2))
		local v5, text

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			text = v[2]
		else
			v5 = nil
			text = nil
		end

		local demon = arg2.race == "Demon" or arg2.race == "Hybrid"

		if demon then
			demon = tbl.DEMON
		end

		demon = demon or tbl.HUMAN
		local v6 = fn2(demon, v5)
		local text2 = text

		if v6 then
			text2 = ("Step %d of %d: %s"):format(v6, #demon, text:sub(1, 1):lower() .. text:sub(2))
		end

		local tbl2 = { id = v5, index = v6 }
		local total = v6

		if total then
			total = #demon
		end

		tbl2.total = total or nil
		tbl2.text = text
		tbl2.line = text2
		return tbl2
	end

	tbl.explain = function(arg2, arg3)
		local flag = type(arg3) == "table"

		if flag then
			flag = arg3
		end

		local tbl2 = flag or {}

		if arg2 == Errors.NOT_EVIL_ENOUGH then
			if tbl2.toGo then
				if tbl2.below then
					return ("Lower your reputation below %d first (%d to go)."):format(tbl2.below, tbl2.toGo)
				end
				return ("Lower your reputation to %d first (%d to go)."):format(tbl2.target or -40, tbl2.toGo)
			end
		end

		if arg2 == Errors.WAIT_NIGHT then
			if tbl2.seconds then
				return ("Muzan only comes out at night. Night starts in %s."):format(tbl.duration(tbl2.seconds))
			end
		end

		if arg2 == Errors.IN_COMBAT then
			if tbl2.seconds then
				return ("You fought a player too recently. Wait %s."):format(tbl.duration(tbl2.seconds))
			end
		end

		if arg2 == Errors.NO_SPINS then
			if tbl2.need then
				return ("That needs %d spins and you have %d."):format(tbl2.need, tonumber(tbl2.have) or 0)
			end
		end

		if arg2 == Errors.OVER_BUDGET then
			if tbl2.budget then
				return ("That would go over the %d spins you set aside (%d spent)."):format(tbl2.budget, tonumber(tbl2.spent) or 0)
			end
		end

		if arg2 == Errors.HAS_ART then
			if tbl2.art then
				return ("You already have %s. It has to be removed first."):format(tbl2.art)
			end
		end

		if arg2 == Errors.QUEST_BLOCKED then
			if type(tbl2.line) == "string" then
				return ("The game won't start that core training: %s"):format(tbl2.line)
			end
		end

		return Errors.MESSAGES[arg2] or Errors.MESSAGES[Errors.FAILED]
	end

	return tbl
end)

