v4("Features/Auto/Quest/Words", function()
	local tbl = {
		REASONS = {
			loading = "Waiting for the game to load",
			nothing_chosen = "Pick at least one quest in the list",
			none = "No quest you can do right now. Try ticking more quest types.",
		},
	}

	tbl.PLAYER_TOOK_OVER = "Paused while Auto Quest does your own quests"

	tbl.number = function(arg)
		local str = tostring(math.floor((tonumber(arg) or 0) + 0.5))
		local v = table.pack(str:match("^(-?)(%d+)$"))
		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
		else
			v5 = nil
			v6 = nil
		end

		if v6 then
			local str2 = v6:reverse():gsub("(%d%d%d)", "%1,"):reverse()

			if str2:sub(1, 1) == "," then
				str2 = str2:sub(2)
			end

			return v5 .. str2
		end

		return str
	end

	tbl.duration = function(arg)
		local n = math.max(0, math.ceil(tonumber(arg) or 0))
		if n < 60 then
			return ("%ds"):format(n)
		end
		local n8 = math.floor(n / 60)
		local n9 = n % 60
		if n9 ~= 0 then
			return ("%dm %ds"):format(n8, n9)
		end
		return ("%dm"):format(n8)
	end

	local function fn2(wait)
		local num = tonumber(wait)
		local flag = num ~= nil

		if flag then
			flag = num == num
		end

		if flag then
			flag = num < math.huge
		end

		return flag
	end

	tbl.bossBack = function(arg)
		local str = tostring(arg.boss or "the boss")

		if arg.night then
			if fn2(arg.wait) then
				return ("%s only comes out at night, which starts in %s"):format(str, tbl.duration(arg.wait))
			end
			return ("%s only comes out at night"):format(str)
		end

		if fn2(arg.wait) then
			return ("%s is back in %s"):format(str, tbl.duration(arg.wait))
		end
		return ("%s isn't up right now"):format(str)
	end

	tbl.reason = function(arg, arg2, arg3)
		if tbl.REASONS[arg] then
			return tbl.REASONS[arg]
		end
		local flag = type(arg2) == "table"

		if flag then
			flag = arg2
		end

		local tbl2 = flag or {}

		if arg ~= "cant_do" then
			if arg ~= "boss_down" then
				if arg ~= "power" then
					if arg ~= "costs" then
						if arg ~= "not_held" then
							if not arg3 then
								return "Waiting"
							end

							if type(arg3.explain) ~= "function" then
								return "Waiting"
							end
							local v = table.pack(arg3.explain(arg))
							local v5

							if select("#", table.unpack(v, 1, v.n)) ~= 0 then
								v5 = v[2]
							else
								v5 = nil
							end

							if type(v5) == "string" then
								return v5
							end
							return "Waiting"
						end

						return ("Waiting for %s. Nobody hands it out, so it has to be started another way"):format(tostring(tbl2.quest or "the quest"))
					end

					return ("%s costs something to take, so it isn't taken for you"):format(tostring(tbl2.quest or "That quest"))
				end

				return ("%s gives you a new power, so it isn't taken for you"):format(tostring(tbl2.quest or "That quest"))
			end

			return ("Waiting for the boss before taking %s: %s"):format(tostring(tbl2.quest or "its quest"), tbl.bossBack(tbl2))
		end

		return ("Auto Quest can't do \"%s\" by itself"):format(tostring(tbl2.name or "a step"))
	end

	tbl.best = function(arg, arg2)
		local flag = type(arg2) == "table"

		if flag then
			flag = arg2
		end

		local tbl2 = flag or {}
		local tbl3 = {}
		local giver = arg.giver

		if giver then
			giver = (", from %s"):format(arg.giver)
		end

		giver = giver or ""
		tbl3[1] = ("Best quest for you: %s (Lv %d%s)."):format(tostring(arg.name), tonumber(arg.level) or 1, giver)

		if tbl2.new then
			tbl3[#tbl3 + 1] = "You've never done it."
		end

		if tonumber(tbl2.rate) then
			if tbl2.rate > 0 then
				tbl3[#tbl3 + 1] = ("About %s exp a minute."):format(tbl.number(tbl2.rate))
			end
		end

		local instead = tbl2.instead

		if type(instead) == "table" then
			if type(instead.record) == "table" then
				if type(instead.boss) == "table" then
					local tbl4 = {
						boss = instead.boss.title or instead.boss.name,
						wait = instead.wait,
						night = instead.boss.status == "waiting",
					}

					tbl3[#tbl3 + 1] = ("%s pays more, but %s."):format(tostring(instead.record.name), tbl.bossBack(tbl4))
				end
			end
		end

		if tbl2.fromGame then
			tbl3[#tbl3 + 1] = "(The game's own pick, since none of your ticked quest types fit.)"
		end

		return table.concat(tbl3, " ")
	end

	tbl.held = function(arg, arg2)
		return ("Auto Quest is working for %s: %s"):format(tostring(arg or "another feature"), tostring(arg2))
	end

	return tbl
end)

