			tbl4.completed = function(arg3)
				if type(arg3) ~= "table" then
					return
				end
				local now = os.clock()
				local key = arg3.key

				if key then
					key = tbl[arg3.key]
				end

				key = key or nil

				if arg3.key then
					tbl[arg3.key] = nil
				end

				run.count("quests")
				local note = run.note
				local str = "%s%s"
				local format = ("%s%s").format
