		"levelUnknown",
		"race",
		"training",
		"busy",
		"dead",
		"benched",
		"gone",
	}

	tbl.name = function(player, arg)
		if arg then
			return tbl.HIDDEN
		end

		if player then
			local v = table.pack(pcall(function()
				return player.DisplayName
			end))

			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			if v5 then
				if type(v6) == "string" then
					if v6 ~= "" then
						return v6
					end
				end
			end

			local v7 = table.pack(pcall(function()
				return player.Name
			end))

			local v8, v9

			if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
				v8 = v7[1]
				v9 = v7[2]
			else
				v8 = nil
				v9 = nil
			end

			local flag = v8

			if flag then
				flag = type(v9) == "string"
			end

			if flag then
				flag = v9
			end

			return flag or tbl.HIDDEN
		end

		return tbl.HIDDEN
	end

	tbl.about = function(arg, arg2)
		local tbl2 = {}

		if tonumber(arg) then
