			if arg2 ~= "" then
				tbl2[#tbl2 + 1] = arg2
			end
		end

		if #tbl2 ~= 0 then
			return table.concat(tbl2, " ")
		end
		return nil
	end

	local function fn2(arg)
		if arg == tbl.HIDDEN then
			return (arg:gsub("^%l", string.upper))
		end
		return arg
	end

	tbl.fighting = function(arg, arg2, arg3, arg4, arg5)
		local tbl2 = {}
		local v = tbl.about(arg2, arg3)

		if v then
			tbl2[#tbl2 + 1] = v
		end

		if tonumber(arg4) then
			tbl2[#tbl2 + 1] = ("%d%% health"):format(math.floor(tonumber(arg4) + 0.5))
		end

		local str = ("Fighting %s"):format(arg)

		if #tbl2 > 0 then
			str ..= " (" .. table.concat(tbl2, ", ") .. ")"
		end

		if type(arg5) == "string" then
			if arg5 ~= "" then
				str ..= ". " .. arg5
			end
		end

		return str
	end

	tbl.following = function(arg)
		return ("Following %s. Turn on Use M1s in Autofarm Settings to fight them"):format(arg)
	end

	tbl.heading = function(arg)
		return ("Heading for %s"):format(arg)
	end

	tbl.lost = function(arg)
		return ("Lost hold of %s, finding them again"):format(arg)
	end

	tbl.beat = function(arg, arg2)
		return ("Beat %s (%d so far)"):format(arg, arg2)
	end

	tbl.left = function(arg)
		return ("%s left the server"):format(fn2(arg))
	end

	tbl.absent = function(arg)
		return ("%s isn't in this server"):format(fn2(arg))
	end

	tbl.outOfRange = function(arg)
		return ("%s went out of range. Waiting for them to come back"):format(fn2(arg))
	end

	tbl.gaveUp = function(arg)
		return ("Gave up on %s for now, your hits weren't landing"):format(arg)
	end

	tbl.cantReach = function(arg, arg2)
		return ("Couldn't get to %s (%s)"):format(arg, tostring(arg2))
	end

	tbl.safeMe = function(arg)
		return ("You're in a safe zone, so your hits can't land on %s"):format(arg)
	end

	tbl.waiting = function(arg, arg2)
		local reason = tbl.REASONS[arg2]
		local reason2 = reason

		if reason2 then
			reason2 = reason.named
		end

		reason2 = reason2 or "they can't be fought right now"
		return ("Waiting for %s: %s"):format(arg, reason2)
	end

	tbl.none = function(arg, arg2)
		if (tonumber(arg2) or 0) <= 0 then
			return "No player to fight: nobody else is in the server"
		end
		local v = nil
		local count = 0
		local v5 = pairs
		local tbl2 = arg or {}
		local v6 = table.pack(v5(tbl2))
		local v7, v8, v9

		if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
			v7 = v6[1]
			v8 = v6[2]
			v9 = v6[3]
		else
			v7 = nil
			v8 = nil
			v9 = nil
		end

		for k, v10 in v7, v8, v9 do
			if v10 > 0 then
				count += 1
				v = k
			end
		end

		if count == 1 then
			if tbl.REASONS[v] then
				return "No player to fight: " .. tbl.REASONS[v].all
			end
		end

		local tbl3 = {}
		local v10 = table.pack(ipairs(tbl.ORDER))
		local v11, v12, v13

		if select("#", table.unpack(v10, 1, v10.n)) ~= 0 then
			v11 = v10[1]
			v12 = v10[2]
			v13 = v10[3]
		else
			v11 = nil
			v12 = nil
			v13 = nil
		end

		for _, v14 in v11, v12, v13 do
			local n = arg

			if n then
				n = arg[v14]
			end

			n = n or 0
			local reason = tbl.REASONS[v14]

			if n > 0 then
				if reason then
					tbl3[#tbl3 + 1] = ("%s: %d"):format(reason.label, n)
				end
			end
		end

		if #tbl3 == 0 then
			return "No player to fight right now"
		end
		return "No player to fight right now. " .. table.concat(tbl3, ". ")
	end

	return tbl
end)

