v4("Features/Auto/PlayerFarm/Spot", function(arg)
	local Shared = arg("Features/Auto/FarmSettings/Shared")

	local tbl = {
		MODES = { "Below", "Above", "Behind", "In Front" },
		DEFAULT = "Below",
		DISTANCE_MAX = 20,
		FINE_MIN = -20,
		FINE_MAX = 20,
		FLAT_FLOOR = 2,
	}

	local tbl2 = {}
	local v = table.pack(ipairs(tbl.MODES))
	local v5, v6, v7

	if select("#", table.unpack(v, 1, v.n)) ~= 0 then
		v5 = v[1]
		v6 = v[2]
		v7 = v[3]
	else
		v5 = nil
		v6 = nil
		v7 = nil
	end

	for _, v8 in v5, v6, v7 do
		tbl2[v8] = true
	end

	local function fn2(arg2, arg3, arg4, arg5)
		local num = tonumber(arg2)

		if num ~= nil then
			if num == num then
				return math.max(arg3, math.min(arg4, num))
			end
		end

		return arg5
	end

	tbl.norm = function(arg2)
		local flag = type(arg2) == "table"

		if flag then
			flag = arg2
		end

		local tbl3 = flag or {}
		local mode = tbl2[tbl3.mode]

		if mode then
			mode = tbl3.mode
		end

		mode = mode or tbl.DEFAULT
		local v8 = fn2(tbl3.distance, 0, tbl.DISTANCE_MAX, 0)

		return {
			mode = mode,
			distance = v8,
			x = fn2(tbl3.x, tbl.FINE_MIN, tbl.FINE_MAX, 0),
			y = fn2(tbl3.y, tbl.FINE_MIN, tbl.FINE_MAX, 0),
			z = fn2(tbl3.z, tbl.FINE_MIN, tbl.FINE_MAX, 0),
		}
	end

	tbl.vertical = function(arg2)
		return arg2 == "Below" or arg2 == "Above"
	end

	tbl.side = function(arg2)
		if tbl.vertical(arg2) then
			return arg2
		end
		return nil
	end

	tbl.pose = function(arg2)
		if tbl.vertical(arg2) then
			return Shared.POSE
		end
		return "upright"
	end

	tbl.auto = function(arg2)
		return (tonumber(arg2.distance) or 0) <= 0
	end

	tbl.key = function(arg2)
		local mode = arg2.mode
		local str = tbl.auto(arg2)

		if str then
			str = ":auto"
		end

		return mode .. (str or ":fixed")
	end

	tbl.shared = function(arg2)
		local flag = tbl.vertical(arg2.mode)

		if flag then
			flag = tbl.auto(arg2)
		end

		if flag then
			flag = math.abs(arg2.x) < 0.05
		end

		if flag then
			flag = math.abs(arg2.y) < 0.05
		end

		if flag then
			flag = math.abs(arg2.z) < 0.05
		end

		return flag
	end

	tbl.floor = function(arg2)
		if tbl.vertical(arg2) then
			return Shared.FLOOR
		end
		return tbl.FLAT_FLOOR
	end

	tbl.limit = function(arg2, arg3, arg4)
		if tbl.vertical(arg4) then
			if arg2 then
				return Shared.limit(arg2, arg3, arg4)
			end
			return Shared.FLOOR
		end

		if not arg2 then
			return tbl.FLAT_FLOOR
		end
		local v8 = table.pack(pcall(arg2.reach))
		local v9, v10, v11

		if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
			v9 = v8[1]
			v10 = v8[2]
			v11 = v8[3]
		else
			v9 = nil
			v10 = nil
			v11 = nil
		end

		if v9 then
			if v10 then
				if type(v11) == "table" then
					if tonumber(v11.forward) then
						return math.max(tbl.FLAT_FLOOR, v11.forward - 0.25)
					end
				end
			end
		end

		return tbl.FLAT_FLOOR
	end

	tbl.start = function(arg2, arg3, arg4)
		if tbl.auto(arg2) then
			return tbl.limit(arg3, arg4, arg2.mode)
		end
		return arg2.distance
	end

	tbl.offset = function(arg2, arg3, arg4)
		local n = math.max(0, tonumber(arg3) or 0)
		local x = arg2.x
		local y = arg2.y
		local n8 = arg2.z + (tonumber(arg4) or 0)

		if arg2.mode ~= "Below" then
			if arg2.mode ~= "Above" then
				if arg2.mode ~= "Behind" then
					n8 += n
				else
					n8 -= n
				end
			else
				y += n
			end
		else
			y -= n
		end

		return { right = x, up = y, forward = n8 }
	end

	return tbl
end)

v4("Features/Auto/PlayerFarm/Runner", function(arg)
	local Holds = arg("Utility/Holds")
