v4("Features/Auto/FarmSettings/Bridge", function()
	local tbl = { OLD = { "BF_Chests", "AQ_Chests", "YT_Chests" } }
	tbl.NEW = "Farm_Loot"

	tbl.translate = function(arg)
		local objects = type(arg) == "table"

		if objects then
			objects = arg.objects
		end

		objects = objects or nil
		if type(objects) ~= "table" then
			return false
		end
		local flag = false
		local flag2 = false
		local v = table.pack(ipairs(objects))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for _, v8 in v5, v6, v7 do
			if type(v8) ~= "table" then
				continue
			end

			if v8.idx == tbl.NEW then
				return false
			end
			local v9 = table.pack(ipairs(tbl.OLD))
			local v10, v11, v12

			if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
				v10 = v9[1]
				v11 = v9[2]
				v12 = v9[3]
			else
				v10 = nil
				v11 = nil
				v12 = nil
			end

			for _, v13 in v10, v11, v12 do
				if v8.idx == v13 then
					flag = true

					if v8.value == true then
						flag2 = true
					end
				end
			end
		end

		if flag then
			objects[#objects + 1] = { type = "Toggle", idx = tbl.NEW, value = flag2 }
			return true
		end
		return false
	end

	tbl.install = function(arg, arg2)
		if type(arg2) == "table" then
			if type(arg2.ApplyConfigData) == "function" then
				local applyConfigData = arg2.ApplyConfigData

				local function applyConfigData2(arg3, arg4, ...)
					pcall(tbl.translate, arg4)
					return applyConfigData(arg3, arg4, ...)
				end

				arg2.ApplyConfigData = applyConfigData2

				arg.onUnload(function()
					if arg2.ApplyConfigData == applyConfigData2 then
						arg2.ApplyConfigData = applyConfigData
					end
				end)

				return true
			end
		end

		return false
	end

	return tbl
end)

do
	v4("Features/Auto/FarmSettings/StepAway", function(arg)
		local Control = arg("Utility/Control")
		local tbl = { NAME = "Step Away To Heal" }
		tbl.UP = "Straight Up"
		tbl.SAVED = "My Saved Spot"
		tbl.WHERE = { tbl.UP, tbl.SAVED }
		tbl.HEIGHT = 150
		tbl.REST = 3

		tbl.new = function(arg2)
			local clock = arg2.clock or os.clock
			local values = arg2.values

			local locked = arg2.locked or function()
				return false
			end

			local v = Control.register(tbl.NAME, { label = tbl.NAME })
			local tbl2 = { away = false, since = nil, endedAt = -math.huge, part = nil, session = nil, line = nil }

			local function fn2(line)
				if line == tbl2.line then
					return
				end
				tbl2.line = line

				if arg2.setStatus then
					pcall(arg2.setStatus, line)
				end
			end

			local function fn3()
				local State = arg2.api("State")
				if not State then
					return nil
				end
				local v5 = table.pack(State.health())
				local v6, v7

				if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
					v6 = v5[1]
					v7 = v5[2]
				else
					v6 = nil
					v7 = nil
				end

				if v6 then
					if type(v7) == "table" then
						return (tonumber(v7.percent) or 0) * 100, tonumber(v7.current) or 0
					end
				end

				return nil
			end

			local function fn4()
				if values.stepWhere == tbl.SAVED then
					local saved = arg2.saved

					if saved then
						saved = arg2.saved()
					end

					saved = saved or nil
					if saved then
						return saved
					end
				end

				local State = arg2.api("State")
				local flag = false
				local v5 = nil

				if State then
					local v6 = table.pack(State.position())
					local v7, v8

					if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
						v7 = v6[1]
						v8 = v6[2]
					else
						v7 = nil
						v8 = nil
					end

					flag = v7
					v5 = v8
				end

				if flag then
					if v5 then
						return v5 + Vector3.new(0, tbl.HEIGHT, 0)
					end
				end

				return nil
			end

			local function fn5()
				local session = tbl2.session
				local part = tbl2.part
				tbl2.session = nil
				tbl2.part = nil

				if session then
					pcall(function()
						session:Destroy()
					end)
				end

				if part then
					pcall(function()
						part:Destroy()
					end)
				end
			end

			local function fn6(arg3)
				if tbl2.away then
					tbl2.away = false
					tbl2.endedAt = clock()
					fn5()
					v.want(false)
					fn2(arg3)
					return
				end
			end

			local function fn7()
				local v5 = fn4()
				local Attach = arg2.api("Attach")
				if not v5 then
					return false
				end

				if not Attach then
					return false
				end
				v.want(true)
				local v6 = table.pack(pcall(arg2.newPart, v5))
				local v7, part

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[1]
					part = v6[2]
				else
					v7 = nil
					part = nil
				end

				if v7 then
					if part then
						local session = Attach.AttachTo(part, {
							owner = tbl.NAME,
							name = "Healing spot",
							mover = "cframe",
							pose = "upright",
							offset = { right = 0, up = part.Size.Y / 2 + 3, forward = 0 },
						})

						if session then
							local since = clock()
							tbl2.away = true
							tbl2.since = since
							tbl2.part = part
							tbl2.session = session
							return true
						end

						pcall(function()
							part:Destroy()
						end)

						v.want(false)
						return false
					end
				end

				v.want(false)
				return false
			end

			local function fn8()
				return math.max(tonumber(values.stepBack) or 90, (tonumber(values.stepBelow) or 30) + 10)
			end

			local tbl3 = {
				tick = function()
					if locked() then
						if tbl2.away then
							fn6("Step Away To Heal is a premium feature")
						else
							fn2("Step Away To Heal is a premium feature")
						end

						return
					end

					local flag = values.stepAway == true

					if flag then
						if arg2.running() then
							local v5 = table.pack(fn3())
							local v6, v7

							if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
								v6 = v5[1]
								v7 = v5[2]
							else
								v6 = nil
								v7 = nil
							end

							if not v6 then
								return
							end
							local v8 = clock()

							if tbl2.away then
								local v9 = fn8()

								if not (v7 <= 0) then
									if v9 <= v6 then
										return fn6(("Back to the fight at %d%%"):format(math.floor(v6)))
									end
									local n = v8 - tbl2.since
									if (tonumber(values.stepTimeout) or 60) <= n then
										return fn6(("Back to the fight after %ds, at %d%%"):format(math.floor(v8 - tbl2.since), math.floor(v6)))
									end
									fn2(("Stepping away to heal: %d%% -> %d%%"):format(math.floor(v6), v9))
									return
								end

								return fn6("You went down while healing")
							end

							local n = tonumber(values.stepBelow) or 30

							if v7 > 0 then
								if v6 < n then
									if tbl.REST <= v8 - tbl2.endedAt then
										if fn7() then
											fn2(("Stepping away to heal: %d%% -> %d%%"):format(math.floor(v6), fn8()))
										else
											fn2("Couldn't step away just now")
										end

										return
									end
								end
							end

							fn2(("Ready: steps away below %d%%"):format(n))
							return
						end
					end

					if tbl2.away then
						local v5 = fn6
						local str = flag

						if str then
							str = "The farm stopped, so the step away ended"
						end

						v5(str or "Off")
					else
						local v5 = fn2
						local str = flag

						if str then
							str = "Waiting for a farm to fight"
						end

						v5(str or "Off")
					end
				end,
				away = function()
					return tbl2.away
				end,
				awayUntil = function()
					if tbl2.away then
						return clock()
					end
					return tbl2.endedAt
				end,
				stop = function()
