v4("Features/Auto/CacheFarm/Hop", function()
	local tbl = { COST = 120, FRESH_SLACK = 60, RETRY = 60, SETTLE = 60, REASON = "caches" }

	local function clock(arg)
		local n = math.max(0, math.floor(arg))

		if not (n >= 3600) then
			if not (n >= 60) then
				return ("%ds"):format(n)
			end
			return ("%dm %02ds"):format(math.floor(n / 60), n % 60)
		end

		return ("%dh %02dm"):format(math.floor(n / 3600), math.floor(n % 3600 / 60))
	end

	tbl.clock = clock

	local function fn2(tiers)
		local tbl2 = {}
		local v = pairs
		local tiers2 = tiers or {}
		local v5 = table.pack(v(tiers2))
		local v6, v7, v8

		if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
			v6 = v5[1]
			v7 = v5[2]
			v8 = v5[3]
		else
			v6 = nil
			v7 = nil
			v8 = nil
		end

		for k, v9 in v6, v7, v8 do
			if v9 then
				tbl2[#tbl2 + 1] = k
			end
		end

		table.sort(tbl2)
		if #tbl2 == 0 then
			return { "T1", "T2", "T3" }
		end
		return tbl2
	end

	tbl.new = function(arg)
		local cfg = arg.cfg
		local api = arg.api
		local tbl2 = { waitUntil = 0, line = nil, hops = 0, lead = nil }

		local function getLead()
			return tbl2.lead or "Every cache here is opened"
		end

		local function fn3()
			return arg.premium == nil or arg.premium() == true
		end

		local function fn4()
			if arg.workable == nil then
				return false
			end
			local v = table.pack(pcall(arg.workable))
			local v5, v6

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
			else
				v5 = nil
				v6 = nil
			end

			local flag = v5

			if flag then
				flag = v6 == true
			end

			return flag
		end

		return {
			due = function(arg2)
				if not cfg.hop then
					return false
				end

				if not fn3() then
					return false
				end

				if arg2.waiting() then
					local v = arg2.why()

					if v ~= "strong" then
						if v ~= "none" then
							return false
						end
					elseif not fn4() then
						return false
					end

					if os.clock() < tbl2.waitUntil then
						return false, tbl2.line
					end
					local Caches = api("Caches")
					if not Caches then
						return false
					end

					if type(Caches.survey) ~= "function" then
						return false
					end
					local n = tonumber(cfg.rescanEvery) or 120
					local v5 = table.pack(Caches.survey({ tiers = cfg.tiers, maxAge = n + tbl.FRESH_SLACK }))
					local v6, v7

					if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
						v6 = v5[1]
						v7 = v5[2]
					else
						v6 = nil
						v7 = nil
					end

					if not v6 then
						return false
					end

					if type(v7) ~= "table" then
						return false
					end

					if not v7.complete then
						return false
					end

					if v == "none" then
						if v7.up ~= 0 then
							return false
						end
					end

					local lead = v == "strong"

					if lead then
						lead = "Only caches guarded too hard for you are left here"
					end

					tbl2.lead = lead or "Every cache here is opened"
					local v8 = table.pack(Caches.nextDue({ tiers = cfg.tiers }))
					local v9, v10

					if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
						v9 = v8[1]
						v10 = v8[2]
					else
						v9 = nil
						v10 = nil
					end

					if v9 then
						if type(v10) == "table" then
							if tonumber(v10.dueIn) then
								if v10.dueIn <= tbl.COST then
									return false, ("%s. The next one is due in about %s, sooner than moving servers would take"):format(getLead(), clock(v10.dueIn))
								end
							end
						end
					end

					return true
				end

				return false
			end,
			go = function(job, arg2)
				local Servers = api("Servers")

				if Servers then
					Servers.note(tbl.REASON, { farm = "Auto Cache Farm", tiers = fn2(cfg.tiers), opened = tonumber(arg2) or 0 })
					local hop = Servers.hop
					local tbl3 = { avoidVisited = true }

					while true do
						tbl3.job = job
						local v = table.pack(hop(tbl3))

						if select("#", table.unpack(v, 1, v.n)) ~= 0 then
							hop = v[1]
							tbl3 = v[2]
						else
							hop = nil
							tbl3 = nil
						end

						if not job.alive then
							break
						end
						local errors = type(Servers.Errors) == "table"

						if errors then
							errors = Servers.Errors
						end

						errors = errors or {}

						if hop then
							tbl2.hops += 1
							local deadline = os.clock() + tbl.SETTLE
							local line = ("%s. Moving to a new server"):format(getLead())
							tbl2.waitUntil = deadline
							tbl2.line = line
							return 1, tbl2.line
						end

						if tbl3 == errors.CANCELLED then
							return 0, nil
						end

						if tbl3 == errors.BUSY then
							return 5, ("%s. Waiting for the move to another server to finish"):format(getLead())
						end
						local v5 = nil

						if type(Servers.explain) == "function" then
							local v6 = table.pack(Servers.explain(tbl3))
							local v7, v8

							if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
								v7 = v6[1]
								v8 = v6[2]
							else
								v7 = nil
								v8 = nil
							end

							if v7 then
								if type(v8) == "string" then
									v5 = v8
								end
							end
						end

						tbl2.waitUntil = os.clock() + tbl.RETRY
						tbl2.line = ("%s, but moving servers didn't work: %s Trying again in %s"):format(getLead(), v5 or "something went wrong.", clock(tbl.RETRY))
						return 1, tbl2.line
					end

					return 0, nil
				end

				local deadline = os.clock() + tbl.RETRY
				local line = ("%s, but moving servers isn't available right now"):format(getLead())
				tbl2.waitUntil = deadline
				tbl2.line = line
				return 1, tbl2.line
			end,
			count = function()
				return tbl2.hops
			end,
			reset = function()
				tbl2.waitUntil = 0
				tbl2.line = nil
				tbl2.hops = 0
				tbl2.lead = nil
			end,
		}
	end

	return tbl
end)

v4("Features/Auto/BossFarm", function(arg)
