			local v = Loot.new({ api = api, owner = "Boss Farm", cfg = cfg, travel = cfg.travel, tell = fn3 })
			local obj = setmetatable({}, { __mode = "k" })
			local tbl2 = {}

			local function fn4(arg3, arg4)
				local v5 = api(arg3)

				if v5 then
					if type(v5.explain) == "function" then
						local v6 = table.pack(v5.explain(arg4))
						local v7, v8

						if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
							v7 = v6[1]
							v8 = v6[2]
						else
							v7 = nil
							v8 = nil
						end

						if v7 then
							if type(v8) == "string" then
								return v8
							end
						end
					end
				end

				return "Something went wrong, trying again"
			end

			local function fn5()
				local State = api("State")

				if State then
					local v5 = table.pack(State.position())
					local v6, v7

					if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
						v6 = v5[1]
						v7 = v5[2]
					else
						v6 = nil
						v7 = nil
					end

					local v8 = v6

					if v8 then
						v8 = v7
					end

					return v8 or nil
				end

				return nil
			end

			local function fn6(arg3)
				local v5 = fn5()

				if v5 then
					if arg3 then
						return (v5 - arg3).Magnitude
					end
				end

				return math.huge
			end

			local function fn7()
				local trip = tbl.trip
				tbl.trip = nil

				if trip then
					if not trip.done then
						pcall(trip.stop)
					end
				end
			end

			local function fn8()
				local session = tbl.session
				tbl.session = nil
				tbl.note = nil

				if session then
					pcall(function()
						session:Detach("boss farm")
					end)
				end
			end

			local function fn9()
				if tbl.aura then
					tbl.aura.release()
				end

				tbl.aura = nil
				tbl.auraModel = nil
			end

			local function fn10()
				if tbl.instakill then
					tbl.instakill.release()
				end

				tbl.instakill = nil
			end

			local function fn11()
				fn8()
				fn9()
				fn10()
			end

			local function fn12()
				local platform = tbl.platform
				tbl.platform = nil

				if platform then
					pcall(function()
						platform:Destroy()
					end)
				end
			end

			local function fn13()
				tbl.slot = nil
				tbl.model = nil
				tbl.since = nil
				tbl.held = nil
				tbl.hunting = false
				tbl.name = nil
				tbl.note = nil
			end

			local hunts = arg2.hunts

