						end

						tbl3.remaining = remaining or nil
						return tbl3
					end

					return nil
				end

				return nil
			end

			tbl2.target = function()
				local v5 = tbl2.held()
				local Bosses = api("Bosses")
				if not v5 then
					return nil, v5
				end

				if not v5.boss then
