					v6 = nil
					v7 = nil
				end

				if not v6 then
					return nil, "Reading the boss hunt board..."
				end
				local now = os.clock()
				local tbl3 = {}
				local count = 0
				local reason = nil
				local v8 = table.pack(ipairs(v7))
				local v9, v10, v11

				if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
					v9 = v8[1]
					v10 = v8[2]
					v11 = v8[3]
				else
					v9 = nil
					v10 = nil
					v11 = nil
				end

				for _, v12 in v9, v10, v11 do
					if v12.forMe then
						if not v12.expired then
							count += 1

							if not v12.claimable then
								if reason == nil then
									reason = v12.reason
								end
							end
						end
					end

					local forMe = v12.forMe

					if forMe then
						forMe = v12.claimable
					end

					if forMe then
						forMe = not v12.expired
					end

					if forMe then
						forMe = v12.target ~= nil
					end

					if forMe then
						local flag = tbl[v12.id]

						if flag then
							flag = now < tbl[v12.id]
						end

						forMe = not flag
					end

					local forMe2 = forMe

					if forMe2 then
						forMe2 = pick.refresh(v12.target.slot)
					end

					forMe2 = forMe2 or nil
					if not forMe2 then
						continue
					end

					if not pick.allowed(forMe2) then
