							end

							rewards = rewards or 0
							local rewards2 = arg4.hunt.rewards

							if rewards2 then
								rewards2 = arg4.hunt.rewards.exp
							end

							rewards2 = rewards2 or 0
							if rewards == rewards2 then
								return (arg3.entry.distance or math.huge) < (arg4.entry.distance or math.huge)
							end
							return rewards > rewards2
						end

						return arg3.wait == 0
					end)

					return tbl3[1]
				end

				if count ~= 0 then
