					else
						fn4(("Your hunt for %s isn't for a boss this farm knows. It still blocks new hunts until it runs out"):format(str))
					end

					return nil
				end

				local v6 = table.pack(Quests.cooldown())
				local v7, v8

				if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
					v7 = v6[1]
					v8 = v6[2]
				else
					v7 = nil
					v8 = nil
				end

				if v7 then
					if v8.remaining > 0 then
