					end
				end

				local v9 = table.pack(fn13(arg2))
				local v10, v11

				if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
					v10 = v9[1]
					v11 = v9[2]
				else
					v10 = nil
					v11 = nil
				end

				if v10 then
					if Quests.claimHunt(v10.hunt.id) then
						fn4(("Doing your hunt for %s"):format(v10.entry.name))
						local rewards = v10.hunt.rewards

