								return ("Took the hunt for %s (+%s exp)"):format(v10.entry.name, fn10(rewards))
							end
						end

						return ("Took the hunt for %s"):format(v10.entry.name)
					end

					tbl[v10.hunt.id] = os.clock() + 60
					fn4(("The game didn't give you the hunt for %s. It tries the board again in a minute. %s"):format(v10.entry.name, fn5()))
					return nil
				end

				fn4(v11)
				return nil
			end

			return tbl2
		end,
