				Callback = function(finishWithInstakill)
					arg4.onInstakill(finishWithInstakill == true)
				end,
			})

			v5:AddToggle("YT_Caches", {
				Text = "Farm Caches For Hearts",
				Default = false,
				Premium = true,
				Disabled = arg4.caches ~= true,
				Tooltip = "While the Yeti's ice comes back, and when you run out of Frozen Hearts, clears sealed caches instead of waiting. Any cache can drop a Frozen Heart. Tier 3 caches, next to the Yeti, go first once you beat their guards quickly.",
