		end
		local library = arg2.Library
		local toggles = arg2.Toggles
		local tbl2 = { chests = false, drops = false, souls = false }
		local tbl3 = { travel = false, range = 80, returnHome = true, anyChest = true }
		local v5 = nil
		local flag = false
		local tbl4 = nil
		local tbl5 = {}
		local now = nil

		local function getApi()
			local api = arg2.Api
			local api2 = api

			if api2 then
				api2 = api.Chests
			end

			local api3 = type(api2) == "table"

			if api3 then
				api3 = api2
			end

			return api3 or nil
		end

		local function fn2(arg3)
			Identity.elevate()

			pcall(function()
				library:Notify(arg3, 4)
			end)
		end

		local function getChests()
			return tbl2.chests or tbl2.drops or tbl2.souls
		end

		local function fn3()
			return {
				kinds = { chest = tbl2.chests, drop = tbl2.drops, soul = tbl2.souls },
				radius = tbl3.range,
				travel = tbl3.travel,
				returnTo = tbl3.returnHome,
				anyChest = tbl3.anyChest,
				free = true,
			}
		end

		local function fn4()
			local v6 = v5
			v5 = nil

			if v6 then
				pcall(v6.release)
			end
		end

		local function fn5()
			local api = getApi()

			if api then
				if getChests() then
					if not Premium.isLocked() then
						if v5 then
							v5.update(fn3())
							return
						end
						local v6 = api.want("Auto Collect", fn3())

						if v6 then
							v5 = v6
						end

						return
					end
				end
			end

			fn4()
		end

		local function fn6()
			tbl2.chests = false
			tbl2.drops = false
			tbl2.souls = false
			fn5()
			Identity.elevate()
			local v6 = table.pack(ipairs({ "AC_Chests", "AC_Drops", "AC_Souls" }))
			local v7, v8, v9

			if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
				v7 = v6[1]
				v8 = v6[2]
				v9 = v6[3]
			else
				v7 = nil
				v8 = nil
				v9 = nil
			end

			for _, v10 in v7, v8, v9 do
				local toggles2 = toggles

				if toggles2 then
					toggles2 = toggles[v10]
				end

				if toggles2 then
					pcall(toggles2.SetValue, toggles2, false)
				end
			end
		end

		local function fn7(arg3)
			tbl4 = { text = arg3, at = os.clock() }
		end

		local api = getApi()

		if api then
			v.track(api.onClaimed:Connect(function(arg3)
				if type(arg3) ~= "table" then
					return
				end

				if arg3.by ~= "Auto Collect" then
					return
				end

				if arg3.kind ~= "chest" then
					if arg3.kind ~= "soul" then
						fn7(("Picked up %s"):format(tostring(arg3.name)))
						tbl5[#tbl5 + 1] = tostring(arg3.name)
						now = now or os.clock()
						return
					end

					fn7(("Took a %s"):format(tostring(arg3.name or "soul")))
					return
				end

				fn7(("Opened a %s"):format(tostring(arg3.name or "chest")))
			end))

			v.track(api.onMissed:Connect(function(arg3, arg4)
				if type(arg4) ~= "table" then
					return
				end

				if arg4.by ~= "Auto Collect" then
					return
				end

				if arg3 ~= "no_input" then
					if arg3 == "not_ready" then
						return
					end
					local flag2 = arg4.kind == "chest"

					if flag2 then
						flag2 = "open"
					end

					if not flag2 then
						flag2 = arg4.kind == "soul"

						if flag2 then
							flag2 = "take"
						end

						flag2 = flag2 or "pick up"
					end

					fn7(("Couldn't %s %s: %s"):format(flag2, tostring(arg4.name or "that"), api.missWords(arg3)))
					return
				end

				if not flag then
					flag = true
					local v6 = table.pack(api.explain(api.Errors.NO_INPUT))
					local v7

					if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
						v7 = v6[2]
					else
						v7 = nil
					end

					fn2(v7)
				end

				fn6()
			end))
		end

		local v6 = Place.groupbox(arg2, "Auto Collect", "package-open", { fallback = tbl, side = "Left" })

		if v6 then
			local flag2 = api == nil

			v6:AddToggle("AC_Chests", {
				Text = "Open Chests",
				Default = false,
				Premium = true,
				Disabled = flag2,
				Tooltip = "Opens boss chests near you. Everyone who fought the boss gets their own loot from the chest, so opening one never takes anybody else's.",
				Callback = function(openChests)
					tbl2.chests = openChests == true
					fn5()
				end,
			})

			local v7 = v6:AddDependencyBox()

			v7:AddToggle("AC_AnyChest", {
				Text = "Open Every Chest",
				Default = true,
				Premium = true,
				Disabled = flag2,
				Tooltip = "Opens every chest you reach, not only ones from bosses you fought. Turn it off to open just the chests from your own fights.",
				Callback = function(openEveryChest)
					tbl3.anyChest = openEveryChest == true
					fn5()
				end,
			})

			if toggles then
				if toggles.AC_Chests then
					v7:SetupDependencies({ { toggles.AC_Chests, true } })
				end
			end

			v6:AddToggle("AC_Drops", {
				Text = "Pick Up Drops",
				Default = false,
				Premium = true,
				Disabled = flag2,
				Tooltip = "Picks up loot on the ground that you're allowed to take: your own drops and free ones.",
				Callback = function(pickUpDrops)
					tbl2.drops = pickUpDrops == true
					fn5()
				end,
			})

			v6:AddToggle("AC_Souls", {
				Text = "Pick Up Souls",
				Default = false,
				Premium = true,
				Disabled = flag2,
				Tooltip = "Demons only: picks up the souls monsters leave when they die, which fill your demon progress. Does nothing if you're not a demon.",
				Callback = function(pickUpSouls)
					tbl2.souls = pickUpSouls == true
					fn5()
				end,
			})

			v6:AddToggle("AC_Travel", {
				Text = "Go To Them",
				Default = false,
				Premium = true,
				Disabled = flag2,
				Tooltip = "Hops you right next to each chest, drop and soul in range instead of only taking what's already next to you. While a farm is using your character it only takes what's next to you.",
				Callback = function(goToThem)
					tbl3.travel = goToThem == true
					fn5()
				end,
			})

			local v8 = v6:AddDependencyBox()

			v8:AddSlider("AC_Range", {
				Text = "Range",
				Default = 80,
				Min = 10,
				Max = 300,
				Rounding = 0,
				Suffix = " studs",
				Premium = true,
				Disabled = flag2,
				Tooltip = "How far away something can be for it to go and get it.",
				Callback = function(range)
					tbl3.range = math.max(10, math.floor(tonumber(range) or 80))
					fn5()
				end,
			})

			v8:AddToggle("AC_Return", {
				Text = "Come Back Afterwards",
				Default = true,
				Premium = true,
				Disabled = flag2,
				Tooltip = "Takes you back to where you were once everything in range is picked up.",
				Callback = function(comeBackAfterwards)
					tbl3.returnHome = comeBackAfterwards == true
					fn5()
				end,
			})

			if toggles then
				if toggles.AC_Travel then
					v8:SetupDependencies({ { toggles.AC_Travel, true } })
				end
			end

			local Off = v6:AddLabel("Off", true)
			local v9 = nil

			local function fn8(arg3)
				if v9 == arg3 then
					return
				end
				Identity.elevate()

				if pcall(Off.SetText, Off, arg3) then
					v9 = arg3
				end
			end

			local function fn9()
				if not getChests() then
					return "Off"
				end
				local api2 = getApi()

				if api2 then
					if Premium.isLocked() then
						return "Auto Collect needs premium"
					end
					local now2 = os.clock()

					if tbl4 then
						if now2 - tbl4.at <= 6 then
							return tbl4.text
						end
					end

					local v10 = table.pack(api2.status())
					local v11, v12

					if select("#", table.unpack(v10, 1, v10.n)) ~= 0 then
						v11 = v10[1]
						v12 = v10[2]
					else
						v11 = nil
						v12 = nil
					end

					if v11 then
						if type(v12) == "table" then
