								end
							end

							if v12.collecting then
								return "Collecting..."
							end
						end
					end

					if tbl3.travel then
						return ("Looking for loot within %d studs"):format(tbl3.range)
					end
					return "Waiting for loot next to you"
				end

				return "Loot collecting isn't available right now"
			end

			v.track(Jobs_.interval(0.5, function()
