			v13:AddLabel("<b>Script</b>  @tevilii")
			v13:AddLabel("<b>UI Library</b>  Obsidian by deivid")
			local urls2 = meta.urls or {}

			if helpers.copyLink then
				if urls2.obsidian then
					v13:AddButton({
						Text = "Obsidian Library",
						Tooltip = urls2.obsidian,
						Func = function()
							helpers.copyLink(urls2.obsidian, "Obsidian link copied!")
						end,
					})
				end
			end

			v13:AddDivider()
			v13:AddLabel("This script is provided for educational and customization purposes.\nRespect Roblox and game TOS. You are responsible for your usage.", true)
		end
	end)
end

v4("Features/Connectivity", function(arg)
	local State = arg("Features/Connectivity/State")
	local Broadcaster = arg("Features/Connectivity/Broadcaster")
	local Scanner = arg("Features/Connectivity/Scanner")
	local Overlay = arg("Features/Connectivity/Overlay")

	local function fn2(player)
		if player then
			local displayName = player.DisplayName ~= ""

			if displayName then
				displayName = player.DisplayName
			end

			return displayName or player.Name
		end

		return ""
	end

	return function(arg2)
		local library = arg2.Library
		local tabs = arg2.Tabs
		local services = arg2.Services
		local references = arg2.References
		local unloader = arg2.Unloader
		if not library then
			return
		end

		if not tabs then
			return
		end

		if not tabs.Home then
			return
		end
		local v = State.load()
		local tbl = { broadcast = v.broadcast, overlay = v.overlay }
		local v5 = nil
		local v6 = nil
		local v7 = nil

		local function fn3()
			if v7 then
				return v7
			end
			v7 = Overlay.start({ services = services, references = references })
			return v7
		end

		local function fn4()
			if v6 then
				return
			end

			v6 = Scanner.start({
				services = services,
				references = references,
				onIdentified = function(arg3)
					library:Notify(string.format("Cerberus user spotted: %s", fn2(arg3)), 4)

					if tbl.overlay then
						if v7 then
							v7:attach(arg3, fn2(arg3))
						end
					end
				end,
				onLost = function(arg3)
					if v7 then
						v7:detach(arg3)
					end
				end,
			})
		end

		local function fn5()
			if v6 then
				v6:stop()
				v6 = nil
			end
		end

		local function fn6(arg3)
			if arg3 then
				if not v5 then
					v5 = Broadcaster.start({ references = references })
				end
			elseif v5 then
				v5:stop()
				v5 = nil
			end
		end

		local function fn7(arg3)
			if arg3 then
				fn3()
				local player = references.player

				if player then
					player = references.player.UserId
				end

				if v6 then
					local v8 = table.pack(pairs(v6.identified))
					local v9, v10, v11

					if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
						v9 = v8[1]
						v10 = v8[2]
						v11 = v8[3]
					else
						v9 = nil
						v10 = nil
						v11 = nil
					end

					for k in v9, v10, v11 do
						if k ~= player then
							local playerByUserId = services.Players:GetPlayerByUserId(k)

							if playerByUserId then
								v7:attach(playerByUserId, fn2(playerByUserId))
							end
						end
					end
				end
			elseif v7 then
				v7:detachAll()
			end
		end

		local Connectivity = tabs.Home:AddRightGroupbox("Connectivity", "wifi")

		Connectivity:AddLabel({
			Text = "Find other <b>Cerberus</b> users in your server. Broadcast your presence and see an overlay above other Cerberus users.",
			DoesWrap = true,
		})

		Connectivity:AddDivider()

		Connectivity:AddToggle("Connectivity_Broadcast", {
			Default = tbl.broadcast,
			Text = "Broadcast Identity",
			Tooltip = "Lets other Cerberus users in this server detect you. Disable to stay invisible.",
			Callback = function(broadcastIdentity)
				tbl.broadcast = broadcastIdentity
				State.save(tbl)
				fn6(broadcastIdentity)
			end,
		})

		Connectivity:AddToggle("Connectivity_Overlay", {
			Default = tbl.overlay,
			Text = "Cerberus Overlay",
			Tooltip = "Show the Cerberus logo above identified Cerberus users (you'll see it; other players don't).",
			Callback = function(cerberusOverlay)
				tbl.overlay = cerberusOverlay
				State.save(tbl)
				fn7(cerberusOverlay)
			end,
		})

		fn6(tbl.broadcast)

		if tbl.overlay then
			fn7(true)
		end

		fn4()

		if unloader then
			if unloader.Register then
				unloader:Register(function()
					if v5 then
						v5:stop()
						v5 = nil
					end

					fn5()

					if v7 then
						v7:stop()
						v7 = nil
					end
				end)
			end
		end
	end
end)

v4("Features/Connectivity/Overlay", function(arg)
	local VMath = arg("Utility/Helpers/VMath")
	local Scheduler = arg("Utility/Scheduler")
	local UiHost = arg("UI/UiHost")
	local y = 3.5
	local n8 = 30
	local n9 = 0.25
	local n10 = 4

	local function getVector2()
		return Vector2.new(56, 56)
	end

	local function createFrame()
		local vector2 = getVector2()
		local overlayRoot = Instance.new("Frame")
		overlayRoot.Name = "OverlayRoot"
		overlayRoot.AnchorPoint = Vector2.new(0.5, 1)
		overlayRoot.Size = UDim2.fromOffset(vector2.X, vector2.Y)
		overlayRoot.BackgroundTransparency = 1
		overlayRoot.Visible = false

		local uiScale = Instance.new("UIScale")
		uiScale.Scale = 1
		uiScale.Parent = overlayRoot

		local logoFrame = Instance.new("Frame")
		logoFrame.Name = "LogoFrame"
		logoFrame.AnchorPoint = Vector2.new(0.5, 0.5)
		logoFrame.Position = UDim2.fromScale(0.5, 0.5)
		logoFrame.Size = UDim2.fromOffset(48, 48)
		logoFrame.BackgroundColor3 = Color3.fromRGB(15, 15, 18)
		logoFrame.BackgroundTransparency = 0.05
		logoFrame.BorderSizePixel = 0
		logoFrame.Parent = overlayRoot

		local uiCorner = Instance.new("UICorner")
		uiCorner.CornerRadius = UDim.new(0, 8)
		uiCorner.Parent = logoFrame

		local uiStroke = Instance.new("UIStroke")
		uiStroke.Color = Color3.fromRGB(0, 200, 130)
		uiStroke.Thickness = 1.5
		uiStroke.Transparency = 0.2
		uiStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		uiStroke.Parent = logoFrame

		local logo = Instance.new("ImageLabel")
		logo.Name = "Logo"
		logo.Size = UDim2.new(1, -8, 1, -8)
		logo.Position = UDim2.fromOffset(4, 4)
		logo.BackgroundTransparency = 1
		logo.Image = "rbxassetid://136497541793809"
		logo.ScaleType = Enum.ScaleType.Fit
		logo.Parent = logoFrame
		return overlayRoot
	end

	local function getHead(instance)
		if not instance then
			return nil
		end
		return instance:FindFirstChild("Head") or instance:FindFirstChild("HumanoidRootPart")
	end

	local tbl = { start = function(arg2)
		local workspace = arg("Services").Workspace
		local tbl = { stopped = false, entries = {} }
		local parentGui = arg2

		if parentGui then
			parentGui = arg2.parentGui
		end

		tbl.parent = parentGui

		if not tbl.parent then
			local connectivityOverlay = Instance.new("ScreenGui")
			connectivityOverlay.Name = "ConnectivityOverlay"
			connectivityOverlay.ResetOnSpawn = false
			connectivityOverlay.IgnoreGuiInset = true
			connectivityOverlay.DisplayOrder = 200
			connectivityOverlay.Parent = UiHost.pick()
			tbl.parent = connectivityOverlay
			tbl.ownsParent = true
		end

		tbl.renderConn = Scheduler.render(function()
			local n = workspace.CurrentCamera
			if not n then
				return
			end
			local k = n.ViewportSize
			local v = n.CFrame.Position

			for P, P in pairs(tbl.entries) do
				local C = P.frame

				if C and C.Parent then
					local b = getHead(P.player.Character)

					if b then
						local z = b.Position + Vector3.new(0, y, 0)
						local A = n:WorldToViewportPoint(z)

						if A.Z > 0 then
							local n = math.clamp(A.X, 0, k.X)
							local b = math.clamp(A.Y, 0, k.Y)
							C.Position = UDim2.fromOffset(n, b)
							C.Visible = true

							if P.uiScale then
								local n = VMath.distanceSqr3(v, z)

								if n < 1 then
									n = 1
								end

								local p = n8 / math.sqrt(n)

								if p < n9 then
									p = n9
								end

								if p > n10 then
									p = n10
								end

								P.uiScale.Scale = p
							end
						else
							C.Visible = false
						end
					else
						C.Visible = false
					end
				end
			end
		end, { name = "ConnectivityOverlay", priority = 200, deferrable = true })

		tbl.attach = function(arg3, player)
			if not arg3.stopped then
				if player then
					if arg3.entries[player.UserId] then
						return
					end
					local frame = createFrame()
					frame.Parent = arg3.parent
					arg3.entries[player.UserId] = { player = player, frame = frame, uiScale = frame:FindFirstChildOfClass("UIScale") }
				end
			end
		end

		tbl.detach = function(arg3, player)
			if player then
				local entry = arg3.entries[player.UserId]

				if entry then
					if entry.frame then
						pcall(function()
							entry.frame:Destroy()
						end)
					end

					arg3.entries[player.UserId] = nil
					return
				end

				return
			end
		end

		tbl.detachAll = function(arg3)
			local v = table.pack(pairs(arg3.entries))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for k, v8 in v5, v6, v7 do
				if v8.frame then
					pcall(function()
						v8.frame:Destroy()
					end)
				end

				arg3.entries[k] = nil
			end
		end

		tbl.stop = function(arg3)
			if arg3.stopped then
				return
			end
			arg3.stopped = true

			if arg3.renderConn then
				pcall(function()
					arg3.renderConn:Disconnect()
				end)

				arg3.renderConn = nil
			end

			arg3:detachAll()

			if arg3.ownsParent then
				if arg3.parent then
					pcall(function()
						arg3.parent:Destroy()
					end)

					arg3.parent = nil
				end
			end
		end

		return tbl
	end }

	return tbl
end)

v4("Features/Connectivity/Scanner", function(arg)
	local Jobs_ = arg("Utility/Jobs")
	local secretSpeed = arg("Features/Connectivity/Broadcaster").SECRET_SPEED

	local function fn2(player, player2)
		if player2 then
			if player.UserId == player2.UserId then
				return false
			end
		end

		local character = player.Character
		if not character then
			return false
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		local humanoid2 = humanoid

		if humanoid2 then
			humanoid2 = humanoid:FindFirstChildOfClass("Animator")
		end

		if humanoid2 then
			local v = table.pack(ipairs(humanoid2:GetPlayingAnimationTracks()))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				if math.abs(v8.Speed - secretSpeed) < 1e-05 then
					return true
				end
			end

			return false
		end

		return false
	end

	local tbl = { start = function(arg2)
		local players = arg2.services.Players
		local references = arg2.references

		if references then
			references = arg2.references.player
		end

		local onIdentified = arg2.onIdentified
		local onLost = arg2.onLost
		local tbl = { stopped = false, identified = {} }

		local connection = players.PlayerRemoving:Connect(function(player)
			if tbl.stopped then
				return
			end

			if tbl.identified[player.UserId] then
				tbl.identified[player.UserId] = nil

				if onLost then
					pcall(onLost, player)
				end
			end
		end)

		local references2 = references

		if references2 then
			references2 = references.UserId
		end

		tbl.job = Jobs_.interval(1, function()
			local v = table.pack(ipairs(players:GetPlayers()))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, player in v5, v6, v7 do
				if player.UserId == references2 then
					continue
				end
				local v8 = fn2(player, references)
				local flag = tbl.identified[player.UserId] == true

				if v8 then
					if not flag then
						tbl.identified[player.UserId] = true
						if not onIdentified then
							continue
						end
						pcall(onIdentified, player)
						continue
					end
				end

				if v8 then
					continue
				end

				if flag then
					tbl.identified[player.UserId] = nil

					if onLost then
						pcall(onLost, player)
					end
				end
			end
		end, { name = "ConnectivityScan", immediate = true })

		tbl.stop = function(arg3)
			if arg3.stopped then
				return
			end
			arg3.stopped = true

			if arg3.job then
				arg3.job:Cancel()
				arg3.job = nil
			end

			if connection then
				pcall(function()
					connection:Disconnect()
				end)
			end

			arg3.identified = {}
		end

		return tbl
	end }

	return tbl
end)

v4("Features/Connectivity/Broadcaster", function(arg)
	local Log = arg("Utility/Log")

	local function fn2(instance, arg2)
		local humanoid = instance:WaitForChild("Humanoid", 5)
		if not humanoid then
			return
		end

		if arg2.stopped then
			return
		end
		local animator = humanoid:WaitForChild("Animator", 5)
		if not animator then
			return
		end

		if arg2.stopped then
			return
		end
		local animationId = nil

		while not animationId do
			if arg2.stopped then
				break
			end
			local tracks = animator:GetPlayingAnimationTracks()
			local v = table.pack(ipairs(tracks))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, track in v5, v6, v7 do
				if not track.Animation then
					continue
				end

				if track.Animation.AnimationId ~= "" then
					if math.abs(track.Speed - 0.01337) > 0.0001 then
						animationId = track.Animation.AnimationId
						break
					end
				end
			end

			if not animationId then
				task.wait(0.5)
			end
		end

		if not arg2.stopped then
			if animationId then
				local animation = Instance.new("Animation")
				animation.AnimationId = animationId
				local v = table.pack(pcall(animator.LoadAnimation, animator, animation))
				local v5, track

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					track = v[2]
				else
					v5 = nil
					track = nil
				end

				if not v5 then
					return
				end

				if not track then
					return
				end
				pcall(track.Play, track, 0, 0.0001, 0.01337)
				arg2.track = track
				arg2.anim = animation
			end
		end
	end

	local tbl = {
		SECRET_SPEED = 0.01337,
		start = function(arg2)
			local references = arg2.references
			local references2 = references

			if references2 then
				references2 = references.player
			end

			if references2 then
				local tbl = { stopped = false }

				local function onCharacterAdded(character)
					if tbl.stopped then
						return
					end
					tbl.character = character

					task.spawn(function()
						local n, A = pcall(fn2, character, tbl)

						if not n then
							Log.warn("[Cerberus.Connectivity] broadcaster hijack threw: " .. tostring(A))
						end
					end)
				end

				if references2.Character then
					onCharacterAdded(references2.Character)
				end

				tbl.charConn = references2.CharacterAdded:Connect(onCharacterAdded)

				tbl.stop = function(arg3)
					if arg3.stopped then
						return
					end
					arg3.stopped = true

					if arg3.charConn then
						pcall(function()
							arg3.charConn:Disconnect()
						end)
					end

					if arg3.track then
						pcall(arg3.track.Stop, arg3.track)
					end

					if arg3.track then
						pcall(arg3.track.Destroy, arg3.track)
					end

					if arg3.anim then
						pcall(arg3.anim.Destroy, arg3.anim)
					end

					arg3.track = nil
					arg3.anim = nil
				end

				return tbl
			end

			return nil
		end,
	}

	return tbl
end)

v4("Features/Connectivity/State", function(arg)
	local Store = arg("Utility/Store")
	local str = Store.GAME .. "/settings"
	local tbl = { broadcast = true, overlay = true }

	local tbl2 = {
