			v18 = v17[1]
			v19 = v17[2]
			v20 = v17[3]
		else
			v18 = nil
			v19 = nil
			v20 = nil
		end

		for k in v18, v19, v20 do
			n += 1
		end

		local n8 = n - #tbl - #tbl2
		local flag3 = #tbl + #tbl2 > 0
		local str2

		if flag3 then
			str2 = string.format("Partial support (%d/%d required)", n8, n)
		elseif v16 then
			local str3 = "Partial support (%s — known limitations)"
			local format = ("Partial support (%s — known limitations)").format
			local str4 = flag

			if str4 then
				str4 = "Xeno"
			end

			str2 = format(str3, str4 or "Solara")
		elseif not (#tbl3 > 0) then
			str2 = "Full support"
		else
			str2 = string.format("Partial support (%d recommended unavailable)", #tbl3)
		end

		return {
			ok = not flag3,
			isXeno = flag,
			isSolara = flag2,
			isLimited = v16,
			executorName = tostring(arg3 or "Unknown"),
			missingRequired = tbl,
			missingAnyOfGroups = tbl2,
			missingRecommended = tbl3,
			totalRequired = n,
			satisfiedRequired = n8,
			statusLabel = str2,
		}
	end

	local function fn3(arg2)
		local tbl = {}

		if #arg2.missingRequired > 0 then
			tbl[#tbl + 1] = "Missing required: " .. table.concat(arg2.missingRequired, ", ")
		end

		local v = table.pack(ipairs(arg2.missingAnyOfGroups))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for _, v8 in v5, v6, v7 do
			tbl[#tbl + 1] = string.format("Missing any-of [%s]: %s", v8.name, table.concat(v8.options, " / "))
		end

		if #arg2.missingRecommended > 0 then
			tbl[#tbl + 1] = "Missing recommended: " .. table.concat(arg2.missingRecommended, ", ")
		end

		return tbl
	end

	local function fn4(arg2)
		local tbl = {}

		if #arg2.missingRequired > 0 then
			tbl[#tbl + 1] = string.format("%d required missing (%s)", #arg2.missingRequired, table.concat(arg2.missingRequired, ", "))
		end

		if #arg2.missingAnyOfGroups > 0 then
			local names = {}
			local v = table.pack(ipairs(arg2.missingAnyOfGroups))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				names[#names + 1] = v8.name
			end

			tbl[#tbl + 1] = string.format("%d required group(s) unmet (%s)", #arg2.missingAnyOfGroups, table.concat(names, ", "))
		end

		if #tbl ~= 0 then
			return "Executor missing capabilities — " .. table.concat(tbl, "; ")
		end
		return nil
	end

	return { analyze = fn2, resolveExec = get, describeGaps = fn3, buildLaunchMessage = fn4 }
end)

v4("UI/Vendor/SaveManager", function()
	return assert(loadstring([[local cloneref = (cloneref or clonereference or function(instance: any)
    return instance
end)
local clonefunction = (clonefunction or copyfunction or function(func)
    return func
end)

local HttpService: HttpService = cloneref(game:GetService("HttpService"))
local Players: Players = cloneref(game:GetService("Players")) -- cerberus: per-player autoload profiles
local isfolder, isfile, listfiles = isfolder, isfile, listfiles

if typeof(clonefunction) == "function" then
    -- Fix is_____ functions for shitsploits, those functions should never error, only return a boolean.

    local
        isfolder_copy,
        isfile_copy,
        listfiles_copy = clonefunction(isfolder), clonefunction(isfile), clonefunction(listfiles)

    local isfolder_success, isfolder_error = pcall(function()
        return isfolder_copy("test" .. tostring(math.random(1000000, 9999999)))
    end)

    if isfolder_success == false or typeof(isfolder_error) ~= "boolean" then
        isfolder = function(folder)
            local success, data = pcall(isfolder_copy, folder)
            return (if success then data else false)
        end

        isfile = function(file)
            local success, data = pcall(isfile_copy, file)
            return (if success then data else false)
        end

        listfiles = function(folder)
            local success, data = pcall(listfiles_copy, folder)
            return (if success then data else {})
        end
    end
end

local SaveManager = {
    Library = nil,

    Folder = "ObsidianLibSettings",
    SubFolder = "",

    Ignore = {},
    LoadingOrder = {},
    UseLoadingOrder = false,

    AutoloadConfig = nil,

    -- cerberus fork additions: per-player autoload mapping, encrypted web configs, and the shared secret that decrypts them
    PlayerConfigs = {},
    WebConfigs = {},
    WebConfigIndex = {},
    SecretKey = nil
}

function SaveManager:SetLibrary(Library)
    SaveManager.Library = Library
end

--// Element Parser \\--
local SpecialValueParser = {
    UDim2 = {
        Encode = function(Value: UDim2)
            return {
                X = { Scale = Value.X.Scale, Offset = Value.X.Offset },
                Y = { Scale = Value.Y.Scale, Offset = Value.Y.Offset }
            }
        end,

        Decode = function(Data: any)
            local DataType = typeof(Data)
            if DataType == "table" then
                return UDim2.new(Data.X.Scale, Data.X.Offset, Data.Y.Scale, Data.Y.Offset)
            elseif DataType == "UDim2" then
                return Data
            end

            return nil
        end
    }
}

local ElementParser = {}; do
    local function CreateParser(
        ElementType: string,
        LibaryIndex: string,

        Save: (string, any, ...any) -> any,
        Load: (any?, any) -> any,
        CustomElementFetcher: boolean?
    )
        ElementParser[ElementType] = {
            Save = function(Index: string, Element: any, ...)
                local Data = Save(Index, Element, ...)
                Data.type = ElementType
                Data.idx = Index

                return Data
            end,

            Load = function(Index: string?, Data: any)
                if CustomElementFetcher == true then
                    return Load(nil, Data)
                end

                local Elements = SaveManager.Library and SaveManager.Library[LibaryIndex]
                local Element = Elements and Elements[Index]
                return Load(Element, Data)
            end
        }
    end

    CreateParser(
        "Toggle", "Toggles",
        function(Index: string, Toggle: any)
            return { value = Toggle.Value }
        end,
        function(Element: any?, Data: any)
            if not Element then return end
            if Element.Value == Data.value then
                Element:RunChanged()
                return
            end

            Element:SetValue(Data.value)
        end
    )

    CreateParser(
        "Slider", "Options",
        function(Index: string, Slider: any)
            return { value = tostring(Slider.Value) }
        end,
        function(Element: any?, Data: any)
            if not Element then return end
            if Element.Value == Data.value then
                Element:RunChanged()
                return
            end

            Element:SetValue(Data.value)
        end
    )

    CreateParser(
        "Dropdown", "Options",
        function(Index: string, Dropdown: any)
            return { value = Dropdown.Value, multi = Dropdown.Multi }
        end,
        function(Element: any?, Data: any)
            if not Element then return end
            if Element.Value == Data.value then
                Element:RunChanged()
                return
            end

            Element:SetValue(Data.value)
        end
    )

    CreateParser(
        "ColorPicker", "Options",
        function(Index: string, ColorPicker: any)
            return { value = ColorPicker.Value:ToHex(), transparency = ColorPicker.Transparency }
        end,
        function(Element: any?, Data: any)
            if not Element then return end

            Element:SetValueRGB(Color3.fromHex(Data.value), Data.transparency)
        end
    )

    CreateParser(
        "KeyPicker", "Options",
        function(Index: string, KeyPicker: any)
            return { mode = KeyPicker.Mode, key = KeyPicker.Value, modifiers = KeyPicker.Modifiers, toggled = KeyPicker.Toggled }
        end,
        function(Element: any?, Data: any)
            if not Element then return end

            Element:SetValue({ Data.key, Data.mode, Data.modifiers })
            if Data.mode == "Toggle" and Data.toggled ~= nil then
                Element.Toggled = Data.toggled
                Element:Update()
            end
        end
    )

    CreateParser(
        "Input", "Options",
        function(Index: string, Input: any)
            return { text = Input.Value }
        end,
        function(Element: any?, Data: any)
            if not Element then return end
            if typeof(Data.text) ~= "string" then return end

            if Element.Value == Data.text then
                Element:RunChanged()
                return
            end

            Element:SetValue(Data.text)
        end
    )

    CreateParser(
        "Groupbox", "Tabs",
        function(Index: string, Groupbox: any, TabIndex: string)
            return { collapsed = Groupbox.Collapsed, tabIdx = TabIndex }
        end,
        function(_, Data: any)
            local TabIndex, Index = Data.tabIdx, Data.idx
            if typeof(TabIndex) ~= "string" or typeof(Index) ~= "string" then return end

            local Tabs = SaveManager.Library and SaveManager.Library.Tabs
            local Tab = Tabs and Tabs[TabIndex]
            if not Tab then return end

            local Groupbox = Tab.Groupboxes[Index]
            if not Groupbox or Groupbox.Collapsed == Data.collapsed then return end

            Groupbox:SetCollapsed(Data.collapsed == true)
        end,
        true
    )
end

--// Helpers \\--
local function Trim(Text: string)
    return Text:match("^%s*(.-)%s*$")
end

local function IsStringEmpty(String: string): boolean
    return if typeof(String) == "string" then Trim(String) == "" else true
end

local function IsValidFolderPath(Name: string): boolean
    return typeof(Name) == "string" and (
        Trim(Name) ~= "" and
        not Name:match("^%s*$") and
        not Name:find('[<>:"|%?%*%z]')
    )
end

--// Folder helper \\--
local function SplitPath(Path: string): {string}
	local Result = {}
	local Current = ""

	for Part in string.gmatch(Path, "[^/]+") do
		Current = if Current == "" then Part else (Current .. "/" .. Part)
		table.insert(Result, Current)
	end

	return Result
end

local function GetFolderPath(): false | string
    if IsStringEmpty(SaveManager.Folder) then
        return false
    end

    return string.format("%s/settings", SaveManager.Folder)
end

local function GetSubFolderPath(): false | string
    if IsStringEmpty(SaveManager.Folder) or IsStringEmpty(SaveManager.SubFolder) then
        return false
    end

    return string.format("%s/settings/%s", SaveManager.Folder, SaveManager.SubFolder)
end

local function GetCurrentSettingsPath(): false | string
    local SubFolderPath = GetSubFolderPath()
    return if SubFolderPath == false then GetFolderPath() else SubFolderPath
end

--// Files helper \\--
local function GetConfigPath(ConfigName: string): false | string
    local CurrentSettingsPath = GetCurrentSettingsPath()
    return if CurrentSettingsPath == false then false else string.format("%s/%s.json", CurrentSettingsPath, ConfigName)
end

local function DoesConfigExist(ConfigName: string): boolean
    local ConfigPath = GetConfigPath(ConfigName)
    return if ConfigPath == false then false else isfile(ConfigPath)
end

local function GetAutoloadPath(): false | string
    local CurrentSettingsPath = GetCurrentSettingsPath()
    return if CurrentSettingsPath == false then false else string.format("%s/autoload.txt", CurrentSettingsPath)
end

-- cerberus: path to the per-player autoload mapping file
local function GetPlayerConfigPath(): false | string
    local CurrentSettingsPath = GetCurrentSettingsPath()
    return if CurrentSettingsPath == false then false else string.format("%s/autoload_players.json", CurrentSettingsPath)
end

-- cerberus: a config is loadable if it exists on disk OR is a known web config
local function IsWebConfig(Name: string): boolean
    return SaveManager.WebConfigIndex ~= nil and SaveManager.WebConfigIndex[Name] ~= nil
end

local function ConfigIsLoadable(Name: string): boolean
    if typeof(Name) ~= "string" or Name == "" then
        return false
    end
    return DoesConfigExist(Name) or IsWebConfig(Name)
end

--// Cerberus: web-config crypto helpers \\--
local function normalizeWebConfigs(list)
    local configs = {}
    if type(list) == "table" then
        for i, cfg in ipairs(list) do
            if type(cfg) == "table" then
                local name = tostring(cfg.Name or cfg.name or ("Web Config " .. i))
                configs[#configs + 1] = {
                    Name = name,
                    Url = cfg.Url or cfg.url,
                    EncryptedUrl = cfg.EncryptedUrl or cfg.encryptedUrl or cfg.EncryptedURL or cfg.encryptedURL,
                    Config = cfg.Config or cfg.config,
                }
            end
        end
    end
    return configs
end

local function decodeBase64(data)
    if type(data) ~= "string" then
        return nil
    end
    local ok, res = pcall(function()
        if crypt and crypt.base64 and crypt.base64.decode then
            return crypt.base64.decode(data)
        elseif bit and bit.base64 and bit.base64.decode then
            return bit.base64.decode(data)
        end
        return HttpService:JSONDecode('"' .. data .. '"')
    end)
    if ok and type(res) == "string" then
        return res
    end
    return nil
end

local function xorDecrypt(decodedStr, key)
    if type(decodedStr) ~= "string" or decodedStr == "" then
        return nil
    end
    if type(key) ~= "string" or key == "" then
        return nil
    end
    if not (bit32 and bit32.bxor) then
        return nil
    end
    local output = table.create(#decodedStr)
    local keyLen = #key
    for i = 1, #decodedStr do
        local b = string.byte(decodedStr, i, i)
        local k = string.byte(key, (i - 1) % keyLen + 1, (i - 1) % keyLen + 1)
        output[i] = string.char(bit32.bxor(b, k))
    end
    return table.concat(output)
end

local function decryptPayload(encryptedString, key)
    if type(encryptedString) ~= "string" then
        return nil, "invalid payload"
    end
    if type(key) ~= "string" or key == "" then
        return nil, "missing key"
    end
    local decodedStr = decodeBase64(encryptedString)
    if not decodedStr then
        return nil, "base64 decode failed"
    end
    local plain = xorDecrypt(decodedStr, key)
    if not plain then
        return nil, "xor decrypt failed"
    end
    return plain
end

--// Indexes \\--
function SaveManager:SetLoadingOrder(Enabled: boolean, Order: {string}?)
    SaveManager.UseLoadingOrder = Enabled == true
    SaveManager.LoadingOrder = typeof(Order) == "table" and Order or SaveManager.LoadingOrder
end

function SaveManager:SetIgnoreIndexes(Indexes: {string}?)
    assert(typeof(Indexes) == "table", "Expected table, got " .. typeof(Indexes))

    for _, Index in Indexes do
        SaveManager.Ignore[Index] = true
    end
end

function SaveManager:IgnoreThemeSettings()
    SaveManager:SetIgnoreIndexes({
        "BackgroundColor", "MainColor", "AccentColor", "OutlineColor", "FontColor", "FontFace", "BackgroundImage",
        "ThemeManager_ThemeList", "ThemeManager_CustomThemeList", "ThemeManager_CustomThemeName"
    })
end

-- cerberus: shared secret used to decrypt gated web configs
function SaveManager:SetConfigSecrets(Secrets)
    if type(Secrets) == "table" then
        SaveManager.SecretKey = Secrets.Key or Secrets.ConfigKey or Secrets.AutoParryKey
    elseif type(Secrets) == "string" then
        SaveManager.SecretKey = Secrets
    end
end

-- cerberus: register remote/community configs surfaced alongside disk ones
function SaveManager:SetWebConfigs(list)
    SaveManager.WebConfigs = normalizeWebConfigs(list)
    SaveManager.WebConfigIndex = {}
    for _, cfg in ipairs(SaveManager.WebConfigs) do
        if type(cfg.Name) == "string" then
            SaveManager.WebConfigIndex[cfg.Name] = cfg
        end
    end
end

--// Folders \\--
function SaveManager:GetPaths(): {string}
    local SubFolderPath = GetSubFolderPath()
    if SubFolderPath == false then
        local FolderPath = GetFolderPath()
        return if FolderPath == false then {} else SplitPath(FolderPath)
    end

    return SplitPath(SubFolderPath)
end

function SaveManager:BuildFolderTree(SkipWhenCreated: boolean?)
    local Paths = SaveManager:GetPaths()
    if #Paths == 0 then
        return false
    end

    if SkipWhenCreated == true then
        if isfolder(Paths[1]) then
            return true
        end
    end

    for _, Path in Paths do
        if isfolder(Path) then continue end

        makefolder(Path)
    end

    return true
end

function SaveManager:CheckFolderTree()
    return SaveManager:BuildFolderTree(true)
end

function SaveManager:CheckSubFolder(CreateFolder: boolean)
    local SubFolderPath = GetSubFolderPath()
    if SubFolderPath == false then
        return false
    end

    local FolderExists = isfolder(SubFolderPath)
    if not CreateFolder then
        return FolderExists
    end

    makefolder(SubFolderPath)
    return true
end

function SaveManager:SetFolder(Folder: string)
    assert(IsValidFolderPath(Folder), "Invalid path provided")

    SaveManager.Folder = Folder
    SaveManager:BuildFolderTree()
end

function SaveManager:SetSubFolder(SubFolder: string)
    assert(IsValidFolderPath(SubFolder), "Invalid path provided")

    SaveManager.SubFolder = SubFolder
    SaveManager:BuildFolderTree()
end

--// Cerberus: per-player autoload mapping \\--
function SaveManager:LoadPlayerConfigs()
    local Path = GetPlayerConfigPath()
    if Path == false or not isfile(Path) then
        SaveManager.PlayerConfigs = {}
        return SaveManager.PlayerConfigs
    end

    local Success, Decoded = pcall(HttpService.JSONDecode, HttpService, readfile(Path))
    SaveManager.PlayerConfigs = (Success and typeof(Decoded) == "table") and Decoded or {}
    return SaveManager.PlayerConfigs
end

function SaveManager:SavePlayerConfigs()
    local Path = GetPlayerConfigPath()
    if Path == false then
        return false
    end

    SaveManager:CheckFolderTree()

    local Success, Encoded = pcall(HttpService.JSONEncode, HttpService, SaveManager.PlayerConfigs)
    if not Success then
        return false
    end

    local WriteSuccess = pcall(writefile, Path, Encoded)
    return WriteSuccess
end

--// Config Management \\--
function SaveManager:RefreshConfigList()
    local SettingsPath = GetCurrentSettingsPath()
    if SettingsPath == false then
        return {}
    end

    local SuccessList, Files = pcall(listfiles, SettingsPath)
    if not (SuccessList and typeof(Files) == "table") then
        SaveManager.Library:Notify(string.format("Failed to load config list: %s", tostring(Files)))
        return {}
    end

    local FileNames = {}
    for _, FilePath in Files do
        local RawFileName = FilePath:match("(.+)%..+$")
        if not RawFileName then continue end

        local Position = RawFileName:gsub("\\", "/"):find("/[^/]*$")
        local FileName = Position and RawFileName:sub(Position + 1) or RawFileName
        -- cerberus: hide the internal per-player mapping file
        if not FileName or FileName == "autoload" or FileName == "autoload_players" then continue end

        table.insert(FileNames, FileName)
    end

    -- cerberus: surface web/community configs alongside disk ones
    if typeof(SaveManager.WebConfigs) == "table" then
        for _, cfg in SaveManager.WebConfigs do
            if cfg.Name and not table.find(FileNames, cfg.Name) then
                table.insert(FileNames, cfg.Name)
            end
        end
    end

    return FileNames
end

function SaveManager:Save(ConfigName: string): (boolean, string?)
    if IsStringEmpty(ConfigName) then
        return false, "Invalid config name provided"
    end

    if string.lower(ConfigName) == "autoload" then
        return false, "Invalid config name provided"
    end

    local ConfigPath = GetConfigPath(ConfigName)
    if ConfigPath == false then
        return false, "Invalid config name provided"
    end

    SaveManager:CheckFolderTree()

    local Library = SaveManager.Library
    local IgnoreIndexes = SaveManager.Ignore
    local CurrentData = {
        timestamp = os.date("%d.%m.%Y %H:%M:%S"),
        name = ConfigName,

        objects = {},
        keybindMenu = if Library.KeybindFrame then {
            visible = Library.KeybindFrame.Visible,
            position = SpecialValueParser.UDim2.Encode(Library.KeybindFrame.Position)
        } else nil
    }

    --// Toggles
    for Index, Toggle in Library.Toggles do
        if not Toggle.Type then continue end
        if IgnoreIndexes[Index] then continue end

        local Parser = ElementParser[Toggle.Type]
        if not Parser then continue end

        table.insert(CurrentData.objects, Parser.Save(Index, Toggle))
    end

    --// Options
    for Index, Option in Library.Options do
        if not Option.Type then continue end
        if IgnoreIndexes[Index] then continue end

        local Parser = ElementParser[Option.Type]
        if not Parser then continue end

        table.insert(CurrentData.objects, Parser.Save(Index, Option))
    end

    --// Groupboxes
    for TabIndex, Tab in Library.Tabs do
        if not Tab.Groupboxes then continue end

        for Index, Groupbox in Tab.Groupboxes do
            if IgnoreIndexes[Index] then continue end

            local Parser = ElementParser.Groupbox
            if not Parser then continue end

            table.insert(CurrentData.objects, Parser.Save(Index, Groupbox, TabIndex))
        end
    end

    local SuccessEncode, EncodedData = pcall(HttpService.JSONEncode, HttpService, CurrentData)
    if not SuccessEncode then
        return false, "Failed to encode data"
    end

    local SuccessWrite, ErrorMessage = pcall(writefile, ConfigPath, EncodedData)
    if not SuccessWrite then
        return false, "Failed to write config file: " .. tostring(ErrorMessage)
    end

    return true
end

-- cerberus: extracted from Load so web-config and disk paths share one sort / keybind-restore / element-dispatch path
function SaveManager:ApplyConfigData(Decoded: any): (boolean, string?)
    if typeof(Decoded) ~= "table" then
        return false, "Failed to decode config data"
    end

    -- Allow a bare objects array (hand-authored web configs).
    if typeof(Decoded.objects) ~= "table" then
        if #Decoded > 0 then
            Decoded = { objects = Decoded }
        else
            return false, "Failed to decode config data"
        end
    end

    local Library = SaveManager.Library
    local LoadingOrder = SaveManager.LoadingOrder
    local IgnoreIndexes = SaveManager.Ignore

    if SaveManager.UseLoadingOrder == true and typeof(LoadingOrder) == "table" then
        table.sort(Decoded.objects, function(a, b)
            local aIndex = table.find(LoadingOrder, a.type) or math.huge
            local bIndex = table.find(LoadingOrder, b.type) or math.huge
            return aIndex < bIndex
        end)
    end

    --// Keybind Menu
    if Library.KeybindFrame and typeof(Decoded.keybindMenu) == "table" then
        local KeybindFrameData = Decoded.keybindMenu
        local IsVisible = KeybindFrameData.visible == true
        local Position = SpecialValueParser.UDim2.Decode(KeybindFrameData.position)

        Library.KeybindFrame.Visible = IsVisible
        Library.KeybindFrame.Position = Position or Library.KeybindFrame.Position

        local KeybindMenuToggle = Library.Options and Library.Options.KeybindMenuOpen
        if KeybindMenuToggle then
            KeybindMenuToggle:SetValue(IsVisible)
        end
    end

    --// Elements
    for _, Option in Decoded.objects do
        if not Option.type then continue end
        if IgnoreIndexes[Option.idx] then continue end

        local Parser = ElementParser[Option.type]
        if not Parser then continue end

        task.defer(Parser.Load, Option.idx, Option)
    end

    return true
end

-- cerberus: load a config from a remote URL, optionally XOR-encrypted with the shared SecretKey, for gated configs from SetWebConfigs
function SaveManager:LoadWebConfig(entry): (boolean, string?)
    if type(entry) ~= "table" then
        return false, "invalid web config"
    end

    local decoded
    if type(entry.Config) == "table" then
        decoded = entry.Config
    elseif type(entry.EncryptedUrl) == "string" and entry.EncryptedUrl ~= "" then
        local s, r = pcall(game.HttpGet, game, entry.EncryptedUrl)
        if not s then
            return false, "fetch error"
        end
        local payload = r:gsub("%s+", "")
        local plain, err = decryptPayload(payload, SaveManager.SecretKey)
        if not plain then
            return false, "decrypt failed: " .. tostring(err)
        end
        local s2, d = pcall(HttpService.JSONDecode, HttpService, plain)
        if not s2 then
            return false, "decode error"
        end
        decoded = d
    elseif type(entry.Url) == "string" and entry.Url ~= "" then
        local s, r = pcall(game.HttpGet, game, entry.Url)
        if not s then
            return false, "fetch error"
        end
        local s2, d = pcall(HttpService.JSONDecode, HttpService, r)
        if not s2 then
            return false, "decode error"
        end
        decoded = d
    else
        return false, "missing config source"
    end

    return SaveManager:ApplyConfigData(decoded)
end

function SaveManager:Load(ConfigName: string): (boolean, string?)
    if IsStringEmpty(ConfigName) then
        return false, "No config is selected"
    end

    -- cerberus: web configs are resolved by name before touching disk
    local WebConfig = SaveManager.WebConfigIndex and SaveManager.WebConfigIndex[ConfigName]
    if WebConfig then
        return SaveManager:LoadWebConfig(WebConfig)
    end

    local ConfigPath = GetConfigPath(ConfigName)
    if ConfigPath == false or not isfile(ConfigPath) then
        return false, "Config file does not exist"
    end

    local SuccessRead, Content = pcall(readfile, ConfigPath)
    if not SuccessRead then
        return false, "Failed to read config file"
    end

    local SuccessDecode, Decoded = pcall(HttpService.JSONDecode, HttpService, Content)
    if not SuccessDecode then
        return false, "Failed to decode config data"
    end

    return SaveManager:ApplyConfigData(Decoded)
end

function SaveManager:Delete(ConfigName: string): (boolean | string?)
    if IsStringEmpty(ConfigName) then
        return false, "No config is selected"
    end

    local ConfigPath = GetConfigPath(ConfigName)
    if ConfigPath == false or not isfile(ConfigPath) then
        return false, "Config file does not exist"
    end

    local SuccessDelete, ErrorMessage = pcall(delfile, ConfigPath)
    if not SuccessDelete then
        return false, "Failed to delete config file: " .. tostring(ErrorMessage)
    end

    if ConfigName == SaveManager.AutoloadConfig then
        SaveManager:DeleteAutoLoadConfig()
    end

    return true
end

--// Auto Load Config \\--
function SaveManager:GetAutoloadConfig(): (string, boolean, string?)
    SaveManager:CheckFolderTree()

    -- cerberus: a per-player assignment takes precedence over the global autoload
    SaveManager:LoadPlayerConfigs()
    local LocalPlayer = Players.LocalPlayer
    local LocalName = LocalPlayer and LocalPlayer.Name
    if LocalName then
        local PlayerConfig = SaveManager.PlayerConfigs[LocalName]
        if typeof(PlayerConfig) == "string" and PlayerConfig ~= "" and ConfigIsLoadable(PlayerConfig) then
            SaveManager.AutoloadConfig = PlayerConfig
            return PlayerConfig, true
        end
    end

    local AutoloadPath = GetAutoloadPath()
    if AutoloadPath == false then
        return "none", false, "Invalid path provided"
    end

    if not isfile(AutoloadPath) then
        return "none", false, "Autoload config is not set"
    end

    local SuccessRead, AutoloadConfigName = pcall(readfile, AutoloadPath)
    if not (SuccessRead and typeof(AutoloadConfigName) == "string") then
        return "none", false, AutoloadConfigName
    end

    -- cerberus: ConfigIsLoadable also accepts known web configs
    if not ConfigIsLoadable(AutoloadConfigName) then
        return "none", false, "Config file not found"
    end

    SaveManager.AutoloadConfig = AutoloadConfigName
    return AutoloadConfigName, true
end

function SaveManager:SaveAutoloadConfig(ConfigName: string, Target: string?): (boolean, string?)
    if IsStringEmpty(ConfigName) then
        return false, "No config is selected"
    end

    SaveManager:CheckFolderTree()

    -- cerberus: per-player assignment writes to the mapping file, not autoload.txt
    if Target and Target ~= "Global" then
        SaveManager:LoadPlayerConfigs()
        SaveManager.PlayerConfigs[Target] = ConfigName
        if not SaveManager:SavePlayerConfigs() then
            return false, "Failed to write player autoload file"
        end
        return true
    end

    local AutoloadPath = GetAutoloadPath()
    if AutoloadPath == false then
        return false, "Invalid path provided"
    end

    if not ConfigIsLoadable(ConfigName) then
        return false, "Config does not exist"
    end

    local SuccessWrite, ErrorMessage = pcall(writefile, AutoloadPath, ConfigName)
    if not SuccessWrite then
        return false, ErrorMessage
    end

    SaveManager.AutoloadConfig = ConfigName
    return true
end

function SaveManager:LoadAutoloadConfig()
    local ConfigName, Success, FetchErrorMessage = SaveManager:GetAutoloadConfig()
    if not Success or FetchErrorMessage then
        if FetchErrorMessage ~= "Autoload config is not set" then
            SaveManager.Library:Notify(string.format("Failed to load autoload config: %s", FetchErrorMessage))
        end

        return
    end

    local SuccessLoad, LoadErrorMessage = SaveManager:Load(ConfigName)
    if not SuccessLoad then
        SaveManager.Library:Notify(string.format("Failed to load autoload config: %s", LoadErrorMessage))
        return
    end

    SaveManager.Library:Notify(string.format("Successfully loaded autoload config %q", ConfigName))
end

function SaveManager:DeleteAutoLoadConfig(Target: string?): (boolean, string?)
    SaveManager:CheckFolderTree()

    -- cerberus: per-player clear keeps the user in the list, drops the assignment
    if Target and Target ~= "Global" then
        SaveManager:LoadPlayerConfigs()
        if SaveManager.PlayerConfigs[Target] then
            SaveManager.PlayerConfigs[Target] = ""
            SaveManager:SavePlayerConfigs()
        end
        return true
    end

    local AutoloadPath = GetAutoloadPath()
    if AutoloadPath == false then
        return false, "Invalid path provided"
    end

    if not isfile(AutoloadPath) then
        return false, "Autoload config is not set"
    end

    local SuccessDelete, ErrorMessage = pcall(delfile, AutoloadPath)
    if not SuccessDelete then
        return false, ErrorMessage
    end

    SaveManager.AutoloadConfig = nil
    return true
end

--// GUI \\--
local function ShowDialog(
    Condition: () -> boolean,

    Index: string,
    Title: string,
    Description: string,

    DestructiveText: string,
    DestructiveAction: () -> nil
)
    if Condition() == false then
        return DestructiveAction()
    end

    return SaveManager.Library.Window:AddDialog(Index, {
        Title = Title,
        Description = Description,
        AutoDismiss = false,

        FooterButtons = {
            Cancel = {
                Title = "Cancel",
                Variant = "Ghost",
                Order = 1,
                Callback = function(Dialog)
                    Dialog:Dismiss()
                end
            },

            DestructiveAction = {
                Title = DestructiveText,
                Variant = "Destructive",
                Order = 2,
                Callback = function(Dialog)
                    Dialog:Dismiss()
                    DestructiveAction()
                end
            }
        }
    })
end

function SaveManager:BuildConfigSection(Tab: any, IconName: string)
    assert(SaveManager.Library, "Library is not set, call SaveManager:SetLibrary(Library) first.")
    local ConfigurationBox = Tab:AddRightGroupbox("Configuration", IconName or "folder-cog")

    local ConfigNameInput, ConfigList, AutoloadTarget, AutoloadConfigLabel
    local function RefreshList()
        ConfigList:SetValues(SaveManager:RefreshConfigList())
        ConfigList:SetValue(nil)
    end

    -- cerberus: "Global" plus every registered per-player target
    local function GetAutoloadTargets()
        local Targets = { "Global" }
        SaveManager:LoadPlayerConfigs()
        for Name in SaveManager.PlayerConfigs do
            table.insert(Targets, Name)
        end
        return Targets
    end

    local function RefreshAutoloadConfigLabel()
        local AutoloadConfigName, _Success, _ErrorMessage = SaveManager:GetAutoloadConfig()

        AutoloadConfigLabel:SetText(string.format("Current autoload config: %s", AutoloadConfigName))
        if ConfigList then RefreshList() end
    end

    --// Create
    ConfigurationBox:AddInput("SaveManager_ConfigName", {
        Text = "Config name"
    })

    ConfigurationBox:AddButton("Create config", function()
        local ConfigName = ConfigNameInput.Value
        if IsStringEmpty(ConfigName) then
            SaveManager.Library:Notify("Configuration name cannot be empty.")
            return
        end

        if string.lower(ConfigName) == "autoload" then
            SaveManager.Library:Notify("Invalid config name provided.")
            return
        end

        ShowDialog(
            function(): boolean
                return DoesConfigExist(ConfigName)
            end,

            "SaveManager_CreateConfig",
            "Config already exists",
            string.format("A config named %q already exists. Overwriting will replace it with your current settings.", ConfigName),

            "Overwrite",
            function()
                local Success, ErrorMessage = SaveManager:Save(ConfigName)
                if not Success then
                    SaveManager.Library:Notify(string.format("Failed to create config %q: %s", ConfigName, ErrorMessage))
                    return
                end

                SaveManager.Library:Notify(string.format("Successfully created config %q", ConfigName))
                RefreshList()
            end
        )
    end)

    ConfigurationBox:AddDivider()

    --// Manage
    ConfigurationBox:AddDropdown("SaveManager_ConfigList", {
        Text = "Config list",

        Values = SaveManager:RefreshConfigList(),
        AllowNull = true,
        Multi = false,

        FormatDisplayValue = function(Value: any)
            if Value == SaveManager.AutoloadConfig then
                return string.format("%s (autoload)", Value)
            end

            return Value
        end,
        FormatListValue = function(Value: any)
            if Value == SaveManager.AutoloadConfig then
                return string.format("%s (autoload)", Value)
            end

            return Value
        end
    })

    ConfigurationBox:AddButton({
        Text = "Load config",
        DoubleClick = false,

        Func = function()
            local ConfigName = ConfigList.Value
            if IsStringEmpty(ConfigName) then
                SaveManager.Library:Notify("Please select a config first.")
                return
            end

            local Success, ErrorMessage = SaveManager:Load(ConfigName)
            if not Success then
                SaveManager.Library:Notify(string.format("Failed to load config %q: %s", ConfigName, ErrorMessage))
                return
            end

            SaveManager.Library:Notify(string.format("Successfully loaded config %q", ConfigName))
        end
    })

    ConfigurationBox:AddButton({
        Text = "Overwrite config",
        DoubleClick = false,

        Func = function()
            local ConfigName = ConfigList.Value
            if IsStringEmpty(ConfigName) then
                SaveManager.Library:Notify("Please select a config first.")
                return
            end

            ShowDialog(
                function(): boolean
                    return true --// Always show
                end,

                "SaveManager_OverwriteConfig",
                "Overwrite config",
                string.format("Are you sure you want to overwrite %q with your current settings? This cannot be undone.", ConfigName),

                "Overwrite",
                function()
                    local Success, ErrorMessage = SaveManager:Save(ConfigName)
                    if not Success then
                        SaveManager.Library:Notify(string.format("Failed to overwrite config %q: %s", ConfigName, ErrorMessage))
                        return
                    end

                    SaveManager.Library:Notify(string.format("Successfully overwrote config %q", ConfigName))
                end
            )
        end
    })

    ConfigurationBox:AddButton({
        Text = "Delete config",
        DoubleClick = false,

        Func = function()
            local ConfigName = ConfigList.Value
            if IsStringEmpty(ConfigName) then
                SaveManager.Library:Notify("Please select a config first.")
                return
            end

            ShowDialog(
                function(): boolean
                    return true --// Always show
                end,

                "SaveManager_DeleteConfig",
                "Delete config",
                string.format("Are you sure you want to delete %q? This cannot be undone.", ConfigName),

                "Delete",
                function()
                    local Success, ErrorMessage = SaveManager:Delete(ConfigName)
                    if not Success then
                        SaveManager.Library:Notify(string.format("Failed to delete config %q: %s", ConfigName, ErrorMessage))
                        return
                    end

                    SaveManager.Library:Notify(string.format("Successfully deleted config %q", ConfigName))
                    RefreshAutoloadConfigLabel()
                end
            )
        end
    })

    ConfigurationBox:AddButton("Refresh list", RefreshList)

    -- cerberus: opens the community-configs popup; the opener is published on getgenv() at boot, and no-ops with a notify if Configs failed to init
    ConfigurationBox:AddButton("Browse Community Configs", function()
        local Env = (typeof(getgenv) == "function") and getgenv() or _G
        local Open = Env.CERBERUS_CONFIGS_OPEN
        if typeof(Open) == "function" then
            Open()
        else
            SaveManager.Library:Notify("Community Configs unavailable in this build", 3)
        end
    end)

    ConfigurationBox:AddDivider()

    --// Cerberus: per-player autoload target \\--
    ConfigurationBox:AddDropdown("SaveManager_AutoloadTarget", {
        Text = "Autoload target",

        Values = GetAutoloadTargets(),
        Default = "Global",
        AllowNull = false,
        Multi = false
    })

    --// Autoload Config
    ConfigurationBox:AddButton({
        Text = "Set as autoload",
        DoubleClick = false,

        Func = function()
            local ConfigName = ConfigList.Value
            if IsStringEmpty(ConfigName) then
                SaveManager.Library:Notify("Please select a config first.")
                return
            end

            local Target = AutoloadTarget.Value
            local Success, ErrorMessage = SaveManager:SaveAutoloadConfig(ConfigName, Target)
            if not Success then
                SaveManager.Library:Notify(string.format("Failed to set autoload config %q: %s", ConfigName, ErrorMessage))
                return
            end

            SaveManager.Library:Notify(string.format("Set %q to autoload for %s", ConfigName, Target))
            RefreshAutoloadConfigLabel()
        end
    })

    ConfigurationBox:AddButton({
        Text = "Reset autoload",
        DoubleClick = false,

        Func = function()
            local Target = AutoloadTarget.Value

            ShowDialog(
                function(): boolean
                    return true --// Always show
                end,

                "SaveManager_ResetAutoload",
                "Reset autoload config",
                string.format("Are you sure you want to clear the autoload config for %s? No config will be loaded automatically for them.", Target),

                "Reset",
                function()
                    local Success, ErrorMessage = SaveManager:DeleteAutoLoadConfig(Target)
                    if not Success then
                        SaveManager.Library:Notify(string.format("Failed to reset autoload config: %s", ErrorMessage))
                        return
                    end

                    SaveManager.Library:Notify(string.format("Successfully reset autoload config for %s.", Target))
                    RefreshAutoloadConfigLabel()
                end
            )
        end
    })

    AutoloadConfigLabel = ConfigurationBox:AddLabel("Current autoload config: ...", true);

    --// Cerberus: player management \\--
    local PlayerBox = Tab:AddRightGroupbox("Player Management", "users")

    PlayerBox:AddInput("SaveManager_PlayerInput", {
        Text = "Username"
    })

    PlayerBox:AddButton("Add user to list", function()
        local Username = SaveManager.Library.Options.SaveManager_PlayerInput.Value
        if IsStringEmpty(Username) then
            SaveManager.Library:Notify("Invalid username.")
            return
        end

        SaveManager:LoadPlayerConfigs()
        if SaveManager.PlayerConfigs[Username] then
            SaveManager.Library:Notify("User already in list.")
            return
        end

        SaveManager.PlayerConfigs[Username] = ""
        SaveManager:SavePlayerConfigs()
        AutoloadTarget:SetValues(GetAutoloadTargets())
        SaveManager.Library:Notify(string.format("Added %s to the player list.", Username))
    end)

    PlayerBox:AddButton("Remove user from list", function()
        local Target = AutoloadTarget.Value
        if Target == "Global" then
            SaveManager.Library:Notify("Cannot remove Global from the list.")
            return
        end

        SaveManager:LoadPlayerConfigs()
        if SaveManager.PlayerConfigs[Target] == nil then
            SaveManager.Library:Notify("User not found in list.")
            return
        end

        SaveManager.PlayerConfigs[Target] = nil
        SaveManager:SavePlayerConfigs()
        AutoloadTarget:SetValues(GetAutoloadTargets())
        AutoloadTarget:SetValue("Global")
        SaveManager.Library:Notify(string.format("Removed %s from the list.", Target))
    end)

    --// Set variables
    ConfigNameInput, ConfigList, AutoloadTarget =
        SaveManager.Library.Options.SaveManager_ConfigName,
        SaveManager.Library.Options.SaveManager_ConfigList,
        SaveManager.Library.Options.SaveManager_AutoloadTarget;

    --// Refresh
    RefreshAutoloadConfigLabel()
    SaveManager:SetIgnoreIndexes({ "SaveManager_ConfigList", "SaveManager_ConfigName", "SaveManager_AutoloadTarget", "SaveManager_PlayerInput" })

    return ConfigurationBox
end

SaveManager:BuildFolderTree()
return SaveManager
]], "SaveManager"))()
