		end

		if start then
			if now ~= start then
				local str = ("%s (%s)"):format(Format.number(now), Format.signed(now - start))
				local flag = now > start

				if flag then
					flag = Format.perHour(now - start, arg2.elapsed)
				end

				flag = flag or nil

				if flag then
