		end

		if not now.level then
			return nil
		end
		local start = arg2.start

		if start then
			start = arg2.start.level
		end

		if start then
			if start < now.level then
				return ("%d → %s"):format(start, Character.level(now))
			end
		end

		return Character.level(now)
	end

