		fn2("This Run", tbl2.pace(arg2))
		fn2("Wen", tbl2.wen(arg2))
		fn2("Level", tbl2.level(arg2))
		return tbl3
	end

	return tbl2
end)

v4("Api/Webhook/Events/LootClaimed", function(arg)
	local Format = arg("Api/Webhook/Format")
