		end

		return nil
	end

	local tbl2 = { "Never" }
	local v = table.pack(ipairs(tbl))
	local v5, v6, v7

	if select("#", table.unpack(v, 1, v.n)) ~= 0 then
		v5 = v[1]
		v6 = v[2]
		v7 = v[3]
	else
		v5 = nil
		v6 = nil
		v7 = nil
	end

	for _, v8 in v5, v6, v7 do
		tbl2[#tbl2 + 1] = v8
	end

	return {
		key = "LootClaimed",
		label = "Loot",
		default = true,
		options = {
			{
				key = "minRarity",
				kind = "dropdown",
				label = "Min Loot Rarity",
				values = tbl,
				default = tbl[1],
				tooltip = "Loot below this rarity isn't posted.",
			},
			{
				key = "pingRarity",
				kind = "dropdown",
				label = "Ping For Loot",
				values = tbl2,
				default = "Never",
				ping = true,
				tooltip = "Pings you for loot this rare or rarer.",
			},
		},
		build = function(arg2, arg3)
			local n = fn2(arg3.getOption("minRarity", tbl[1])) or 1
			local v8 = fn2(arg3.getOption("pingRarity", "Never"))
			local tbl3 = {}
			local tbl4 = {}
			local count = 0
			local v9 = ipairs
			local items = type(arg2.items) == "table"

			if items then
				items = arg2.items
			end

			items = items or {}
			local v10 = table.pack(v9(items))
			local v11, v12, v13

			if select("#", table.unpack(v10, 1, v10.n)) ~= 0 then
				v11 = v10[1]
				v12 = v10[2]
				v13 = v10[3]
			else
				v11 = nil
				v12 = nil
				v13 = nil
			end

			for _, v14 in v11, v12, v13 do
				local v15 = table.pack(arg3.Tables.itemRarity(v14))
				local v16, v17

				if select("#", table.unpack(v15, 1, v15.n)) ~= 0 then
					v16 = v15[1]
					v17 = v15[3]
				else
					v16 = nil
					v17 = nil
				end

				local n8 = fn2(v16) or 1
				if not (n <= n8) then
					continue
				end
				local tbl5 = tbl3[v14]

				if not tbl5 then
					tbl5 = { id = tostring(v14), count = 0, rarity = v16, rank = n8, color = v17 }
					tbl3[v14] = tbl5
					tbl4[#tbl4 + 1] = tbl5
				end

				tbl5.count += 1
				count += 1
			end

			if count == 0 then
				return nil
			end

			table.sort(tbl4, function(arg4, arg5)
				if arg4.rank == arg5.rank then
					return arg4.id < arg5.id
				end
				return arg4.rank > arg5.rank
			end)

			local tbl5 = {}
			local v14 = table.pack(ipairs(tbl4))
			local v15, v16, v17

			if select("#", table.unpack(v14, 1, v14.n)) ~= 0 then
				v15 = v14[1]
				v16 = v14[2]
				v17 = v14[3]
			else
