				v16 = nil
				v17 = nil
			end

			for _, v18 in v15, v16, v17 do
				local flag = v18.count > 1

				if flag then
					flag = (" ×%d"):format(v18.count)
				end

				flag = flag or ""
				local rarity = v18.rarity

				if rarity then
