v4("Api/Webhook/Events/LevelUp", function(arg)
	local Character = arg("Api/Webhook/Character")
	local Format = arg("Api/Webhook/Format")
	local color = Color3.fromRGB(240, 190, 60)

	return {
		key = "LevelUp",
		label = "Level Up",
		default = true,
		options = {
			{
				key = "every",
				kind = "slider",
				label = "Levels Per Post",
				min = 1,
				max = 25,
				default = 1,
				tooltip = "At 5 it posts on 5, 10, 15 and so on. Max level always posts.",
			},
		},
		arm = function(arg2)
			local v = arg2.Api()
			local state = v

			if state then
				state = v.State
			end

			if state then
				local level2 = nil

				local v5 = table.pack(state.watch("slot", "Exp/Goal", function()
					local v5 = table.pack(state.level())
					local v6, v7

					if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
						v6 = v5[1]
						v7 = v5[2]
					else
						v6 = nil
						v7 = nil
					end

					if not v6 then
						return
					end
					local level = v7.level
					local level3 = level2
					level2 = level
					if not level3 then
						return
					end

					if not (level <= level3) then
						local n = math.clamp(math.floor(tonumber(arg2.getOption("every", 1)) or 1), 1, 25)
						local n8 = math.floor(level / n)

						if math.floor(level3 / n) < n8 then
							arg2.emit({ from = level3, to = level })
						elseif v7.maxed then
							arg2.emit({ from = level3, to = level })
							return
						end

						return
					end
				end))

				local v6, connection

				if select("#", table.unpack(v5, 1, v5.n)) ~= 0 then
					v6 = v5[1]
					connection = v5[2]
				else
					v6 = nil
					connection = nil
				end

				if v6 then
					arg2.cleanup(function()
						connection.Disconnect()
					end)
				end

				return
			end
		end,
		build = function(arg2, arg3)
			local v = arg3.character()
			local fields = {}

			local function fn2(arg4, arg5)
				if arg5 then
					fields[#fields + 1] = { name = arg4, value = arg5, inline = true }
				end
			end

			if v.level then
				fn2("Progress", ("%d of %d\n%s"):format(v.level, v.maxLevel or v.level, Format.bar(v.level / math.max(v.maxLevel or v.level, 1))))
			end

			if v.skillPoints then
				if v.skillPoints > 0 then
					fn2("Skill Points", Format.number(v.skillPoints) .. " to spend")
				end
			end

			local v5 = fn2
			local str = "Wen"
			local wen = v.wen

			if wen then
				wen = Format.number(v.wen)
			end

			v5(str, wen or nil)
			fn2("Where", Character.where(v))
			local n = arg2.to - arg2.from
			local tbl = {}
			local maxed = v.maxed

			if maxed then
				maxed = ("Reached the max level, %d"):format(arg2.to)
			end

			tbl.title = maxed or ("Reached level %d"):format(arg2.to)
			local description = n > 1

			if description then
				description = ("Up %d levels from %d."):format(n, arg2.from)
			end

			tbl.description = description or ("Up from %d."):format(arg2.from)
			tbl.color = color
			tbl.fields = fields
			return tbl
		end,
	}
end)

