v4("Api/Webhook/Events/FarmSummary", function(arg)
	local Character = arg("Api/Webhook/Character")
	local Format = arg("Api/Webhook/Format")
	local Tally = arg("Api/Webhook/Tally")

	local reasons = {
		progress = "Still running.",
		off = "You turned it off.",
		finished = "It went through every quest you picked.",
		climbed = "The climb ended with Keep Climbing off, so it stopped in the shops.",
	}

	local function fn2(loot, tables)
		local v = nil
		local n = -1
		local v5 = nil
		local v6 = ipairs
		local loot2 = loot or {}
		local v7 = table.pack(v6(loot2))
		local v8, v9, v10

		if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
			v8 = v7[1]
			v9 = v7[2]
			v10 = v7[3]
		else
			v8 = nil
			v9 = nil
			v10 = nil
		end

		for _, v11 in v8, v9, v10 do
			local v12 = table.pack(tables.itemRarity(v11))
			local v13, v14

			if select("#", table.unpack(v12, 1, v12.n)) ~= 0 then
				v13 = v12[1]
				v14 = v12[2]
			else
				v13 = nil
				v14 = nil
			end

			local n8 = v14 or 0

			if n < n8 then
				v = v11
				n = n8
				v5 = v13
			end
		end

		if v then
			local v11 = Format.escape(tostring(v))
			local str = v5

			if str then
				str = (" (%s)"):format(v5)
			end

			return v11 .. (str or "")
		end

		return nil
	end

	return {
		key = "FarmSummary",
		label = "Summary",
		default = true,
		options = {
			{
				key = "every",
				kind = "slider",
				label = "Summary Every",
				min = 0,
				max = 180,
				default = 30,
				suffix = " min",
				tooltip = "How often a running farm posts. 0 posts only when it stops.",
			},
		},
		build = function(arg2, arg3)
			local run = arg2.run or {}
			local counts = run.counts or {}
			local reason = reasons[arg2.reason]

			if reason then
				reason = arg2.reason
			end

			reason = reason or "off"
			local v = Format.escape(run.farm or "The farm")
			local v5 = Format.duration(run.elapsed)
			local tbl = {}

			local function fn3(arg4, arg5, arg6)
				if arg5 then
					tbl[#tbl + 1] = { name = arg4, value = arg5, inline = arg6 ~= false }
				end
			end

			local v6 = table.pack(Tally.done(run))
			local v7, v8

			if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
				v7 = v6[1]
				v8 = v6[2]
			else
				v7 = nil
				v8 = nil
			end

			if v7 then
				local v9 = Format.perHour(v7, run.elapsed)
				local str = v8.many:sub(1, 1)
				local v10 = fn3
				local str2 = str:upper() .. v8.many:sub(2)
				local v11 = Format.number(v7)
				local flag = v9

				if flag then
					flag = v7 > 0
				end

				if flag then
					flag = ("\n%s an hour"):format(v9)
				end

				v10(str2, v11 .. (flag or ""))
			end

			fn3("Wen", Tally.wen(run))
			fn3("Level", Tally.level(run))

			if (counts.loot or 0) > 0 then
				local v9 = fn2(run.loot, arg3.Tables)
				local v10 = fn3
				local str = "Loot"
				local v11 = Format.plural(counts.loot, "item")
				local str2 = v9

				if str2 then
					str2 = ("\nBest: %s"):format(v9)
				end

				v10(str, v11 .. (str2 or ""))
			end

			if (counts.caches or 0) > 0 then
				local v9 = Format.perHour(counts.caches, run.elapsed)
				local v10 = fn3
				local str = "Caches Opened"
				local v11 = Format.number(counts.caches)
				local str2 = v9

				if str2 then
					str2 = ("\n%s an hour"):format(v9)
				end

				v10(str, v11 .. (str2 or ""))
			end

			if (counts.climbs or 0) > 0 then
				local v9 = Format.perHour(counts.climbs, run.elapsed)
				local v10 = fn3
				local str = "Climbs"
				local v11 = Format.number(counts.climbs)
				local str2 = v9

				if str2 then
					str2 = ("\n%s an hour"):format(v9)
				end

				v10(str, v11 .. (str2 or ""))
				local floor = type(run.best) == "table"

				if floor then
					floor = run.best.floor
				end

				floor = floor or nil

				if floor then
					fn3("Best Floor", Format.number(floor))
				end

				if (counts.points or 0) > 0 then
					local v12 = Format.perHour(counts.points, run.elapsed)
					local v13 = fn3
					local str3 = "Points Banked"
					local v14 = Format.number(counts.points)
					local str4 = v12

					if str4 then
						str4 = ("\n%s an hour"):format(v12)
					end

					v13(str3, v14 .. (str4 or ""))
				end

				if (counts.kills or 0) > 0 then
					fn3("Kills", Format.number(counts.kills))
				end

				if (counts.bought or 0) > 0 then
					fn3("Bought", Format.plural(counts.bought, "thing"))
				end

				if (counts.crafted or 0) > 0 then
					fn3("Crafted", Format.plural(counts.crafted, "item"))
				end

				if (counts.chests or 0) > 0 then
					fn3("Chests", Format.number(counts.chests))
				end
			end

			if (counts.hunts or 0) > 0 then
				local v9 = Format.perHour(counts.hunts, run.elapsed)
				local v10 = fn3
				local str = "Boss Hunts"
				local v11 = Format.number(counts.hunts)
				local str2 = v9

				if str2 then
					str2 = ("\n%s an hour"):format(v9)
				end

				v10(str, v11 .. (str2 or ""))
			end

			if (counts.deaths or 0) > 0 then
				fn3("Deaths", Format.number(counts.deaths))
			end

			if (counts.gaveUp or 0) > 0 then
				fn3("Given Up", Format.number(counts.gaveUp))
			end

			fn3("Where", Character.where(run.now))

			if reason == "progress" then
				if run.status then
					fn3("Doing Now", Format.escape(run.status), false)
				end
			end

			if type(run.recent) == "table" then
				if #run.recent > 0 then
					local tbl2 = {}

					for i = #run.recent, 1, -1 do
						tbl2[#tbl2 + 1] = "• " .. Format.escape(run.recent[i])
					end

					fn3("Latest", table.concat(tbl2, "\n"), false)
				end
			end

			local flag = reason == "progress"

			if flag then
				flag = ("%s · %s in"):format(v, v5)
			end

			if not flag then
				flag = reason == "finished"

				if flag then
					flag = ("%s finished after %s"):format(v, v5)
				end
			end

			return { title = flag or ("%s stopped after %s"):format(v, v5), description = reasons[reason], fields = tbl }
		end,
	}
end)

v4("Api/Webhook/Events/FarmProblem", function(arg)
	local Format = arg("Api/Webhook/Format")
	local Tally = arg("Api/Webhook/Tally")
	local color = Color3.fromRGB(235, 150, 40)

	return {
		key = "FarmProblem",
		label = "Problems",
		default = true,
		build = function(arg2, arg3)
			local run = arg2.run or {}
			local seen = arg3.state.seen or {}
			arg3.state.seen = seen
			local str = tostring(run.farm) .. "|" .. tostring(arg2.text)
			local now = os.clock()

			if seen[str] then
				if now - seen[str] < 600 then
					return nil
				end
			end

			seen[str] = now
			local tbl = {}

			if arg2.after then
				tbl[#tbl + 1] = { name = "What Happens Now", value = Format.escape(arg2.after) }
			end

			local v = Tally.pace(run)

			if v then
				tbl[#tbl + 1] = { name = "This Run", value = v, inline = true }
			end

			if run.counts then
				if (run.counts.gaveUp or 0) > 1 then
					tbl[#tbl + 1] = { name = "Given Up This Run", value = Format.number(run.counts.gaveUp), inline = true }
				end
			end

			return {
				title = ("%s hit a problem"):format(Format.escape(run.farm or "A farm")),
				description = Format.escape(arg2.text or "Something went wrong."),
				color = color,
				fields = tbl,
			}
		end,
	}
end)

do
