		end

		bin[#bin + 1] = tbl
		return tbl
	end

	local function fn3(bin, arg2, arg3)
		local tbl = {}

		for i = 1, arg2 do
			tbl[i] = fn2(bin, "Line", arg3)
		end

		return tbl
	end

	index.new = function(arg2, arg3, shared_, deps)
		local obj = setmetatable({}, index)
		obj.cfg = arg3.config
		obj.shared = shared_
		obj.deps = deps
		obj.bin = {}
		obj.shown = true
		obj.parts = {}
		obj.halves = {}
		obj.partCount = 0
		obj.skelParts = {}
		obj.skelA = {}
		obj.skelB = {}
		obj.skelCount = 0
		obj.boneCount = 0
		obj.skelScreen = {}
		obj.skelOn = {}
		obj.corners = {}
		local elements = arg3.elements
		local bin = obj.bin

		if elements.boxFill then
			obj.boxFill = fn2(bin, "Square", { Filled = true, Visible = false })
		end

		if elements.box then
			obj.boxOutline = fn2(bin, "Square", { Thickness = 3, Filled = false, Visible = false })
			obj.box = fn2(bin, "Square", { Thickness = 1, Filled = false, Visible = false })
		end

		if elements.box3d then
			obj.box3d = fn3(bin, 12, { Thickness = 1, Visible = false })
		end

		if elements.skeleton then
			obj.skeleton = fn3(bin, 16, { Thickness = 1, Visible = false })
		end

		if elements.health then
			obj.healthOutln = fn2(bin, "Line", { Thickness = 3, Visible = false })
			obj.healthBar = fn2(bin, "Line", { Thickness = 1, Visible = false })
			obj.healthText = fn2(bin, "Text", { Center = true, Visible = false })
		end

		if elements.bar2 then
			obj.bar2Outln = fn2(bin, "Line", { Thickness = 3, Visible = false })
			obj.bar2 = fn2(bin, "Line", { Thickness = 1, Visible = false })
		end

		if elements.tracer then
			obj.tracerOutln = fn2(bin, "Line", { Thickness = 3, Visible = false })
			obj.tracer = fn2(bin, "Line", { Thickness = 1, Visible = false })
		end

		if elements.arrow then
			obj.arrowOutln = fn2(bin, "Triangle", { Thickness = 3, Filled = false, Visible = false })
			obj.arrow = fn2(bin, "Triangle", { Filled = true, Visible = false })
		end

		if elements.name then
			obj.name = fn2(bin, "Text", { Center = true, Visible = false })
		end

		if elements.distance then
			obj.distance = fn2(bin, "Text", { Center = true, Visible = false })
		end

		if elements.info then
			obj.info = {}

			for i = 1, 5 do
				obj.info[i] = fn2(bin, "Text", { Center = true, Visible = false })
			end
		end

		obj.chamsAllowed = elements.chams == true
		obj:Refresh(arg2)
		return obj
	end

	index.measure = function(arg2)
		local t = arg2.t
		local model = arg2.model
		local root = t.root
		local parts = arg2.parts
		local halves = arg2.halves
		local partCount = 0
		local n = 0
		local n8 = 0
		local n9 = 0

		if model then
			if root then
				if root.Parent then
					local position = root.Position
					local v = table.pack(ipairs(model:GetChildren()))
					local v5, v6, v7

					if select("#", table.unpack(v, 1, v.n)) ~= 0 then
						v5 = v[1]
						v6 = v[2]
						v7 = v[3]
					else
						v5 = nil
						v6 = nil
						v7 = nil
					end

					for _, instance in v5, v6, v7 do
						if not instance:IsA("BasePart") then
							continue
						end

						if not Geometry.isBodyPart(instance.Name) then
							continue
						end
						partCount += 1
						parts[partCount] = instance
						local size = instance.Size * 0.5
						halves[partCount] = size
						local position2 = instance.Position - position
						n = max(n, position2.Y + size.Y)
						n8 = max(n8, size.Y - position2.Y)
						n9 = max(n9, abs(position2.X) + size.X, abs(position2.Z) + size.Z)
					end
				end
			end
		end

		for i = partCount + 1, #parts do
			parts[i] = nil
			halves[i] = nil
		end

		arg2.partCount = partCount

		if partCount == 0 then
			n = 2.5
			n8 = 3
			n9 = 1.5
		end

		local y = max(n, 0.5)
		local y2 = max(n8, 0.5)
		arg2.upV = Vector3.new(0, y, 0)
		arg2.downV = Vector3.new(0, y2, 0)
		arg2.aspect = n9 * 2 / (y + y2)

		local skelParts = arg2.skelParts
		local skelA = arg2.skelA
		local skelB = arg2.skelB
		local skelCount = 0
		local boneCount = 0

		if arg2.skeleton then
			if model then
				local tbl = {}

				local function fn4(name)
					local v = tbl[name]

					if v == nil then
						local child = model:FindFirstChild(name)

						if child then
							if child:IsA("BasePart") then
								skelCount += 1
								skelParts[skelCount] = child
								tbl[name] = skelCount
								return skelCount
							end
						end

						tbl[name] = false
						return false
					end

					return v
				end

				local v = table.pack(ipairs(Geometry.bones(model, t.humanoid)))
				local v5, v6, v7

				if select("#", table.unpack(v, 1, v.n)) ~= 0 then
					v5 = v[1]
					v6 = v[2]
					v7 = v[3]
				else
					v5 = nil
					v6 = nil
					v7 = nil
				end

				for _, v8 in v5, v6, v7 do
					local v9 = fn4(v8[1])
					local v10 = fn4(v8[2])
					if not v9 then
						continue
					end

					if v10 then
						if boneCount < 16 then
							boneCount += 1
							skelA[boneCount] = v9
							skelB[boneCount] = v10
						end
					end
				end
			end
		end

		for i = skelCount + 1, #skelParts do
			skelParts[i] = nil
		end

		arg2.skelCount = skelCount
		arg2.boneCount = boneCount
	end

	index.Refresh = function(arg2, t)
		arg2.t = t
		local body = t.body

		if body then
			body = t.model
		end

		arg2.model = body or nil

		if t.body then
			arg2:measure()
		end
	end

	index.makeHighlight = function(arg2)
		local v = table.pack(pcall(Instance.new, "Highlight"))
		local v5, instance

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			instance = v[2]
		else
			v5 = nil
			instance = nil
		end

		if v5 then
			instance.Enabled = false

			pcall(function()
				instance.Parent = arg2.deps.container
			end)

			arg2.hl = { d = instance, s = { Enabled = false } }
			return arg2.hl
		end

		arg2.chamsAllowed = false
		return nil
	end

	index.hideAll = function(arg2)
		if not arg2.shown then
			return
		end
		arg2.shown = false
		local bin = arg2.bin

		for i = 1, #bin do
			put(bin[i], "Visible", false)
		end

		if arg2.hl then
			put(arg2.hl, "Enabled", false)
		end
	end

	local hideAll = index.hideAll

	index.text = function(arg2, arg3, arg4, arg5, arg6)
		put(arg2, "Text", arg3)
		put(arg2, "Size", arg4.textSize or 13)
		put(arg2, "Font", arg4.textFont or 2)
		put(arg2, "Color", arg5)
		put(arg2, "Transparency", arg6.transparency or 1)
		put(arg2, "Outline", arg6.outline)
		put(arg2, "OutlineColor", arg6.outlineColor)
	end

	local text = index.text

	index.Frame = function(arg2, arg3)
		local cfg = arg2.cfg
		local t = arg2.t

		if cfg.enabled then
			local root = t.root
			local position = nil

			if not root then
				position = t.position
			elseif root.Parent then
				position = root.Position
			end

			if position then
				local humanoid = t.humanoid
				local health = nil
				local maxHealth = nil

				if humanoid then
					health = humanoid.Health
					maxHealth = humanoid.MaxHealth
					if health <= 0 then
						return hideAll(arg2)
					end
				end

				local myPos = arg3.myPos
				local myPos2 = myPos

				if myPos2 then
					myPos2 = (position - myPos).Magnitude
				end

				myPos2 = myPos2 or nil

				if myPos2 then
					if cfg.limitDistance then
						if cfg.maxDistance < myPos2 then
							return hideAll(arg2)
						end
					end
				end

				local camera = arg3.camera
				local flag = t.body == true
				local v = nil
				local v5 = nil
				local flag2 = nil

				if not flag then
					local v6 = table.pack(camera:WorldToViewportPoint(position))

					if select("#", table.unpack(v6, 1, v6.n)) ~= 0 then
						v = v6[1]
						flag2 = v6[2]
						v5 = v
					else
						v5 = v
					end
				else
					local v6 = nil
					local v7 = nil
					local v8 = table.pack(camera:WorldToViewportPoint(position + arg2.upV))
					local v9

					if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
						v = v8[1]
						local v10 = v8[2]
						local v11 = table.pack(camera:WorldToViewportPoint(position - arg2.downV))

						if select("#", table.unpack(v11, 1, v11.n)) ~= 0 then
							v5 = v11[1]
							v7 = v11[2]
							v9 = v10 or v7
						else
							v9 = v10 or v7
						end
					else
						local v10 = table.pack(camera:WorldToViewportPoint(position - arg2.downV))

						if select("#", table.unpack(v10, 1, v10.n)) ~= 0 then
							v5 = v10[1]
							v7 = v10[2]
							v9 = v7
						else
							v9 = v7
						end
					end

					flag2 = v9 and v.Z > 0 and v5.Z > 0
				end

				myPos2 = myPos2 or v.Z
				arg2.shown = true
				local shared_ = arg2.shared
				local accent = t.accent
				local textSize = (shared_.textSize or 13) + 1
				local chams = cfg.chams
				local adornee = t.adornee

				if chams.enabled then
					if not arg2.chamsAllowed then
						if arg2.hl then
							put(arg2.hl, "Enabled", false)
						end
					elseif not adornee then
						if arg2.hl then
							put(arg2.hl, "Enabled", false)
						end
					else
						local hl = arg2.hl or arg2:makeHighlight()

						if hl then
							put(hl, "Adornee", adornee)
							put(hl, "FillColor", accent or chams.fillColor)
							put(hl, "FillTransparency", chams.fillTransparency)
							put(hl, "OutlineColor", chams.outlineColor)
							put(hl, "OutlineTransparency", chams.outlineTransparency)
							put(hl, "DepthMode", chams.visibleOnly and Enum.HighlightDepthMode.Occluded or Enum.HighlightDepthMode.AlwaysOnTop)
							put(hl, "Enabled", true)
						end
					end
				elseif arg2.hl then
					put(arg2.hl, "Enabled", false)
				end

				local x = nil
				local v6 = nil
				local v7 = nil

				if flag2 then
					if not flag then
						x = floor(v.X)
						local vector2 = Vector2.new
						local x2 = x
						local v8 = table.pack(floor(v.Y))

						if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
							local v9 = table.pack(vector2(x2, table.unpack(v8, 1, v8.n)))
							v6 = v9[1]
							v7 = v6
						else
							local v9 = table.pack(vector2(x2, table.unpack(v8, 1, v8.n)))
							v6 = v9[1]
							v7 = v6
						end
					else
						local n = v5.Y - v.Y

						if n < 2 then
							n = 2
						end

						local v8 = max(n * arg2.aspect, 2)
						x = floor((v.X + v5.X) * 0.5)
						local vector2 = Vector2.new
						local v9 = floor(x - v8 * 0.5)
						local v10 = table.pack(floor(v.Y))

						if select("#", table.unpack(v10, 1, v10.n)) ~= 0 then
							local v11 = table.pack(vector2(v9, table.unpack(v10, 1, v10.n)))
							v6 = v11[1]
							local vector22 = Vector2.new
							local v12 = table.pack(floor(x + v8 * 0.5))
							local v13 = v12[1]
							local v14 = table.pack(floor(v.Y + n))

							if select("#", table.unpack(v14, 1, v14.n)) ~= 0 then
								local v15 = table.pack(vector22(v13, table.unpack(v14, 1, v14.n)))
								v7 = v15[1]
							else
								local v15 = table.pack(vector22(v13, table.unpack(v14, 1, v14.n)))
								v7 = v15[1]
							end
						else
							local v11 = table.pack(vector2(v9, table.unpack(v10, 1, v10.n)))
							v6 = v11[1]
							local vector22 = Vector2.new
							local v12 = table.pack(floor(x + v8 * 0.5))
							local v13 = v12[1]
							local v14 = table.pack(floor(v.Y + n))

							if select("#", table.unpack(v14, 1, v14.n)) ~= 0 then
								local v15 = table.pack(vector22(v13, table.unpack(v14, 1, v14.n)))
								v7 = v15[1]
							else
								local v15 = table.pack(vector22(v13, table.unpack(v14, 1, v14.n)))
								v7 = v15[1]
							end
						end
					end
				end

				local v8 = flag2 and flag

				if arg2.box then
					local box = cfg.box
					local enabled = v8 and box.enabled
					put(arg2.box, "Visible", enabled)
					local put2 = put
					local boxOutline = arg2.boxOutline
					local str = "Visible"
					local enabled2 = enabled

					if enabled2 then
						enabled2 = box.outline
					end

					put2(boxOutline, str, enabled2)

					if enabled then
						local n = v7 - v6
						put(arg2.box, "Position", v6)
