				if arg2.healthBar then
					local health2 = cfg.health
					local flag3 = v8

					if flag3 then
						flag3 = maxHealth ~= nil
					end

					flag3 = flag3 and maxHealth > 0
					local hpRatio = flag3 and clamp(health / maxHealth, 0, 1) or 0
					local bar = flag3 and health2.bar
					put(arg2.healthBar, "Visible", bar)
