						local put2 = put
						local healthBar = arg2.healthBar
						local str = "From"
						local v9 = table.pack(Vector2.new(x2, v7.Y))
						local put3, healthOutln, str2, put4, healthOutln2, str3, put5, healthOutln3, str4

						if select("#", table.unpack(v9, 1, v9.n)) ~= 0 then
							put2(healthBar, str, table.unpack(v9, 1, v9.n))
							local put6 = put
