		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		if v5 then
			if v6 then
				if v7 then
					if v7.Y > 0 then
