			return v8, v8.Y
		end
		return nil, nil
	end

	local function fn9(arg)
		local v = table.pack(arg.Quests.status(tbl.QUEST))
		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
		else
			v5 = nil
			v6 = nil
		end

		if v5 then
			return v6
		end
		return nil
	end

	local function fn10(arg)
		local trip = arg.trip
		arg.trip = nil

		if trip then
			if not trip.done then
				pcall(trip.stop)
			end
		end
	end

	local function fn11(arg, vector)
		local rctx = arg.rctx
		local errors = arg.rctx.Errors
		local v = table.pack(arg.Movement.moveTo(vector, { mover = "instant", exact = true, arrive = 4, settle = 3 }))
		local v5, trip

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			trip = v[2]
		else
			v5 = nil
			trip = nil
		end

		if v5 then
			arg.trip = trip
			local deadline = os.clock() + 6

			while true do
				if trip.done then
					arg.trip = nil
					if trip.ok ~= true then
