				else
					if rctx.cancelled() then
						fn10(arg)
						return false, errors.CANCELLED
					end

					if rctx.sleep(0.05) then
						if deadline < os.clock() then
							break
						end
						continue
					end

					fn10(arg)
					return false, errors.CANCELLED
				end
			end

			fn10(arg)
			return false, errors.TRAVEL_FAILED
		end

