			end
			return false, errors.CANCELLED
		end

		if rctx.owned(tbl.ITEM) then
			return true
		end
		return false, errors.NOT_GRANTED, arg2
	end

	local function fn15(arg, arg2)
		local rctx = arg.rctx
		local errors = arg.rctx.Errors
		arg2.used = true
		local n = arg2.at + arg2.lead + #arg2.pads * arg2.step + 0.5

