v4("Api/Fishing/Stats", function()
	local tbl = { "caught", "empty", "got_away", "missed", "cancelled", "unknown" }

	local function fn2(arg)
		if type(arg) ~= "table" then
			return arg
		end
		local tbl2 = {}
		local v = table.pack(pairs(arg))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for k, v8 in v5, v6, v7 do
			tbl2[k] = fn2(v8)
		end

		return tbl2
	end

	local tbl2 = { new = function()
		local tbl2 = nil

		local tbl3 = { reset = function()
			tbl2 = {
				since = os.clock(),
				casts = 0,
				bites = 0,
				noBite = 0,
				failed = 0,
				collected = 0,
				lost = 0,
				dropped = 0,
				items = {},
				bait = {},
				lastDrop = nil,
				lastLost = nil,
			}

			local v = table.pack(ipairs(tbl))
			local v5, v6, v7

			if select("#", table.unpack(v, 1, v.n)) ~= 0 then
				v5 = v[1]
				v6 = v[2]
				v7 = v[3]
			else
				v5 = nil
				v6 = nil
				v7 = nil
			end

			for _, v8 in v5, v6, v7 do
				tbl2[v8] = 0
				continue
			end
		end }

		tbl3.reset()

		tbl3.record = function(arg)
			tbl2.casts += 1

			if arg.biteAfter then
				tbl2.bites += 1
			end

			local outcome = arg.outcome

			if outcome then
				if tbl2[outcome] then
					tbl2[outcome] += 1
				end
			end

			if arg.bait then
				if arg.biteAfter then
					if outcome ~= "cancelled" then
						tbl2.bait[arg.bait] = (tbl2.bait[arg.bait] or 0) + 1
					end
				end
			end
		end

		tbl3.collect = function(arg)
			if type(arg) ~= "table" then
				return
			end
			local n = tonumber(arg.amount) or 1
			tbl2.collected += n

			if arg.item then
				tbl2.items[arg.item] = (tbl2.items[arg.item] or 0) + n
			end
		end

		tbl3.drop = function(arg)
			if type(arg) ~= "table" then
				return
			end
			tbl2.dropped += 1
			tbl2.lastDrop = { item = arg.item, cause = arg.cause, recent = fn2(arg.recent), at = arg.at or os.clock() }
		end

		tbl3.lose = function(arg)
			if type(arg) ~= "table" then
				return
			end
			tbl2.lost += 1
			tbl2.lastLost = { item = arg.item, reason = arg.reason, dropped = arg.dropped, cause = arg.cause, at = os.clock() }
		end

		tbl3.miss = function(arg)
			if arg then
				tbl2.casts += 1
				tbl2.noBite += 1
			else
				tbl2.failed += 1
			end
		end

		tbl3.snapshot = function()
			local v = fn2(tbl2)
			local elapsed = (os.clock() - tbl2.since) / 3600
			v.seconds = os.clock() - tbl2.since
			local perHour = elapsed > 0

			if perHour then
				perHour = tbl2.collected / elapsed
			end

			v.perHour = perHour or 0
			return v
		end

		return tbl3
	end }

	return tbl2
end)

v4("Api/Fishing/Spots", function(arg)
	local Store = arg("Utility/Store")
