	local function getVector(arg2)
		if type(arg2) ~= "table" then
			return nil
		end
		local num = tonumber(arg2[1] or arg2.x)
		local num2 = tonumber(arg2[2] or arg2.y)
		local num3 = tonumber(arg2[3] or arg2.z)
		if not num then
			return nil
		end

		if not num2 then
			return nil
		end

		if not num3 then
			return nil
		end

		if num ~= num then
			return nil
		end

		if num2 == num2 then
			if num3 == num3 then
				return Vector3.new(num, num2, num3)
			end
		end

		return nil
	end

	local function fn2(arg2)
		return { arg2.X, arg2.Y, arg2.Z }
	end

	local function fn3(arg2)
		return (tostring(arg2 or ""):gsub("^%s+", ""):gsub("%s+$", ""))
