				end

				if spots then
					spots = v6.spots
				end

				spots = spots or {}
				local v7 = table.pack(ipairs(spots))
				local v8, v9, v10

				if select("#", table.unpack(v7, 1, v7.n)) ~= 0 then
					v8 = v7[1]
					v9 = v7[2]
					v10 = v7[3]
