			end

			return nil
		end

		tbl.point = function(arg)
			local target = arg.target
			local velocity = arg.velocity

			if velocity then
				if type(arg.rtt) == "number" then
					if arg.rtt > 0 then
						local vector = velocity * arg.rtt
						local magnitude = vector.Magnitude

						if tbl.LEAD_MAX < magnitude then
							vector *= tbl.LEAD_MAX / magnitude
						end

						if magnitude == magnitude then
							target += vector
						end
					end
				end
			end

			local root = arg.root

			if type(arg.range) == "number" then
				if arg.range > 0 then
					local offset = target - root

					if arg.range < offset.Magnitude then
						local v = unit(offset)

						if v then
							target = root + v * arg.range
						end
					end
				end
			end

			local vector = getVector(target - root)

			if vector.Magnitude < tbl.NUDGE then
				local up = vector.Magnitude > 0.001

				if up then
					up = unit(vector)
				end

				if not up then
					up = arg.up

					if up then
						up = unit(getVector(arg.up))
					end
				end

				if not up then
					up = arg.look

					if up then
						up = unit(getVector(arg.look))
					end
				end

				up = up or Vector3.new(1, 0, 0)
				target = Vector3.new(root.X, target.Y, root.Z) + up * tbl.NUDGE
			end

			return target
		end

		return tbl
	end)
end

