v4("Utility/EventBuffer", function()
	local function fn2()
		local v = table.pack(pcall(os.date, "!%Y-%m-%d %H:%M:%S UTC"))
		local v5, v6

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
		else
			v5 = nil
			v6 = nil
		end

		local v7 = v5

		if v7 then
			v7 = v6
		end

		return v7 or "unknown-time"
	end

	local tbl = {
		new = function(arg)
			local tbl = { events = {}, max = arg or 160 }

			tbl.push = function(arg2, arg3, arg4)
				arg2.events[#arg2.events + 1] = string.format("%s | [%s] %s", fn2(), tostring(arg3 or "INFO"), tostring(arg4 or ""))

				if arg2.max < #arg2.events then
					table.remove(arg2.events, 1)
				end
			end

			tbl.snapshot = function(arg2)
				return arg2.events
			end

			return tbl
		end,
		nowStamp = fn2,
	}

	return tbl
end)

v4("UI/LoadingScreen", function(arg)
	local Services = arg("Services")
