		local task_ = tasks[arg3]
		if task_ == arg4 then
			return
		end
		tasks[arg3] = arg4

		if task_ then
			fn2(task_)
		end
	end

	tbl.Add = function(arg2, arg3)
		if not arg3 then
			error("Task cannot be false or nil", 2)
		end

		arg2[#arg2._tasks + 1] = arg3

		if type(arg3) == "table" then
			if not arg3.Destroy then
				Log.warn("[Maid.Add] - Gave table task without .Destroy\n\n" .. debug.traceback())
			end
		end

		return arg3
	end

	tbl.GiveTask = function(arg2, arg3)
		if not arg3 then
			error("Task cannot be false or nil", 2)
		end

		local n = #arg2._tasks + 1
		arg2[n] = arg3

		if type(arg3) == "table" then
			if not arg3.Destroy then
				Log.warn("[Maid.GiveTask] - Gave table task without .Destroy\n\n" .. debug.traceback())
			end
		end

		return n
	end

