		if arg3:IsPending() then
			local v = arg3:resolved()
			local v5 = arg2:GiveTask(v)

			v:Finally(function()
				arg2[v5] = nil
			end)

			return v
		end

		return arg3
	end

	tbl.DoCleaning = function(arg2)
		local tasks = arg2._tasks
		local v = table.pack(pairs(tasks))
		local v5, v6, v7

		if select("#", table.unpack(v, 1, v.n)) ~= 0 then
			v5 = v[1]
			v6 = v[2]
			v7 = v[3]
		else
			v5 = nil
			v6 = nil
			v7 = nil
		end

		for k, v8 in v5, v6, v7 do
			if typeof(v8) ~= "RBXScriptConnection" then
