		local v8 = table.pack(pairs(tasks))
		local v9, v10, v11

		if select("#", table.unpack(v8, 1, v8.n)) ~= 0 then
			v9 = v8[1]
			v10 = v8[2]
			v11 = v8[3]
		else
			v9 = nil
			v10 = nil
			v11 = nil
		end

		for k in v9, v10, v11 do
			if type(k) == "number" then
				if n < k then
